P.entries["item:okra"] = {n="Okra",s="L'okra è una verdura coltivata che cresce nei terreni arati delle Marche Occidentali. Molto apprezzata dai coloni locali, funge da fondamentale addensante nei sostanziosi e improvvisati stufati della regione.",h="L'okra è una verdura coltivata che cresce nei terreni arati delle Marche Occidentali.",kw={"raccolto","fattoria","okra","saldean","salma saldean","verdura","westfall stew"},ang={["faction:Alliance"]="Mentre i nobili di Roccavento banchettano con carni importate, i coloni di frontiera dell'Alleanza sopravvivono coltivando colture tenaci come l'okra tra le rovine delle Marche Occidentali.",["profession:Cooking"]="Qualsiasi chef itinerante sa che un buon stufato ha bisogno di più che semplice carne cruda; l'okra fornisce l'amido e la consistenza necessari per trasformare il duro cibo raccolto nella natura selvaggia in un vero pasto caldo."},sec={{t="Un alimento base della Fattoria dei Saldean",b="Mentre gran parte delle Marche Occidentali giace a maggese sotto la minaccia dei fuorilegge Defias e degli attacchi dei golem mietitori impazziti, coloni ostinati come i Saldean riescono ancora a strappare robuste verdure dal terreno. L'okra cresce bassa e verde nella terra arata attorno alla Fattoria dei Saldean. Nonostante le dure condizioni della campagna, la coltura persiste, fornendo ai coloni locali nutrimento e sostanza essenziali quando il commercio esterno e le provviste da Roccavento vengono del tutto a mancare."},{t="Stufato delle Marche Occidentali",b="L'okra è nota soprattutto come base indispensabile per il famoso Westfall Stew di Salma Saldean. Combinati con qualsiasi carne si riesca a cacciare attraverso le pianure polverose, come carne di avvoltoio, grugni di zannacupa e occhi di murloc costieri, i baccelli tagliati a fette si sfaldano con il calore, addensando i brodi leggeri in un pasto saziante e rinvigorente. Per i coloni in difficoltà aggrappati alle loro proprietà, i baccelli freschi di okra trasformano un misero racimolo selvatico in una cena calda e sostanziosa."}},faq={{q="Dove cresce l'okra nelle Marche Occidentali?",a="L'okra cresce negli appezzamenti di colture arati presso la Fattoria dei Saldean, situata lungo la strada centrale delle Marche Occidentali. I viaggiatori possono trovare le caratteristiche piante verdi che prosperano nei solchi vicino alla fattoria del Contadino Saldean.",al={"posizione dell'okra","dove trovare l'okra","dove cresce l'okra"}},{q="A cosa serve l'okra?",a="L'okra viene raccolta per Salma Saldean alla Fattoria dei Saldean per cucinare il suo caratteristico Westfall Stew. Il suo amido naturale addensa il brodo, amalgamando ingredienti aspri come carne di avvoltoio, grugni di cinghiale e occhi di murloc in un pasto sostanzioso.",al={"usi dell'okra","a cosa serve l'okra","perché ho bisogno dell'okra"}},{q="Perché l'okra è importante per i Saldean?",a="Con le rotte commerciali interrotte e il regno che fornisce pochi aiuti, i coloni devono fare affidamento interamente su ciò che riescono a coltivare e cacciare da soli. L'okra è una delle poche colture rimaste alla Fattoria dei Saldean, permettendo di sfamare la famiglia e i viaggiatori di passaggio.",al={"okra dei saldean","perché l'okra è importante"}}},fx={["301f0b5e"]={q="Cos'è l'okra?",a="L'okra è una verdura commestibile che cresce nel terreno coltivato delle Marche Occidentali. Coltivati in fattorie come la Fattoria Saldean, i suoi baccelli sono abbastanza robusti da sopravvivere al clima difficile della regione e costituiscono un raccolto base affidabile per i coloni in difficoltà.",al={"cos'è l'okra","oggetto okra","pianta okra"}},["5bbd3a8c"]={q="Da dove proviene l'okra?",a="L'okra viene coltivata localmente nelle fattorie delle Marche Occidentali, in particolare da Salma e dal Contadino Saldean presso la Fattoria Saldean. Mentre gran parte della campagna è caduta in rovina e abbandono, colture resistenti come l'okra continuano a crescere nei campi coltivati superstiti.",al={"da dove proviene l'okra","chi coltiva l'okra","origine okra"}},b45f6830={q="Perché Salma Saldean vuole l'okra?",a="Salma Saldean ha bisogno di okra fresca come ingrediente essenziale per il suo famoso Westfall Stew. Quando viene affettata e fatta sobbollire insieme a selvaggina e carne locale, la verdura aiuta ad addensare il brodo saporito, fornendo un pasto ricco e sostanzioso per sostenere la gente delle pianure.",al={"perché l'okra è richiesta","perché salma vuole l'okra","chi vuole l'okra"}}},fp="4,209,43.527.0,32.535.0,44.272.0,20.273.0,43.304.0"}
P.entries["item:ordanus-head"] = {n="Testa di Ordanus",s="La Testa di Ordanus è il macabro trofeo preso al Custode Ordanus presso il Rifugio di Legnovivo a Valtetra. Reclamata per conto della maga elfa del sangue Braelyn Ardimano, funge da prova innegabile che uno dei figli più anziani di Cenarius è caduto sotto i colpi della vendetta arcana.",h="La Testa di Ordanus è il macabro trofeo preso al Custode Ordanus presso il Rifugio di Legnovivo a Valtetra.",kw={"valtetra","braelyn ardimano","cenarius","custode del boschetto","ordanus","testa di ordanus","rifugio di legnovivo","petrartiglio","sunrock retreat"},ang={["class:Druid"]="Per un druido, trasportare la testa mozzata di un figlio maggiore di Cenarius serve da crudo promemoria dell'aspra e sanguinosa animosità che i maghi arcani nutrono ancora verso i protettori della natura.",["faction:Horde"]="Abbattere Ordanus e consegnare la sua testa a Braelyn aiuta a consolidare la presenza dell'Orda lungo i confini contesi tra Petrartiglio e Valtetra, indebolendo la leadership locale degli Elfi della Notte."},sec={{t="Un rancore dal passato",b="Il Custode Ordanus era un antico custode del boschetto, uno dei rampolli più anziani del dio della foresta Cenarius. Quando Braelyn Ardimano scalò le alture delle Vette di Petrartiglio su ordine del suo maestro, cercò di porre fine al soffocamento della magia perpetrato dai druidi sulla vetta ed esigere vendetta su Ordanus. Tuttavia, il custode fu portato via in fretta e furia verso il cuore di Valtetra prima che lei potesse colpire. Usando la divinazione arcana per scrutare attraverso la chioma della foresta, Ardimano localizzò il suo santuario tra i rami del Rifugio di Legnovivo, pretendendo la sua testa mozzata come prova che all'arroganza del semidio selvaggio era stata finalmente data una risposta."},{t="Il prezzo della superbia",b="Braelyn nutre un vecchio rancore contro Ordanus, che conobbe molto tempo fa, e odia i druidi che cercano di soffocare il flusso della magia. In vita, Ordanus si considerava superiore persino all'antica nobiltà degli Eletti. Prendendo la sua testa, Ardimano si vendica simbolicamente dell'eredità di Cenarius, dichiarando che nessun guardiano della natura può arginare il ritorno del potere magico puro."}},faq={{q="Chi era il Custode Ordanus?",a="Il Custode Ordanus era un antico custode del boschetto e un figlio maggiore di Cenarius. Molto tempo fa, si scontrò con i praticanti dell'arcano della nobiltà degli Elfi della Notte, guadagnandosi la reputazione di profonda arroganza nei confronti di coloro che praticavano le arti arcane.",al={"chi è ordanus","storia di ordanus","cos'è ordanus"}},{q="Dove si raccoglie questa testa?",a="La testa viene reclamata dal Custode Ordanus in cima alla piattaforma di legno sopraelevata presso il Rifugio di Legnovivo, un'enclave fortificata tra le chiome degli Elfi della Notte situata nella parte centrale di Valtetra.",al={"dove trovare la testa di ordanus","posizione di ordanus","rifugio di legnovivo ordanus"}},{q="Perché Braelyn Ardimano vuole la sua testa?",a="Braelyn Ardimano conobbe Ordanus molto tempo fa e ne disprezzava l'arroganza, poiché egli si considerava superiore persino agli Eletti. Odia inoltre i druidi e i figli di Cenarius per aver cercato di arrestare il flusso della magia, e per aver portato via Ordanus dalla vetta prima che lei potesse raggiungerlo.",al={"perché braelyn vuole la testa di ordanus","rancore di braelyn","perché uccidere ordanus"}},{q="Cosa succede dopo che la testa viene consegnata?",a="Consegnare la Testa di Ordanus a Braelyn a Sunrock Retreat soddisfa il suo debito di sangue, e lei ricompensa il mercenario con il potente dono promesso.",al={"consegna testa di ordanus","dopo la morte di ordanus","ricompensa missione braelyn ardimano"}}},fx={e1459048={q="Da dove proviene la Testa di Ordanus?",a="Questo macabro trofeo è stato preso direttamente dal Custode Ordanus, uno dei figli maggiori del semidio della foresta Cenarius. Sebbene un tempo si pensasse fosse al sicuro in cima al Picco di Petrartiglio, Ordanus è fuggito a Valtetra e si è rifugiato in alto all'interno del Rifugio di Legnovivo prima di essere braccato.",al={"origine testa di ordanus","da dove viene la testa di ordanus","a chi appartiene la testa di ordanus"}}},fp="13,250,22.596.0,19.383.1,23.243.0,29.165.0,40.270.0,41.145.1"}
P.entries["item:orendil-s-cure"] = {n="Cura di Orendil",s="La Cura di Orendil è una pozione medicinale preparata dall'erborista Orendil Foglialarga nella parte settentrionale di Valtetra. Creata utilizzando la rara erba Capelli di Bathran, ha lo scopo di curare la misteriosa e letale malattia che affligge Relara Lunabianca ad Astranaar.",h="La Cura di Orendil è una pozione medicinale preparata dall'erborista Orendil Foglialarga nella parte...",kw={"valtetra","astranaar","capelli di bathran","orendil foglialarga","cura di orendil","pelturas lunabianca","relara"},ang={["profession:Herbalism"]="Il rimedio mette in mostra il profondo potere curativo della flora nativa di Valtetra, in particolare dei Capelli di Bathran, che prosperano solo in selezionati angoli ombrosi della foresta.",["race:NightElf"]="Per gli elfi della notte di Astranaar, salvare Relara è una questione comunitaria urgente, che unisce la conoscenza silvana di eremiti come Orendil alla fede divina in Elune."},sec={{t="La Speranza di un Padre",b="Quando la giovane Relara Lunabianca cadde mortalmente malata ad Astranaar, i rimedi convenzionali si rivelarono inutili contro il suo malanno. Il suo disperato padre, Pelturas Lunabianca, si rivolse a Orendil Foglialarga, un eremita e maestro di medicina naturale che dimorava lungo i confini settentrionali di Valtetra. Utilizzando fasci della rara pianta Capelli di Bathran raccolti tra le rovine infestate del Covo di Bathran, Orendil preparò questo intruglio su misura. L'arrivo della fiala dona speranza a Pelturas laddove prima ne aveva poca, sebbene la cura rallenti soltanto la malattia, e Pelturas debba ricorrere agli ulteriori rimedi suggeriti da Orendil."}},faq={{q="A cosa serve la Cura di Orendil?",a="La cura è formulata per dare sollievo e curare Relara Lunabianca, una giovane bambina elfa della notte ad Astranaar colpita da un'improvvisa e grave malattia.",al={"scopo della cura di orendil","cosa fa la cura","per chi è la cura"}},{q="Chi ha creato la cura?",a="È stata preparata da Orendil Foglialarga, un solitario erborista elfo della notte che vive nei boschi settentrionali di Valtetra, rinomato per la sua maestria nella flora della foresta e nei rimedi.",al={"chi ha creato la cura di orendil","creatore della cura di orendil"}},{q="Quali ingredienti sono stati usati per crearla?",a="L'ingrediente vitale sono i Capelli di Bathran, una pianta delicata e rara raccolta tra le rovine del Covo di Bathran nella parte settentrionale di Valtetra.",al={"ingredienti della cura","cosa c'è nella cura di orendil"}},{q="Questa pozione guarisce completamente la bambina?",a="Non del tutto. Pelturas scopre in seguito che la cura di Orendil ha soltanto rallentato la malattia che attanaglia sua figlia, perciò cerca un rimedio più potente suggerito da Orendil: la Lacrima di Elune.",al={"ha curato relara","relara è guarita"}}},fx={["8e86537e"]={q="Cos'è la Cura di Orendil?",a="La Cura di Orendil è un preparato medicinale creato dall'erborista Orendil Foglialarga nel nord di Valtetra. Progettato come trattamento specializzato per una malattia improvvisa e grave, rappresenta uno sforzo urgente per salvare la vita di una giovane bambina elfo della notte che soffre di un malanno misterioso.",al={"lore cura di orendil","cos'è la cura di orendil","rimedio di orendil"}},["6add91d1"]={q="Perché è necessaria la Cura di Orendil?",a="Ad Astranaar, la giovane figlia di Pelturas Lunabianca, Relara, è gravemente malata. Disperato per un rimedio dopo che i trattamenti standard si sono rivelati inefficaci, suo padre ha cercato l'esperienza di Orendil Foglialarga. L'erborista ha preparato questa specifica miscela nella speranza di stabilizzare la bambina prima che la malattia le tolga la vita.",al={"perché serve la cura di orendil","chi ha bisogno della cura di orendil","perché consegnare la cura di orendil"}}},fp="14,245,15.600.0,32.151.0,21.175.0,38.136.0,43.182.1"}
P.entries["item:oslow-s-toolbox"] = {n="Cassetta degli Attrezzi di Oslow",s="La Cassetta degli Attrezzi di Oslow contiene i fondamentali strumenti da costruzione necessari al Caposquadra Oslow a Borgolago. In viaggio da Borgodoro, le provviste vennero trasportate attraverso il Lago Placido, solo per essere affondate dal bombardamento di una catapulta orchesca.",h="La Cassetta degli Attrezzi di Oslow contiene i fondamentali strumenti da costruzione necessari al Caposquadra...",kw={"caposquadra oslow","lago placido","borgolago","oslow","crestarossa","forziere affondato","the lost tools","cassetta degli attrezzi"},ang={["faction:Alliance"]="Con Borgolago quasi isolata sotto l'assedio dei Blackrock, recuperare le provviste di Oslow è fondamentale per mantenere intatte le opere difensive della città."},sec={{t="Una traversata fatidica",b="Mantenere le difese e le infrastrutture di Borgolago è una sfida estenuante, in particolare con gli orchi Blackrock che assediano le Montagne Crestarossa. Il Caposquadra Oslow ordinò un set essenziale di attrezzi da costruzione fatto arrivare da Borgodoro. Poiché il ponte principale che conduceva a Borgolago era stato distrutto da un'azione nemica, il carico dovette essere imbarcato su una barca a remi per attraversare il Lago Placido. La traversata venne bruscamente interrotta quando le forze Blackrock colpirono l'imbarcazione con un colpo di catapulta, facendo sprofondare la barca e la pesante cassa di Oslow direttamente nelle profondità infestate dai murloc."}},faq={{q="Perché la Cassetta degli Attrezzi di Oslow si trova sul fondo del lago?",a="Il carico di attrezzi veniva trasportato da Borgodoro. Poiché il ponte di Borgolago era stato distrutto durante l'assedio, i rifornimenti dovettero attraversare il Lago Placido in barca. Gli orchi Blackrock bombardarono la barca a remi con una catapulta, affondando l'imbarcazione e facendo finire la cassetta degli attrezzi sul fondale del lago.",al={"perché la cassetta degli attrezzi è in acqua","come ha perso gli attrezzi oslow","storia della cassetta degli attrezzi affondata"}},{q="A chi appartiene questa cassetta degli attrezzi?",a="La cassetta degli attrezzi appartiene al Caposquadra Oslow, il supervisore che sovrintende alle costruzioni e alle riparazioni a Borgolago. Senza l'equipaggiamento adeguato, mantenere le fortificazioni della città contro i continui attacchi è praticamente impossibile.",al={"chi è oslow","proprietario oslow","attrezzi del caposquadra oslow"}},{q="In quale punto del Lago Placido sono affondati gli attrezzi?",a="Gli attrezzi riposano all'interno di una cassa affondata vicino al relitto della barca a remi distrutta nel Lago Placido, adagiata tra i massi sottomarini a sud di un evidente accampamento murloc sulla riva.",al={"posizione della cassetta degli attrezzi","dove si trova il forziere affondato","dove è affondata la barca"}},{q="Quali minacce fanno la guardia alla cassa affondata?",a="Le acque che circondano il relitto sono infestate da murloc ostili e bestie acquatiche predatrici, compresi pericolosi Lake Thresher che si aggirano nelle zone più profonde del lago.",al={"pericoli vicino alla cassetta degli attrezzi","nemici di lago placido","cosa fa la guardia agli attrezzi di oslow"}}},fx={["543d5407"]={q="Perché il Caposquadra Oslow ha bisogno che venga recuperata la sua cassetta degli attrezzi?",a="Borgolago è sotto pesante assedio, il che lascia la città isolata e disperatamente a corto di rifornimenti essenziali. Come caposquadra della città, Oslow ha bisogno della sua attrezzatura per mantenere e riparare le strutture e le difese di Borgolago. Poiché il carro delle consegne da Borgodoro non è riuscito ad attraversare il ponte distrutto, perdere gli attrezzi sostitutivi nel lago ha bloccato lavori di costruzione critici, rendendo il loro recupero vitale per la sopravvivenza della città.",al={"perché oslow vuole la cassetta degli attrezzi","perché oslow ha bisogno degli attrezzi","perché recuperare la cassetta degli attrezzi di oslow"}}},fp="15,215,18.576.0,49.284.0,22.215.0,43.182.0,36.175.0"}
P.entries["item:osric-s-crate"] = {n="Cassa di Osric",s="La Cassa di Osric è un pesante pacco di armature appena forgiate, inviato da Roccavento ai difensori in difficoltà di Guardiacolle. Trasportata a bordo di un grifone attraverso la rete di rotte aeree del regno, fornisce equipaggiamento vitale per aiutare The People's Militia a difendere le Marche Occidentali contro le bande di fuorilegge.",h="La Cassa di Osric è un pesante pacco di armature appena forgiate, inviato da Roccavento ai difensori in...",kw={"dungar longdrink","grifone","osric","cassa di osric","the people's militia","quartiermastro lewis","guardiacolle","marche occidentali"},ang={["faction:Alliance"]="Ogni spedizione di armi e armature che raggiunge Guardiacolle contribuisce a impedire che i confini occidentali del regno cadano completamente nelle mani della Fratellanza dei Defias."},sec={{t="Rifornimenti per il Fronte",b="Le Marche Occidentali soffrono sotto le predazioni della Fratellanza dei Defias e di gnoll razziatori, mentre l'esercito di Roccavento rimane assente. I difensori locali, organizzati come The People's Militia a Guardiacolle, sono privi del sostegno formale della corona e devono fare affidamento su rifornimenti frammentari. La Cassa di Osric contiene una nuova fornitura di armature protettive inviata dalla capitale al Quartiermastro Lewis, destinata a essere distribuita direttamente ai miliziani volontari sul campo."},{t="Rete di Corrieri Alati",b="Trasportare l'equipaggiamento via terra da Roccavento attraverso la Foresta di Elwynn e oltre il confine delle Marche Occidentali è lento e pieno di imboscate dei banditi. Per aggirare le strade, la cassa viene affidata a un avventuriero in volo tramite il Gryphon Roost di Dungar Longdrink nel Distretto Commerciale di Roccavento fino a Thor a Guardiacolle. Questa rapida consegna dimostra il ruolo cruciale svolto dai grifoni nel mantenere riforniti i presidi di frontiera in tempo di guerra."}},faq={{q="Cosa c'è dentro la Cassa di Osric?",a="La cassa contiene armature protettive forgiate a Roccavento. Il Quartiermastro Lewis ispeziona la consegna e si prepara immediatamente a distribuire le armature tra i combattenti che difendono Guardiacolle.",al={"cosa c'è nella cassa","contenuto della cassa di osric","contenuto cassa di osric"}},{q="Chi è Osric?",a="Osric è un corazzaio con base a Roccavento che ha preparato questa spedizione di equipaggiamento per The People's Militia a presidio delle Marche Occidentali.",al={"chi è osric","chi ha inviato la cassa di osric"}},{q="Chi riceve la cassa?",a="La spedizione è indirizzata al Quartiermastro Lewis, l'ufficiale che gestisce i rifornimenti e l'equipaggiamento per The People's Militia a Guardiacolle, nelle Marche Occidentali.",al={"dove va la cassa","a chi consegno la cassa di osric","destinatario della cassa"}},{q="Perché la cassa viene consegnata tramite grifone?",a="Banditi e fuorilegge rendono pericolose le strade che collegano Roccavento, la Foresta di Elwynn e le Marche Occidentali. Volare via grifone da Dungar Longdrink a Roccavento direttamente fino a Thor a Guardiacolle garantisce che l'armatura arrivi rapidamente e in sicurezza.",al={"perché trasportare la cassa in volo","perché usare i grifoni","volo cassa di osric"}}},fx={["34d354cb"]={q="Cos'è la Cassa di Osric?",a="La Cassa di Osric è una spedizione di armature inviata da Roccavento. È preparata per i difensori di stanza a Guardiacolle nelle Marche Occidentali, che sono disperatamente a corto di equipaggiamento mentre resistono contro la Fratellanza dei Defias.",al={"cos'è la cassa di osric","oggetto cassa di osric","cosa c'è nella cassa di osric"}},["091b5cbb"]={q="Da dove proviene la Cassa di Osric e chi l'ha preparata?",a="La cassa proviene da Roccavento, preparata e spedita da Osric per rifornire The People's Militia. Il Mastro Grifone Dungar Longdrink la affida a te per trasportarla in grifone attraverso il regno fino alle Marche Occidentali.",al={"chi ha preparato la cassa di osric","da dove proviene la cassa di osric","origine cassa di osric"}},["11fb3015"]={q="Perché qualcuno vuole la Cassa di Osric?",a="Il Quartiermastro Lewis e The People's Militia a Guardiacolle hanno un disperato bisogno dell'armatura all'interno. Con le Marche Occidentali abbandonate dalle forze reali e invase dai fuorilegge, ogni pezzo di equipaggiamento protettivo è vitale per mantenere in vita i difensori.",al={"perché consegnare la cassa di osric","perché lewis vuole la cassa di osric","scopo della cassa di osric"}}},fp="13,284,22.458.0,22.421.0,29.192.0,13.116.0,23.148.0,38.228.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Cassa di Contenitori di Melma",s="Questo pacco è un set di barattoli per campioni specializzati e vuoti, fornito dal ricercatore gnomo Laris Perdiruote a Forgiardente. Destinato a pericolosi campionamenti sul campo nelle foreste devastate di Vilbosco, contiene barattoli progettati per contenere in sicurezza estratti di melma corrotta e maledetta senza dissolversi.",h="Questo pacco è un set di barattoli per campioni specializzati e vuoti, fornito dal ricercatore gnomo Laris...",kw={"contenitori","maledetta","vilbosco","forgiardente","barattoli","laris perdiruote","melma","pacco","corrotta"},ang={["faction:Alliance"]="Raccogliere questi campioni aiuta l'Alleanza a tenere il passo con le inquietanti ricerche condotte dalla Società degli Speziali Reali dei Reietti.",["race:Gnome"]="Laris Perdiruote considera questa ricerca sulle melme come un'opportunità vitale per dimostrare ai Nani di Forgiardente che accogliere gli gnomi rifugiati è valsa assolutamente la pena."},sec={{t="Equipaggiamento Scientifico da Campo",b="Contenente una dozzina di barattoli vuoti, suddivisi tra contenitori destinati a melme maledette e corrotte, questo kit è stato assemblato da Laris Perdiruote per gli intrepidi viaggiatori diretti a Vilbosco. Poiché i campioni grezzi di melma sono notoriamente caustici e inclini a dissolvere i normali bagagli, un vetro robusto e sigillato è essenziale per trasportare i residui acidi attraverso i continenti fino al banco di lavoro dell'inventore a Forgiardente."},{t="Il Mistero della Melma",b="L'interesse di Perdiruote per la melma è ben lungi dall'essere un semplice hobby eccentrico. Avendo notato che i ricercatori Reietti della Società degli Speziali Reali raccolgono abitualmente questi bizzarri organismi in tutta Azeroth, sospetta che le melme possano celare profondi segreti sull'origine del mondo. Perdiruote teorizza che le melme possano essere secrezioni primordiali collegate alla creazione stessa del pianeta, e fa affidamento sugli agenti sul campo che utilizzano questo kit per raccogliere le prove necessarie a ottenere il plauso all'interno della Lega degli Esploratori."}},faq={{q="Cosa contiene la cassa di contenitori di melma?",a="Il pacco contiene dodici barattoli per campioni: sei barattoli vuoti calibrati per la Melma Maledetta e sei designati per la melma corrotta.",al={"contenuto del pacco","cosa contiene il pacco","barattoli per melma all'interno"}},{q="Chi fornisce questo pacco?",a="Viene consegnato agli avventurieri dell'Alleanza da Laris Perdiruote, uno studioso e ricercatore gnomo che opera a Forgiardente.",al={"chi fornisce i barattoli","oggetto di missione di laris perdiruote","dove trovare la cassa di melma"}},{q="Dove devono essere utilizzati questi contenitori?",a="Sono destinati all'uso nelle terre selvagge e corrotte di Vilbosco, dove gli avventurieri devono sconfiggere melme corrotte e maledette per raccogliere campioni di residui direttamente dalle creature cadute.",al={"dove usare i barattoli per melma","quale zona per le melme","posizione dei barattoli per melma"}},{q="Perché Laris Perdiruote vuole questi campioni di melma?",a="Laris ha notato che la Società degli Speziali Reali dei Reietti raccoglie melma in tutto il mondo e vuole svelarne i segreti. Nutre inoltre la teoria non convenzionale secondo cui le melme potrebbero essere secrezioni primordiali legate alla creazione di Azeroth, e spera che dimostrarlo gli valga prestigio all'interno della Lega degli Esploratori.",al={"perché raccogliere melma","ricerca di perdiruote","perché laris vuole la melma"}}},fx={d8bf9111={q="Cos'è la Cassa di Contenitori di Melma?",a="È un kit da campo assemblato dal ricercatore gnomo Laris Perdiruote a Forgiardente. Il pacco contiene una serie di barattoli appositamente preparati per raccogliere e conservare in sicurezza i campioni prelevati dalle melme corrotte che si trovano in tutto Vilbosco.",al={"cos'è la cassa di contenitori di melma","pacchetto contenitori di melma","set contenitori di melma vuoti"}}},fp="32,289,24.409.0,23.492.0,52.121.0,26.116.0,44.183.0,50.308.0"}
P.entries["item:painted-gnoll-armband"] = {n="Polsiera degli Gnoll Dipinta",s="Le Polsiere degli Gnoll Dipinte sono rozzi ornamenti indossati dagli gnoll Riverpaw che si aggirano nei dintorni della Foresta di Elwynn. Il Presidio Rivombroso raccoglie queste fasce contrassegnate come prova tangibile delle taglie riscosse contro i branchi che avanzano.",h="Le Polsiere degli Gnoll Dipinte sono rozzi ornamenti indossati dagli gnoll Riverpaw che si aggirano nei...",kw={"taglia","vicesceriffo rainer","foresta di elwynn","gnoll","polsiera degli gnoll dipinta","riverpaw","lago del memoriale","presidio rivombroso"},ang={["faction:Alliance"]="Raccogliere queste polsiere aiuta direttamente il Presidio Rivombroso, rafforzando la frontiera occidentale di Roccavento mentre l'esercito permanente della città è dislocato altrove."},sec={{t="Simboli dei Riverpaw",b="Il branco Riverpaw contraddistingue i propri guerrieri e razziatori con rozze polsiere dipinte con motivi tribali grezzi. Le fasce dipinte vengono recuperate dagli gnoll Riverpaw lungo i confini selvaggi della Foresta di Elwynn. Per i difensori di Roccavento, tuttavia, rappresentano una crescente minaccia territoriale che incombe vicino al Lago del Memoriale e ai boschi a sud del Presidio Rivombroso."},{t="Taglia per il Presidio Rivombroso",b="Con l'esercito di Roccavento disperso in tutto il regno, il Presidio Rivombroso fatica a mantenere sicuro il confine occidentale contro le minacce incombenti. Il Vicesceriffo Rainer ha imposto una taglia permanente sui branchi invasori, incaricando gli avventurieri di uccidere Riverpaw Outrunner e Riverpaw Runt. Le polsiere dipinte fungono da prova innegabile dell'uccisione, consentendo ai vice del presidio di conteggiare le taglie e sfoltire la popolazione di gnoll che invade i terreni agricoli vicini."}},faq={{q="Perché il Presidio Rivombroso vuole queste polsiere?",a="Il Vicesceriffo Rainer al Presidio Rivombroso raccoglie le polsiere come prova degli gnoll Riverpaw uccisi. Poiché le truppe del presidio non riescono a gestire da sole i branchi che avanzano, Roccavento paga taglie a qualsiasi avventuriero riporti questi pegni.",al={"perché le polsiere","chi vuole le polsiere degli gnoll dipinte","taglia del vicesceriffo rainer"}},{q="Quali gnoll indossano queste polsiere dipinte?",a="Sono portate dagli gnoll Riverpaw nella Foresta di Elwynn, in particolare dai Riverpaw Outrunner e dai Riverpaw Runt che infestano i boschi a sud del Presidio Rivombroso e le rive attorno al Lago del Memoriale.",al={"dove si trovano le polsiere","chi rilascia la polsiera degli gnoll dipinta","quali gnoll hanno le polsiere"}},{q="Perché gli gnoll Riverpaw si trovano nella Foresta di Elwynn?",a="I branchi Riverpaw si sono spinti a est lungo i confini della Foresta di Elwynn, allestendo accampamenti vicino al Lago del Memoriale e ai margini della foresta. Approfittano della ridotta presenza militare del regno per cacciare, depredare e minacciare gli insediamenti vicini.",al={"perché gli gnoll sono qui","invasione degli gnoll a elwynn","riverpaw elwynn"}},{q="Qual è il significato della pittura sulle polsiere?",a="Le fasce identificano i trofei presi dagli gnoll Riverpaw e servono come prova per il Vicesceriffo Rainer. La fonte non attribuisce ranghi o significati specifici ai motivi dipinti.",al={"perché sono dipinte","segni sulle polsiere degli gnoll"}}},fx={["586b453e"]={q="Cos'è la Polsiera degli Gnoll Dipinta?",a="La Polsiera degli Gnoll Dipinta è un rozzo ornamento personale indossato dagli gnoll Riverpaw. Realizzate e dipinte dal branco, queste polsiere segnano la loro presenza nelle terre di confine della Foresta di Elwynn. Per l'esercito di Roccavento, fungono da innegabile prova fisica che un predone gnoll è stato ucciso.",al={"cos'è la polsiera degli gnoll dipinta","lore della polsiera degli gnoll dipinta","polsiera gnoll"}}},fp="21,230,22.370.0,29.441.0,48.231.0,41.201.0,41.247.0,54.175.0"}
P.entries["item:panther-cage-key"] = {n="Chiave della Gabbia della Pantera",s="La Chiave della Gabbia della Pantera è una piccola chiave di metallo custodita da Wizlo Bearingshiner all'Accampamento di Manto Bianco. Apre una gabbia rinforzata che racchiude un feroce predatore prigioniero tra i resti di una carovana caduta in un'imboscata a Millepicchi.",h="La Chiave della Gabbia della Pantera è una piccola chiave di metallo custodita da Wizlo Bearingshiner...",kw={"centauri","ingranaggio ipercapacitante","chiave della gabbia della pantera","millepicchi","accampamento di manto bianco","wizlo bearingshiner"},ang={["faction:Horde"]="Assistere Wizlo contribuisce a rendere sicure le strade di Millepicchi attorno all'Accampamento di Manto Bianco dalle instabili conseguenze delle incursioni dei centauri.",["profession:Engineering"]="La chiave apre la gabbia che racchiude l'instabile prototipo di un inventore, a riprova del fatto che gli eccentrici inventori nascondono i loro meccanismi più delicati nei luoghi più pericolosi che si possano immaginare."},sec={{t="Una serratura precaria",b="Quando una carovana in viaggio fu attaccata e saccheggiata dai predoni centauri a nord dell'Accampamento di Manto Bianco, il meccanico goblin Wizlo Bearingshiner riuscì a malapena a fuggire e a salvarsi la vita. Tra le macerie dei carri e il carico depredato, i predoni lasciarono una sola cosa del tutto intatta: una robusta gabbia che ospitava una feroce e rara pantera. Attorno al collo del predatore era appesa la preziosa invenzione di Wizlo, un Ingranaggio Ipercapacitante. Riluttanti ad avvicinarsi alla bestia ringhiante, i centauri si tennero a debita distanza dalla gabbia, lasciando la chiave di Wizlo come unico modo per aprire la porta e recuperare il congegno."}},faq={{q="Chi fornisce la Chiave della Gabbia della Pantera?",a="La chiave viene consegnata agli avventurieri da Wizlo Bearingshiner, un meccanico goblin che riposa all'Accampamento di Manto Bianco, nella parte nord-occidentale di Millepicchi.",al={"chi dà la chiave della gabbia della pantera","dove trovare la chiave della gabbia della pantera","fonte della chiave della gabbia della pantera"}},{q="Cosa apre la chiave?",a="Apre una gabbia di ferro che si trova tra i carri distrutti di una carovana in rovina poco a nord dell'Accampamento di Manto Bianco, la quale racchiude una pericolosa pantera infuriata.",al={"cosa apre la chiave della pantera","posizione della gabbia della pantera","dove si trova la gabbia"}},{q="Perché i centauri non hanno saccheggiato la gabbia?",a="I centauri hanno saccheggiato il resto della carovana, ma la pantera prigioniera all'interno era così feroce e minacciosa che persino i predoni si sono rifiutati di manomettere la sua gabbia.",al={"perché i centauri hanno lasciato la pantera","centauri spaventati dalla pantera"}},{q="Cosa c'è dentro la gabbia oltre alla bestia?",a="Il prezioso Ingranaggio Ipercapacitante di Wizlo è legato attorno al collo della pantera, costringendo chiunque speri di recuperare l'invenzione ad aprire la gabbia e ad affrontare direttamente il predatore.",al={"perché aprire la gabbia","cosa ha addosso la pantera"}}},fx={b335554a={q="Perché Wizlo Bearingshiner vuole indietro la Chiave della Gabbia della Pantera?",a="Wizlo Bearingshiner ti affida la chiave solo affinché tu possa aprire la gabbia presso la sua carovana distrutta per uccidere la feroce pantera al suo interno. La bestia indossa al collo il suo prezioso ingranaggio ipercapacitante. Vuole che la chiave gli venga restituita insieme alla sua invenzione una volta compiuta l'azione, assicurandosi che i resti della carovana e la sua pericolosa proprietà siano interamente recuperati.",al={"perché la chiave della gabbia della pantera","perché wizlo ha bisogno della chiave","perché volere la chiave della gabbia della pantera"}}},fp="16,219,17.550.0,34.133.0,25.147.0,37.165.0,42.176.0"}
P.entries["item:parker-s-lunch"] = {n="Pasto di Parker",s="Il Pasto di Parker è un pasto preparato al momento e confezionato da Darcy a Borgolago. Destinato alla Guardia Parker di pattuglia, offre un semplice scorcio sui legami quotidiani e sui modesti comfort dei difensori di Crestarossa.",h="Il Pasto di Parker è un pasto preparato al momento e confezionato da Darcy a Borgolago.",kw={"a free lunch","darcy","guardia parker","borgolago","pasto di parker","crestarossa"},ang={["faction:Alliance"]="Con la capitale lenta nell'inviare rinforzi, la solidarietà locale tra gli abitanti della città e le poche guardie rimaste è ciò che mantiene in funzione Borgolago.",["profession:Cooking"]="Un pasto caldo e al sacco è spesso l'unico conforto che sostiene le guardie di frontiera contro le lunghe ore e le bestie ostili nelle terre selvagge."},sec={{t="Un pasto per il viaggio",b="Mentre le Montagne Crestarossa barcollano sotto gli attacchi degli gnoll e degli orchi Roccianera, i piccoli gesti della vita quotidiana persistono. Darcy, una cameriera della locanda di Borgolago, prepara questo pasto sano per la Guardia Parker, che pattuglia la strada esposta che conduce a sud verso Boscovespro. Il presidio di Crestarossa è ridotto allo stremo e isolato dagli aiuti di Roccavento, costringendo le singole guardie a mantenere turni di guardia lunghi e solitari. Consegnare questo fagotto non solo mantiene nutrita una sentinella, ma accende anche un timido e duraturo corteggiamento tra i due abitanti della città."}},faq={{q="Chi ha preparato il Pasto di Parker?",a="Il pranzo è stato preparato da Darcy, una cameriera della locanda di Borgolago. Preoccupata per la Guardia Parker mentre è impegnato in una pericolosa pattuglia, fa affidamento sugli avventurieri di passaggio affinché glielo consegnino sano e salvo.",al={"chi ha preparato il pasto di parker","chi mi ha dato il pasto di parker","darcy crestarossa pasto"}},{q="Dove si trova la Guardia Parker?",a="La Guardia Parker pattuglia la strada sterrata principale che si dirige a sud-ovest fuori Borgolago verso il confine con Boscovespro. Fa la spola lungo quel percorso facendo la guardia contro gli gnoll erranti.",al={"posizione della guardia parker","dove si trova la guardia parker","trova la guardia parker"}},{q="Cosa fa la Guardia Parker dopo aver ricevuto il suo pasto?",a="Parker è profondamente toccato dalla premura di Darcy. Grato per il cibo caldo durante la sua difficile pattuglia, cerca presto un modo per ricambiare la sua gentilezza, chiedendo aiuto per inviarle narcisi freschi dall'erborista.",al={"seguito pasto di parker","darcy e parker","reazione di parker al pasto"}},{q="Perché Darcy non consegna il pranzo di persona?",a="Le strade fuori Borgolago pullulano di aggressivi gnoll di Crestarossa e invasori Roccianera. Sebbene la Guardia Parker abbia l'addestramento al combattimento e l'armatura necessari per sopravvivere di pattuglia, i comuni cittadini come Darcy non possono rischiare di compiere il viaggio da soli in sicurezza.",al={"perche darcy non puo portarlo","perche consegnare il pasto crestarossa"}}},fx={["2351e721"]={q="Cos'è il Pasto di Parker?",a="Il Pasto di Parker è un pasto confezionato preparato da Darcy, l'assistente di un locandiere a Borgolago. Lo ha preparato appositamente per sostenere la Guardia Parker, che trascorre lunghe ed estenuanti ore a pattugliare le insidiose strade a sud della città verso Boscovespro.",al={"cos'è il pasto di parker","oggetto pasto di parker"}},b73a829b={q="Perché la Guardia Parker ha bisogno che gli venga consegnato il pasto?",a="La Guardia Parker è di stanza ben lontano dalla relativa sicurezza di Borgolago, a fare la guardia contro gnoll erranti e orchi Roccia Nera lungo la strada di confine. Impossibilitato ad abbandonare il suo posto per tornare alla locanda, dipende dalla gentilezza degli abitanti come Darcy, e dei viaggiatori di passaggio, per essere sfamato durante il servizio.",al={"perché consegnare il pasto di parker","perché parker vuole il pasto","perché la guardia parker ha bisogno del pasto"}}},fp="14,201,19.526.0,28.194.0,32.182.0,52.210.1,44.241.0"}
P.entries["item:partially-filled-vessel"] = {n="Ampolla Mezza Piena",s="L'Ampolla Mezza Piena è un contenitore incantato utilizzato per trasportare l'acqua benedetta dei pozzi lunari attraverso Teldrassil. Consegnata ai giovani iniziati elfi della notte da Tenaron Fermatuono ad Aldrassil, trasporta l'acqua attinta da Vallombra verso l'insediamento di Dolanaar.",h="L'Ampolla Mezza Piena è un contenitore incantato utilizzato per trasportare l'acqua benedetta dei pozzi...",kw={"aldrassil","corithras lunafuria","crown of the earth","dolanaar","pozzo lunare","ampolla mezza piena","vallombra","tenaron fermatuono","ampolla"},ang={["class:Druid"]="Trasportare le acque consacrate è un dovere essenziale al servizio del continuo impegno del Circolo Cenariano per nutrire e verificare la salute dell'Albero del Mondo.",["race:NightElf"]="Portare questa ampolla rappresenta un rito di passaggio, che conduce i giovani elfi della notte lontano dal santuario di Vallombra e verso le responsabilità più ampie di prendersi cura di Teldrassil."},sec={{t="Una consegna sacra",b="Tra i rami di Aldrassil, gli iniziati dei kaldorei raccolgono le acque benedette dal pozzo lunare appartato di Vallombra. Tenaron Fermatuono versa quel campione puro in questo recipiente speciale, preparandolo per il viaggio attraverso l'Albero del Mondo. L'ampolla rimane solo parzialmente piena perché il suo viaggio è appena iniziato; alla fine dovranno essere raccolte altre acque sacre da tutta Teldrassil per prendersi cura della salute dell'isola."},{t="Verso Dolanaar",b="Trasportare l'ampolla richiede di viaggiare a sud attraverso i cancelli della valle e seguire le strade di ciottoli verso ovest fino a Dolanaar. Il viaggio segna la partenza di un giovane avventuriero dal rifugio protetto di Vallombra verso le più ampie terre selvagge di Teldrassil. Presso il pozzo lunare centrale di Dolanaar, Corithras Lunafuria prende in custodia l'ampolla per dirigere la fase successiva del rituale."}},faq={{q="Cosa c'è dentro l'ampolla?",a="Contiene acqua pura del pozzo lunare raccolta dalla pozza sacra di Vallombra, versata nel contenitore dal druido Tenaron Fermatuono.",al={"cosa c'è nell'ampolla","contenuto dell'ampolla","che acqua c'è dentro"}},{q="Perché è solo mezza piena?",a="Il pozzo lunare di Vallombra fornisce solo il primo campione. I continui sforzi per prendersi cura di Teldrassil richiedono di raccogliere l'acqua da molteplici pozzi lunari attraverso l'albero prima che il contenitore sia pieno.",al={"perché mezza piena","perché non è piena"}},{q="A chi porto questa ampolla?",a="Porta l'ampolla a sud fuori da Vallombra e segui la strada di ciottoli verso ovest fino a Dolanaar. Lì, consegnala a Corithras Lunafuria, che si occupa del pozzo lunare della città.",al={"a chi va l'ampolla","dove la porto","consegna ampolla"}},{q="Perché l'acqua del pozzo lunare viene spostata su Teldrassil?",a="I druidi e le sacerdotesse monitorano e nutrono Teldrassil attraverso le acque dei suoi pozzi lunari. Trasportare l'acqua tra i pozzi aiuta a mantenere le loro benedizioni tra i rami tormentati del neonato Albero del Mondo.",al={"perché trasportare l'acqua del pozzo lunare","scopo dell'acqua","perché spostare l'acqua"}}},fx={["5f4a3df1"]={q="Cos'è l'Ampolla Mezza Piena?",a="L'Ampolla Mezza Piena è un contenitore incantato usato dai druidi elfi della notte per raccogliere e trasportare le acque sacre dei pozzi lunari di Teldrassil. Quando Tenaron Fermatuono ti invia da Vallombra, unisce la tua fiala raccolta di acqua benedetta del pozzo lunare in questa ampolla, affinché il lavoro sacro possa continuare attraverso i rami dell'Albero del Mondo.",al={"lore dell'ampolla mezza piena","cos'è questa ampolla","cos'è l'ampolla mezza piena"}},["4f920d4c"]={q="Da dove proviene l'Ampolla Mezza Piena e chi l'ha creata?",a="Tenaron Fermatuono, uno dei druidi anziani di stanza in cima ad Aldrassil a Vallombra, ti fornisce questo contenitore. Dopo che avrai attinto l'acqua dal pozzo lunare di Vallombra, Tenaron verserà la tua fiala nel contenitore per iniziare la raccolta, affidandoti il compito di trasportarlo verso le distese più ampie di Teldrassil.",al={"chi ha creato l'ampolla","da dove proviene l'ampolla","origine dell'ampolla"}},["089d2d88"]={q="Perché Corithras Lunafuria vuole l'Ampolla Mezza Piena?",a="Corithras Lunafuria attende il contenitore presso il pozzo lunare di Dolanaar per proseguire un compito druidico vitale noto come la Crown of the Earth. Raccogliere le acque di Teldrassil è essenziale per ispezionare e prendersi cura del giovane Albero del Mondo, e Corithras richiede l'acqua che hai trasportato da Aldrassil prima di poterti indirizzare verso le fasi successive del rituale.",al={"perché corithras vuole questo","perché portare l'ampolla a dolanaar","perché portare l'ampolla a corithras"}}},fp="23,257,17.421.0,18.376.0,26.135.0,32.190.0,29.161.0,52.216.0"}
P.entries["item:pendant-of-shadow"] = {n="Pendente dell'Ombra",s="Il Pendente dell'Ombra è un oscuro talismano indossato dal rinnegato stregone Morganth in cima alla Torre di Ilgalar nelle Montagne Crestarossa. Portato al mago Theocritus presso la Torre di Azora, serve come prova innegabile che il malefico incantatore è stato eliminato prima che le sue sinistre ambizioni potessero dare frutti.",h="Il Pendente dell'Ombra è un oscuro talismano indossato dal rinnegato stregone Morganth in cima alla Torre di...",kw={"morganth","pendente dell'ombra","crestarossa","falce di elune","theocritus","torre di azora","torre di ilgalar"},ang={["class:Mage"]="Recuperare l'oscuro talismano per volere di Theocritus evidenzia la costante responsabilità che grava sui maghi nel sorvegliare gli sconsiderati incantatori rinnegati che minacciano il reame.",["class:Warlock"]="Morganth rappresenta il pericolo di attirare troppa attenzione da parte della Torre di Azora mentre si inseguono instabili manufatti proibiti come la Falce di Elune."},sec={{t="Emblema di un Oscuro Stregone",b="Custodito dal rinnegato stregone Morganth nel suo rifugio presso la Torre di Ilgalar, il Pendente dell'Ombra è intriso di magia oscura. Morganth cercava di svelare i misteri della Falce di Elune, un'antica reliquia dall'immenso e instabile potere. Temendo la devastazione che lo stregone avrebbe potuto scatenare sulle Montagne Crestarossa e sul regno di Roccavento, il mago Theocritus incaricò gli avventurieri di infiltrarsi a Ilgalar, porre fine alle trame di Morganth e strappare il talismano dalla sua presa come prova della sua scomparsa."}},faq={{q="Dove trovo il Pendente dell'Ombra?",a="Il pendente è custodito dallo stregone Morganth, che risiede sulla cima della Torre di Ilgalar, nella parte nordorientale delle Montagne Crestarossa.",al={"posizione del pendente dell'ombra","dove si trova il pendente dell'ombra","come ottenere il pendente dell'ombra"}},{q="Chi vuole il Pendente dell'Ombra?",a="Il talismano deve essere portato al mago Theocritus, che risiede nella Torre di Azora, situata nella parte orientale della Foresta di Elwynn.",al={"chi accetta il pendente dell'ombra","consegna del pendente dell'ombra","il pendente di theocritus"}},{q="Perché Theocritus ha bisogno di questo pendente?",a="Theocritus richiede il pendente come prova tangibile che Morganth è stato ucciso e che la sua ricerca della pericolosa Falce di Elune è stata interrotta.",al={"perché theocritus lo vuole","scopo del pendente dell'ombra"}},{q="Quale minaccia rappresentava Morganth con il pendente?",a="Morganth era a caccia dell'elusiva Falce di Elune. Theocritus temeva che, se l'oscuro stregone fosse riuscito a impadronirsi del manufatto, avrebbe scatenato un potere catastrofico su tutta Crestarossa e sul regno circostante.",al={"cosa stava facendo morganth","storia di morganth"}}},fx={d0e37f9a={q="Cos'è il Pendente dell'Ombra?",a="Il Pendente dell'Ombra è un oscuro talismano indossato dal famigerato stregone Morganth in cima alla Torre di Ilgalar nelle Montagne Crestarossa. Legato direttamente alle sinistre ambizioni e alle arti oscure di Morganth, il pendente funge da prova della sua sconfitta per il mago Theocritus, che teme il caos che Morganth potrebbe scatenare su Roccavento se lasciato indisturbato.",al={"cos'è il pendente dell'ombra","lore del pendente dell'ombra","informazioni sul pendente dell'ombra"}}},fp="17,310,23.500.1,38.135.0,32.122.0,38.160.1,47.209.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Pendente del Leone Marino",s="Il Pendente del Leone Marino è un sacro talismano druidico che rappresenta l'unione di agilità acquatica e resistenza. Assemblato presso il Santuario di Remulos a Radaluna, serve come prova che un iniziato è pronto a padroneggiare la propria Aquatic Form.",h="Il Pendente del Leone Marino è un sacro talismano druidico che rappresenta l'unione di agilità acquatica e...",kw={"aquatic form","dendrite ardistella","mathrengyl domaorsi","radaluna","pendente del leone marino","remulos","turak totem runico"},ang={["class:Druid"]="L'assemblaggio di questo talismano segna una pietra miliare fondamentale nell'addestramento di un druido, sbloccando la capacità di respirare sott'acqua e nuotare con naturale velocità sotto forma di leone marino.",["race:Tauren"]="Per gli Shu'halo che percorrono la via del Circolo Cenariano, riportare il pendente a Turak Totem Runico onora sia gli antenati che gli insegnamenti di Radaluna."},sec={{t="Un Simbolo degli Abissi",b="Per reclamare l'aspetto acquatico del leone marino, un druido deve dimostrare la padronanza sui più grandi pericoli dell'acqua. Il pendente viene creato recuperando due metà distinte: una incarna l'agilità necessaria per sfuggire ai predatori acquatici, e l'altra conferisce la resistenza richiesta per sopportare un'immersione prolungata. Portati davanti al Santuario di Remulos a Radaluna, i due pezzi vengono uniti in un unico insieme."},{t="Prova di Maestria",b="Una volta forgiato, il pendente completato viene portato davanti ai mentori anziani, come Turak Totem Runico sulle imponenti alture di Picco del Tuono o Mathrengyl Domaorsi a Darnassus. Il talismano fornisce una prova innegabile delle prove dell'iniziato sotto Dendrite Ardistella, consentendo agli anziani di conferire i segreti della trasformazione in un'Aquatic Form."}},faq={{q="Qual è lo scopo del Pendente del Leone Marino?",a="Serve come prova che un iniziato druido ha completato le prove di agilità e resistenza acquatica, dimostrando di essere pronto a imparare la propria forma di mutamento acquatico.",al={"a cosa serve il pendente del leone marino","uso del pendente del leone marino","perché ottenere il pendente del leone marino"}},{q="Dove viene assemblato il pendente?",a="Le due metà, che rappresentano l'agilità e la resistenza, devono essere unite presso il Santuario di Remulos situato all'interno del sacro rifugio di Radaluna.",al={"come creare il pendente del leone marino","dove unire le metà del pendente"}},{q="A chi presento il pendente a Picco del Tuono?",a="I druidi tauren presentano il pendente completato a Turak Totem Runico sull'Altura degli Anziani a Picco del Tuono per completare il loro addestramento.",al={"chi prende il pendente a picco del tuono","pendente turak totem runico","consegna aquatic form orda"}},{q="Anche gli elfi della notte possono ottenere questo pendente?",a="Sì. I druidi elfi della notte affrontano la stessa prova a Radaluna, portando invece il loro pendente assemblato a Mathrengyl Domaorsi a Darnassus.",al={"pendente del leone marino alleanza","pendente del leone marino darnassus"}}},fx={["203d1c94"]={q="Cos'è il Pendente del Leone Marino?",a="Il Pendente del Leone Marino è un sacro talismano druidico che simboleggia la maestria sull'acqua. Incarna l'agilità necessaria per eludere i pericolosi predatori acquatici insieme alla profonda resistenza necessaria per rimanere immersi senza riemergere. I druidi portano questa reliquia unita come prova tangibile che comprendono l'equilibrio selvaggio della natura prima di adottare un aspetto acquatico.",al={"cos'è il pendente del leone marino","informazioni sul pendente del leone marino","lore del pendente del leone marino"}},ad633d46={q="Da dove proviene il Pendente del Leone Marino e chi l'ha creato?",a="Il talismano è forgiato dai giovani druidi che affrontano la Trial of the Sea Lion. Viene creato recuperando due pezzi separati, il Mezzo Pendente dell'Agilità Acquatica e il Mezzo Pendente della Resistenza Acquatica, dai luoghi della prova e riunendoli davanti al Santuario di Remulos a Radaluna, unendo gli aspetti in un unico sacro emblema.",al={"chi ha creato il pendente del leone marino","origine del pendente del leone marino","come viene creato il pendente del leone marino"}},["384283bf"]={q="Perché qualcuno vuole il Pendente del Leone Marino?",a="I mentori druidici richiedono di vedere il pendente completato come prova innegabile del tuo addestramento. A Picco del Tuono, Turak Totem Runico richiede il medaglione per verificare che tu abbia superato le prove di Radaluna prima di impartirti i segreti dell'Aquatic Form. Anche Dendrite Ardistella a Radaluna ispeziona la reliquia unita per confermare il completamento della prova.",al={"perché volere il pendente del leone marino","chi vuole il pendente del leone marino","perché mostrare il pendente del leone marino"}}},fp="23,237,19.408.0,16.338.0,51.166.0,31.148.0,49.125.0,39.138.0"}
P.entries["item:perenolde-tiara"] = {n="Diadema di Perenolde",s="Il Diadema di Perenolde è un cimelio tempestato di smeraldi della decaduta casa reale di Alterac, originariamente forgiato da artigiani nani di Forgiardente. Andato perduto durante la distruzione del regno, finì infine nelle avide mani di un ogre che vagava tra le rovine prima di attirare l'interesse dei collezionisti di Roccavento.",h="Il Diadema di Perenolde è un cimelio tempestato di smeraldi della decaduta casa reale di Alterac...",kw={"alterac","smeraldi","grel'borg","forgiardente","avaro","perenolde","remington","crestafonda","diadema"},ang={["faction:Alliance"]="Il manufatto è un amaro promemoria della Casa dei Perenolde, il cui tradimento durante la Seconda Guerra distrusse quasi l'originaria Alleanza di Lordaeron.",["race:Dwarf"]="Il diadema funge da testimonianza della rinomata arte delle gemme di Forgiardente, i cui maestri gioiellieri tagliarono e incastonarono gli smeraldi per i reali umani del nord."},sec={{t="Una reliquia di un regno in rovina",b="Prima che il regno montuoso di Alterac crollasse nell'infamia e tra le macerie durante la Seconda Guerra, la sua casata regnante era la famiglia Perenolde. Tra i loro tesori c'era questo delicato diadema, commissionato ai maestri gioiellieri di Forgiardente e incastonato con brillanti smeraldi. Quando Alterac andò in rovina a seguito del tradimento di re Aiden Perenolde, il gioiello della corona svanì nella caotica devastazione delle alte rupi."},{t="Il bottino dell'avaro",b="Piuttosto che rimanere sepolto per sempre sotto la neve, il diadema fu dissotterrato da Grel'borg the Miser, un ogre mago che rovista tra le Rovine d'Alterac alla ricerca di ricchezze abbandonate. La notizia della reliquia sopravvissuta raggiunse il Conte Remington Crestafonda, un ricco nobile di Roccavento desideroso di acquisire celebri reliquie per il museo della sua famiglia, dando il via a una ricerca per strappare il diadema dalle mani avide dell'ogre."}},faq={{q="Cos'è il Diadema di Perenolde?",a="È un cimelio appartenuto un tempo alla famiglia reale Perenolde di Alterac. Fu forgiato da maestri gioiellieri nani di Forgiardente e adornato con pregiati smeraldi prima di andare perduto durante la caduta di Alterac.",al={"storia del diadema di perenolde","cos'è questo diadema","diadema di alterac"}},{q="Chi possiede il diadema adesso?",a="Un ogre mago noto come Grel'borg the Miser ha scoperto il diadema tra le innevate Rovine d'Alterac. Lo custodisce gelosamente mentre perlustra il regno in rovina alla ricerca di altri tesori perduti.",al={"dove si trova il diadema","chi rilascia il diadema","diadema di grelborg"}},{q="Perché il Conte Remington Crestafonda lo vuole?",a="Il Conte Remington Crestafonda colleziona antichità storiche e prestigiose per il museo della sua famiglia a Roccavento. Recuperare un autentico gioiello della corona da un regno umano caduto offre un pezzo centrale straordinario per la sua collezione.",al={"chi vuole il diadema","perché remington lo vuole","movente di remington crestafonda"}},{q="Chi erano i Perenolde?",a="I Perenolde erano la dinastia regnante del regno di Alterac. Durante la Seconda Guerra, re Aiden Perenolde tradì l'Alleanza a favore dell'Orda degli Orchi, portando al crollo e alla rovina del suo regno sovrano.",al={"famiglia perenolde","casata dei perenolde","governanti di alterac"}}},fx={da959daa={q="Da dove proviene il Diadema di Perenolde e chi l'ha creato?",a="Il diadema proviene dal distrutto regno settentrionale di Alterac, dove fungeva da prezioso cimelio di famiglia per la stirpe reale di Perenolde. Invece di essere forgiato da artigiani umani, si dice che sia stato realizzato da maestri gioiellieri nanici a Forgiardente, che hanno incastonato il pezzo ornato con i migliori smeraldi.",al={"chi ha creato il diadema di perenolde","origine del diadema di perenolde","dove è stato creato il diadema"}}},fp="15,311,27.406.0,17.401.0,28.211.0,28.183.0,43.223.0,24.209.0"}
P.entries["item:phial-of-scrying"] = {n="Fiala della Chiaroveggenza",s="La Fiala della Chiaroveggenza è un recipiente incantato fornito dall'antico della sapienza Onu a Darkshore. Quando viene usata, manifesta un bacile di chiaroveggenza che consente la comunione a distanza attraverso i boschi corrotti.",h="La Fiala della Chiaroveggenza è un recipiente incantato fornito dall'antico della sapienza Onu a Darkshore.",kw={"darkshore","gladio del maestro","onu","fiala della chiaroveggenza","bacile di chiaroveggenza","martello del crepuscolo"},ang={["class:Druid"]="I druidi riconoscono i bacili di chiaroveggenza come un'armoniosa fusione di acqua naturale e magia di comunione, permettendo ai custodi della foresta di scambiarsi sussurri attraverso il suolo corrotto.",["race:NightElf"]="Per gli elfi della notte di Darkshore, antichi strumenti di divinazione come le acque di chiaroveggenza sono vitali per mantenere la vigilanza sui boschi sacri invasi da sette aliene."},sec={{t="Una Lente Attraverso Darkshore",b="Affidata agli esploratori che indagano nelle profondità di Darkshore, la Fiala della Chiaroveggenza contiene acque mistiche che evocano un temporaneo bacile di chiaroveggenza sul terreno. Questo strumento permette la divinazione a lunga distanza, consentendo ai viaggiatori che si avventurano in zone pericolose come il Gladio del Maestro di comunicare direttamente con Onu senza dover tornare immediatamente al suo boschetto."},{t="Svelare la Setta",b="Onu fornisce la fiala nello specifico per monitorare l'inquietante presenza dei cultisti del Martello del Crepuscolo. Stabilendo un legame di chiaroveggenza presso il luogo dell'antico maestro caduto, trafitto da un'enorme spada, l'esploratore conferma che oscuri cultisti si stanno radunando attivamente attorno agli antichi resti, alla ricerca di frammenti di potere dimenticato che persistono persino nella morte."}},faq={{q="Cosa fa la Fiala della Chiaroveggenza?",a="Quando viene stappata, la fiala manifesta un magico bacile di chiaroveggenza sul terreno, consentendo a un avventuriero sul campo di contattare e parlare con l'antico della sapienza Onu attraverso vaste distanze.",al={"usare la fiala della chiaroveggenza","funzione del bacile di chiaroveggenza","a cosa serve questa fiala"}},{q="Chi fornisce la Fiala della Chiaroveggenza?",a="L'antico treant Onu affida la fiala agli esploratori a Darkshore quando affida loro il compito di perlustrare il Gladio del Maestro a sud.",al={"chi dà la fiala della chiaroveggenza","dove ottengo la fiala"}},{q="Cosa succede se la fiala viene persa o esaurita?",a="Se la fiala viene persa o utilizzata prima di completare la tua missione, Onu può fornirne un'altra mentre sta meditando a Darkshore.",al={"fiala della chiaroveggenza persa","ottenere un'altra fiala","sostituire la fiala"}},{q="Perché Onu scruta verso il Gladio del Maestro?",a="Onu sa che il Gladio del Maestro è il luogo in cui cadde un antico signore e ti chiede di cercarvi i cultisti del Martello del Crepuscolo. Il loro scopo viene svelato man mano che l'indagine continua.",al={"perché scrutare gladio del maestro","missione di onu gladio"}}},fx={["92e56a99"]={q="Cos'è la Fiala della Chiaroveggenza?",a="La Fiala della Chiaroveggenza è un contenitore incantato contenente acque mistiche fornite dall'antico del sapere, Onu. Quando viene versata sul campo, crea una Coppa della Chiaroveggenza temporanea che funge da condotto magico, permettendoti di stabilire un legame spirituale diretto con l'antico attraverso vaste distanze.",al={"cos'è la fiala della chiaroveggenza","lore della fiala della chiaroveggenza","fiala della chiaroveggenza spiegata"}},["16c85a4e"]={q="Perché Onu vuole che tu usi la Fiala della Chiaroveggenza?",a="Onu ti chiede di perlustrare il Gladio del Maestro alla ricerca dei cultisti del Martello del Crepuscolo. La fiala ti permette di creare una coppa della chiaroveggenza e parlare con lui dopo aver perlustrato il sito, senza dover prima tornare al suo boschetto.",al={"perché usare la fiala della chiaroveggenza","perché onu vuole la fiala","perché serve la fiala della chiaroveggenza"}}},fp="16,194,23.356.0,19.359.1,34.181.0,34.136.0,47.121.0,44.174.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Pezzo dello Stendardo di Krom'zar",s="Una striscia di stoffa strappata presa dagli stendardi del Signore della Guerra Krom'zar, comandante della forza di rappresaglia dei Kolkar. Serve come prova tangibile per Regthar Deathgate che l'invasione dei centauri da Desolanda è stata spezzata.",h="Una striscia di stoffa strappata presa dagli stendardi del Signore della Guerra Krom'zar, comandante della...",kw={"stendardo","centauro","contrattacco","crocevia","deathgate","kolkar","krom'zar","regthar"},ang={["faction:Horde"]="Sconfiggere Krom'zar e rivendicare i suoi colori ferma un'importante offensiva dei centauri, mettendo in sicurezza i corridoi settentrionali tra Durotar, Mulgore e Crocevia.",["race:Tauren"]="L'aggressività dei centauri ha afflitto a lungo le tribù nomadi, rendendo la distruzione dell'avanguardia di Krom'zar un gradito segnale di sicurezza per i sentieri che conducono a Mulgore."},sec={{t="Trofeo dell'Incursione dei Centauri",b="In seguito alla sistematica sconfitta dei capitribù Kolkar attraverso The Barrens, una furiosa banda da guerra marciò verso est da Desolanda in cerca di vendetta. Guidati dal Signore della Guerra Krom'zar, questi invasori assaltarono i bunker difensivi a ovest di Crocevia. Tagliare un lembo dal caduto stendardo da battaglia del signore della guerra fornisce a Regthar Deathgate la prova innegabile che l'assalto è stato respinto e che le rotte commerciali meridionali sono state preservate per l'Orda."}},faq={{q="A cosa serve questo pezzo di stendardo?",a="La stoffa strappata viene portata a Regthar Deathgate presso il suo bunker a ovest di Crocevia. Dimostra che il Signore della Guerra Krom'zar è stato ucciso e la sua forza d'assalto sbaragliata, concludendo la difesa delle The Barrens settentrionali.",al={"scopo dello stendardo","perché tenere lo stendardo","cosa fare con il pezzo di stendardo"}},{q="Chi era il Signore della Guerra Krom'zar?",a="Krom'zar era un feroce comandante Kolkar inviato dalle distese di Desolanda. Guidò un contrattacco diretto contro gli avamposti dell'Orda in risposta alla morte dei capi Kolkar locali.",al={"chi è kromzar","storia di krom'zar","signore della guerra krom'zar"}},{q="Perché i Kolkar hanno attaccato il bunker?",a="Dopo che i campioni dell'Orda ebbero eliminato i capitribù locali di The Barrens — inclusi Barak, Verog e Hezrul — gli infuriati centauri radunarono rinforzi da Desolanda per esigere vendetta sulla Horde Presence a ovest di Crocevia.",al={"perché il contrattacco","perché invasione kolkar","motivo contrattacco the barrens"}},{q="Thrall viene a conoscenza di questa vittoria?",a="Sì. Dopo aver ricevuto il frammento dello stendardo, Regthar Deathgate promette di inviare formale comunicazione direttamente al Gran Capo Thrall a Orgrimmar, elogiando i difensori che hanno fermato l'invasione.",al={"ricompensa di thrall","thrall lo sa"}}},fx={["92115071"]={q="Cos'è il Pezzo dello Stendardo di Krom'zar?",a="È un brandello strappato recuperato dallo stendardo da battaglia del Signore della Guerra Krom'zar, comandante dell'esercito di centauri Kolkar in cerca di vendetta che ha marciato da Desolanda verso The Barrens. Per le forze dell'Orda a difesa dei bunker occidentali, funge da innegabile prova fisica che il signore della guerra è caduto in battaglia e la sua invasione è stata spezzata.",al={"cos'è il pezzo dello stendardo di krom'zar","pezzo dello stendardo di krom'zar","cos'è il frammento di stendardo"}},caa193f6={q="Da dove proviene il Pezzo dello Stendardo di Krom'zar?",a="Lo stendardo è stato portato a The Barrens dal Signore della Guerra Krom'zar e dalla sua orda Kolkar, che hanno viaggiato fino dalla loro patria a Desolanda per vendicarsi sull'Orda. Quando Krom'zar scende in campo fuori dai bunker occidentali e cade in combattimento, il suo stendardo viene lasciato sul campo di battaglia, dove questo frammento può essere strappato via.",al={"da dove proviene lo stendardo di krom'zar","chi ha creato lo stendardo di krom'zar","origine dello stendardo di krom'zar"}},["7a980ed6"]={q="Perché Regthar Deathgate vuole un Pezzo dello Stendardo di Krom'zar?",a="Regthar Deathgate ha bisogno di una prova concreta che l'invasore esercito Kolkar sia stato decisamente schiacciato. Presentare questo stendardo strappato conferma che il Signore della Guerra Krom'zar è stato ucciso davanti ai bunker dell'Orda, permettendo a Regthar di dichiarare ufficialmente finita l'invasione e inviare notizia del tuo valore direttamente al Capoguerra Thrall.",al={"perché regthar vuole lo stendardo","perché portare lo stendardo di krom'zar a regthar","perché serve lo stendardo di krom'zar"}}},fp="26,216,31.423.0,35.207.0,25.182.0,37.222.0,33.178.0"}
P.entries["item:plainstrider-beak"] = {n="Becco di Zampalunga delle Pianure",s="I Becchi di Zampalunga delle Pianure vengono ricavati dagli alti uccelli incapaci di volare che popolano le boscaglie di The Barrens. I maestri di caccia a Crocevia raccolgono questi becchi come prova tangibile che un cacciatore ha abbattuto gli uccelli locali che minacciano le scorte dell'insediamento.",h="I Becchi di Zampalunga delle Pianure vengono ricavati dagli alti uccelli incapaci di volare che popolano le...",kw={"the barrens","crocevia","becco di zampalunga delle pianure","minaccia dei plainstrider","sergra darkthorn","tallstrider"},ang={["class:Hunter"]="Abbattere gli zampalunga e ricavarne i becchi offre ai tracciatori alle prime armi una lezione introduttiva su come seguire le tracce e abbattere le prede attraverso le pianure aperte di Kalimdor.",["faction:Horde"]="Abbattere gli stormi fastidiosi a est di Crocevia protegge direttamente le fragili rotte commerciali e di rifornimento che mantengono rifornito l'avamposto dell'Orda."},sec={{t="Una misura della caccia",b="Le vaste savane che circondano Crocevia sono popolate da varie razze di zampalunga, incluse le varietà maggiore, fugace e irascibile. Sebbene siano prede relativamente semplici rispetto alle bestie più feroci di Kalimdor centrale, il loro aggressivo foraggiamento le rende una costante piaga nei pressi degli insediamenti. Sergra Darkthorn incarica i cacciatori che arrivano di riportare Becchi di Zampalunga delle Pianure per confermare che lo stormo sia stato allontanato e decimato lontano da magazzini e linee di rifornimento essenziali."}},faq={{q="Perché Sergra Darkthorn vuole i Becchi di Zampalunga delle Pianure?",a="Sergra Darkthorn chiede ai cacciatori di abbattere gli zampalunga perché questi uccelli aggressivi insidiano regolarmente le scorte di cibo attorno a Crocevia. I becchi servono come prova tangibile di una caccia riuscita, a conferma che la minaccia alle linee di rifornimento locali è stata ridotta.",al={"perché raccogliere becchi","sergra missione becco di zampalunga delle pianure","perché becchi"}},{q="Quali creature forniscono questi becchi?",a="Vengono ricavati dalle varie specie di tallstrider che popolano la savana, inclusi gli zampalunga maggiori, gli zampalunga fugaci e gli zampalunga irascibili in The Barrens.",al={"cosa rilascia becco di zampalunga delle pianure","fonti becco di zampalunga delle pianure","dove trovare becchi"}},{q="Perché non tutti gli zampalunga forniscono un becco quando vengono uccisi?",a="Nel caos del combattimento, specialmente contro uccelli veloci e che si agitano violentemente, un becco viene spesso spaccato, frantumato o reso inutilizzabile come trofeo di caccia integro, il che significa che si raccolgono solo esemplari intatti.",al={"perché percentuale di rilascio bassa","becco di zampalunga delle pianure non viene rilasciato"}}},fx={["7e2762f5"]={q="Cos'è il Becco di Zampalunga delle Pianure?",a="Un Becco di Zampalunga delle Pianure è il becco reciso preso dai volatili incapaci di volare che vagano per la savana di The Barrens. Duri e appuntiti, questi becchi vengono raccolti dai cacciatori come prova tangibile che gli uccelli fastidiosi che minacciavano le scorte locali sono stati abbattuti.",al={"oggetto becco di zampalunga delle pianure","cos'è il becco di zampalunga delle pianure","becchi di zampalunga delle pianure"}},["6978f6b2"]={q="Da dove proviene il Becco di Zampalunga delle Pianure?",a="Questi becchi provengono direttamente dalle varie razze di zampalunghe, come gli zampalunghe maggiori, fuggitivi e irascibili, nativi di The Barrens. Vengono raccolti dai cacciatori attraverso le pianure aride come trofei e prova di un abbattimento riuscito.",al={"dove ottenere il becco di zampalunga delle pianure","chi lascia il becco di zampalunga delle pianure","fonte del becco di zampalunga delle pianure"}}},fp="17,249,21.464.0,50.264.0,34.174.0,54.199.0"}
P.entries["item:plainstrider-feather"] = {n="Piuma di Zampalunga delle Pianure",s="Strappate ai rapidi uccelli che vagano per le pianure di Mulgore, le Piume di Zampalunga delle Pianure sono materiali essenziali raccolti dai giovani cacciatori su Mesa Nuvola Rossa. I tauren di Campo Narache le utilizzano principalmente per confezionare abiti e ornamenti tribali, onorando al tempo stesso le creature che provvedono al villaggio.",h="Strappate ai rapidi uccelli che vagano per le pianure di Mulgore, le Piume di Zampalunga delle Pianure sono...",kw={"campo narache","piuma","grull vento agile","mulgore","zampalunga","mesa nuvola rossa","the hunt begins"},ang={["class:Hunter"]="Braccare i rapidi zampalunga attraverso Mesa Nuvola Rossa costituisce la prova fondamentale di un iniziato in fatto di pazienza, tracciamento e rispetto per la preda.",["race:Tauren"]="Per un giovane tauren, raccogliere le piume da uno zampalunga è una prima lezione essenziale per non dare per scontate le creature della Madre Terra, utilizzando ogni parte della preda per il cibo e il vestiario."},sec={{t="La prima offerta di un cacciatore",b="Su Mesa Nuvola Rossa, i giovani tauren imparano presto che la sopravvivenza dipende da abilità affinate di tracciamento e caccia. Gli zampalunga corrono liberi attraverso l'altopiano erboso, offrendo sia sostentamento che materiali utili. Strappare le loro robuste piume consente all'accampamento di creare indumenti ed equipaggiamento tradizionali. Presentare queste piume insieme a carne fresca a Grull Vento Agile dimostra rispetto per i bisogni della tribù e funge da primissima prova per essere riconosciuti dal Capo Vento Agile e accolti a Picco del Tuono."}},faq={{q="A cosa servono le Piume di Zampalunga delle Pianure?",a="I tauren di Campo Narache le usano principalmente per confezionare abiti e oggetti cerimoniali. Grull Vento Agile le raccoglie dai novizi cacciatori per rifornire le scorte tribali.",al={"scopo delle piume","uso piuma di zampalunga delle pianure","perché raccogliere piume"}},{q="Chi raccoglie le Piume di Zampalunga delle Pianure su Mesa Nuvola Rossa?",a="Grull Vento Agile le richiede per conto di Campo Narache per ricostituire le provviste del villaggio e per verificare se i giovani cacciatori posseggano la disciplina necessaria per provvedere alla tribù.",al={"chi vuole le piume","chi ha bisogno di piume","piume grull vento agile"}},{q="Dove si possono trovare gli zampalunga?",a="Si aggirano per i pascoli aperti attraverso Mesa Nuvola Rossa e lungo tutta la Piana Ondulata di Mulgore.",al={"dove trovare gli zampalunga","posizione zampalunga","raccolta piume"}},{q="Perché Grull Vento Agile richiede queste piume per i riti tribali?",a="La caccia è un pilastro fondamentale della cultura dei tauren, intrapresa sia per la sopravvivenza che per lo sport. Fare ritorno con carne e piumaggio dimostra al Capo Vento Agile che un iniziato è in grado di sostenere la tribù prima di avventurarsi verso Picco del Tuono.",al={"the hunt begins storia","caccia di prova tauren","perché cacciare gli zampalunga"}}},fx={f2ff74a3={q="Cos'è una Piuma di Zampalunga delle Pianure?",a="Una Piuma di Zampalunga delle Pianure è un piumaggio raccolto dai grandi uccelli non volatori che vagano per le praterie di Mulgore. I tauren della Mesa Nuvola Rossa utilizzano ogni risorsa offerta dalla terra con profondo rispetto, e queste penne robuste e colorate servono come materiali pratici per fabbricare capi di vestiario quotidiani così come ornamenti tradizionali.",al={"cos'è la piuma di zampalunga delle pianure","informazioni sulla piuma di zampalunga delle pianure","piume di zampalunga delle pianure"}},["8bb68bd8"]={q="Da dove provengono le Piume di Zampalunga delle Pianure?",a="Queste piume sono piumaggio cresciuto naturalmente, raccolto direttamente dai zampalunga selvatici che vagano per la Mesa Nuvola Rossa e le vaste pianure di Mulgore. Non sono fabbricate da mani mortali, ma raccolte dai cacciatori dopo una battuta di caccia riuscita nella prateria.",al={"fonte piuma di zampalunga delle pianure","dove trovare piume di zampalunga delle pianure","chi ha creato la piuma di zampalunga delle pianure"}}},fp="20,300,25.496.0,40.164.0,52.172.0,33.97.0,64.234.0"}
P.entries["item:plainstrider-kidney"] = {n="Fegato di Zampalunga delle Pianure",s="Un organo raccolto dai veloci zampalunga che vagano per le aride pianure delle Barrens. Sebbene poco appetibile per la maggior parte dei viaggiatori, funge da bizzarro ma essenziale componente nelle esotiche tradizioni di birrificazione di Kalimdor.",h="Un organo raccolto dai veloci zampalunga che vagano per le aride pianure delle Barrens.",kw={"mastro birraio drohn","chen stormstout","plainstrider","fegato di zampalunga delle pianure","porto paranco","stormstout","the barrens"},ang={["class:Hunter"]="La macellazione sul campo degli zampalunga attraverso la savana mette alla prova la precisione di un cacciatore, assicurando che gli organi interni rimangano intatti per il commercio con i mastri birrai di Porto Paranco.",["profession:Cooking"]="Gli avventurieri della gastronomia potrebbero esitare a fermentare fegati aviari in liquori raffinati, eppure la sopravvivenza nella natura selvaggia di Kalimdor fa spesso affidamento sullo sfruttamento completo di ogni parte della preda."},sec={{t="Un insolito ingrediente di birrificazione",b="Le vaste distese delle Barrens sono popolate da alti uccelli incapaci di volare noti come plainstrider. Mentre le loro piume e la loro carne vengono spesso raccolte dai cacciatori per ricavarne strumenti e semplici razioni, il Mastro Birraio Drohn a Porto Paranco cerca i loro organi interni per uno scopo completamente diverso. Secondo l'eccentrico birraio, i fegati di zampalunga delle pianure sono un ingrediente necessario per replicare la birra leggendariamente potente di Chen Stormstout, donando un tocco unico tramandato attraverso un'insolita stirpe di mastri birrai."}},faq={{q="A cosa serve un Fegato di Zampalunga delle Pianure?",a="Il Mastro Birraio Drohn a Porto Paranco li richiede per ricreare una leggendaria cotta di birra Stormstout. Sostiene che la ricetta sia stata insegnata al suo mentore direttamente dal Mastro Birraio pandaren errante, Chen Stormstout.",al={"uso fegato di zampalunga delle pianure","perché servono i fegati di zampalunga delle pianure","scopo fegato di zampalunga delle pianure"}},{q="Perché qualcuno dovrebbe produrre birra con organi animali?",a="Le birre esotiche di Kalimdor incorporano spesso parti della fauna locale per ottenere sapori forti e memorabili e una sferzata distintiva. Il Mastro Birraio Drohn fa notare che la creazione di ricette così potenti e selvagge gli ricorda con affetto creazioni eterodosse come la birra di trogg.",al={"rene nella birra","perché il fegato nella birra di stormstout","parti di animali nell'alcol"}},{q="Quali creature rilasciano questi fegati?",a="Vengono raccolti dalle varie specie di plainstrider che corrono attraverso le Barrens, inclusi i fleeting, gli ornery e i greater plainstrider.",al={"dove si trova il fegato di zampalunga delle pianure","chi rilascia il fegato di zampalunga delle pianure","fonte fegato di zampalunga delle pianure"}},{q="Quali altri ingredienti sono necessari oltre ai fegati?",a="Per completare il suo intruglio, il Mastro Birraio Drohn richiede cinque fegati di zampalunga delle pianure, cinque savannah lion tusks e un singolo corno di sauro del tuono.",al={"altri ingredienti della birra","cos'altro serve a drohn","ingredienti stormstout"}}},fx={d14d143c={q="Cos'è un Fegato di Zampalunga delle Pianure?",a="È un organo interno estratto dai grandi zampalunga non volatori che vagano per le savane delle The Barrens. Mentre la maggior parte dei cacciatori scarta tali interiora o le lascia agli spazzini, alcuni birrai eccentrici le apprezzano come aggiunte potenti e non convenzionali a liquori esotici.",al={"cos'è il fegato di zampalunga delle pianure","informazioni sul fegato di zampalunga delle pianure","parlami del fegato di zampalunga delle pianure"}},["4fd58422"]={q="Da dove proviene un Fegato di Zampalunga delle Pianure?",a="Questi organi vengono estratti direttamente dai zampalunga selvatici nativi delle The Barrens, incluse le varietà più grandi, scontrose e fugaci. Sono parti naturali dell'anatomia degli uccelli piuttosto che beni manifatturieri, sebbene procurarsene uno richieda di cacciare le veloci e aggressive bestie aviarie attraverso le pianure.",al={"fonte fegato di zampalunga delle pianure","dove trovare fegato di zampalunga delle pianure","origine fegato di zampalunga delle pianure"}},["53f4067b"]={q="Perché il Mastro Birraio Drohn vuole i Fegati di Zampalunga delle Pianure?",a="Il Mastro Birraio Drohn a Porto Paranco cerca questi fegati per ricreare la leggendaria e potente birra omonima di Chen Stormstout. Chen ha tramandato la ricetta non convenzionale al mentore di Drohn, e Drohn ha bisogno dei fegati insieme a zanne di leone e a un Corno di Sauro del Tuono per produrre la birra con il suo caratteristico, feroce vigore.",al={"perché sono necessari i fegati di zampalunga delle pianure","chi vuole i fegati di zampalunga delle pianure","scopo fegato di zampalunga delle pianure drohn"}}},fp="19,224,32.498.0,39.200.0,46.250.0,36.143.0,56.140.0"}
P.entries["item:plainstrider-meat"] = {n="Carne di Zampalunga delle Pianure",s="La Carne di Zampalunga delle Pianure è selvaggina appena raccolta ricavata dagli uccelli non volatori che vagano per le pianure di Mulgore. Per i giovani tauren che raggiungono la maggiore età su Mesa Nuvola Rossa, raccogliere questo sostentamento funge sia da scorta vitale per l'inverno sia da fondamentale rito di passaggio.",h="La Carne di Zampalunga delle Pianure è selvaggina appena raccolta ricavata dagli uccelli non volatori che...",kw={"campo narache","capo vento agile","grull vento agile","mulgore","zampalunga","carne di zampalunga delle pianure","mesa nuvola rossa","the hunt begins"},ang={["class:Hunter"]="Il rapido zampalunga offre ai novelli cacciatori una prima prova delle loro doti di tracciamento e mira attraverso le aperte pianure di Mulgore.",["race:Tauren"]="Per i giovani tauren che muovono i primi passi su Mesa Nuvola Rossa, cacciare gli zampalunga è il primo passo concreto per conquistare il rispetto di Capo Vento Agile e guadagnarsi il diritto di accedere a Picco del Tuono."},sec={{t="Sostentamento per la Mesa",b="La vita dei tauren è indissolubilmente legata alla terra, in equilibrio tra il rispetto per la natura e la necessità pratica della sopravvivenza. Su Mesa Nuvola Rossa, l'insediamento di Campo Narache dipende fortemente dalla selvaggina cacciata nelle praterie circostanti. La Carne di Zampalunga delle Pianure fornisce riserve di cibo essenziali per il villaggio quando le scorte scarseggiano, mentre il piumaggio degli uccelli offre materiale per vestiti e ornamenti cerimoniali."},{t="La prova di un giovane cacciatore",b="Cacciare gli zampalunga è una delle prime prove assegnate ai giovani che cercano di guadagnarsi il rispetto della tribù. Grull Vento Agile guida gli aspiranti cacciatori a inseguire i rapidi volatili attraverso la mesa, raccogliendo carne e piume per dimostrare le proprie capacità di tracciamento e autosufficienza prima di presentarsi al cospetto di suo padre, Capo Vento Agile."}},faq={{q="A cosa serve la Carne di Zampalunga delle Pianure?",a="La Carne di Zampalunga delle Pianure viene raccolta dai giovani cacciatori su Mesa Nuvola Rossa per rifornire le provviste di cibo impoverite di Campo Narache, compiendo un compito essenziale per Grull Vento Agile.",al={"perché la carne di zampalunga delle pianure","missione carne di zampalunga delle pianure","cosa fare con la carne di zampalunga delle pianure"}},{q="Chi richiede questa carne?",a="Grull Vento Agile, figlio di Capo Vento Agile, chiede agli iniziati di cacciare gli zampalunga della mesa per rimpinguare le scorte alimentari della tribù e dimostrare il loro valore come procacciatori.",al={"chi vuole la carne di zampalunga delle pianure","grull vento agile carne"}},{q="Dove si può trovare la Carne di Zampalunga delle Pianure?",a="Si ricava dagli zampalunga inabili al volo che vagano per le praterie di Mulgore, in particolare attraverso le dolci colline di Mesa Nuvola Rossa.",al={"dove trovare la carne di zampalunga delle pianure","posizioni zampalunga","farmare carne di zampalunga delle pianure"}},{q="Perché la caccia agli zampalunga è considerata importante per i tauren?",a="I tauren cacciano sia per necessità pratica che come disciplina spirituale. Riportare la selvaggina all'accampamento dimostra rispetto per la Madre Terra, autosufficienza e la capacità di sostenere la tribù.",al={"cultura della caccia dei tauren","perché cacciare gli zampalunga"}}},fx={f404715e={q="Cos'è la Carne di Zampalunga delle Pianure?",a="La Carne di Zampalunga delle Pianure è selvaggina fresca ricavata dagli uccelli non volatori che vagano per le pianure di Mulgore. Per i tauren della Mesa Nuvola Rossa, funge da alimento base vitale, raccolto tramite le tradizionali battute di caccia che sostengono l'insediamento e onorano il legame tra cacciatore e preda.",al={"informazioni sulla carne di zampalunga delle pianure","cos'è la carne di zampalunga delle pianure","lore carne di zampalunga delle pianure"}},["00c8b7f8"]={q="Da dove proviene la Carne di Zampalunga delle Pianure?",a="La Carne di Zampalunga delle Pianure proviene dai zampalunga selvatici nativi di Mulgore. I giovani cacciatori la raccolgono direttamente dalle bestie che vagano per la Mesa Nuvola Rossa durante i loro primi riti di caccia per la tribù.",al={"da dove proviene la carne di zampalunga delle pianure","origine carne di zampalunga delle pianure","come ottenere carne di zampalunga delle pianure"}},f1043112={q="Perché la Carne di Zampalunga delle Pianure è richiesta a Campo Narache?",a="Le scorte di cibo di Campo Narache sono diminuite e la tribù conta su un'abile caccia per rifornire le proprie provviste. Grull Vento Agile chiede ai giovani cacciatori di raccogliere Carne di Zampalunga delle Pianure per sfamare il villaggio e dimostrare la loro abilità al Capo Vento Agile.",al={"perché serve carne di zampalunga delle pianure","scopo carne di zampalunga delle pianure","perché raccogliere carne di zampalunga delle pianure"}}},fp="17,257,23.401.0,22.311.0,35.162.0,23.166.0,37.138.0,64.202.0"}
P.entries["item:plainstrider-scale"] = {n="Scaglia di Zampalunga delle Pianure",s="Una resistente scaglia ricavata dai tallstrider che vagano per le sconfinate pianure di Mulgore. Funge da componente vitale in un rimedio tradizionale preparato da Maur Invoca Pioggia per contrastare una virulenta infezione.",h="Una resistente scaglia ricavata dai tallstrider che vagano per le sconfinate pianure di Mulgore.",kw={"villaggio di zoccolo sanguinario","maur invoca pioggia","mazzranache","mulgore","zampalunga delle pianure","rimedio","scaglia","tallstrider"},ang={["race:Tauren"]="Raccogliere rimedi dalla terra riflette le tradizionali abilità di sopravvivenza insegnate ai giovani cacciatori a Mulgore, utilizzando ogni parte della fauna delle pianure per sostenere la tribù."},sec={{t="Un ingrediente raro",b="Sebbene gli zampalunga delle pianure siano noti soprattutto per le loro morbide piume e la carne magra, le loro zampe possenti sono ricoperte da scaglie dure e protettive. Queste scaglie sono resistenti all'aspro terreno della boscaglia e agli artigli dei predatori. Trovarne una intatta e adatta all'uso medicinale richiede pazienza, poiché solo alcuni zampalunga delle pianure selezionati in tutta Mulgore forniscono scaglie abbastanza sode da poter essere macinate e preparate per rimedi popolari."},{t="Un rimedio per un morso velenoso",b="Quando Maur Invoca Pioggia al Villaggio di Zoccolo Sanguinario ha incrociato il cammino di Mazzranache, un leggendario zampalunga noto per i suoi demoniaci occhi rossi e il morso velenoso, ha subito una grave ferita alla spalla. Caduto in preda a una febbre delirante, Maur necessita di una Scaglia di Zampalunga delle Pianure insieme a un cuore di lupo, un femore di puma e uno stomaco di avvoltoio per purificare l'infezione che si sta diffondendo prima che risulti fatale."}},faq={{q="A cosa serve la Scaglia di Zampalunga delle Pianure?",a="È un ingrediente medicinale essenziale raccolto per Maur Invoca Pioggia al Villaggio di Zoccolo Sanguinario. Combinato con parti di altri predatori di Mulgore, viene infuso in un rimedio per trattare una ferita infetta e velenosa inflitta dal feroce tallstrider Mazzranache.",al={"a cosa serve la scaglia di zampalunga delle pianure","uso scaglia di zampalunga delle pianure","perché serve la scaglia di zampalunga delle pianure"}},{q="Dove si trova una Scaglia di Zampalunga delle Pianure?",a="Le scaglie si ottengono cacciando i selvaggi zampalunga delle pianure che vagano per le praterie aperte in tutta Mulgore.",al={"dove trovare la scaglia di zampalunga delle pianure","come ottenere la scaglia di zampalunga delle pianure","posizione scaglia di zampalunga delle pianure"}},{q="Perché Maur Invoca Pioggia è infetto?",a="Mentre viaggiava per le pianure, Maur è caduto in un'imboscata ed è stato morso alla spalla da Mazzranache, un terrificante tallstrider famigerato per il suo morso velenoso e gli occhi cremisi. Il morso gli ha lasciato una febbre delirante in continuo peggioramento che il normale riposo non può guarire.",al={"come si è ammalato maur","perché maur è malato","morso di mazzranache"}},{q="Di quali altri ingredienti ha bisogno Maur per il suo rimedio?",a="Oltre alla Scaglia di Zampalunga delle Pianure, Maur necessita di un Cuore di Lupo della Prateria, un Femore di Puma delle Pianure e uno Stomaco dell'Avvoltoio per completare la mistura medicinale.",al={"ingredienti di maur invoca pioggia","cura per mazzranache","oggetti della missione di mazzranache"}}},fx={["95a4c3dd"]={q="Cos'è una Scaglia di Zampalunga delle Pianure?",a="È una scaglia resistente e specializzata raccolta dagli zampalunga che vagano per le praterie spazzate dal vento di Mulgore. Sebbene uccelli e zampalunga siano noti principalmente per il loro piumaggio e i becchi affilati, le loro zampe robuste e i piedi portano scaglie grossolane e indurite capaci di resistere alle pianure impervie. Sciamani ed erboristi apprezzano queste rare e dense scaglie per le loro proprietà protettive quando preparano impiastri e cure specializzate.",al={"cos'è la scaglia di zampalunga delle pianure","scaglia di zampalunga delle pianure","scaglie di zampalunga delle pianure"}},d7ded3c8={q="Da dove proviene una Scaglia di Zampalunga delle Pianure?",a="È una parte animale naturale presa direttamente dai zampalunga selvatici che vagano per Mulgore. Nessuno la fabbrica; i cacciatori la raccolgono dalle zampe degli zampalunga caduti attraverso le pianure, riunendo solo le scaglie più robuste per l'uso in preparazioni medicinali.",al={"fonte scaglia di zampalunga delle pianure","da dove proviene la scaglia di zampalunga delle pianure","chi ha creato la scaglia di zampalunga delle pianure"}}},fp="18,201,17.395.0,28.371.1,40.252.0,39.107.0,32.247.0,53.149.0"}
P.entries["item:plainstrider-talon"] = {n="Artiglio di Zampalunga delle Pianure",s="Un Artiglio di Zampalunga delle Pianure è un affilato artiglio ricavato dai grandi zampalunga delle pianure incapaci di volare, originari di Mulgore. Gli sciamani tauren utilizzano questi artigli insieme ad altri reagenti naturali per creare totem della purificazione sacri quando le sorgenti d'acqua della terra vengono contaminate.",h="Un Artiglio di Zampalunga delle Pianure è un affilato artiglio ricavato dai grandi zampalunga delle pianure...",kw={"villaggio di zoccolo sanguinario","totem della purificazione","mulgore","mull corno tonante","zampalunga delle pianure","artiglio di zampalunga delle pianure","poison water","pozzo degli zoccolo artico"},ang={["class:Shaman"]="L'uso di parti fisiche di bestie come gli artigli per fabbricare totem purificatori esemplifica le pratiche sciamaniche tradizionali dei tauren, attingendo potere direttamente dagli spiriti nativi della terra.",["race:Tauren"]="Onorare il sacrificio della fauna selvatica di Mulgore è fondamentale per la caccia dei tauren, garantendo che ogni bestia abbattuta aiuti a guarire la Madre Terra quando colpisce lo sfruttamento dei goblin."},sec={{t="Legami delle Pianure",b="I grandi zampalunga delle pianure, incapaci di volare, vagano per le distese erbose aperte di Mulgore, affidandosi a zampe potenti e artigli affilati per difendersi dai predatori e scavare nella dura terra della prateria. Per i tauren del Villaggio di Zoccolo Sanguinario, ogni parte di una bestia cacciata racchiude una risonanza spirituale. Quando le speculazioni dei goblin hanno contaminato fonti sacre come il Pozzo degli Zoccolo Artico, lo sciamano Mull Corno Tonante ha richiesto artigli di zampalunga delle pianure assieme a zampe di lupo della prateria. Nella creazione rituale dei tauren, raccogliere reagenti da predatori e cercatori nativi consente di incanalare l'essenza spirituale della terra in totem capaci di purificare i veleni innaturali."}},faq={{q="Quali creature rilasciano un Artiglio di Zampalunga delle Pianure?",a="Gli artigli di zampalunga delle pianure si ottengono dai plainstrider adulti, dagli elder plainstrider e dal famigerato zampalunga Mazzranache attraverso le praterie di Mulgore.",al={"chi rilascia l'artiglio di zampalunga delle pianure","dove trovare gli artigli di zampalunga delle pianure","fonte dell'artiglio di zampalunga delle pianure"}},{q="A cosa servono gli Artigli di Zampalunga delle Pianure?",a="Mull Corno Tonante al Villaggio di Zoccolo Sanguinario richiede artigli di zampalunga delle pianure e zampe di lupo della prateria per creare un Totem della Purificazione, utilizzato per purificare il contaminato Pozzo degli Zoccolo Artico.",al={"uso dell'artiglio di zampalunga delle pianure","perché servono gli artigli","missione artiglio di zampalunga delle pianure"}},{q="Perché Mull Corno Tonante ha bisogno di parti di animali per purificare l'acqua?",a="Lo sciamanesimo tauren si basa sull'armonia con gli spiriti naturali di Mulgore. Legando elementi della fauna locale nel totem rituale, lo sciamano fa appello al potere primordiale della terra stessa per respingere gli inquinanti estranei introdotti dai goblin della S.P.R. & Co.",al={"perché zampe e artigli di animali","artigli per il rituale di purificazione sciamanico"}},{q="Chi ha avvelenato i pozzi d'acqua a Mulgore?",a="I goblin — nello specifico gli agenti della S.P.R. & Co. operanti a Mulgore — e i loro sgherri hanno contaminato i sacri pozzi d'acqua tribali, sconvolgendo l'ambiente locale e minacciando le tribù tauren.",al={"chi ha corrotto i pozzi","chi ha avvelenato l'acqua di mulgore","colpevole di poison water"}}},fx={fdecb439={q="Cos'è un Artiglio di Zampalunga delle Pianure?",a="Un Artiglio di Zampalunga delle Pianure è l'artiglio affilato raccolto dai grandi zampalunga non volatori che vagano per Mulgore. Sebbene usato naturalmente da questi veloci uccelli per la difesa e per foraggiare attraverso le pianure, gli artigli portano anche un legame innato con il mondo naturale. Per i tauren, tali materiali rappresentano la forza della terra e possono essere canalizzati attraverso rituali sciamanici.",al={"cos'è l'artiglio di zampalunga delle pianure","lore artiglio di zampalunga delle pianure","artigli di zampalunga delle pianure"}},["07c33870"]={q="Da dove provengono gli Artigli di Zampalunga delle Pianure?",a="Questi artigli sono presi dai zampalunga maturi che vagano per le pianure aperte di Mulgore, a sud-ovest del Villaggio di Zoccolo Sanguinario. I cacciatori li raccolgono da zampalunga adulti e anziani, o anche da bestie rare come Mazzranache, come offerte della generosità della terra.",al={"fonte artiglio di zampalunga delle pianure","dove trovare artigli di zampalunga delle pianure","origine artiglio di zampalunga delle pianure"}},["826885d3"]={q="Perché Mull Corno Tonante vuole gli Artigli di Zampalunga delle Pianure?",a="Mull Corno Tonante nel Villaggio di Zoccolo Sanguinario ha bisogno di questi artigli per fabbricare un Totem della Purificazione per il Pozzo degli Zoccolo Artico. I goblin e i loro lacchè della S.P.R. & Co. hanno contaminato l'acqua sacra, e Mull deve invocare l'essenza primordiale delle bestie native di Mulgore per contrastare il veleno e ripristinare la purezza del pozzo.",al={"perché mull vuole gli artigli","perché serve l'artiglio di zampalunga delle pianure","scopo artiglio di zampalunga delle pianure"}}},fp="18,249,19.620.0,41.152.0,38.177.0,63.258.0,40.205.0"}
P.entries["item:podrig-s-order"] = {n="Podrig's Order",s="Podrig's Order è una richiesta militare scritta redatta dalla Guardiamorte Podrig a Mausolea. Richiede una nuova fornitura di armi dal mercante di Undercity Gordon Wendham per mantenere adeguatamente armato il presidio dei Forsaken di Selva Pinargento.",h="Podrig's Order è una richiesta militare scritta redatta dalla Guardiamorte Podrig a Mausolea.",kw={"gordon wendham","hadrec","karos razok","podrig","podrig's order","mausolea","selva pinargento"},ang={["profession:Blacksmithing"]="Le armi forgiate sono vitali in prima linea, dove i combattimenti continui prosciugano costantemente le scorte del presidio.",["race:Undead"]="La richiesta sottolinea il collegamento logistico vitale tra Undercity e gli avamposti esterni come Mausolea, assicurando che i soldati della Dama Oscura rimangano adeguatamente armati contro il Flagello."},sec={{t="Armare Mausolea",b="Selva Pinargento è una frontiera precaria per i Forsaken, stretta tra l'avanzata del Flagello, bestie feroci e altre minacce in agguato. Dopo un inventario dell'equipaggiamento condotto dalla Guardiamorte Podrig su ordine dell'Executor Hadrec, le scorte di Mausolea sono risultate per lo più adeguate, ma disperatamente scarse di armi di ricambio. Questo dispaccio ufficiale descrive in dettaglio le lame e le armi necessarie per sostenere le Guardiemorte a difesa dell'avamposto."},{t="Dispaccio tramite Maestro dei Pipistrelli",b="Poiché le armi non possono essere forgiate facilmente tra le cripte umide di Selva Pinargento, la richiesta è indirizzata a Gordon Wendham, un mercante d'armi che si trova nel vivace Trade Quarter di Undercity. Per accelerare l'ordine, i corrieri portano il documento direttamente al maestro dei pipistrelli Karos Razok, sfruttando le rotte aeree dei Forsaken per garantire un rapido rifornimento dalla capitale."}},faq={{q="Cosa c'è scritto in Podrig's Order?",a="È una richiesta ufficiale che elenca le armi di ricambio necessarie alle Guardiemorte di stanza a Mausolea dopo le consuete perdite sul campo.",al={"cosa dice l'ordine","contenuto di podrig's order","dettagli di podrig's order"}},{q="Chi ha scritto Podrig's Order?",a="È stato redatto dalla Guardiamorte Podrig sotto le istruzioni dell'Executor Hadrec, in seguito a una verifica dell'inventario dell'armeria di Mausolea.",al={"chi lo ha scritto","autore di podrig's order"}},{q="Chi riceve l'ordine?",a="È destinato a Gordon Wendham, un mercante d'armi che conduce i propri affari nel Trade Quarter di Undercity.",al={"chi riceve l'ordine","dove va podrig's order","destinatario di podrig's order"}},{q="Perché Mausolea ha bisogno di nuove armi?",a="I continui scontri contro il Flagello e altre forze ostili a Selva Pinargento comportano frequentemente armi ed equipaggiamenti rotti o smarriti tra le Guardiemorte in difesa.",al={"perché servono armi","carenza di armi a mausolea"}}},fx={["92a3bbc0"]={q="Cos'è l'Ordine di Podrig?",a="L'Ordine di Podrig è un documento ufficiale di requisizione dei Reietti scritto per assicurare nuovi armamenti per l'avamposto alla Mausolea. Redatto da Podrig per conto dell'Esecutore Hadrec, il rotolo elenca le armi sostitutive necessarie alle Guardie della Morte della guarnigione per sopravvivere ai loro continui scontri contro il Flagello e altri terrori che si annidano nella Selva Pinargento.",al={"cos'è l'ordine di podrig","oggetto ordine di podrig","requisizione podrig"}},["6fc9fe58"]={q="Perché Gordon Wendham ha bisogno dell'Ordine di Podrig?",a="Come mercante di armi nel Trade Quarter di Undercity, Gordon Wendham necessita della requisizione formale per verificare ed evadere la richiesta di rifornimenti della guarnigione. Senza questo manifesto verificato, la Mausolea non può ricevere la necessaria spedizione di lame ed equipaggiamento per rifornire le sue Guardie della Morte in prima linea.",al={"perché gordon wendham vuole l'ordine","perché portare l'ordine di podrig a undercity","perché serve l'ordine di podrig"}}},fp="14,228,20.431.0,24.366.0,34.139.0,25.133.0,23.106.0,40.164.0"}
P.entries["item:pork-belly-pie"] = {n="Pasticcio di Carne di Cinghiale",s="Il Pasticcio di Carne di Cinghiale è un piatto salato fatto in casa preparato da \\\"Zia\\\" Bernice Stonefield nella Foresta di Elwynn. Nonostante l'aspra e duratura faida tra le famiglie Stonefield e Maclure, il giovane Billy Maclure non riesce a resistere alla cucina di zia Bernice, pretendendo un pasticcio come tangente per rivelare informazioni su un cimelio di famiglia perduto.",h="Il Pasticcio di Carne di Cinghiale è un piatto salato fatto in casa preparato da \\\"Zia\\\" Bernice Stonefield...",kw={"zia bernice pietradura","ritorno da billy","billy maclure","foresta di elwynn","maclure","pasticcio di carne di cinghiale","pietradura"},ang={["faction:Alliance"]="Per i viaggiatori dell'Alleanza che aiutano le zone rurali di Elwynn, sbrigare faccende come consegnare pasticci fa luce sui piccoli ma profondamente radicati battibecchi che dividono il cuore agricolo di Roccavento.",["profession:Cooking"]="Il pasticcio evidenzia come il cibo casalingo possa esercitare una vera e propria influenza sulle dispute locali, anche se la ricetta stessa rimane un segreto gelosamente custodito da zia Bernice."},sec={{t="Una tangente tra fattorie rivali",b="Le famiglie Stonefield e Maclure coltivano un'aspra rivalità da anni, litigando per la terra e per l'orgoglio nel cuore della Foresta di Elwynn. Nonostante questa ostilità, il giovane Billy Maclure nutre un evidente punto debole: adora il famoso pasticcio di carne di cinghiale di zia Bernice. Quando scompare una preziosa collana di famiglia, Billy si rifiuta di condividere ciò che sa finché un avventuriero non gli consegna una fetta calda. Bernice lo cucina con grande riluttanza — e con l'esplicito augurio che il ragazzo ingordo ci si strozzi — a dimostrazione del fatto che la reputazione culinaria può a volte fare breccia persino nelle faide familiari più ostinate."}},faq={{q="A cosa serve il Pasticcio di Carne di Cinghiale?",a="Il pasticcio viene preparato da zia Bernice Stonefield per corrompere il giovane Billy Maclure. Billy è in possesso di indizi cruciali su una collana, cimelio appartenente alla famiglia Stonefield, ma si rifiuta di parlare finché il suo appetito non viene soddisfatto dalla cucina di zia Bernice.",al={"uso del pasticcio","perché pasticcio di carne di cinghiale","cosa faccio con il pasticcio"}},{q="Chi prepara il Pasticcio di Carne di Cinghiale?",a="Il pasticcio viene sfornato fresco da zia Bernice Stonefield alla Fattoria dei Pietradura. Sebbene provi un profondo rancore verso Billy Maclure e il resto della sua famiglia, lo prepara comunque per aiutare a recuperare la collana perduta della sua famiglia.",al={"chi ha fatto il pasticcio","preparatore del pasticcio","pasticcio di nonna pietradura"}},{q="Perché Billy Maclure vuole il cibo di una famiglia rivale?",a="Nonostante la feroce e rumorosa faida tra gli Stonefield e i Maclure, la cucina di zia Bernice è ben nota in tutta la valle. A Billy importano molto di più il proprio stomaco e la saporita carne di cinghiale che mantenere i rancori di famiglia.",al={"perché billy vuole il pasticcio","perché maclure vuole cibo dei pietradura"}},{q="I giocatori possono mangiare il Pasticcio di Carne di Cinghiale?",a="No. Il pasticcio è un oggetto di missione destinato esclusivamente a Billy Maclure. Non puoi consumarlo personalmente per ripristinare salute o mana, per quanto possa sembrare appetitoso.",al={"posso mangiarlo","il pasticcio di carne di cinghiale è commestibile"}}},fx={["6505ed9f"]={q="Cos'è il Pasticcio di Carne di Cinghiale?",a="È un saporito pasticcio di carne cotto con pancetta di cinghiale, rinomato per essere delizioso nonostante l'amara faida tra le due famiglie di contadini della Foresta di Elwynn meridionale. Appena preparato nella cucina dei Stonefield, serve come succulento tributo per estorcere informazioni al ragazzo Maclure, Billy, che sostiene che la sua memoria funzioni solo a stomaco pieno.",al={"cos'è il pasticcio di carne di cinghiale","lore pasticcio di carne di cinghiale","a proposito del pasticcio di carne di cinghiale"}}},fp="14,318,29.572.0,36.258.0,29.212.0,53.232.0,35.153.0"}
P.entries["item:powdered-azurite"] = {n="Azurite Polverosa",s="L'Azurite Polverosa è un reagente minerale frantumato ricavato dalla Miniera di Venazzurra nelle Alture di Colletorto. È ricercata dal maestro armaiolo Thun'grim Firegaze per temprare e forgiare la Brutal Armor per i guerrieri emergenti dell'Orda.",h="L'Azurite Polverosa è un reagente minerale frantumato ricavato dalla Miniera di Venazzurra nelle Alture di...",kw={"miniera di venazzurra","azurite","brutal armor","colletorto","azurite polverosa","reagente","thun'grim firegaze"},ang={["class:Warrior"]="Ottenere l'Azurite Polverosa dimostra la tua resistenza all'estero, raccogliendo i reagenti specializzati necessari a Thun'grim Firegaze per forgiare un'armatura personale dalla forza selvaggia.",["faction:Horde"]="Reclamare questa polvere raffinata richiede di colpire in profondità nei Regni Orientali, sottraendo risorse direttamente dalle mani dell'Alleanza nelle Alture di Colletorto."},sec={{t="Un raro composto minerale",b="L'Azurite Polverosa è una polvere raffinata derivata dalle vene minerali sotto le Alture di Colletorto. I lavoratori umani della Miniera di Venazzurra scavano nella terra per estrarre questa caratteristica pietra blu, polverizzandola e imballandola per il commercio e la metallurgia. Nelle mani di un abile fabbro, la polvere funge da fondente o additivo fondamentale durante la lavorazione di metalli densi, migliorando la durevolezza e conferendo una resilienza unica all'armatura finita."},{t="Forgiare la Brutal Armor",b="Sebbene sia originaria dei tunnel controllati dagli umani oltre il Grande Mare, l'Azurite Polverosa è riconosciuta dai fabbri veterani dell'Orda per le sue eccezionali proprietà metallurgiche. Thun'grim Firegaze, un anziano armaiolo orco che risiede nei Barrens, richiede piccole quantità di pietra polverizzata insieme a ferro raffinato e reagenti infuocati. Mescolata nella fusione, la polvere gli consente di forgiare la pesante e punitiva corazzatura che caratterizza la sua armatura da battaglia magistrale."}},faq={{q="A cosa serve l'Azurite Polverosa?",a="Serve come componente metallurgico essenziale per Thun'grim Firegaze, un maestro armaiolo di stanza nei Barrens. Egli combina il minerale frantumato con lingotti di ferro e reagenti volatili per forgiare pezzi di Brutal Armor per i campioni dell'Orda.",al={"uso di azurite polverosa","cos'è l'azurite polverosa"}},{q="Dove si trova l'Azurite Polverosa?",a="Viene raccolta dai minatori umani che faticano all'interno della Miniera di Venazzurra, situata lungo la costa meridionale delle Alture di Colletorto nei Regni Orientali.",al={"dove trovare l'azurite polverosa","posizione di azurite polverosa","chi rilascia azurite polverosa"}},{q="Perché un armaiolo nei Barrens richiede reagenti da Colletorto?",a="Thun'grim Firegaze cerca i materiali migliori per produrre armature degne di guerrieri leggendari. Sebbene il ferro sia prontamente disponibile, le specifiche qualità di tempra conferite dal minerale di Venazzurra rendono opportuno inviare i suoi campioni attraverso il mare per procurarselo.",al={"perché colletorto","fonte del minerale di thungrim"}}},fx={["139f7c50"]={q="Cos'è l'Azurite Polverosa?",a="L'Azurite Polverosa è un reagente minerale blu frantumato estratto da vene profonde nelle Alture di Colletorto. Riverito dai maestri armaioli per le sue proprietà metallurgiche uniche, la polvere fine può essere legata o temprata in metalli di base durante la forgiatura. È particolarmente apprezzata dall'armaiolo dell'Orda Thun'grim Firegaze, che la usa insieme a reagenti esotici per fabbricare armature a maglia pesanti e resilienti degne di rinomati guerrieri.",al={"cos'è l'azurite polverosa","lore azurite polverosa","oggetto azurite polverosa"}},["720f3d61"]={q="Da dove proviene l'Azurite Polverosa e chi l'ha estratta?",a="La sostanza viene estratta dalla Miniera di Venazzurra annidata lungo le colline meridionali delle Alture di Colletorto. I minatori umani che lavorano nei pozzi sotterranei di Venazzurra dissotterrano il grezzo minerale di azurite e lo macinano riducendolo in una polvere raffinata. Poiché la miniera rimane sotto il saldo controllo dei lavoratori umani di Colletorto, ottenere la polvere richiede di prenderla direttamente dai minatori che lavorano sotto terra.",al={"dove trovare azurite polverosa","chi estrae l'azurite polverosa","fonte azurite polverosa"}}},fp="16,217,23.418.0,20.454.0,34.245.0,36.156.0,67.267.0"}
P.entries["item:powers-of-the-void"] = {n="Poteri del Vuoto",s="Poteri del Vuoto è un raro tomo magico originariamente custodito in un'ala riservata della biblioteca dell'Abbazia della Contea del Nord. Dopo che un novizio ribelle lo ha rubato disertando a favore della Fratellanza dei Defias, l'istruttrice dei negromanti Drusilla La Salle ne cerca il recupero per proseguire i propri studi sulla magia oscura.",h="Poteri del Vuoto è un raro tomo magico originariamente custodito in un'ala riservata della biblioteca...",kw={"fratellanza dei defias","drusilla la salle","demonietto","khadgar","abbazia della contea del nord","poteri del vuoto","libri rubati","the stolen tome","negromante"},ang={["class:Warlock"]="Il recupero di questo grimorio rubato funge da prova fondamentale per i giovani negromanti umani, dimostrando una forza di volontà sufficiente a meritare il segreto per evocare un demonietto.",["race:Human"]="La presenza del tomo nella Contea del Nord rivela che il Sacro Ordine conserva pericolosi documenti magici accanto ai normali testi clericali, tenendoli nascosti agli occhi dei novizi."},sec={{t="Un testo riservato della Contea del Nord",b="Gli archivi dell'Abbazia della Contea del Nord custodiscono molto più che sacre scritture e documenti clericali. Nascosto in un'ala protetta della biblioteca dell'abbazia c'era Poteri del Vuoto, un'opera accademica riguardante le energie dell'ombra e del potere fatuo, presumibilmente redatta dall'arcimago Khadgar. Data la natura pericolosa di tali ricerche, le autorità dell'abbazia mantenevano il libro strettamente sorvegliato e rigorosamente inaccessibile ai visitatori occasionali. Ciò lo tenne lontano dalle mani dell'istruttrice locale dei negromanti della Contea del Nord, Drusilla La Salle, che non poteva aggirarsi nei pressi degli scaffali riservati senza destare indesiderati sospetti da parte del clero."},{t="Furto dei Defias e recupero",b="Il tomo lasciò infine le mura dell'abbazia non per mano di Drusilla, ma a causa di Betrayal from Within. Un novizio che studiava alla Contea del Nord abbandonò i suoi voti per unirsi alla Fratellanza dei Defias, saccheggiando diversi volumi di valore mentre fuggiva verso le vicine vigne. Approfittando dell'opportunismo del ladro, Drusilla invia promettenti iniziati negromanti direttamente nell'accampamento di banditi dei Defias per sottrarre il tomo dalle loro tende. Recuperare il testo persegue un duplice scopo: mette la conoscenza oscura a disposizione dell'istruttrice e mette alla prova se un novizio possieda la fermezza necessaria per vincolare demoni ultraterreni."}},faq={{q="Che cos'è Poteri del Vuoto?",a="È un raro libro occulto che descrive in dettaglio energie oscure e concetti del potere fatuo, che si ritiene sia stato scritto dall'arcimago Khadgar. Era rinchiuso all'interno di un'ala riservata dell'Abbazia della Contea del Nord prima di essere rubato.",al={"cos'è poteri del vuoto","libro poteri del vuoto","cos'è the stolen tome"}},{q="Perché il libro era rinchiuso nell'Abbazia della Contea del Nord?",a="L'Abbazia della Contea del Nord conserva archivi storici, inclusi testi pericolosi sulle magie illecite. I libri che descrivono in dettaglio le energie del Vuoto e la demonologia sono tenuti sotto chiave per impedire a novizi e praticanti erranti di farne cattivo uso.",al={"perché si trovava nell'abbazia","perché i sacerdoti lo avevano","ala della biblioteca della contea del nord"}},{q="Come ha ottenuto il libro la Fratellanza dei Defias?",a="Un novizio dell'abbazia ha disertato per unirsi alla Fratellanza dei Defias e ha portato con sé diversi volumi di valore dalla biblioteca riservata della Contea del Nord, nascondendoli nell'accampamento di banditi situato nelle Vigne della Contea del Nord.",al={"chi ha rubato il libro","libri rubati defias","come l'hanno ottenuto i defias"}},{q="Perché Drusilla La Salle vuole Poteri del Vuoto?",a="Drusilla è l'istruttrice dei negromanti residente della Contea del Nord. Brama l'esoterica conoscenza del tomo per le sue arti oscure, ma non avrebbe mai potuto entrare negli archivi sicuri della biblioteca dell'abbazia senza dare l'allarme.",al={"perché drusilla lo vuole","chi vuole il libro","drusilla la salle the stolen tome"}},{q="Cosa dimostra a Drusilla il recupero del tomo?",a="Recuperare il tomo dimostra a Drusilla che un iniziato possiede l'astuzia, la forza e la determinazione necessarie per comandare servitori demoniaci, meritandosi le istruzioni su come evocare il suo primo demonietto.",al={"perché i negromanti hanno bisogno del libro","prova di evocazione del demonietto","ricompensa the stolen tome"}}},fx={["082e56cb"]={q="Chi ha scritto Poteri del Vuoto?",a="Si ritiene che il trattato arcano sia stato redatto dal leggendario arcimago Khadgar, che studiò molti aspetti profondi e pericolosi della magia prima di avventurarsi oltre il Portale Oscuro. Le sue intuizioni proibite sul vuoto profondo furono considerate troppo pericolose per una lettura casuale, spingendo i sacerdoti e gli studiosi dell'Abbazia della Contea del Nord a sigillarlo all'interno di un'ala protetta della loro biblioteca finché un novizio traditore non lo rubò.",al={"autore di poteri del vuoto","chi ha creato poteri del vuoto","creatore di poteri del vuoto"}}},fp="18,280,28.591.0,25.595.0,27.203.0,47.227.0,44.200.0,51.200.0,48.190.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Dente di Lupo Alfa",s="Un Dente di Lupo Alfa viene ricavato dai feroci capibranco che si aggirano per le pianure attorno a Picco del Tuono. Nella tradizione dei tauren, questi denti fungono da potente offerta per purificare e onorare le preziose fonti d'acqua della terra.",h="Un Dente di Lupo Alfa viene ricavato dai feroci capibranco che si aggirano per le pianure attorno a Picco del...",kw={"villaggio di zoccolo sanguinario","mulgore","mull corno tonante","dente di lupo alfa","lupo alfa della prateria","pozzo d'acqua","wildmane totem"},ang={["class:Shaman"]="Gli spiriti dei pozzi d'acqua devono essere placati attraverso l'equilibrio terreno, e offrire le zanne di un predatore all'apice radica quell'armonia naturale.",["race:Tauren"]="Prendere la zanna di un alfa della prateria rappresenta il sacro dovere del cacciatore di raccogliere ciò che è necessario con rispetto, restituendo quell'essenza primordiale per sanare la terra avvelenata."},sec={{t="Un'offerta purificatrice",b="I pozzi d'acqua di Mulgore sono fonti di vita vitali per i tauren, e mantenere la loro purezza spirituale richiede riti di rispetto e sacrificio. Per purificare il Pozzo di Wildmane, Mull Corno Tonante del Villaggio di Zoccolo Sanguinario richiede denti raccolti dai lupi alfa della prateria che si aggirano nell'ombra di Picco del Tuono. In quanto predatori all'apice delle ondulate pianure erbose, questi alfa rappresentano la pura forza della natura selvaggia. Offrire i loro denti onora l'equilibrio tra cacciatore, preda e spiriti della terra."}},faq={{q="A cosa serve un Dente di Lupo Alfa?",a="Mull Corno Tonante usa otto di questi denti in un rituale per purificare il Pozzo di Wildmane, l'ultimo pozzo d'acqua contaminato vicino al Villaggio di Zoccolo Sanguinario.",al={"scopo dente alfa","a cosa servono i denti di lupo mulgore","oggetto wildmane totem"}},{q="Dove si aggirano i lupi alfa della prateria?",a="I lupi alfa della prateria si aggirano nelle aperte pianure erbose di Mulgore centrale e settentrionale, circondando in particolare i promontori attorno alla base di Picco del Tuono.",al={"dove trovare i lupi alfa della prateria","posizioni lupo alfa","punti lupo alfa della prateria"}},{q="Perché un rituale di purificazione dell'acqua richiede denti di lupo?",a="I riti dei tauren onorano The Balance of Nature. Purificare i pozzi richiede componenti sacri presi direttamente dalle feroci bestie native della terra, a simboleggiare sia il sacrificio che la vitalità della fauna selvatica di Mulgore.",al={"perché denti di lupo per acqua","lore rituale dente mull corno tonante"}}},fx={f1f3b80c={q="Cos'è un Dente di Lupo Alfa?",a="Un Dente di Lupo Alfa è un dente preso da un lupo alfa della prateria, uno dei più feroci capibranco che si aggirano per le pianure di Mulgore. Tra i tauren, queste zanne rappresentano la forza e lo spirito dei predatori alfa della terra, portando un peso spirituale quando offerte in rituale.",al={"dente di lupo alfa","cos'è il dente di lupo alfa"}},["0674aadd"]={q="Da dove proviene un Dente di Lupo Alfa?",a="Questi denti vengono raccolti dai lupi alfa della prateria che vagano per le praterie di Mulgore, in particolare vicino alla base di Picco del Tuono a nord. Essendo zanne naturali di predatori viventi, vengono prelevate direttamente dalle bestie durante la caccia anziché essere fabbricate da mani mortali.",al={"da dove provengono i denti di lupo alfa","origine dente di lupo alfa","chi lascia cadere il dente di lupo alfa"}}},fp="19,216,20.495.0,39.142.0,34.148.0,53.212.0"}
P.entries["item:prairie-wolf-heart"] = {n="Cuore di Lupo della Prateria",s="Un Cuore di Lupo della Prateria è un organo vitale ricavato dai lupi che si aggirano per le praterie di Mulgore. Serve come ingrediente essenziale in un urgente rimedio popolare preparato da Maur Invoca Pioggia al Villaggio di Zoccolo Sanguinario per contrastare un'infezione velenosa.",h="Un Cuore di Lupo della Prateria è un organo vitale ricavato dai lupi che si aggirano per le praterie di...",kw={"villaggio di zoccolo sanguinario","maur invoca pioggia","mazzranache","mulgore","predatore della prateria","cuore di lupo della prateria","cuore di lupo"},ang={["class:Hunter"]="Rintracciare specifici branchi di lupi nelle pianure dimostra una precoce comprensione delle prede e dell'ecologia delle bestie a Mulgore.",["race:Tauren"]="Usare parti di animali raccolte per preparare cure di sopravvivenza riflette le tradizioni pragmatiche e legate alla terra dei tauren nelle terre selvagge di Mulgore."},sec={{t="Un rimedio per un morso velenoso",b="I lupi delle pianure sono predatori feroci, resistenti e tenaci attraverso le distese erbose di Mulgore. I loro cuori sono ricercati da Maur Invoca Pioggia, un tauren residente al Villaggio di Zoccolo Sanguinario caduto vittima del leggendario zampalunga noto come Mazzranache. Colpito dal veleno virulento e febbrile della creatura, Maur si affida alla medicina tradizionale delle pianure per arrestare il veleno che si diffonde. Insieme ad altri potenti reagenti come l'osso di puma e lo stomaco di volatile, l'essenza vitale di un lupo della prateria appena ucciso fornisce le proprietà purificatrici necessarie per preparare una cura prima che il delirio si riveli fatale."}},faq={{q="A cosa serve un Cuore di Lupo della Prateria?",a="Viene raccolto per Maur Invoca Pioggia al Villaggio di Zoccolo Sanguinario. Maur ne ha bisogno insieme a diverse altre parti di animali per preparare una potente medicina popolare per curare un morso velenoso inflitto dal famigerato zampalunga Mazzranache.",al={"uso del cuore di lupo","perché procurarsi il cuore di lupo","scopo del cuore di lupo della prateria"}},{q="Dove si ottiene un Cuore di Lupo della Prateria?",a="Si ottiene dai corpi di lupi della prateria, lupi della prateria alfa e predatori della prateria trovati a cacciare attraverso la Piana Ondulata di Mulgore.",al={"posizione del cuore di lupo","chi rilascia il cuore di lupo","come trovare il cuore di lupo della prateria"}},{q="Perché Maur Invoca Pioggia ha bisogno di organi animali per curare la sua ferita?",a="Mazzranache infligge un morso terribile e infetto che causa febbre e delirio. Maur usa i rimedi tradizionali delle pianure dei tauren composti da potenti reagenti — cuore di lupo, femore di puma, Scaglia di Zampalunga delle Pianure e Stomaco dell'Avvoltoio — per purificare l'infezione prima che si riveli letale.",al={"perché il cuore di lupo per la medicina","rimedio di maur"}},{q="Si può usare qualsiasi cuore di lupo per il rimedio?",a="Maur Invoca Pioggia chiede semplicemente un cuore di lupo. Quello raccolto per il rimedio viene prelevato dai lupi della prateria, dai lupi della prateria alfa o dai predatori della prateria che cacciano nelle pianure di Mulgore.",al={"qualsiasi cuore di lupo","quali lupi lo rilasciano"}}},fx={ee1c9772={q="Cos'è un Cuore di Lupo della Prateria?",a="Un Cuore di Lupo della Prateria è l'organo raccolto dai lupi predatori che si aggirano nella Piana Ondulata di Mulgore. Sebbene abbia poco valore commerciale comune, la vitalità del cuore di una bestia selvatica lo rende un ingrediente pregiato nella medicina tradizionale tauren. Serve come uno dei numerosi e potenti reagenti necessari per preparare rimedi in grado di purificare veleni naturali virulenti e infezioni profonde.",al={"cos'è il cuore di lupo della prateria","cuore di lupo della prateria","informazioni cuore di lupo della prateria"}},["1392571f"]={q="Da dove proviene un Cuore di Lupo della Prateria?",a="Il cuore viene preso direttamente dai lupi della prateria selvatici, dai lupi alfa della prateria e dagli inseguitori della prateria nativi degli altipiani erbosi di Mulgore. È un organo biologico naturale raccolto da un predatore ucciso piuttosto che un oggetto fabbricato da mani mortali.",al={"da dove proviene il cuore di lupo della prateria","origine cuore di lupo della prateria","chi ha creato il cuore di lupo della prateria"}}},fp="18,243,28.598.0,38.211.0,43.140.0,63.269.0,42.184.0"}
P.entries["item:prairie-wolf-paw"] = {n="Zampa di Lupo della Prateria",s="Le Zampe di Lupo della Prateria vengono ricavate dai predatori che si aggirano per le pianure di Mulgore. I praticanti sciamanici, come Mull Corno Tonante al Villaggio di Zoccolo Sanguinario, le usano come componenti organici per infondere il potere naturale della terra nei totem della purificazione.",h="Le Zampe di Lupo della Prateria vengono ricavate dai predatori che si aggirano per le pianure di Mulgore.",kw={"villaggio di zoccolo sanguinario","mulgore","mull corno tonante","artiglio di zampalunga delle pianure","poison water","lupo della prateria","zampa di lupo della prateria","pozzo degli zoccolo artico"},ang={["class:Shaman"]="Creare totem della purificazione a partire da parti di animali locali dimostra il principio elementale secondo cui si usa l'essenza vivente della terra per purgare la corruzione innaturale.",["race:Tauren"]="Per i tauren, raccogliere zampe di lupo è un solenne dovere di tutela, che fa appello alle bestie native della terra per risanare i pozzi d'acqua ancestrali contaminati dall'avidità dei goblin."},sec={{t="Reagenti Naturali delle Pianure",b="I lupi della prateria si aggirano furtivi tra le distese d'erba di Mulgore, cacciando in branco insieme ai cacciatori delle praterie e ai loro capobranco. Sebbene siano pericolose per i giovani cacciatori e il bestiame locale, queste creature sono profondamente legate all'equilibrio spirituale delle pianure. Gli sciamani tauren non considerano le zampe di lupo meri trofei, ma condotti vitali dell'innata energia della terra."},{t="Purificare i Pozzi",b="Quando le attività dei goblin hanno contaminato le sacre riserve d'acqua di Mulgore, lo sciamano Mull Corno Tonante ha richiesto l'aiuto tangibile della terra stessa per contrastare l'inquinamento. Unite agli artigli di zampalesta, le zampe di lupo forniscono la risonanza spirituale grezza necessaria a forgiare totem della purificazione, dando inizio all'opera fondamentale di purificazione del Pozzo degli Zoccolo Artico."}},faq={{q="Quali creature rilasciano una Zampa di Lupo della Prateria?",a="Si raccolgono dai lupi della prateria, dai cacciatori delle praterie e dai lupi alfa della prateria che cacciano nelle pianure di Mulgore, principalmente a sud-ovest del Villaggio di Zoccolo Sanguinario.",al={"chi rilascia zampa di lupo della prateria","dove trovare zampe di lupo della prateria","fonte zampa di lupo della prateria"}},{q="Chi richiede le Zampe di Lupo della Prateria?",a="Mull Corno Tonante, uno sciamano tauren di stanza al Villaggio di Zoccolo Sanguinario, le richiede per aiutare a creare un Totem della Purificazione e ripristinare i pozzi d'acqua contaminati.",al={"chi ha bisogno di zampe di lupo della prateria","zampe di lupo mull corno tonante","consegna zampa di lupo della prateria"}},{q="Perché sono necessarie le zampe di lupo per purificare l'acqua?",a="Lo sciamanesimo dei tauren si basa sull'incanalare la naturale vitalità della terra per contrastare la corruzione. Le zampe di lupo, combinate con gli artigli di uccello, consentono allo sciamano di vincolare lo spirito vivente di Mulgore in un totem elementale in grado di purgare i veleni dei goblin.",al={"perché zampe di lupo","storia zampa di lupo della prateria","perché mull vuole le zampe"}},{q="Quale pozzo d'acqua aiutano a purificare queste zampe?",a="Le zampe vengono raccolte specificamente per creare il Totem della Purificazione per il Pozzo degli Zoccolo Artico, che è stato avvelenato da intrusi goblin e dai loro agenti.",al={"quale pozzo","purificazione pozzo degli zoccolo artico"}}},fx={["94c15e4c"]={q="Cos'è una Zampa di Lupo della Prateria?",a="Una Zampa di Lupo della Prateria è un componente rituale naturale raccolto dai canidi selvatici che vagano per le pianure di Mulgore. Piuttosto che servire come semplici trofei, queste zampe portano l'essenza vivente della terra, rendendole preziose per gli sciamani tauren che fabbricano totem per guarire e preservare la terra.",al={"zampa di lupo della prateria","cosa sono le zampe di lupo della prateria","zampa di lupo mulgore"}},["7a637be5"]={q="Da dove provengono le Zampe di Lupo della Prateria?",a="Queste zampe vengono raccolte direttamente dai lupi della prateria, dagli inseguitori della prateria e dai lupi alfa nativi degli altipiani erbosi di Mulgore. Sono parti naturali della natura selvaggia, prese dai cacciatori per offrire la forza della terra nei momenti di bisogno spirituale.",al={"da dove provengono le zampe di lupo della prateria","fonte zampe di lupo della prateria","chi lascia cadere le zampe di lupo"}}},fp="16,244,30.370.0,19.354.0,39.166.0,28.147.0,42.251.0,44.154.0"}
P.entries["item:pridewing-venom-sac"] = {n="Sacca di Veleno di Viverna",s="Le Sacche di Veleno di Viverna vengono ricavate dalle letali viverne che nidificano attorno al Lago Mirkfallon nelle Vette di Petrartiglio. Gli elfi della notte di Astranaar cercano di accumulare e distruggere queste sacche dopo che informazioni di intelligence hanno suggerito che gli agenti dell'Orda raccolgono il potente veleno per compiere assassinii segreti.",h="Le Sacche di Veleno di Viverna vengono ricavate dalle letali viverne che nidificano attorno al Lago...",kw={"astranaar","lago mirkfallon","pridewing","shindrell fuocolesto","vette di petrartiglio","sacca di veleno","viverna"},ang={["faction:Alliance"]="Negare all'Orda l'accesso al veleno dei pridewing è vitale per proteggere le pattuglie di frontiera dagli assassini invisibili lungo i confini contesi tra le Vette di Petrartiglio e Valtetra.",["race:NightElf"]="Sebbene i vertici delle Sentinelle si rammarichino di dover abbattere bestie selvatiche innocenti, proteggere le vite degli elfi contro le lame avvelenate ha la precedenza sull'armonia naturale."},sec={{t="Una minaccia tra i picchi",b="I Pridewings of Stonetalon sono pericolosi predatori alati originari delle cime a sud di Valtetra, in particolare attorno al Lago Mirkfallon. Sebbene le viverne selvatiche siano naturalmente velenose, le informazioni dell'Alleanza provenienti da Theramore suggeriscono che gli assassini dell'Orda abbiano iniziato a estrarre il loro veleno per cospargere le lame usate in incursioni clandestine contro gli insediamenti degli elfi della notte. Per proteggere la propria gente e interrompere i rifornimenti nemici, le Sentinelle di Astranaar assoldano esploratori affinché diano la caccia a queste bestie e raccolgano le ghiandole di veleno prima che l'Orda possa appropriarsene."}},faq={{q="Quali creature rilasciano una Sacca di Veleno di Viverna?",a="Queste sacche di veleno vengono recuperate dalle varie viverne che popolano i dirupi vicino al Lago Mirkfallon nelle Vette di Petrartiglio, inclusi giovani pridewing, skyhunter, patriarchi e consorti.",al={"dove trovare la sacca di veleno di viverna","chi rilascia la sacca di veleno di viverna","fonti di veleno di pridewing"}},{q="Perché Astranaar vuole le Sacche di Veleno di Viverna?",a="Shindrell Fuocolesto ha ricevuto rapporti secondo cui gli agenti dell'Orda estraggono il veleno dei pridewing per cospargere armi usate in assassinii silenziosi contro l'Alleanza. Distruggere o confiscare le ghiandole previene questi attacchi.",al={"perché raccogliere le sacche di veleno","shindrell fuocolesto veleno"}},{q="Chi accetta queste sacche di veleno a Valtetra?",a="Shindrell Fuocolesto, di stanza nella città degli elfi della notte di Astranaar a Valtetra, le raccoglie per proteggere la propria gente da attacchi segreti.",al={"chi accetta il veleno di pridewing","consegna missione pridewing"}},{q="I pridewing sono naturalmente alleati dell'Orda?",a="No. I pridewing selvatici che popolano i dintorni del Lago Mirkfallon sono bestie che non aiutano spontaneamente l'Orda, sebbene gli agenti degli orchi sfruttino la loro biologia velenosa per la propria condotta bellica.",al={"i pridewing appartengono all'orda","i pridewing lavorano per gli orchi"}}},fx={e2bba8d5={q="Cos'è una Sacca di Veleno di Viverna?",a="Una Sacca di Veleno di Viverna è un organo raccolto dalle viverne pridewing che nidificano nelle Vette di Petrartiglio. Contiene le potenti tossine naturali che questi predatori alati producono per soggiogare le loro prede. Nel fragile stallo tra gli elfi della notte e l'Orda, tale veleno è diventato un'arma pregiata per attacchi furtivi, spingendo i difensori di Astranaar a prestare attenzione.",al={"cos'è la sacca di veleno di viverna","oggetto sacca di veleno di viverna","cosa sono le sacche di veleno di viverna"}},["816b56c2"]={q="Da dove proviene una Sacca di Veleno di Viverna?",a="Queste sacche vengono raccolte direttamente dai corpi delle pridewing, feroci viverne selvatiche che si appollaiano vicino al Lago Mirkfallon nelle Vette di Petrartiglio. Poiché sono organi corporei naturali prodotti dalle bestie stesse anziché beni manufatti, ottenerle richiede di cacciare le viverne tra le rocce e assicurarsi il veleno prima che gli agenti dell'Orda possano raccoglierlo.",al={"fonte sacca di veleno di viverna","da dove provengono le sacche di veleno di viverna","chi lascia cadere la sacca di veleno di viverna"}}},fp="19,286,21.530.0,43.192.0,45.209.0,42.140.0,51.166.0"}
P.entries["item:prismatic-punch-card"] = {n="Scheda Perforata Prismatica",s="La Scheda Perforata Prismatica è la scheda dati con il livello di sicurezza più alto reperibile all'interno della città caduta di Gnomeregan. Potenziata in sequenza attraverso una serie di terminali Matrix Punchograph, contiene dati disperatamente ricercati dai profughi gnomi a Forgiardente.",h="La Scheda Perforata Prismatica è la scheda dati con il livello di sicurezza più alto reperibile all'interno...",kw={"tuboduro","data rescue","engineering labs","gnomeregan","matrix punchograph","scheda perforata prismatica"},ang={["profession:Engineering"]="La programmazione sequenziale a schede perforate e la rete di terminali automatizzati dimostrano gli elevati standard dei macchinari informatici costruiti dagli inventori di Gnomeregan.",["race:Gnome"]="L'elaborato sistema di sicurezza Punchograph è un eccellente esempio dell'ingegno e della burocrazia gnomesca sopravvissuti intatti perfino dopo la caduta della loro dimora."},sec={{t="Una questione di sicurezza",b="Quando gli gnomi fuggirono dall'invasione dei trogg e dall'irradiazione tossica di Gnomeregan, enormi quantità di ricerche e documenti civici furono abbandonati nelle profondità. Per salvaguardare i sistemi di alto livello, gli gnomi utilizzarono un protocollo di sicurezza progressivo. Accedere al terminale Matrix Punchograph 3005-D nei livelli inferiori degli Engineering Labs richiede di seguire una progressione di schede perforate: partendo da una Scheda Perforata Bianca di base e avanzando attraverso i livelli di sicurezza Giallo, Blu e Rosso presso terminali dedicati, prima di punzonare la Scheda Perforata Prismatica finale. Il suo livello di sicurezza codificato è bizzarramente indicato come in attesa dell'invenzione di un numero completamente nuovo."},{t="La trasmissione vitale",b="Il Maestro Meccanico Tuboduro, ora di stanza tra le enclave dei profughi a Forgiardente, invia coraggiosi avventurieri nei meandri contaminati di Gnomeregan per una missione di recupero dati di fondamentale importanza. Sebbene Tuboduro descriva i dati bersaglio come assolutamente vitali e impossibili da ignorare, il messaggio binario decodificato punzonato sulla scheda prismatica finale svela una divertente verità della vita civica quotidiana degli gnomi: una notifica automatica che informa Tuboduro che il suo bucato è pronto per il ritiro."}},faq={{q="Come si crea una Scheda Perforata Prismatica?",a="Ottieni una Scheda Perforata Prismatica inserendo una Scheda Perforata Rossa in un terminale Matrix Punchograph 3005-D situato al livello inferiore degli Engineering Labs a Gnomeregan. Raggiungere tale fase richiede di potenziare in sequenza una Scheda Perforata Bianca iniziale attraverso i terminali modello A, B e C presenti nell'intero complesso.",al={"come ottenere la scheda perforata prismatica","creare la scheda perforata prismatica","sequenza di potenziamento delle schede perforate"}},{q="Quali dati sono memorizzati sulla Scheda Perforata Prismatica?",a="La scheda dichiara che il suo livello di sicurezza è così alto da essere in attesa dell'invenzione di un nuovo numero, seguito da una lunga stringa di codice binario. Il Maestro Meccanico Tuboduro insiste sul fatto che i dati siano di vitale importanza.",al={"cosa dice la scheda","traduzione binaria della scheda perforata","scheda perforata decodificata"}},{q="Chi vuole la Scheda Perforata Prismatica?",a="Il Maestro Meccanico Tuboduro, un ingegnere gnomo in esilio che risiede a Forgiardente, richiede la scheda durante la missione Data Rescue. Considera il contenuto della scheda come informazioni urgenti e inestimabili, lasciate indietro durante l'evacuazione di Gnomeregan.",al={"a chi consegnare la scheda perforata prismatica","missione di tuboduro","chi ha bisogno della scheda"}},{q="Dove si trovano i terminali Matrix Punchograph?",a="I terminali sono sparsi per tutta Gnomeregan in base al livello di sicurezza. Il Punchograph 3005-A si trova vicino al Train Depot di superficie e al Workshop Entrance, il modello B è situato nel Dormitory oltre la Clean Zone, il modello C si trova più in profondità all'interno del complesso e il modello D si erge nei livelli inferiori degli Engineering Labs.",al={"posizioni dei terminali","dove sono i punchograph","dove perforare le schede"}}},fx={f4168582={q="Cos'è una Scheda Perforata Prismatica?",a="Una Scheda Perforata Prismatica è una scheda dati con un livello di autorizzazione straordinariamente alto generata dai sistemi computazionali all'interno di Gnomeregan. La sua classificazione di sicurezza automatizzata è presumibilmente così elevata che la matematica gnomica non ha ancora inventato un numero adeguato per descriverla. In verità, contiene testo binario codificato prodotto dai terminali della città profonda, funzionando come l'apice del protocollo di recupero dati a livelli degli gnomi.",al={"cos'è la scheda perforata prismatica","storia della scheda perforata prismatica","scheda prismatica gnomeregan"}},["7551673e"]={q="Da dove proviene la Scheda Perforata Prismatica e chi l'ha creata?",a="La scheda è prodotta nelle profondità della città caduta di Gnomeregan dal Matrix Punchograph 3005-D, un terminale automatizzato ad alta sicurezza che si trova al livello inferiore degli Engineering Labs. Non è fatta a mano da una persona, ma piuttosto codificata dalla rete meccanizzata degli gnomi quando un utente inserisce una Scheda Perforata Rossa adeguatamente potenziata nell'apparato.",al={"origine scheda perforata prismatica","chi ha creato la scheda perforata prismatica","dove ottenere la scheda perforata prismatica"}}},fp="20,249,20.637.0,22.483.1,41.311.0,48.205.1,35.242.0,51.303.0"}
P.entries["item:pristine-spider-silk"] = {n="Seta di Ragno Intatta",s="La Seta di Ragno Intatta è un filo eccezionalmente pregiato raccolto dai velenosi aracnidi di Boscovespro. I maghi di Roccavento commissionano questo raro materiale per tessere vesti resistenti e incantate, degne di riconosciuti praticanti delle arti arcane.",h="La Seta di Ragno Intatta è un filo eccezionalmente pregiato raccolto dai velenosi aracnidi di Boscovespro.",kw={"black widow hatchling","carrion recluse","boscovespro","veste da mago","seta di ragno intatta","santuario della magia","wynne larson"},ang={["class:Mage"]="I maghi di Roccavento vengono inviati direttamente a Boscovespro a raccogliere questo filo intatto come rito di passaggio per guadagnarsi una veste adatta alla loro crescente levatura arcana.",["profession:Tailoring"]="Raccolti da letali aracnidi, questi fili delicati ma resistenti rappresentano l'apice dei tessuti naturali impiegati per tessere paramenti magici."},sec={{t="Tessere l'Arcano",b="Non un filo qualunque può reggere gli incantamenti e l'usura richiesti a un mago praticante. Sebbene la comune seta di ragno sia abbastanza diffusa tra i sarti, solo gli immacolati fili prelevati dai carrion recluse e dai black widow hatchling nei boschetti oscuri di Boscovespro possiedono la necessaria resilienza. I maghi del Santuario della Magia di Roccavento inviano i loro emergenti adepti in questi boschi pericolosi per raccogliere rocchetti intatti, incaricando la maestra sarta locale Wynne Larson di foggiare il materiale in una veste adatta a un adepto."}},faq={{q="Da dove proviene la Seta di Ragno Intatta?",a="Viene raccolta dagli aracnidi in agguato a Boscovespro, nello specifico dai carrion recluse e dai black widow hatchling che nidificano sotto la cupa volta boschiva.",al={"dove trovare la seta di ragno intatta","chi rilascia la seta di ragno intatta","posizione della seta di ragno intatta"}},{q="Chi crea indumenti con questa seta?",a="Wynne Larson, una sarta attiva nel Quartiere dei Maghi di Roccavento, confeziona i rocchetti raccolti trasformandoli in una raffinata veste per conto del Santuario della Magia.",al={"chi usa la seta di ragno intatta","chi trasforma la seta in vesti","veste di wynne larson"}},{q="Perché i maghi richiedono questa seta specifica?",a="I maghi necessitano di indumenti che riflettano la loro crescente maestria arcana. Solo la seta più pura e intatta dei letali ragni di Boscovespro fornisce la resistenza e la qualità necessarie per la veste di un adepto.",al={"perché la seta intatta","uso della seta di ragno magica"}}},fx={dfaa8e27={q="Cos'è la Seta di Ragno Intatta?",a="La Seta di Ragno Intatta è una tela eccezionalmente fine e immacolata filata dagli aracnidi che infestano Boscovespro. A differenza delle comuni ragnatele logore che si trovano appese agli alberi in tutta la foresta oscurata, solo i fili più puri e senza imperfezioni si qualificano come intatti. Sarti e maghi la apprezzano molto per la sua qualità e consistenza superiori, utilizzandola come tessuto base essenziale per confezionare capi distinti adatti a maghi praticanti.",al={"seta di ragno intatta","cos'è la seta intatta","oggetto seta intatta"}}},fp="20,240,18.520.0,42.149.0,35.152.0,44.193.0"}
P.entries["item:prowler-claws"] = {n="Prowler Claws",s="I Prowler Claws sono trofei recisi raccolti dai savannah prowler che si aggirano furtivi per le pianure arse dal sole di The Barrens. Portati a Sergra Darkthorn al Crocevia, servono come prova tangibile che un cacciatore è in grado di pedinare e sopraffare i predatori furtivi più letali di Kalimdor.",h="I Prowler Claws sono trofei recisi raccolti dai savannah prowler che si aggirano furtivi per le pianure arse...",kw={"the barrens","crocevia","prowler claws","prowlers of the barrens","savannah prowler","sergra darkthorn"},ang={["class:Hunter"]="Abbattere i savannah prowler e reclamare i loro artigli è un rito di passaggio essenziale per i giovani cacciatori che desiderano apprendere l'arte della furtività, del tracciamento e della gestione ravvicinata delle bestie.",["faction:Horde"]="Abbattere i pericolosi prowler attorno al Crocevia aiuta a proteggere i messaggeri, le carovane e i coloni dell'Orda che attraversano le perigliose strade centrali di Kalimdor."},sec={{t="Trofei del predatore furtivo",b="L'erba alta di The Barrens nasconde i Savannah Prowler, grandi predatori felini noti per la loro pazienza, astuzia e colpi letali. Cacciarli è un banco di prova fondamentale per i crescenti guerrieri ed esploratori dell'Orda. A differenza delle prede erbivore come i plainstrider o gli zhevra, i prowler tendono agguati attivamente a chiunque entri nei loro territori di caccia. Raccogliere i loro artigli affilati e curvi richiede di avere la meglio su una creatura che fa affidamento su una totale furtività e un'aggressività territoriale, dimostrando alla cacciatrice dell'accampamento che il predatore furtivo è diventato la preda."},{t="Una prova per la cacciatrice",b="Al Crocevia, Sergra Darkthorn richiede questi artigli per misurare la prontezza di un iniziato per prove più grandi. Riportare una manciata di artigli dimostra che un cacciatore ha padroneggiato il tracciamento tra l'erba dorata della savana ed è in grado di resistere ad artigli capaci di squarciare cuoio e carne. Coloro che tornano con il loro trofeo dimostrano di possedere la prontezza necessaria per sopravvivere a bestie ancora più letali in agguato nelle pianure."}},faq={{q="Dove trovo i Prowler Claws?",a="I Prowler Claws si ottengono dai Savannah Prowler, che si aggirano per le praterie in tutta la parte centrale di The Barrens, in particolare nelle pianure a sud-ovest del Crocevia.",al={"posizione prowler claws","come ottenere prowler claws","dove trovare prowler claws"}},{q="Chi vuole questi artigli e perché?",a="Sergra Darkthorn, un'esperta cacciatrice di stanza al Crocevia, chiede ai cacciatori di portarle sette Prowler Claws come prova della loro abilità di tracciamento e combattimento contro pericolosi predatori.",al={"chi ha bisogno di prowler claws","consegnare prowler claws","missione sergra artigli"}},{q="Perché i Savannah Prowler sono considerati una preda significativa?",a="A differenza delle mandrie al pascolo di The Barrens, i prowler sono carnivori furtivi che pedinano attivamente viaggiatori e prede da posizioni nascoste nella fitta vegetazione. Cacciarli mette alla prova la capacità di un avventuriero di evitare imboscate e sconfiggere una bestia letale e astuta.",al={"perché cacciare i prowler","prowler pericolosi"}}},fx={["551eb0e2"]={q="Cosa sono i Prowler Claws?",a="I Prowler Claws sono gli artigli affilati come rasoi presi dalle zampe dei predatori della savana, i mortali felini predatori che perseguitano l'erba alta della savana di The Barrens. Per i cacciatori di Crocevia, prendere questi trofei dimostra che puoi rintracciare e superare una bestia astuta e letale senza diventare tu stesso una preda.",al={"cosa sono i prowler claws","oggetto prowler claws","informazioni prowler claws"}},c8bad4fe={q="Da dove provengono i Prowler Claws?",a="Questi artigli provengono direttamente dai predatori della savana che vagano per le pianure di The Barrens, in particolare nelle praterie a sud-ovest di Crocevia. Sono trofei naturali raccolti dalle carcasse dei grandi felini da cacciatori abbastanza abili da abbatterli.",al={"da dove provengono i prowler claws","fonte prowler claws","come ottenere i prowler claws"}}},fp="13,273,23.532.0,22.418.0,29.161.0,30.192.0,56.250.0"}
P.entries["item:pure-hearts"] = {n="Cuori Puri",s="I Cuori Puri sono reagenti rituali forniti agli stregoni Forsaken da Carendin Halgar a Undercity. Vengono usati per attirare e manifestare una succube attraverso la Distorsione Fatua, così che il praticante possa sconfiggere e vincolare il demone.",h="I Cuori Puri sono reagenti rituali forniti agli stregoni Forsaken da Carendin Halgar a Undercity.",kw={"carendin halgar","magic quarter","cuori puri","succube","evocazione","the binding","undercity"},ang={["class:Warlock"]="Per gli stregoni Forsaken, ottenere e usare questi cuori rappresenta un traguardo fondamentale nella demonologia: dimostrare la propria forza mentale contro le seducenti lusinghe della Distorsione Fatua.",["race:Undead"]="Tra il marciume e la piaga di Undercity, l'uso di cuori puramente incontaminati per manipolare gli appetiti demoniaci esemplifica la fredda e pragmatica stregoneria praticata dai Forsaken."},sec={{t="Esca per la Distorsione",b="La demonologia si basa sullo sfruttamento dei desideri più bassi e delle vulnerabilità spirituali. Per evocare una succube nel Magic Quarter di Undercity, Carendin Halgar fornisce agli stregoni i Cuori Puri. Quando vengono posizionate sul cerchio di evocazione, queste essenze spirituali incontaminate fungono da potente esca, attirando il seducente demone attraverso la Distorsione Fatua nel regno mortale. Una volta che il demone si manifesta, lo stregone deve resistere ai suoi ammalianti incantesimi mentali e abbatterla in combattimento. Sconfiggere la succube afferma il proprio dominio mistico, bandendola di nuovo nella Distorsione Fatua finché Carendin non insegna allo stregone l'incantesimo per evocarla a piacimento."}},faq={{q="A cosa servono i Cuori Puri?",a="Fungono da catalizzatore mistico usato presso il cerchio di evocazione nel Magic Quarter di Undercity per attirare e manifestare una succube attraverso il vuoto, consentendo a uno stregone di combatterla e vincolarla.",al={"uso dei cuori puri","perché i cuori puri","cosa fanno i cuori puri"}},{q="Chi fornisce i Cuori Puri?",a="Carendin Halgar, l'istruttore degli stregoni Forsaken che si trova nel Magic Quarter sotto le Rovine di Lordaeron, li consegna agli aspiranti praticanti pronti a padroneggiare l'evocazione di una succube.",al={"chi dà i cuori puri","chi assegna la missione dei cuori puri"}},{q="Perché una succube risponde ai Cuori Puri?",a="Le succubi prosperano sulla corruzione, sulla seduzione e sul corrompere l'innocenza. Lo splendore di cuori puri e immacolati è un'esca irresistibile attraverso la Distorsione Fatua, attirandole direttamente nel cerchio di evocazione preparato dallo stregone.",al={"perché la succube vuole i cuori puri","storia dei cuori puri"}},{q="Si possono tenere i Cuori Puri dopo il rituale?",a="No. Una volta evocata e sottomessa la succube, i resti dei Cuori Puri vengono restituiti a Carendin Halgar come prova del completamento della prova di vincolo.",al={"si tengono i cuori puri","cosa succede ai cuori puri"}}},fx={["105bfa16"]={q="Cosa sono i Cuori Puri?",a="I Cuori Puri sono potenti componenti rituali usati dagli stregoni Rinnegati a Undercity. Quando vengono lanciati su un cerchio di evocazione, la loro essenza incontaminata funge da esca attraverso la Distorsione Fatua, aprendo una frattura progettata specificamente per attirare ed evocare una pericolosa succube alla tua presenza.",al={"cosa sono i cuori puri","oggetto cuori puri","cuori puri stregone"}},["3abadf0f"]={q="Perché qualcuno vorrebbe i Cuori Puri?",a="Un aspirante stregone richiede i Cuori Puri per completare il pericoloso rituale di vincolo per una succube. Senza offrire un'esca così incontaminata per colmare il vuoto, non puoi attirare il demone attraverso il reame mortale per sottometterla e padroneggiare l'arte di evocarla al tuo comando.",al={"perché volere i cuori puri","scopo dei cuori puri","perché i cuori puri sono ricercati"}}},fp="11,222,19.638.0,34.185.0,29.188.0,43.227.0,52.152.0"}
P.entries["item:purified-kor-gem"] = {n="Gemma Kor Purificata",s="Una Gemma Kor Purificata è un raro cristallo consacrato richiesto dal fabbro d'armi Jordan Stilwell all'esterno di Forgiardente. Un tempo contaminata da oscure energie, deve essere recuperata dalle profondità di Kalimdor e purificata dalla magia elfica prima di poter essere forgiata in una sacra arma della Luce.",h="Una Gemma Kor Purificata è un raro cristallo consacrato richiesto dal fabbro d'armi Jordan Stilwell...",kw={"auberdine","abissi di fondocupo","gemma kor corrotta","dun morogh","jordan stilwell","gemma kor purificata","the test of righteousness","thundris windweaver"},ang={["class:Paladin"]="Ottenere e purificare questa gemma dimostra la devozione di un paladino, portandolo dalle profondità di Kalimdor di nuovo a Dun Morogh per forgiare un'iconica arma della Luce.",["faction:Alliance"]="Procurare la gemma purificata unisce gli sforzi in tutta l'Alleanza, affidandosi alla saggezza degli Elfi della Notte ad Auberdine per potenziare un fabbro umano al lavoro sulle pendici di Dun Morogh."},sec={{t="Dalla Corruzione alla Santità",b="La pietra inizia il suo viaggio come Gemma Kor Corrotta in possesso dei vili naga in agguato negli Abissi di Fondocupo, nelle profondità sotto la costa di Valtetra. Per purificare la pietra dalla sua contaminazione acquatica e oscura, un paladino deve cercare l'Elfo della Notte Thundris Windweaver ad Auberdine. Attingendo alle arti arcane e naturali, Thundris epura la corruzione dalla pietra, trasformandola nella radiosa Gemma Kor Purificata. Solo in questo stato incontaminato è adatta a fungere da condotto per il potere sacro."},{t="Il Capolavoro del Fabbro",b="All'esterno di Forgiardente, tra i dirupi innevati di Dun Morogh, il fabbro d'armi umano Jordan Stilwell richiede la gemma come componente fondamentale per forgiare un'arma magistrale. Avendo a lungo posseduto i progetti per un armamento degno della Mano d'Argento, Stilwell era privo dei materiali esotici per realizzare i suoi piani. La Gemma Kor Purificata, insieme alla Catasta di Legname di Quercia Scorzasecca e a un minerale raro, fornisce il nucleo spirituale necessario per incanalare la giusta ira del paladino."}},faq={{q="A cosa serve la Gemma Kor Purificata?",a="Viene portata al fabbro Jordan Stilwell, posizionato all'esterno dei Cancelli di Forgiardente a Dun Morogh. Stilwell usa la gemma santificata come componente essenziale per forgiare un'arma consacrata per un paladino che sta affrontando le sue prove.",al={"uso della gemma kor purificata","perché mi serve la gemma kor","a cosa serve la gemma kor"}},{q="Da dove proviene la gemma?",a="La pietra ha origine all'interno delle rovine sotterranee degli Abissi di Fondocupo lungo la costa di Valtetra, dove è custodita dai naga come artefatto corrotto.",al={"origine della gemma kor","dove si trova la gemma kor","chi rilascia la gemma kor"}},{q="Chi purifica la gemma?",a="Thundris Windweaver, uno studioso elfico residente nell'insediamento costiero di Auberdine a Darkshore, purifica le oscure energie dalla Gemma Kor Corrotta, ripristinandola a uno stato purificato.",al={"come purificare la gemma kor","chi purifica la gemma kor","thundris windweaver gemma kor"}},{q="Qualsiasi avventuriero può utilizzare la Gemma Kor Purificata?",a="La gemma è ricercata specificamente dai paladini che affrontano The Test of Righteousness. Jordan Stilwell riserva la sua maestria ai sacri guerrieri che gli portano il cristallo purificato insieme ad altri materiali rari.",al={"la gemma kor è solo per paladini","chiunque può usare la gemma kor purificata"}}},fx={a30b14db={q="Cos'è una Gemma Kor Purificata?",a="La Gemma Kor Purificata è un raro componente minerale santificato ripulito da un ripugnante contaminazione. Originariamente recuperata come una pietra corrotta detenuta dai naga negli Abissi di Fondocupo, è stata faticosamente ripulita dalla sua oscura influenza da Thundris Windweaver ad Auberdine in modo che le sue proprietà latenti possano essere sfruttate in sicurezza per opere sacre.",al={"cos'è la gemma kor purificata","significato gemma kor purificata","info gemma kor purificata"}}},fp="16,274,27.493.0,23.438.0,38.235.0,29.155.0,21.188.0,52.200.0"}
P.entries["item:putrid-claw"] = {n="Artiglio Putrido",s="Gli Artigli Putridi sono le mani in decomposizione mozzate dai non morti senza cervello che si aggirano nei boschi a ovest di Brill. Il Guardiamorte Dillinger li raccoglie come prova definitiva che l'avanzata della minaccia del Flagello vicino al vecchio ponte viene tenuta a bada.",h="Gli Artigli Putridi sono le mani in decomposizione mozzate dai non morti senza cervello che si aggirano nei...",kw={"a putrid task","brill","guardiamorte dillinger","artiglio putrido","ravaged corpse","rotting dead","flagello","radure di tirisfal"},ang={["race:Undead"]="Per i nuovi iniziati Reietti che lasciano Albamorta, eliminare questi membri senza cervello del Flagello è un tempestivo promemoria del fatto che la liberazione richiede una difesa costante contro i gusci privi di intelletto a cui un tempo somigliavano."},sec={{t="Trofeo dei senza cervello",b="Anche nella loro stessa terra d'origine, i Reietti non sono del tutto al sicuro dalla morsa del Re dei Lich. Sacche di membri senza cervello del Flagello — morti marcescenti e cadaveri martoriati — vagano regolarmente oltre i confini orientali verso le Radure di Tirisfal, ammassandosi lungo le strade e vicino al vecchio ponte a ovest di Brill. Per garantire la sicurezza dei viaggiatori e delle linee di rifornimento della guarnigione, le Guardiemorte mettono taglie su questi orrori vaganti. Un artiglio putrido mozzato funge da inconfondibile prova tangibile che un altro cadavere barcollante è stato abbattuto per sempre."}},faq={{q="A cosa servono gli artigli putridi?",a="Il Guardiamorte Dillinger di stanza a Brill li raccoglie come taglie per confermare che le reclute locali dei Reietti stiano sfoltendo il Flagello che si aggira per le Radure di Tirisfal.",al={"uso dell'artiglio putrido","perché raccogliere artigli putridi","chi vuole gli artigli putridi"}},{q="Da dove provengono gli artigli putridi?",a="Vengono raccolti dai morti marcescenti e dai cadaveri martoriati che vagano nei boschi infestati a ovest di Brill, in particolare vicino al vecchio ponte sul fiume.",al={"dove trovare gli artigli putridi","bottino artiglio putrido","bottino del morto marcescente"}},{q="Perché il Flagello si trova nelle Radure di Tirisfal?",a="In seguito alla devastazione di Lordaeron, i resti del Flagello senza cervello del Re dei Lich continuano a filtrare verso ovest attraverso i confini verso Tirisfal, minacciando strade e insediamenti a meno che non vengano costantemente abbattuti.",al={"perché ci sono zombi vicino a brill","flagello a tirisfal"}},{q="Perché i Reietti non lasciano semplicemente vagare i non morti senza cervello?",a="A differenza dei Reietti, che si sono liberati sotto la Regina Sylvanas e hanno riconquistato la propria volontà, i membri senza cervello del Flagello obbediscono solo a oscuri istinti o al persistente comando del Re dei Lich, attaccando a vista qualsiasi vivente o non morto libero.",al={"reietti contro zombi senza cervello","perché uccidere altri non morti"}}},fx={["37750c4d"]={q="Cos'è un Artiglio Putrido?",a="Un Artiglio Putrido è la mano mozzata e putrefatta di uno zombi senza mente appartenente al Flagello. Queste appendici in decomposizione vengono prese dai cadaveri che camminano che infestano le Radure di Tirisfal come prova della loro distruzione.",al={"cos'è l'artiglio putrido","info artiglio putrido","storia dell'artiglio putrido"}}},fp="11,231,22.526.0,31.161.0,32.141.0,38.203.0,59.211.0"}
P.entries["item:pyrewood-shackle"] = {n="Manette di Rovonero",s="I Ceppi di Rovonero sono vincoli incantati indossati dai tribolati abitanti di Rovonero nella parte meridionale della Selva Pinargento. Imbevute della strana magia dell'Arcimago Arugal, queste misteriose fasce sembrano svolgere un ruolo nell'oscuro destino che attanaglia i cittadini quando la notte cala sull'insediamento.",h="I Ceppi di Rovonero sono vincoli incantati indossati dai tribolati abitanti di Rovonero nella parte...",kw={"arugal","tessalba","moonrage","rovonero","mausolea","ceppo","selva pinargento","worgen"},ang={["class:Mage"]="I maghi che studiano l'opera di Arugal riconosceranno la sconsiderata applicazione della magia di trasmutazione e vincolante intessuta nell'acciaio comune.",["race:Undead"]="Gli studiosi dei Forsaken a Mausolea considerano la dilagante stregoneria di Arugal una grave minaccia per i propri confini, rendendo il recupero di questi vincoli incantati fondamentale per neutralizzare l'influenza di Forte di Zannascura."},sec={{t="La Magia Vincolante di Arugal",b="Il villaggio maledetto di Rovonero cela un inquietante segreto: di giorno, i suoi residenti conducono vite ordinarie apparendo come normali umani, ma il tramonto li muta in feroci worgen Moonrage. L'Arcimago Arugal vincolò questi abitanti con ceppi incantati come parte dei suoi contorti esperimenti con la stregoneria dei worgen. Dalar Tessalba, un ricercatore arcano dei Forsaken di stanza a Mausolea, studia questi ceppi per decifrare gli incantamenti che alimentano questa duplice esistenza. Raccogliendo e analizzando l'energia residua sulle fasce, Tessalba cerca una comprensione più profonda della magia di Arugal nella speranza di spezzare la morsa del folle arcimago sulla regione."}},faq={{q="A cosa servono i Ceppi di Rovonero?",a="Dalar Tessalba a Mausolea richiede questi ceppi per studiarne gli incantamenti. Assorbendone la magia, spera di svelare gli incantesimi dell'Arcimago Arugal e trovare un modo per smantellare l'influenza dell'arcimago nella Selva Pinargento.",al={"uso dei ceppi di rovonero","perché raccogliere i ceppi","ceppi di dalar tessalba"}},{q="Chi trasporta questi ceppi?",a="I ceppi sono portati dai maledetti residenti di Rovonero nella parte meridionale della Selva Pinargento, indossati durante la loro forma umana diurna e la loro trasformazione notturna in worgen Moonrage.",al={"chi rilascia i ceppi di rovonero","fonte dei ceppi","dove trovare i ceppi di rovonero"}},{q="Perché gli abitanti del villaggio si trasformano di notte?",a="L'Arcimago Arugal sottopose la popolazione di Rovonero a sconsiderati esperimenti magici e incantamenti. I ceppi mantengono un incantamento che consente loro di apparire come normali umani durante il giorno, per poi rivelare le loro forme feroci di worgen quando cala l'oscurità.",al={"perché rovonero si trasforma in worgen","maledizione di rovonero","segreto dei lupi mannari di rovonero"}},{q="Chi è Dalar Tessalba?",a="Dalar Tessalba è un mago dei Forsaken che risiede a Mausolea nella Selva Pinargento. Studia attivamente le anomalie arcane lasciate dall'Arcimago Arugal, concentrandosi sull'analizzare e spezzare le contorte maledizioni dell'arcimago.",al={"dalar tessalba","chi è dalar"}}},fx={b92f5faa={q="Cosa sono le Manette di Rovonero?",a="Le Manette di Rovonero sono un vincolo incantato legato agli sfortunati residenti di Rovonero nella Selva Pinargento meridionale. Imbevute della strana e sconsiderata stregoneria del folle mago Arci-Mago Arugal, queste manette svolgono un ruolo diretto nel legare gli abitanti alla sua volontà e nel mascherare l'oscura maledizione che li affligge.",al={"manette di rovonero","cosa sono le manette di rovonero"}},f6bcbb50={q="Da dove provengono le Manette di Rovonero e chi le ha create?",a="Queste manette incantate sono state forgiate e poste sugli abitanti del villaggio dall'Arci-Mago Arugal, il mago rinnegato di Dalaran che prese residenza a Forte di Zannascura. Arugal ha lanciato le manette sui contadini di Rovonero come parte dei suoi incantesimi contorti, tenendoli sotto il suo controllo mentre nascondeva la loro trasformazione lupina sotto un'illusione diurna di normale vita umana.",al={"chi ha creato le manette di rovonero","origine manette di rovonero","da dove provengono le manette"}},["98d012f7"]={q="Perché qualcuno vuole le Manette di Rovonero?",a="Dalar Tessalba, un ambizioso mago Rinnegato che conduce ricerche a Mausolea, cerca queste manette incantate per studiare la magia di Arugal. Sifonando la loro energia residua, Dalar spera di svelare lo strano incantesimo che fa apparire gli abitanti del villaggio umani di giorno e trasformarsi in voraci worgen Ira Lunare dopo il tramonto, cercando infine di smantellare gli incantesimi di Arugal.",al={"perché raccogliere le manette di rovonero","chi ha bisogno delle manette di rovonero","scopo delle manette di rovonero"}}},fp="16,302,22.656.1,36.232.0,27.194.1,40.256.1,24.223.0"}
P.entries["item:quinn-s-potion"] = {n="Pozione di Quinn",s="La Pozione di Quinn è una pozione ricostituente preparata dallo Speziale Renferrel a Mausolea. Viene distillata per stabilizzare e rivitalizzare il ferito Deathstalker Quinn Yorick a seguito di una disastrosa pattuglia di ricognizione a Selva Pinargento.",h="La Pozione di Quinn è una pozione ricostituente preparata dallo Speziale Renferrel a Mausolea.",kw={"speziale renferrel","deathstalker","podere di ivar","quinn yorick","pozione di quinn","mausolea","selva pinargento"},ang={["race:Undead"]="La Società degli Speziali Reali raramente spreca sforzi in semplici rimedi da campo, a meno che non preservino direttamente gli esploratori Reietti vitali per proteggere i confini di Selva Pinargento."},sec={{t="La cura di Renferrel",b="Dopo che il Deathstalker Quinn Yorick venne duramente percosso e inabilitato vicino al Podere di Ivar, la notizia raggiunse la Società degli Speziali Reali a Mausolea. Lo Speziale Renferrel preparò frettolosamente questo infuso specializzato per facilitare il recupero di Quinn. Sebbene Renferrel raramente lasci che le perdite minori sul campo lo distraggano dalle sue ricerche più grandiose e sinistre per Lady Sylvanas, fornì il ricostituente per rimettere in piedi l'esploratore ferito e renderlo in grado di viaggiare."}},faq={{q="A cosa serve la Pozione di Quinn?",a="La pozione è formulata per aiutare il recupero del Deathstalker Quinn Yorick, che giace ferito nei boschi settentrionali di Selva Pinargento. Berla ripristina abbastanza della sua vitalità da permettergli di viaggiare di nuovo.",al={"scopo pozione di quinn","cosa fa la pozione di quinn","perché creare la pozione di quinn"}},{q="Chi ha distillato questa pozione?",a="Lo Speziale Renferrel, un alchimista della Società degli Speziali Reali di stanza nelle cripte di Mausolea, ha preparato l'infuso.",al={"chi ha creato la pozione di quinn","chi l'ha distillata","pozione di renferrel"}},{q="Dove deve essere consegnata la pozione?",a="Deve essere portata a nord di Mausolea a Quinn Yorick, che si trova al riparo vicino alla fattoria conosciuta come il Podere di Ivar.",al={"dove porto la pozione","posizione di quinn","luogo di quinn yorick"}},{q="Perché Quinn Yorick aveva bisogno di una pozione?",a="Quinn faceva parte di una pattuglia di Deathstalker in ricognizione a nord di Selva Pinargento. Al Podere di Ivar gli esploratori furono attaccati dal ghoul Ivar the Foul, e Quinn fu lasciato gravemente ferito e bloccato lì.",al={"perché quinn è ferito","cosa è successo a quinn yorick","quinn ferito"}}},fx={["52098f03"]={q="Cos'è la Pozione di Quinn?",a="È un infuso ricostituente preparato dallo Speziale Renferrel a Mausolea. Formulato specificamente per aiutare lo scout ferito Quinn Yorick, la pozione fornisce la forza di cui ha bisogno per riprendersi dalle sue ferite e riguadagnare abbastanza mobilità per viaggiare.",al={"pozione di quinn","cos'è questa pozione","cos'è l'infuso di quinn"}}},fp="14,231,16.466.0,32.212.0,23.131.0,43.120.0,41.190.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Teschio di Ran Zannarossa",s="Il Teschio di Ran Zannarossa è un macabro trofeo preso al capotribù dei furbolg corrotti a Valtetra. Riportato agli elfi della notte di Astranaar, funge da prova tangibile che una feroce minaccia per il regno boscoso è stata sventata.",h="Il Teschio di Ran Zannarossa è un macabro trofeo preso al capotribù dei furbolg corrotti a Valtetra.",kw={"valtetra","astranaar","teschio di zannarossa","zannarossa","furbolg","raene braccalupo","raene's cleansing","ran zannarossa"},ang={["faction:Alliance"]="Consegnare questo macabro trofeo dimostra il valore dei campioni dell'Alleanza nel difendere i fragili confini di Valtetra al fianco delle Sentinelle.",["race:NightElf"]="Per gli elfi della notte, ottenere il teschio è una vittoria cupa. Sebbene renda onore al compito incompiuto di Teronis, è anche un promemoria di quanto profondamente la corruzione demoniaca abbia devastato i loro antichi alleati furbolg."},sec={{t="Un trofeo per la difesa di Valtetra",b="Le foreste di Valtetra hanno sofferto immensamente per la corruzione demoniaca e selvaggia, spingendo tribù di furbolg un tempo pacifiche verso una follia omicida. Tra i più feroci di questi capitribù ostili vi era Ran Bloodtooth. Recuperare il suo teschio fornisce alle Sentinelle degli elfi della notte la prova definitiva della caduta del bruto, spezzando la sua presa sui furbolg locali e offrendo un piccolo momento di tregua alla martoriata cittadina di Astranaar."},{t="Onorare i caduti",b="Una volta presentato alla Sentinella Raene Braccalupo ad Astranaar, il teschio segna la conclusione di un'indagine avviata dal caduto esploratore Teronis. Accanto alla Verga di Dartol, la verga ricostruita che Teronis era partito a cercare, il teschio di Ran Zannarossa viene esposto come testimonianza del coraggio di coloro che hanno combattuto per proteggere la sacra foresta."}},faq={{q="Chi era Ran Bloodtooth?",a="Ran Bloodtooth era un capotribù dei furbolg corrotti a Valtetra, considerato dalle Sentinelle degli elfi della notte come una delle minacce locali più feroci.",al={"chi è ran zannarossa","storia di ran zannarossa","chi era zannarossa"}},{q="Perché le Sentinelle vogliono il suo teschio?",a="Raene Braccalupo ad Astranaar riceve il teschio come prova della sconfitta di Ran Bloodtooth. Il teschio viene collocato accanto alla Verga di Dartol come simbolo di vittoria e ricordo di coloro che sono caduti difendendo Valtetra.",al={"perché serve il teschio","teschio raene braccalupo","a cosa serve il teschio"}},{q="Chi era Teronis?",a="Teronis era un vecchio amico di Raene Braccalupo che aiutava le Sentinelle a Valtetra. Era partito per trovare una gemma per una verga creata dal defunto mago Dartol, sperando potesse rallentare gli attacchi dei furbolg, ma fu ucciso dai murloc presso il Lago Falathim. Il suo compito è stato poi portato avanti da Raene Braccalupo e da avventurieri di passaggio.",al={"storia di teronis","chi è teronis","teronis astranaar"}}},fx={["4d0a3ce4"]={q="Cos'è il Teschio di Ran Zannarossa?",a="Questo è il teschio mozzato di Ran Zannarossa, una delle più feroci e pericolose minacce furbolg corrotte che infestano Valtetra. Preso come prova della sua sconfitta, segna la fine del terrore che ha portato contro le Sentinelle e la foresta.",al={"teschio di ran zannarossa","cos'è il teschio di ran","testa di ran zannarossa"}},f5c7858d={q="Da dove proviene il Teschio di Ran Zannarossa?",a="Il teschio viene reclamato direttamente da Ran Zannarossa dopo averlo ucciso a Valtetra. Non è un artefatto forgiato o creato da mani mortali, ma piuttosto il macabro trofeo ottenuto dal capotribù stesso.",al={"da dove viene il teschio di ran","chi ha creato il teschio di ran zannarossa","origine teschio di ran zannarossa"}}},fp="22,242,31.443.0,19.339.1,23.147.0,36.203.0,16.304.0"}
P.entries["item:raptor-head"] = {n="Testa di Raptor",s="Una testa mozzata di raptor funge da sanguinosa prova di una bestia abbattuta nelle Barrens. Gazrog di Crocevia richiede questi macabri trofei per epurare i branchi locali dopo un improbabile furto della paga delle guardie.",h="Una testa mozzata di raptor funge da sanguinosa prova di una bestia abbattuta nelle Barrens.",kw={"the barrens","crocevia","gazrog","testa di raptor","raptor thieves","argento rubato","sunscale"},ang={["class:Hunter"]="Seguire le tracce dei raptor Sunscale attraverso l'arida boscaglia delle Barrens mette alla prova l'abilità di un cacciatore nel superare in astuzia alcuni dei cacciatori da branco più aggressivi e scaltri della savana.",["faction:Horde"]="Crocevia è il cuore logistico dei viaggi dell'Orda nel centro di Kalimdor. Eliminare i predatori ladri mette al sicuro i rifornimenti e la paga della guarnigione."},sec={{t="Taglia di Crocevia",b="La vita nelle aride pianure delle Barrens è già abbastanza dura senza che la fauna locale assalti le torri dell'insediamento. Quando una cassa contenente la paga delle guardie è svanita dalla torre di guardia di Crocevia, i difensori hanno colto un colpevole improbabile sul fatto: un raptor selvaggio. Perplesso e furioso, Gazrog ha posto una taglia immediata sugli scaltri rettili che si aggirano per la savana. Riportare le teste di raptor mozzate all'avamposto dimostra che questi nocivi predatori vengono abbattuti prima che possano sottrarre altre provviste dell'Orda."}},faq={{q="Perché Gazrog vuole teste di raptor?",a="Una spedizione di argento destinata alla paga delle guardie di Crocevia è stata rubata direttamente dalla loro torre. Con incredulità di tutti, uno dei ladri colti sul fatto era un raptor. Gazrog vuole che le bestie vengano cacciate in tutte le Barrens, affinché non possano assalire di nuovo l'insediamento.",al={"perché raccogliere teste di raptor","gazrog raptor","taglia testa di raptor"}},{q="Perché dei raptor selvaggi dovrebbero rubare argento?",a="Gazrog ammette di non avere idea del perché delle bestie selvagge debbano avere interesse per le monete di metallo. Tuttavia, i raptor a Kalimdor sono famigerati per la loro inquietante astuzia, e l'incidente lascia le guardie di Crocevia sia imbarazzate che ansiose di vendetta.",al={"perché i raptor vogliono l'argento","raptor che rubano monete","mistero raptor thieves"}},{q="Quali raptor portano queste teste?",a="Le teste possono essere recuperate da vari raptor Sunscale che si aggirano nelle Barrens centrali e nelle Savane Meridionali, compresi Sunscale Lashtail, Screecher e Scytheclaw. Anche bestie famose come Ishamuhale e Takk the Leaper rilasciano teste.",al={"dove trovare teste di raptor","quali raptor rilasciano teste","raptor delle the barrens"}},{q="Cosa succede dopo aver consegnato le teste?",a="Una volta che Gazrog riceve dodici teste e vede ridotta la minaccia dei raptor, l'attenzione si sposta sulla ricerca del luogo in cui il carico di argento rubato è stato effettivamente portato.",al={"cosa segue raptor thieves","dopo aver raccolto teste di raptor"}}},fx={f6102aac={q="Cos'è una Testa di Raptor?",a="Una Testa di Raptor è il trofeo mozzato e la prova di taglia prelevati dai raptor che vagano nelle Barrens, inclusi i branchi locali dei Sunscale e bestie famigerate come Ishamuhale o Takk il Saltatore. Le autorità di Crocevia richiedono questi macabri pegni come prova verificabile che i predatori astuti che tormentano le loro linee di rifornimento e le guardie siano stati abbattuti.",al={"cos'è la testa di raptor","oggetto testa di raptor","cosa sono le teste di raptor"}},["377da5ba"]={q="Da dove proviene una Testa di Raptor?",a="Queste teste provengono direttamente dai raptor predatori che perseguitano le savane e le creste delle Barrens. I Sunscale Lashtail, gli Screecher, gli Scytheclaw e i noti cacciatori delle pianure le lasciano cadere una volta uccisi. Essendo resti biologici raccolti sul campo, non sono creati da nessuno, ma piuttosto reclamati come trofei di una caccia riuscita.",al={"da dove vengono le teste di raptor","origine testa di raptor","chi ha creato la testa di raptor"}}},fp="11,202,24.506.0,34.274.0,36.246.0,32.220.0,40.155.0"}
P.entries["item:rare-earth"] = {n="Terra Rara",s="La Terra Rara è un pacco speciale di terriccio ricco di minerali procurato da Darnassus per esperimenti botanici su Teldrassil. Viene inviato tramite corriere da Dolanaar al ricercatore erborista Denalan presso il suo accampamento sulle rive del Lago Al'ameth.",h="La Terra Rara è un pacco speciale di terriccio ricco di minerali procurato da Darnassus per esperimenti...",kw={"darnassus","denalan","dolanaar","erbalismo","lago al'ameth","terra rara","syral fogliaguzza"},ang={["profession:Herbalism"]="Gli erboristi apprezzeranno gli sforzi meticolosi di ricercatori come Syral Fogliaguzza e Denalan, che studiano come una terra specializzata possa alterare la crescita e le proprietà dei giovani alberi di Teldrassil.",["race:NightElf"]="Per gli elfi della notte che si prendono cura del loro giovane Albero del Mondo, ogni esperimento botanico presso il Lago Al'ameth offre preziose informazioni su come la vita si adatti ai rami incontaminati di Teldrassil."},sec={{t="Terriccio di Darnassus",b="Il recente ecosistema di Teldrassil richiede un'attenta osservazione e cura, spingendo gli erboristi di tutta l'isola a studiare come varie piante rispondano a terricci estranei o arricchiti. Questo particolare pacco di terra rara è stato richiesto direttamente da Darnassus da Denalan, un eccentrico botanico di stanza lungo la riva orientale del Lago Al'ameth. Dopo essere rimasto a lungo in transito ed essere arrivato in ritardo a Dolanaar, l'erborista Syral Fogliaguzza affida ai viaggiatori di passaggio verso sud il compito di consegnare il terriccio deperibile a Denalan prima che perda la sua efficacia."}},faq={{q="A cosa serve la Terra Rara?",a="La terra rara è destinata a Denalan, un erborista e ricercatore botanico accampato sulle rive del Lago Al'ameth. Egli utilizza composti minerali specializzati e terreni arricchiti importati da Darnassus per coltivare e condurre esperimenti sulla flora nativa di Teldrassil.",al={"uso di terra rara","cosa fa denalan con terra rara","scopo di terra rara"}},{q="Chi invia la Terra Rara a Denalan?",a="Syral Fogliaguzza, un'erborista che risiede nella città di Dolanaar, custodisce il pacco. Arrivato in ritardo da Darnassus, chiede agli avventurieri di passaggio diretti a sud verso il Lago Al'ameth di consegnarlo per suo conto.",al={"chi dà terra rara","dove trovare terra rara","pacco di syral fogliaguzza"}},{q="Perché Denalan era preoccupato per la consegna?",a="La spedizione ha subito ritardi durante il trasporto verso Dolanaar, costringendo Denalan ad attendere sulle rive del lago per un periodo considerevole. Dopo averla ricevuta, teme subito che la terra possa aver perso la sua freschezza e vitalità per i suoi esperimenti botanici.",al={"terra rara è rovinata","terra fresca denalan","perché terra in ritardo"}}},fx={e720b4cb={q="Cos'è la Terra Rara?",a="La Terra Rara è una spedizione di terreno fertile appositamente reperito e inviato da Darnassus. Viene accuratamente preparato e imballato per ricerche agricole e botaniche sensibili, conservando nutrienti specializzati che richiedono che venga consegnato fresco per mantenere la sua potenza per delicati esperimenti di coltivazione.",al={"cos'è la terra rara","oggetto terra rara","storia terra rara"}},["5312d2a9"]={q="Perché Denalan vuole la Terra Rara?",a="Denalan è un ricercatore erborista di stanza sulle rive orientali del Lago Al'ameth, che studia e sperimenta con la flora locale di Teldrassil. Si affida a questo terreno raro e ricco di nutrienti proveniente da Darnassus per nutrire le sue delicate piantagioni e far avanzare il suo lavoro botanico sull'isola.",al={"perché denalan vuole la terra rara","perché volere terra rara","perché serve la terra rara"}}},fp="10,233,17.537.0,28.252.0,36.208.0,43.244.0"}
P.entries["item:rattlecage-skull"] = {n="Teschio di Scuotiossa",s="I Teschi di Scuotiossa sono i resti infranti dei non morti privi di senno che vagano nelle periferie in rovina di Albamorta. I novizi stregoni Reietti devono raccogliere questi trofei calcificati per Venya Marthand per dimostrare la loro nascente forza di volontà e qualificarsi per le arti oscure dell'evocazione.",h="I Teschi di Scuotiossa sono i resti infranti dei non morti privi di senno che vagano nelle periferie in...",kw={"albamorta","evocazione dell'imp","piercing the veil","rattlecage skeleton","teschio di scuotiossa","radure di tirisfal","venya marthand"},ang={["class:Warlock"]="Per gli stregoni Reietti, raccogliere questi teschi rappresenta il traguardo iniziale della loro disciplina, dimostrando di possedere la fredda volontà necessaria per asservire il loro primo demone.",["race:Undead"]="L'atto di fare a pezzi scheletri inferiori e privi di pensiero sottolinea la convinzione dei Reietti di affermare il proprio dominio attraverso la pura forza di volontà, distinguendo i non morti dotati di libero arbitrio dai servi senza mente."},sec={{t="La prova di un neofita",b="Entro i confini privi di sole di Albamorta, i Reietti appena risvegliati con un'affinità per la magia oscura vengono guidati da Venya Marthand. Per dimostrare che un praticante alle prime armi possiede la fermezza necessaria a piegare creature extraplanari al proprio comando, Venya gli assegna il compito di sottomettere i Rattlecage Skeleton rimasti nei pressi della fucina in rovina. Abbattere questi non morti minori e recuperare i loro teschi recisi funge sia da prova pratica di disciplina sia da fondamento rituale prima di imparare a squarciare il vuoto e asservire un primo servitore demoniaco."}},faq={{q="A cosa servono i Teschi di Scuotiossa?",a="Vengono raccolti da Venya Marthand ad Albamorta. Gli stregoni Reietti devono portarle tre teschi per dimostrare la loro concentrazione e determinazione prima che ella insegni loro i riti per evocare e vincolare un imp.",al={"cosa sono i teschi di scuotiossa","uso del teschio di scuotiossa","chi vuole i teschi di scuotiossa"}},{q="Da dove provengono i Teschi di Scuotiossa?",a="Vengono presi dai resti infranti dei Rattlecage Skeleton, non morti privi di senno che vagano lungo le strade invase dalla vegetazione e i terreni fatiscenti vicino alla fucina abbandonata di Albamorta.",al={"dove trovare i teschi di scuotiossa","chi rilascia i teschi di scuotiossa","posizione del teschio di scuotiossa"}},{q="Perché Venya Marthand richiede teschi scheletrici per una prova da stregone?",a="Venya crede che il potere sfugga agli ignoranti e che la maestria richieda di piegare le forze esterne alla propria volontà. Uccidere gli scheletri privi di senno e reclamare le loro teste dimostra che un apprendista possiede la volontà fondamentale di controllare le energie caotiche anziché esserne consumato.",al={"perché teschi per gli stregoni","prova di venya marthand"}},{q="Quale conoscenza viene concessa dopo aver raccolto questi teschi?",a="Una volta offerti i teschi, Venya Marthand impartisce il rituale segreto necessario per richiamare e vincolare un imp, concedendo ai giovani stregoni il loro primo vero servitore demoniaco.",al={"cosa si ottiene dai teschi di scuotiossa","ricompensa di piercing the veil"}}},fx={["9627b388"]={q="Cos'è un Teschio di Scuotiossa?",a="Un Teschio di Scuotiossa è la testa mozzata di uno Scheletro Scuotiossa, uno dei non morti senza mente che vagano per i terreni devastati vicino alla forgia abbandonata di Albamorta. Per gli aspiranti stregoni dei Reietti, questi macabri trofei servono come prova di base di risolutezza e concentrazione magica, mostrando che un iniziato può affrontare e sconfiggere i morti che camminano.",al={"cos'è il teschio di scuotiossa","storia teschio di scuotiossa"}}},fp="16,267,17.530.0,36.202.0,37.169.0,68.285.0,55.164.0"}
P.entries["item:raven-claw-talisman"] = {n="Talismano Artiglio del Corvo",s="Il Talismano Artiglio del Corvo è una sacra reliquia degli elfi della notte legata ai Druidi dell'Artiglio. Custodito nelle profondità dell'Eremo di Ban'ethil su Teldrassil, è una delle quattro Relics of Wakening essenziali necessarie per ricondurre in sicurezza i druidi dormienti dal Sogno di Smeraldo.",h="Il Talismano Artiglio del Corvo è una sacra reliquia degli elfi della notte legata ai Druidi dell'Artiglio.",kw={"athridas orsomanto","ban'ethil","eremo","dolanaar","druidi dell'artiglio","talismano artiglio del corvo","reliquie del risveglio","teldrassil"},ang={["class:Druid"]="Il talismano è un emblema dei Druidi dell'Artiglio, che illustra come i catalizzatori rituali proteggano lo spirito di un druido durante il suo vagare nel Sogno di Smeraldo.",["race:NightElf"]="Recuperare questa reliquia protegge sia l'antica tradizione degli elfi della notte, sia le vite dei fratelli dormienti minacciati dalla follia dei Gnarlpine furbolgs."},sec={{t="Una chiave per il risveglio",b="Il Talismano Artiglio del Corvo è conservato all'interno di una specifica cassa all'interno dell'Eremo di Ban'ethil, il santuario sotterraneo dove i Druidi dell'Artiglio di Teldrassil entravano nei loro profondi sonni meditativi. Il letargo druidico è una delicata soglia spirituale. Se il legame di un druido con il mondo della veglia viene spezzato senza il dovuto focus cerimoniale, il suo spirito rischia di rimanere bloccato nel Sogno di Smeraldo per sempre. Insieme alla Piuma Nera, allo Zaffiro del Cielo e alla Runa della Nidificazione, il talismano è richiesto da Athridas Orsomanto a Dolanaar per officiare il rituale del risveglio e riportare i dormienti indietro in sicurezza."},{t="La minaccia nell'Eremo",b="Quando i corrupted Gnarlpine furbolgs hanno invaso l'Eremo di Ban'ethil, le casse sacre e i druidi dormienti si sono trovati in immediato pericolo. La profanazione dei furbolg ha isolato il santuario dagli aiuti esterni, mettendo le reliquie a rischio di perdita o distruzione. Athridas Orsomanto affida ai difensori di Teldrassil il compito di sfidare i tortuosi cunicoli di terra dell'antro per recuperare il Talismano Artiglio del Corvo prima che i druidi assopiti siano perduti nel Sogno per sempre."}},faq={{q="A cosa serve il Talismano Artiglio del Corvo?",a="È una delle quattro sacre Relics of Wakening necessarie per compiere il rituale che ridesta i Druidi dell'Artiglio dal loro profondo letargo nel Sogno di Smeraldo.",al={"a cosa serve il talismano artiglio del corvo","scopo del talismano artiglio del corvo","perché serve il talismano artiglio del corvo"}},{q="Dove si trova il Talismano Artiglio del Corvo?",a="Riposa all'interno della Chest of the Raven Claw, situata tra i tunnel di terra dell'Eremo di Ban'ethil, a ovest di Dolanaar su Teldrassil.",al={"dove si trova il talismano artiglio del corvo","posizione cassa dell'artiglio del corvo","come trovare il talismano artiglio del corvo"}},{q="Chi ha bisogno del Talismano Artiglio del Corvo?",a="Athridas Orsomanto, un druido elfo della notte di stanza a Dolanaar, richiede il talismano per preparare i riti del risveglio per i suoi confratelli.",al={"chi vuole il talismano artiglio del corvo","chi prende il talismano artiglio del corvo","a chi si consegna"}},{q="Perché i druidi non possono svegliarsi senza di esso?",a="L'accesso al Sogno di Smeraldo attraverso il letargo druidico comporta una trance complessa e delicata. Senza il catalizzatore specifico delle Relics of Wakening per ancorare il rituale del risveglio, lo spirito di un dormiente rischia di rimanere perduto nel Sogno a tempo indefinito.",al={"perché ai druidi servono le reliquie per svegliarsi","perché le reliquie del risveglio","i druidi possono svegliarsi senza reliquie"}}},fx={["33636b37"]={q="Cos'è il Talismano Artiglio del Corvo?",a="Il Talismano Artiglio del Corvo è una delle quattro sacre Reliquie del Risveglio custodite dai Druidi dell'Artiglio. Conservato all'interno di uno scrigno dedicato nell'Eremo di Ban'ethil, è un componente essenziale del delicato rituale necessario per richiamare in sicurezza i druidi dormienti dal loro letargo nel Sogno di Smeraldo.",al={"cos'è il talismano artiglio del corvo","info talismano artiglio del corvo","reliquia talismano artiglio del corvo"}}},fp="19,260,18.627.0,28.447.0,41.158.0,39.135.0,34.136.0,40.243.0"}
P.entries["item:razorflank-s-medallion"] = {n="Medaglione di Fiancospino",s="Il Medaglione di Fiancospino è un pegno personale portato da Charlga Fiancospino, la megera che governa le Gallerie di Lamaspina. Recuperato dal cuore della roccaforte dei verrospino, funge da prova innegabile della caduta della matriarca.",h="Il Medaglione di Fiancospino è un pegno personale portato da Charlga Fiancospino, la megera che governa le...",kw={"agamaggan","charlga fiancospino","falfindel waywarder","lonebrow","gallerie di lamaspina","medaglione di fiancospino","thalanaar"},ang={["faction:Alliance"]="Recuperare il medaglione vendica l'esploratore caduto Heralath e l'esploratore nano Lonebrow, mettendo in sicurezza la via di confine di Thalanaar verso Feralas.",["race:NightElf"]="Uccidere Charlga e rivendicare il suo medaglione consente agli elfi della notte di studiare in sicurezza il sacro luogo di riposo corrotto di Agamaggan."},sec={{t="Prova della caduta della megera",b="Portato da Charlga Fiancospino in persona, questo medaglione rappresenta l'autorità della megera a capo dei verrospino di Lamaspina. Quando Falfindel Waywarder a Thalanaar apprende la sorte degli esploratori caduti come Heralath e il nano Lonebrow, incarica gli avventurieri dell'Alleanza di colpire direttamente la guida dei verrospino. Presentare il medaglione della megera conferma la sua morte, rassicurando le sentinelle elfe della notte a guardia dei confini di Feralas sul fatto che le forze radunate all'interno delle Gallerie hanno perso la loro guida."}},faq={{q="Chi porta il Medaglione di Fiancospino?",a="Il medaglione appartiene a Charlga Fiancospino, la megera e leader indiscussa dei verrospino all'interno delle Gallerie di Lamaspina. Lo porta con sé nel profondo degli spinosi labirinti della roccaforte.",al={"chi rilascia il medaglione di fiancospino","fonte medaglione di fiancospino","medaglione di charlga"}},{q="A chi deve essere portato questo medaglione?",a="Falfindel Waywarder, di stanza all'avamposto di confine di Thalanaar tra Feralas e Millepicchi, chiede il medaglione. Lo cerca come prova definitiva dell'uccisione di Charlga.",al={"chi vuole il medaglione di fiancospino","consegna medaglione di fiancospino","medaglione di falfindel"}},{q="Perché Falfindel ha bisogno della prova della morte di Charlga?",a="Charlga stava radunando una forza ostile di verrospino all'interno delle Gallerie di Lamaspina, minacciando le regioni circostanti e provocando la morte di esploratori come Heralath e Lonebrow. Riportare il medaglione assicura agli elfi della notte che la minaccia immediata è stata sventata e consente alle loro indagini nell'area di continuare.",al={"perché uccidere charlga","scopo del medaglione","perché serve il medaglione"}}},fx={b119a669={q="Cos'è il Medaglione di Fiancospino?",a="Il Medaglione di Fiancospino è un pegno personale portato da Charlga Fiancospino, la vecchia e leader dei quilboar che dimorano nelle profondità delle Gallerie di Lamaspina. Più che un semplice ornamento, funge da inconfondibile simbolo della sua autorità sulle tribù brulicanti nelle Gallerie, rendendolo il trofeo definitivo della sua caduta.",al={"cos'è il medaglione di fiancospino","storia medaglione di fiancospino","medaglione di charlga fiancospino"}}},fp="22,236,25.503.0,35.199.0,41.189.0,49.322.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Reagent Pouch (shaman)",s="Una borsa dei reagenti trasportata dai cultisti delle Lame Ardenti in agguato tra i dirupi di Durotar. Gli sciamani che cercano di comunicare con il fuoco necessitano di questi componenti d'incantesimo raccolti per distillare la loro prima Sapta di Fuoco.",h="Una borsa dei reagenti trasportata dai cultisti delle Lame Ardenti in agguato tra i dirupi di Durotar.",kw={"lame ardenti","call of fire","durotar","grotta di ventolordo","sapta di fuoco","totem del fuoco","borsa dei reagenti","telf joolam"},ang={["class:Shaman"]="Il recupero della borsa è un fondamentale rito di passaggio sul cammino per ottenere il tuo Totem del Fuoco, insegnando che persino i tramiti elementali corrotti possono essere purificati per servire l'equilibrio.",["class:Warlock"]="Le borse riflettono le forniture magiche standard trasportate dai cultisti vili, contenendo elementi rituali destinati alla piromanzia demoniaca piuttosto che alla comunione con la natura."},sec={{t="Componenti della Fiamma",b="Per forgiare una Sapta di Fuoco e sintonizzare un giovane sciamano con gli spiriti della fiamma, catalizzatori rituali specifici sono vitali. I cultisti delle Lame Ardenti trasportano piccole sacche rifornite di reagenti adatti alle evocazioni del fuoco demoniaco. L'eremita Telf Joolam utilizza queste polveri e questi oli raccolti, combinati con il Catrame di Fuoco dei verrospini Razormane, per creare la pozione necessaria a conferire la vista nel regno del fuoco."},{t="Fonti Corrotte, Visione Pura",b="Sebbene le Lame Ardenti pervertano la fiamma a fini di distruzione e stregoneria vile, gli elementi fisici all'interno delle loro borse rimangono legati alla natura primordiale del calore e della combustione. La filosofia sciamanica sostiene che tutte le forze elementali esistano in tensione: il fuoco è sia creatore che distruttore. Impadronendosi degli strumenti rubati dai cultisti, uno sciamano rivendica il tramite elementale per risvegliare un'autentica comunione con gli spiriti."}},faq={{q="A cosa serve la borsa dei reagenti?",a="Serve come materiale essenziale affinché Telf Joolam possa preparare una Sapta di Fuoco. Bere questo elisir conferisce a uno sciamano la vista chiaroveggente necessaria per cercare gli spiriti elementali e reclamare il proprio Totem del Fuoco.",al={"uso della borsa dei reagenti","a cosa serve la borsa dei reagenti","missione sciamano borsa dei reagenti"}},{q="Dove trovo una borsa dei reagenti?",a="La borsa si recupera dai cultisti delle Lame Ardenti annidati all'interno della Grotta di Ventolordo, situata sulle alture rocciose a nord-est di Tranciacolle a Durotar.",al={"bottino borsa dei reagenti","dove trovare la borsa dei reagenti","posizione borsa delle lame ardenti"}},{q="Perché uno sciamano ha bisogno di reagenti da stregone?",a="Le Lame Ardenti riforniscono le loro borse con ingredienti intrisi di magia del fuoco. Poiché i loro rituali dipendono fortemente dalla fiamma, i loro reagenti forniscono catalizzatori elementali pronti all'uso che possono essere riutilizzati per preparare la Sapta di Fuoco.",al={"perché oggetti da stregone","perché reagenti delle lame ardenti","sciamano che usa oggetti vili"}}},fx={ad39cae0={q="Cos'è la Borsa dei Reagenti?",a="È una piccola borsa portata dai cultisti delle Lame Ardenti, piena di erbe rituali, ceneri e catalizzatori occulti che usano per alimentare i loro incantesimi oscuri. Sebbene destinata alla stregoneria oscura, l'elevata concentrazione di componenti infuocati rende l'intera borsa un potente fascio di materiali elementali grezzi.",al={"cos'è la borsa dei reagenti","storia borsa dei reagenti","borsa dei reagenti lame ardenti"}},["2a611680"]={q="Da dove proviene la Borsa dei Reagenti?",a="Le borse sono assemblate e portate dai cultisti delle Lame Ardenti che si nascondono nelle caverne di Durotar e delle Barrens. Questi stregoni raccolgono e conservano componenti specifici necessari per i loro riti distruttivi, tenendoli a portata di mano ogni volta che lanciano magie di fuoco e Shadow Magic.",al={"origine borsa dei reagenti","chi ha creato la borsa dei reagenti","da dove viene la borsa dei reagenti"}}},fp="22,197,23.400.0,28.406.0,35.198.0,32.145.0,40.224.0"}
P.entries["item:reconstructed-tome"] = {n="Tomo Ricostruito",s="Il Tomo Ricostruito è un grimorio ricomposto di oscure conoscenze della cabala, compilato per gli stregoni che cercano di espandere il proprio controllo sui servitori demoniaci. Contiene la conoscenza arcana e i rituali necessari per evocare e vincolare un predatore felhunter dalla Distorsione Fatua.",h="Il Tomo Ricostruito è un grimorio ricomposto di oscure conoscenze della cabala, compilato per gli stregoni...",kw={"vincolo","fauce del drago","felhunter","porto paranco","tomo ricostruito","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Assemblare il Tomo Ricostruito è un rito di passaggio essenziale, che sblocca gli oscuri riti necessari per dominare un felhunter e rivolgere il suo appetito divoratore di magia contro gli incantatori avversari."},sec={{t="Un grimorio riassemblato",b="Recuperato in frammenti e faticosamente ricomposto, il Tomo Ricostruito rappresenta una sfuggente collezione di insegnamenti della cabala formalmente nota come Tome of the Cabal. Gli stregoni sia dell'Alleanza che dell'Orda fanno grandi sforzi per restaurare le sue pagine logore, consultando studiosi dell'occulto desiderosi di dare anche solo una rapida occhiata ai suoi contenuti esoterici prima di consegnare il manoscritto completato."},{t="La chiave per il felhunter",b="L'opera ricostruita viene portata a Strahad Farsan, un esperto maestro delle evocazioni di stanza vicino al porto di Porto Paranco nelle Barrens. Accompagnati da verghe arcane d'incanalamento strappate agli incantatori Fauce del Drago, i rituali descritti all'interno del tomo forniscono le incantazioni esatte necessarie affinché la cerchia di accoliti di Strahad aiuti uno stregone a evocare, sconfiggere e vincolare un famelico felhunter alla propria volontà."}},faq={{q="A cosa serve il Tomo Ricostruito?",a="Il libro contiene oscuri rituali e insegnamenti della cabala necessari per evocare e sottomettere un felhunter. Uno stregone lo consegna insieme a delle verghe d'incanalamento a Strahad Farsan a Porto Paranco per preparare il rituale di vincolo.",al={"scopo del tomo ricostruito","perché serve il tomo ricostruito","uso del tomo ricostruito"}},{q="Chi è Strahad Farsan?",a="Strahad Farsan è un esperto evocatore che dimora sopra la città portuale di Porto Paranco nelle Barrens. Sovrintende alle impegnative prove degli aspiranti stregoni che cercano di asservire entità demoniache più pericolose.",al={"chi è strahad","ruolo di strahad farsan"}},{q="Perché gli studiosi che esaminano il libro ne vogliono una copia?",a="Gli studiosi che aiutano a decifrare le pagine strappate trovano i testi occulti della cabala estremamente affascinanti e rari. Sia i ricercatori nani che quelli Reietti trovano il loro materiale di lettura abituale scarno in confronto e bramano la rara conoscenza demoniaca preservata nelle pagine.",al={"chi l'ha tradotto","studiosi tomo ricostruito"}},{q="Cos'altro serve insieme al tomo per il rituale?",a="Strahad richiede tre verghe d'incanalamento per consentire ai suoi accoliti di sostenere il rituale di evocazione. Queste verghe devono essere sottratte agli incantatori Fauce del Drago trincerati nelle Wetlands.",al={"altri oggetti necessari","cosa serve insieme al tomo ricostruito"}}},fx={a9385a16={q="Cos'è il Tomo Ricostruito?",a="Il Tomo Ricostruito è la versione riassemblata del Tome of the Cabal, un grimorio proibito contenente rituali demoniaci esoterici. Dopo che le sue pagine sparse e i materiali di rilegatura sono stati raccolti da tutto il mondo, gli studiosi riassemblano minuziosamente il testo frammentato in modo che la sua oscura conoscenza possa essere decifrata e messa in uso.",al={"cos'è il tomo ricostruito","storia tomo ricostruito","libro tome of the cabal"}},d276d405={q="Da dove proviene il Tomo Ricostruito e chi l'ha creato?",a="Il libro è la forma recuperata dell'antico Tome of the Cabal. Gli studiosi stregoni riassemblano i suoi capitoli strappati e la rilegatura logora dopo che praticanti avventurosi recuperano i suoi componenti sparsi da luoghi pericolosi in tutti i continenti.",al={"origine tomo ricostruito","chi ha creato il tomo ricostruito","da dove viene il tomo ricostruito"}},["04500ccd"]={q="Perché il Tomo Ricostruito è ricercato?",a="Stregoni e studiosi oscuri cercano il tomo per i segreti potenti e proibiti registrati nelle sue pagine recuperate. Strahad Farsan richiede i suoi riti specifici per guidare un aspirante stregone nell'evocazione e nel legame di un feroce felhunter demoniaco, mentre gli studiosi locali desiderano una copia puramente per la sua rara e affascinante conoscenza magica.",al={"perché volere il tomo ricostruito","perché strahad vuole il tomo ricostruito","scopo del tomo ricostruito"}}},fp="18,269,22.395.0,20.401.1,40.208.0,22.198.0,51.264.0,54.179.0"}
P.entries["item:recruitment-letter"] = {n="Lettera di Reclutamento",s="La Lettera di Reclutamento è un dispaccio ufficiale consegnato ad avventurieri promettenti in partenza da Durotar per prestare servizio nelle Barrens. Rilasciata dall'esploratore Takrin Trovapista, ordina ai volontari abili di fare rapporto all'avamposto di confine sorvegliato da Kargal Sfregiofondo.",h="La Lettera di Reclutamento è un dispaccio ufficiale consegnato ad avventurieri promettenti in partenza da...",kw={"the barrens","recluta dell'orda","crocevia","kargal sfregiofondo","tranciacolle","lettera di reclutamento","takrin trovapista"},ang={["faction:Horde"]="Portare con sé questa lettera rappresenta per una recluta la transizione dalla difesa locale a Durotar al servizio militare attivo lungo la frontiera di Kalimdor.",["race:Orc"]="Per i giovani orchi, presentare una lettera di servizio firmata a un veterano come Kargal Sfregiofondo è un passo iniziale fondamentale per guadagnare l'onore sotto la nuova Orda del Capoguerra Thrall."},sec={{t="Arruolamento per la Frontiera",b="Mentre giovani guerrieri ed esploratori danno prova del loro valore nei dintorni di Tranciacolle, lo sguardo dell'Orda si volge a ovest verso la vasta e selvaggia distesa delle Barrens. Takrin Trovapista individua le reclute promettenti che sembrano abbastanza forti da affrontare il servizio in prima linea e consegna loro questa lettera. Attraversare il ponte sul Fiume Furialunga segna un rito di passaggio: lasciarsi alle spalle la protetta terra rossa di Durotar per unirsi ai ranghi dell'Orda a guardia contro verrospini, centauri ed esploratori dell'Alleanza."},{t="Rapporto a Sfregiofondo",b="Il destinatario designato della lettera è Kargal Sfregiofondo, il veterano brizzolato che gestisce l'avamposto appena oltre il fiume. Kargal valuta ciascun coscritto prima di approvarne formalmente l'arruolamento. Tuttavia, essere in possesso di questa lettera è solo il primo passo; gli avamposti di frontiera sono perennemente a corto di effettivi, e ogni recluta confermata viene rapidamente reindirizzata più a ovest verso il fulcro strategico di Crocevia."}},faq={{q="Chi ha scritto questa lettera di reclutamento?",a="La lettera viene consegnata da Takrin Trovapista, un esploratore orco di stanza lungo la strada che esce da Tranciacolle, incaricato di individuare reclute capaci dirette a ovest.",al={"chi consegna la lettera di reclutamento","chi l'ha scritta","lettera di takrin trovapista"}},{q="Dove deve andare questa lettera?",a="La consegni a Kargal Sfregiofondo presso la postazione di guardia orchesca situata appena oltre il ponte sul Fiume Furialunga, proprio al confine tra Durotar e The Barrens.",al={"dove portare la lettera di reclutamento","consegnare lettera di reclutamento","a chi consegnarla"}},{q="Cosa succede una volta firmata la lettera?",a="Kargal firma il documento per ufficializzare il tuo arruolamento, ma ti ordina immediatamente di addentrarti nelle pianure per fare rapporto a Crocevia, dove sono urgentemente richiesti rinforzi.",al={"cosa succede dopo la firma di kargal","missione successiva a lettera di reclutamento"}},{q="Perché l'Orda sta reclutando avventurieri nelle Barrens?",a="The Barrens è un territorio sterminato e pericoloso che collega i principali insediamenti dell'Orda. Con le costanti minacce da parte dei clan centauro autoctoni, dei verrospini Bristleback aggressivi e delle operazioni dell'Alleanza, i comandanti in prima linea hanno bisogno di ogni braccio abile possibile.",al={"perché stanno reclutando","perché la coscrizione nelle barrens"}}},fx={e6a35429={q="Cos'è la Lettera di Reclutamento?",a="La Lettera di Reclutamento è un documento ufficiale di coscrizione rilasciato ad avventurieri capaci a Durotar. Lo Scout Takrin Trovapista la consegna a coloro che sembrano abbastanza forti da assistere la crescente presenza dell'Orda nella dura frontiera delle Barrens, raccomandandoli ai comandanti degli avamposti militari.",al={"cos'è la lettera di reclutamento","scopo lettera di reclutamento","cos'è questa lettera"}},["6a5949ec"]={q="Perché Kargal Sfregiofondo vuole la Lettera di Reclutamento?",a="Kargal Sfregiofondo comanda l'avamposto di frontiera che protegge il ponte verso le Barrens e ha un disperato bisogno di reclute capaci per rafforzare la frontiera. La lettera firmata verifica che sei stato esaminato dallo Scout Takrin Trovapista e sei pronto per essere assegnato dove l'Orda ha più bisogno di te.",al={"perché kargal vuole la lettera","perché consegnare la lettera di reclutamento","lettera di reclutamento consegnata"}}},fp="18,253,27.482.0,23.395.0,34.157.0,34.152.0,39.187.0,57.256.0"}
P.entries["item:red-burlap-bandana"] = {n="Bandana Avvolta Rossa",s="Le Bandane Avvolte Rosse sono le grezze maschere di stoffa tinta indossate da briganti e borsaioli di basso rango della Fratellanza dei Defias. Nella Valle della Contea del Nord, il Deputy Willem raccoglie questi pezzi di stoffa come prova dell'uccisione dei ladri che sconfinano vicino ai vigneti dell'abbazia.",h="Le Bandane Avvolte Rosse sono le grezze maschere di stoffa tinta indossate da briganti e borsaioli di basso...",kw={"bandana","brotherhood of thieves","defias","maschera","contea del nord","bandana avvolta rossa","willem"},ang={["class:Rogue"]="Per un ladro alle prime armi, strappare maschere rosse ai maldestri furfanti della Contea del Nord è una lezione su quanto rapidamente i fuorilegge indisciplinati si trasformino in facili bersagli per le guardie locali.",["faction:Alliance"]="La diffusione di queste bandane rosse fino alla porta dell'Abbazia della Contea del Nord dimostra quanto gravemente i confini rurali del regno stiano sfuggendo al controllo di Roccavento."},sec={{t="Un segno della Fratellanza",b="Indossata sulla parte inferiore del viso, la Bandana Avvolta Rossa funge da distintivo di riconoscimento per i membri comuni della Fratellanza dei Defias. Realizzata con tessuto ruvido ed economico immerso in tintura rossa, la stoffa cela i lineamenti del ladro segnalando al contempo la sua fedeltà alla crescente ribellione. Nella Contea del Nord, giovani reclute e comuni tagliagole portano queste sciarpe nei frutteti orientali, ignari che le guardie locali usino la vistosa stoffa rossa come macabro contrassegno per le taglie."}},faq={{q="Perché il Deputy Willem vuole queste bandane?",a="Il Deputy Willem raccoglie le bandane come prova tangibile che un avventuriero ha eliminato i teppisti dei Defias che sconfinano oltre il fiume vicino all'Abbazia della Contea del Nord. Poiché i ladri indossano apertamente la stoffa rossa, consegnarle funge da conferma per le taglie pagate sui briganti locali.",al={"perché raccogliere le bandane","bandane willem","consegna brotherhood of thieves"}},{q="Chi indossa le Bandane Avvolte Rosse?",a="Sono indossate da furfanti e tagliagole affiliati alla Fratellanza dei Defias, una banda di fuorilegge organizzati attiva in tutta la Foresta di Elwynn e nelle Marche Occidentali. Il grezzo tessuto rosso funge sia da travestimento sia da emblema di lealtà verso la loro gilda clandestina.",al={"chi indossa la bandana rossa","storia maschera defias","chi rilascia le bandane rosse"}},{q="Perché i ladri Defias operano nella Contea del Nord?",a="Esploratori e briganti dei Defias hanno allestito accampamenti oltre il ruscello a est dell'Abbazia della Contea del Nord per frugare in cerca di provviste e rubarle. Il presidio dell'abbazia è a corto di effettivi, consentendo a briganti di basso livello di aggirarsi per i frutteti vicini.",al={"perché i defias si trovano nella contea del nord","ladri vicino all'abbazia"}},{q="Cosa rende rosse le bandane?",a="Le bandane sono semplicemente pezzi di iuta economica trattati con tintura cremisi. Il colore caratteristico funge da stendardo e uniforme ufficiale della Fratellanza dei Defias, garantendo che i compagni si riconoscano a vicenda sul campo.",al={"perché le maschere defias sono rosse","significato stoffa rossa"}}},fx={c4ebebb0={q="Cos'è una Bandana Avvolta Rossa?",a="Una Bandana Avvolta Rossa è la maschera di stoffa distintiva indossata dai membri della Fratellanza dei Defias. Realizzata a buon mercato con ruvida iuta e tinta di rosso, nasconde il volto di chi la indossa e segna la loro lealtà alla gilda dei fuorilegge. Nella Contea del Nord, funge da prova diretta della presenza e dell'attività di un delinquente a est del fiume.",al={"identità bandana avvolta rossa","cosa sono le bandane rosse","storia bandana defias"}}},fp="18,254,25.446.0,43.285.0,34.248.0,47.223.0,28.221.0"}
P.entries["item:red-leather-bandana"] = {n="Bandana di Cuoio Rossa",s="Un caratteristico capo d'abbigliamento indossato dai membri della Fratellanza dei Defias in tutte le Marche Occidentali. Realizzato in cuoio tinto cremisi, funge sia da pratico coprivolto sia da inconfondibile simbolo di sfida contro la Corona di Roccavento.",h="Un caratteristico capo d'abbigliamento indossato dai membri della Fratellanza dei Defias in tutte le Marche...",kw={"fratellanza","defias","galiaan","maschera","bandana di cuoio rossa","guardiacolle","marche occidentali"},ang={["class:Rogue"]="La maschera cremisi è sinonimo di banditismo clandestino nelle terre degli umani, un emblema inconfondibile di ladri organizzati con precisione militare.",["faction:Alliance"]="Ogni bandana rossa strappata a un fuorilegge caduto segna un brigante in meno a minacciare i contadini affamati e la milizia assediata delle Marche Occidentali."},sec={{t="Marchio della Fratellanza",b="Tra i campi polverosi e le fattorie abbandonate delle Marche Occidentali, queste bandane cremisi celano i volti di briganti della strada, saccheggiatori e braccianti ribelli. Per The People's Militia di stanza a Guardiacolle, questo copricapo è più di un semplice pezzo di stoffa: è la prova tangibile della fedeltà alla confraternita ribelle di Edwin VanCleef. L'Esploratore Galiaan raccoglie queste bandane dagli avventurieri di passaggio per monitorare gli spostamenti e il calo del numero dei membri della fratellanza in tutta la regione."}},faq={{q="Perché i Defias indossano bandane di cuoio rosse?",a="La bandana rossa funge da divisa comune della Fratellanza dei Defias. Cela le loro identità durante gli assalti a fattorie e strade, dichiarando apertamente la loro fedeltà all'insurrezione di Edwin VanCleef contro Roccavento.",al={"maschera defias","perché bandana rossa","significato bandana defias"}},{q="Chi richiede la raccolta di queste bandane nelle Marche Occidentali?",a="L'Esploratore Galiaan, di stanza con The People's Militia a Guardiacolle, chiede ai viaggiatori di raccoglierle. Le usa per tracciare i movimenti delle truppe della banda e confermare l'uccisione dei banditi erranti.",al={"chi prende le bandane rosse","missione bandana galiaan","consegna bandana guardiacolle"}},{q="Dove si trovano queste bandane?",a="Possono essere recuperate da quasi ogni furfante, brigante della strada o contrabbandiere al servizio della Fratellanza dei Defias tra accampamenti, campi e miniere delle Marche Occidentali.",al={"bottino bandana rossa","farmare bandane rosse","chi rilascia bandana di cuoio rossa"}}},fp="19,236,23.473.1,44.220.1,47.184.0,31.139.0"}
P.entries["item:red-linen-bandana"] = {n="Red Linen Bandana",s="Una Red Linen Bandana è la caratteristica maschera facciale indossata dai membri della Fratellanza dei Defias in tutta la Foresta di Elwynn. Oltre a nascondere l'identità di un bandito, la stoffa è tessuta con lino di qualità che gli intraprendenti abitanti del luogo spesso riutilizzano per realizzare utili indumenti.",h="Una Red Linen Bandana è la caratteristica maschera facciale indossata dai membri della Fratellanza dei Defias...",kw={"maschera defias","vallevante","foresta di elwynn","lino","red linen bandana","sara timberlain"},ang={["class:Rogue"]="Una stoffa cremisi legata sulla parte inferiore del viso è diventata l'iconico aspetto di briganti e borseggiatori in tutti i boschi che circondano la capitale.",["profession:Tailoring"]="Le bandane illustrano quanto il lino grezzo rimanga prezioso nella zona rurale di Elwynn, dove i comuni tessitori riutilizzano i colori dei banditi per farne abiti da lavoro."},sec={{t="Marchio dei Defias",b="Mentre gli iniziati di rango inferiore e i semplici teppisti nella Valle della Contea del Nord si accontentano di maschere facciali di ruvida tela di sacco, gli operativi a tutti gli effetti dei Defias in tutta la Foresta di Elwynn indossano Red Linen Bandana tessute. Il tessuto cremisi brillante funge sia da divisa sia da dichiarazione di fedeltà alla confraternita di canaglie di Edwin VanCleef, celando i volti e segnalando al contempo l'insurrezione contro la corona di Roccavento."},{t="Stoffa riutilizzata",b="Nonostante le loro associazioni violente, le bandane sono ricavate da metrature rispettabili. Coloni pragmatici come Sara Timberlain al Campo di Taglio di Vallevante chiedono regolarmente ai viaggiatori di raccoglierle dagli accampamenti di fuorilegge. Con un po' di lavaggio e cucito, la stoffa di contrabbando viene trasformata in abiti robusti e bende per i lavoratori della foresta."}},faq={{q="Perché i Defias indossano red linen bandana?",a="La bandana rossa funge da divisa e distintivo di sfida contro Roccavento, nascondendo l'identità di chi la indossa e mostrando al contempo lealtà alla fratellanza di Edwin VanCleef.",al={"significato maschera defias","perché maschere rosse","bandana rossa defias"}},{q="In che cosa differiscono da quelle indossate nella Contea del Nord?",a="I teppisti che operano nella Valle della Contea del Nord indossano maschere di ruvida tela di sacco, mentre gli operativi affermati dei Defias in tutta la Foresta di Elwynn indossano un lino rosso più raffinato.",al={"tela di sacco contro lino","maschere della contea del nord","bandana di tela di sacco"}},{q="Chi vuole raccogliere queste bandane?",a="Sara Timberlain al Campo di Taglio di Vallevante le colleziona. Essendo una sarta a corto di stoffa, lava e disfa le maschere dei banditi per tesserle in pratici indumenti.",al={"chi accetta red linen bandana","bandana sara timberlain","consegna missione bandana"}},{q="Quali nemici trasportano red linen bandana?",a="Quasi tutti gli operativi dei Defias nella Foresta di Elwynn le trasportano, inclusi i Banditi Defias, gli Ambushers, i Rogue Wizards, gli scaricatori di porto e caporioni come Morgan il Collezionista.",al={"chi rilascia red linen bandana","dove farmare bandane","bottino bandana defias"}}},fp="17,253,18.390.0,16.360.0,42.167.0,54.146.0,36.169.0,39.168.0"}
P.entries["item:red-wool-bandana"] = {n="Bandana di Lana Rossa",s="Le Bandane di Lana Rossa sono simboli improvvisati fabbricati dai tagliagole Defias imprigionati all'interno delle Segrete di Roccavento. Strappate dalle coperte di lana della prigione, fungono da fieri emblemi di fratellanza persino dietro le sbarre.",h="Le Bandane di Lana Rossa sono simboli improvvisati fabbricati dai tagliagole Defias imprigionati all'interno...",kw={"defias","mac raskol","nikova raskol","bandana di lana rossa","roccavento","the color of blood","segrete di roccavento"},ang={["faction:Alliance"]="Per i difensori dell'Alleanza, recuperare queste bandane è un cupo atto di giustizia per il giovane Mac Raskol e un colpo contro i rivoltosi che tengono in pugno la prigione della città.",["profession:Tailoring"]="Queste rozze bandane mostrano come persino grezze coperte di lana possano essere sfilacciate e riutilizzate da mani disperate in prigionia."},sec={{t="Cucite con Sfida",b="Persino rinchiusi nelle profondità delle alte mura di pietra delle Segrete di Roccavento, i membri della Fratellanza dei Defias rifiutano di rinunciare alla propria identità. Usando scampoli strappati dalle coperte di lana della prigione, i detenuti fabbricano in segreto bandane rosse da indossare come colori identificativi. Per le guardie, queste sciarpe sono contrabbando che scatena ammutinamenti fatali; per i prigionieri, sono la dimostrazione che la loro fratellanza e la loro ribellione resistono, persino in catene."},{t="La Vendetta di una Nonna",b="Le bandane acquisirono un'amara notorietà dopo che la guardia carceraria quattordicenne Mac Raskol sorprese i detenuti a fare a brandelli le coperte per realizzarle. Quando tentò di disciplinare i prigionieri, i galeotti Defias lo pugnalarono alla schiena. All'indomani della sua morte, la nonna addolorata Nikova cerca avventurieri disposti ad avventurarsi nella prigione in rivolta, abbattere i rivoltosi e recuperare la stoffa cremisi come prova della vendetta."}},faq={{q="Dove si procurano queste bandane i prigionieri nelle Segrete di Roccavento?",a="I detenuti Defias le realizzano strappando le coperte di lana fornite dalla prigione. Nonostante siano disarmati e imprigionati, trasformano la loro misera biancheria da letto in simboli di sfida da indossare all'interno delle celle.",al={"da dove vengono le bandane","fonte bandane segrete di roccavento","come si fanno le bandane rosse"}},{q="Chi vuole che queste bandane vengano raccolte?",a="Nikova Raskol, una nonna in lutto a Roccavento, chiede agli avventurieri di raccoglierle. Suo nipote quattordicenne Mac era una guardia delle Segrete di Roccavento uccisa dai prigionieri dopo averli sorpresi a fabbricare le bandane.",al={"a chi servono le bandane di lana rossa","chi assegna la missione color of blood","nikova raskol bandana"}},{q="Perché ai prigionieri importa così tanto indossare sciarpe rosse?",a="La Fratellanza dei Defias indossa maschere e bandane rosse come propri colori primari e uniforme della banda. Dietro le sbarre, fabbricare e indossare questi scampoli consente ai detenuti di mantenere il proprio rango, morale e unità.",al={"perché bandane rosse","simbolo rosso defias","significato della bandana rossa"}},{q="Quali detenuti le hanno con sé?",a="Sono portate da quasi tutti i membri Defias in rivolta nelle Segrete di Roccavento, inclusi Defias Captives, Inmates, Prisoners, Insurgents e Convicts.",al={"chi rilascia la bandana di lana rossa","bottino bandane segrete di roccavento"}}},fx={["7f0c1a2a"]={q="Cos'è una Bandana di Lana Rossa?",a="Una Bandana di Lana Rossa è una sciarpa cremisi improvvisata creata dai membri imprigionati della Fratellanza dei Defias all'interno delle Segrete di Roccavento. Facendo a pezzi e tingendo le coperte di lana fornite dalla prigione, i detenuti creano questi pegni di stoffa per mostrare apertamente la loro lealtà alla Fratellanza e mantenere la loro identità di banda anche dietro le sbarre.",al={"cos'è la bandana di lana rossa","oggetto bandana di lana rossa","bandana rossa delle segrete"}}},fp="16,210,20.424.0,25.415.0,54.196.0,35.205.0,60.197.0,25.142.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Ultime Gocce di Acqua Purissima",s="Le Ultime Gocce di Acqua Purissima sono il residuo finale di una pozione specializzata preparata dalla veggente dell'acqua Brine. Gli sciamani che trasportano queste potenti gocce viaggiano attraverso i regni per purificare un sacro santuario dell'acqua corrotto dalla piaga dei non morti del Flagello.",h="Le Ultime Gocce di Acqua Purissima sono il residuo finale di una pozione specializzata preparata dalla...",kw={"braciere della sorgente eterna","brine","call of water","manifestazione corrotta","acqua purissima","selva pinargento","totem dell'acqua"},ang={["class:Shaman"]="Queste gocce rappresentano il culmine delle tue prove per padroneggiare l'acqua. Trasportarle dalle aride Barrens alla costa flagellata di Selva Pinargento è essenziale per ottenere il tuo Totem dell'Acqua.",["faction:Horde"]="Il pellegrinaggio dello sciamano collega i territori dell'Orda a Kalimdor con i precari possedimenti dei Reietti a Selva Pinargento, a dimostrazione della portata della restaurazione spirituale contro la piaga del Flagello."},sec={{t="Un rimedio per le acque contaminate",b="Forgiato attraverso una raccolta rituale tra Kalimdor e Lordaeron, questo elisir concentrato conserva l'essenza più pura di acqua pulita, preparata dall'eremita Brine nelle Barrens. Sebbene una parte della pozione venga consumata per concedere agli sciamani la visione di elementi lontani, le gocce rimanenti sono custodite per un compito ben più pericoloso. Portate sulle rive soffocate dalla piaga della Selva Pinargento vicino a Mausolea, le gocce fungono da catalizzatore purificatore fondamentale sopra il Braciere della Sorgente Eterna. Consumata nelle fiamme rituali insieme ai bracciali di un elementale caduto e corrotto, quest'acqua pura fende la corruzione necrotica, invocando uno spirito dell'acqua incontaminato per comunicare con lo sciamano e completare la sua comunione con l'elemento."}},faq={{q="A cosa servono queste gocce?",a="Vengono collocate sul Braciere della Sorgente Eterna sulla costa della Selva Pinargento insieme ai bracciali di una manifestazione acquatica corrotta. Questo rituale purifica il santuario elementale corrotto ed evoca uno spirito dell'acqua incorrotto.",al={"a cosa servono le ultime gocce","scopo delle ultime gocce","usare l'acqua purissima"}},{q="Da dove proviene il liquido?",a="Sono la porzione rimanente di una pozione purificatrice preparata da Brine, un'orchessa sciamana che dimora su una collina nelle Savane Meridionali, creata durante le prove spirituali intraprese dagli aspiranti sciamani.",al={"chi ha creato l'acqua purissima","origine delle gocce","gocce d'acqua di brine"}},{q="Perché il rituale viene celebrato fino alla Selva Pinargento?",a="Un santuario dell'acqua lungo la costa della Selva Pinargento a ovest di Mausolea è stato corrotto dalla piaga della non morte, rendendo i suoi spiriti elementali ostili e distorti. Purificare quella specifica pozza dimostra la devozione e la maestria di uno sciamano attraverso grandi distanze.",al={"perché selva pinargento","perché andare a selva pinargento","santuario dell'acqua di selva pinargento"}},{q="Cosa succede quando toccano il braciere?",a="Quando vengono versate sulle fiamme del braciere insieme ai bracciali corrotti, le gocce crepitano nel fuoco, innescando un incanto che purifica la piaga persistente ed evoca una pura manifestazione d'acqua.",al={"rituale del braciere","cosa succede sul braciere","rituale del braciere della sorgente eterna"}}},fx={db79eea5={q="Cosa sono le Ultime Gocce di Acqua Purissima?",a="Questa piccola fiala contiene gli ultimi resti della pozione purificante preparata dall'eremita Brine nelle Savane Meridionali. Infuso con acqua raccolta dalle Barrens, dal Mulino di Tarren e da Valtetra, il potente liquido possiede immense proprietà purificanti. Sebbene rimangano solo poche gocce, la sua purezza concentrata è sufficiente per tagliare la corruzione persistente quando offerta nei riti elementali.",al={"cosa sono le ultime gocce di acqua purissima","cosa sono le gocce di acqua purissima","storia gocce di acqua purissima"}},["55d7092f"]={q="Perché Islen Scruta Lagune vuole che tu usi le Ultime Gocce di Acqua Purissima?",a="Islen Scruta Lagune richiede che tu versi le gocce sul Braciere di Everfount nella Selva Pinargento. Un sacro santuario dell'acqua lì ha ceduto alla piaga dei non morti, assordando i suoi spiriti locali alla comunione sciamanica. Offrendo queste gocce rimanenti insieme ai bracciali di una manifestazione corrotta caduta, il braciere può accendere un rituale purificante abbastanza potente da evocare uno spirito d'acqua pura.",al={"perché usare le gocce di acqua purissima","perché servono le ultime gocce di acqua purissima","perché ti servono le gocce di acqua purissima"}}},fp="31,249,27.730.0,30.228.0,31.194.0,61.246.0,41.206.0"}
P.entries["item:remedy-of-arugal"] = {n="Rimedio di Arugal",s="Il Rimedio di Arugal è un incantesimo scritto dal mago Arugal durante i suoi primi esperimenti con la magia dei worgen. Lasciato in una fattoria fatiscente nella Selva Pinargento, l'incantesimo è ricercato da Dalar Tessalba per svelare l'oscura opera dello stregone.",h="Il Rimedio di Arugal è un incantesimo scritto dal mago Arugal durante i suoi primi esperimenti con la magia...",kw={"arugal","arugal's folly","dalar tessalba","libri degli incantesimi impolverati","furia lunare","rimedio di arugal","mausolea","selva pinargento"},ang={["class:Mage"]="I maghi dei Reietti condivideranno il disdegno professionale di Dalar Tessalba per il dilettantismo goffo e sconsiderato di Arugal, pur riconoscendo il pericolo insito nell'evocazione di arcani incontrollati.",["race:Undead"]="Per i Reietti, impossessarsi di questo incantesimo è un primo, vitale passo nel respingere i feroci worgen che minacciano i confini della Selva Pinargento."},sec={{t="Gli avanzi di un mago",b="Prima di impadronirsi del Forte di Zannascura, l'Arcimago Arugal si rifugiò in una fattoria di grano abbandonata a nord del ponte sul fiume nella Selva Pinargento. Lì, tra attrezzi agricoli dimenticati e assi del pavimento marcescenti, documentò le sue strane arti in una serie di polverosi libri degli incantesimi. La pergamena intitolata Rimedio di Arugal si trova tra queste note, delineando i primi metodi e le formulazioni magiche che concepì mentre si dilettava con le pericolose trasmutazioni che maledissero la popolazione locale."},{t="L'attento esame dei Reietti",b="Dalar Tessalba, un abile incantatore dei Reietti che opera da Mausolea, nutre scarso rispetto per il lignaggio di Arugal, liquidando l'intelletto dell'ex mago di Dalaran come fragile e trasparente. Ciononostante, Tessalba riconosce l'urgente necessità di comprendere i meccanismi esatti dietro la maledizione dei worgen. Recuperando il Rimedio di Arugal, gli agenti dei Reietti forniscono a Tessalba gli arcani fondamentali necessari per contrastare la crescente minaccia di Arugal e proteggere Selva Pinargento per Lady Sylvanas."}},faq={{q="Che cos'è il Rimedio di Arugal?",a="È una formula magica messa per iscritto dal mago rinnegato Arugal. Piuttosto che una pozione curativa, si tratta di un incantesimo scritto contenente le tecniche arcane da lui utilizzate quando iniziò a sperimentare con la magia dei worgen nella Selva Pinargento.",al={"cos'è il rimedio di arugal","oggetto rimedio di arugal","incantesimo rimedio"}},{q="Dove è stato lasciato il Rimedio?",a="Arugal lo ha lasciato all'interno di una serie di polverosi libri degli incantesimi al piano superiore di una fattoria di grano abbandonata, situata appena a nord del ponte che attraversa il fiume nella Selva Pinargento.",al={"dove trovare il rimedio di arugal","posizione rimedio di arugal","libro degli incantesimi della fattoria"}},{q="Perché Dalar Tessalba vuole questo incantesimo?",a="Dalar Tessalba cerca di analizzare la magia specifica impiegata da Arugal affinché i Reietti possano sviluppare contromisure efficaci, sperando di volgere i metodi stessi dello stregone contro di lui per mettere in sicurezza la regione.",al={"perché dalar vuole il rimedio","rimedio di dalar tessalba"}},{q="Chi fa la guardia ai libri degli incantesimi alla fattoria?",a="La fattoria è infestata dai servitori lupeschi di Arugal. Quando qualcuno tenta di toccare i polverosi libri degli incantesimi al secondo piano, un Moonrage Darkrunner balza dalle ombre per difendere i beni del suo padrone.",al={"cosa attacca alla fattoria","imboscata del libro degli incantesimi"}}},fx={["157696b2"]={q="Da dove viene il Rimedio di Arugal e chi lo ha creato?",a="Il Rimedio di Arugal è un incantesimo scritto dall'Arcimago Arugal in persona durante i suoi primi giorni nella Selva Pinargento. Dopo che i suoi piani iniziarono a prendere forma, risiedette brevemente in una fattoria di grano a nord del ponte principale del fiume, lasciando dietro di sé polverosi libri di incantesimi contenenti le sue ricerche.",al={"chi ha creato il rimedio di arugal","origine del rimedio di arugal","da dove viene il rimedio di arugal"}}},fp="16,250,18.455.0,17.498.0,29.235.0,33.172.0,42.198.0,38.205.0"}
P.entries["item:rendered-spores"] = {n="Spore Trasformate",s="Le Spore Trasformate sono un'emulsione volatile preparata da campioni fungini raccolti attraverso The Barrens. Creata dallo Speziale Helbrim a Crocevia, la miscela decade rapidamente a meno che non venga consegnata tempestivamente ad Apothecary Zamah sotto Picco del Tuono per la stabilizzazione.",h="Le Spore Trasformate sono un'emulsione volatile preparata da campioni fungini raccolti attraverso The Barrens.",kw={"speziale helbrim","apothecary zamah","the barrens","crocevia","emulsione","pozze delle visioni","spore trasformate","picco del tuono"},ang={["race:Tauren"]="La presenza di speziali Forsaken che sperimentano sulla strana flora di The Barrens all'interno delle sacre Pozze delle Visioni riflette la complessa e pragmatica alleanza forgiata all'interno di Picco del Tuono.",["race:Undead"]="La Royal Apothecary Society cerca costantemente nuovi composti biologici in tutta Kalimdor per aiutare i Forsaken, affidandosi a veloci corrieri per collegare i ricercatori sul campo come Helbrim con gli specialisti di laboratorio come Zamah."},sec={{t="Una Miscela Volatile",b="Dopo aver ottenuto strane spore fungine da funghi vicini alle umide oasi di The Barrens, lo Speziale Helbrim le trasforma in un'emulsione chimica attiva nota come Spore Trasformate. La delicata estrazione sospende i potenti composti delle crescite fungine in un mezzo liquido, ma la soluzione è chimicamente instabile. Mantiene la sua potenza vitale per soli quarantacinque minuti prima di degradarsi e diventare completamente inutile per lo studio scientifico."},{t="Consegna alle Pozze delle Visioni",b="Poiché Helbrim manca delle strutture necessarie o del tempo presso il suo avamposto remoto per completare il processo di raffinazione, l'emulsione deve essere portata di corsa direttamente alla sua collega dei Forsaken, Apothecary Zamah. Nascosta nelle sotterranee Pozze delle Visioni sotto l'Altura degli Spiriti a Picco del Tuono, Zamah possiede l'equipaggiamento specializzato e i reagenti necessari per risigillare e terminare la lavorazione delle spore per la Royal Apothecary Society."}},faq={{q="A cosa servono le Spore Trasformate?",a="Sono materia fungina estratta dallo Speziale Helbrim e trasformata in un'emulsione per le ricerche della Royal Apothecary Society. Apothecary Zamah utilizza la potente miscela a Picco del Tuono per continuare le loro indagini sulle strane crescite che si diffondono attraverso The Barrens.",al={"scopo delle spore trasformate","cosa fa zamah con le spore","perché spore trasformate"}},{q="Perché l'emulsione ha un limite di tempo?",a="L'emulsione chimica creata da Helbrim è altamente volatile e inizia a degradarsi non appena viene mescolata. La sua potenza attiva dura per soli quarantacinque minuti, richiedendo che un corriere la trasporti rapidamente attraverso le pianure fino a Picco del Tuono prima che diventi inerte.",al={"perché le spore trasformate hanno un tempo limite","perché le spore scadono","durata delle spore trasformate"}},{q="Chi ha creato queste spore?",a="Lo Speziale Helbrim, un ricercatore Forsaken di stanza a Crocevia in The Barrens, ha trasformato grezze spore fungine raccolte da funghi vicino alle oasi in questo composto liquido instabile.",al={"chi ha creato le spore trasformate","chi trasforma le spore","spore di helbrim"}},{q="Dove deve andare la miscela?",a="Le spore devono essere consegnate ad Apothecary Zamah. Risiede nelle profondità delle Pozze delle Visioni, un sistema di caverne nascosto sotto l'Altura degli Spiriti nella capitale dei tauren di Picco del Tuono.",al={"dove portare le spore trasformate","posizione di zamah","posizione delle pozze delle visioni"}}},fx={["7897c588"]={q="Cosa sono le Spore Trasformate?",a="Le Spore Trasformate sono l'estratto lavorato di strane escrescenze fungine raccolte in tutte le The Barrens. Lo Speziale Helbrim ha bollito e trasformato le spore grezze in un'emulsione liquida volatile e instabile, preparando accuratamente la miscela per un ulteriore studio alchemico da parte dello Speziale Reale.",al={"cosa sono le spore trasformate","info sulle spore trasformate","cosa sono le spore"}}},fp="15,257,18.452.0,31.417.0,34.273.0,40.261.0,25.187.0,34.177.0"}
P.entries["item:renferrel-s-findings"] = {n="Scoperte di Renferrel",s="Scoperte di Renferrel è una raccolta di appunti di ricerca compilati dallo Speziale Renferrel nella Selva Pinargento. Affidati ai corrieri dell'Orda, questi documenti trasportano dati vitali verso sud allo Speziale Lydon al Mulino di Tarren, per aiutarlo nella creazione della Nuova Piaga dei Relitti.",h="Scoperte di Renferrel è una raccolta di appunti di ricerca compilati dallo Speziale Renferrel nella Selva...",kw={"scoperte","lydon","nuova piaga","renferrel","società degli speziali reali","mausolea","mulino di tarren"},ang={["faction:Horde"]="I corrieri che trasportano le carte di Renferrel contribuiscono a consolidare il dominio dell'Orda su Lordaeron, collegando avamposti isolati come Mausolea e il Mulino di Tarren.",["race:Undead"]="La ricerca contenuta in questi documenti è al servizio della suprema ambizione di Sylvanas Ventolesto: perfezionare una Nuova Piaga per sradicare sia il Flagello sia i nemici viventi che invadono le terre dei Relitti."},sec={{t="Una Piaga in Sviluppo",b="La Società degli Speziali Reali lavora instancabilmente agli ordini diretti della Dama Oscura, Lady Sylvanas Ventolesto, per creare una Nuova Piaga. Il raggiungimento di questa svolta richiede una collaborazione costante tra i ricercatori sparsi per tutta Lordaeron. Di stanza a Mausolea nella Selva Pinargento, lo Speziale Renferrel raccoglie queste scoperte per documentare i suoi progressi e i suoi esperimenti, inviando le informazioni ottenute a sud verso il Mulino di Tarren affinché i colleghi ricercatori possano basarsi sui suoi risultati."},{t="Verso il Mulino di Tarren",b="Trasportare questi documenti oltre il confine da Pinargento alle Alture di Colletorto rappresenta un anello vitale nella rete alchemica dei Relitti. Al Mulino di Tarren, lo Speziale Lydon attende con impazienza gli appunti di Renferrel per confrontare i dati e perfezionare i propri intrugli contro i vivi e il Flagello. Senza corrieri affidabili che percorrano le contese strade di Colletorto, la ricerca decentralizzata della Società subirebbe un rapido arresto."}},faq={{q="Cosa contengono le Scoperte di Renferrel?",a="Il pacchetto contiene gli ultimi dati sperimentali e appunti di ricerca raccolti dallo Speziale Renferrel durante il suo lavoro nella Selva Pinargento, riguardanti nello specifico la sintesi di una Nuova Piaga per i Relitti.",al={"cosa sono le scoperte","ricerche di renferrel","cosa c'è negli appunti"}},{q="Chi dovrebbe ricevere questa ricerca?",a="I documenti sono destinati allo Speziale Lydon. Egli conduce ricerche sulla piaga al Mulino di Tarren, un insediamento dei Relitti situato nelle Alture di Colletorto.",al={"chi riceve le scoperte di renferrel","dove vanno le scoperte","destinazione della consegna"}},{q="Perché gli speziali condividono gli appunti?",a="Lady Sylvanas Ventolesto ha esercitato un'enorme pressione sulla Società degli Speziali Reali affinché inventi una Nuova Piaga. Gli speziali ritengono che la loro svolta arriverà molto più rapidamente coordinandosi e confrontando i risultati, piuttosto che lavorando in isolamento.",al={"perché condividere le scoperte","perché inviare a lydon","comunicazione tra speziali"}},{q="Dove conduce i suoi esperimenti lo Speziale Renferrel?",a="Lo Speziale Renferrel è di stanza a Mausolea, il principale avamposto dei Relitti situato nel cuore della Selva Pinargento.",al={"dove si trova renferrel","posizione dello speziale renferrel","chi ha scritto le scoperte di renferrel"}}},fx={f680c460={q="Cosa sono le Scoperte di Renferrel?",a="Le Scoperte di Renferrel sono una raccolta di appunti alchemici e documenti di ricerca compilati dallo Speziale Renferrel. Dettagliano i suoi esperimenti in corso condotti per conto dello Speziale Reale, destinati ad essere condivisi direttamente con i suoi colleghi in tutta Lordaeron.",al={"cosa sono le scoperte di renferrel","oggetto scoperte di renferrel","cosa sono queste scoperte"}},bf8d559a={q="Da dove vengono le Scoperte di Renferrel e chi le ha create?",a="Questi documenti sono stati scritti dallo Speziale Renferrel, un ricercatore ambizioso di stanza a Mausolea nella Selva Pinargento. Lavorando diligentemente sotto il mandato dei Reietti, ha scritto questi appunti per registrare i suoi progressi e le sue scoperte nella preparazione di miscele sperimentali.",al={"chi ha scritto le scoperte di renferrel","da dove vengono le scoperte di renferrel","creatore delle scoperte di renferrel"}},["21b2c0f4"]={q="Perché qualcuno vuole le Scoperte di Renferrel?",a="Lo Speziale Reale affronta un'immensa pressione da parte di Sylvanas Ventolesto per preparare A New Plague. Credendo che la collaborazione accelererà il loro cupo lavoro, Renferrel ha inviato la sua ricerca allo Speziale Lydon a Mulino di Tarren, che è ansioso di studiare i metodi del suo collega e integrarli nei propri sforzi.",al={"perché consegnare le scoperte di renferrel","chi vuole le scoperte di renferrel","perché lydon vuole le scoperte di renferrel"}}},fp="20,264,23.486.0,14.425.0,36.213.0,41.143.0,39.254.0,56.123.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Rapporto sulla Fratellanza dei Defias",s="Il Rapporto sulla Fratellanza dei Defias è un documento ufficiale redatto dall'Architetto Cittadino Baros Alexston, che illustra in dettaglio le attività e la minaccia rappresentata dagli sfuggenti cospiratori. Destinato a informare la corte reale, viene affidato a un avventuriero che ha iniziato a svelare la loro misteriosa trama per una consegna personale al Forte di Roccavento.",h="Il Rapporto sulla Fratellanza dei Defias è un documento ufficiale redatto dall'Architetto Cittadino Baros...",kw={"udienza con il re","baros alexston","defias","rapporto","forte di roccavento","vancleef","marche occidentali"},ang={["faction:Alliance"]="La consegna di questo dispaccio segna il culmine della lunga lotta per mettere in sicurezza le Marche Occidentali e allertare i vertici di Roccavento sull'insurrezione che serpeggia ai suoi confini.",["race:Human"]="Per gli umani del regno, portare questo rapporto mette in risalto il tragico e irrisolto conflitto tra la nobile casata di Roccavento e gli scalpellini che hanno ricostruito la città."},sec={{t="Un Dispaccio per il Trono",b="Dopo la lunga indagine sui disordini che affliggevano le Marche Occidentali e i territori circostanti, l’architetto cittadino Baros Alexston preparò questo rapporto ufficiale per mettere al corrente i vertici di Roccavento della reale portata della minaccia dei Fratelli di Defias. Invece di affidare il documento a un normale messaggero reale, Alexston lo consegnò proprio all’eroe che aveva fatto luce sulla cospirazione. Recapitato direttamente al Forte di Roccavento, il rapporto è destinato ad accompagnare un’udienza privata in cui verranno illustrati i piani dei cospiratori e il pericolo che rappresentano per il regno."},{t="Ricevimento al Forte",b="Sebbene indirizzato a Re Varian Wrynn, il corriere giunge nella sala del trono solo per scoprire che il monarca è assente, partito per un riservato viaggio diplomatico. Al suo posto, i consiglieri reali e la reggenza che presiede al giovane re Anduin ricevono il rapporto. Sebbene vengano offerti encomi reali per aver sventato i piani di VanCleef, la presenza di figure di corte come Dama Katrana Prestor getta un'ombra di incertezza su quanto seriamente verranno accolti gli avvertimenti contenuti nel documento."}},faq={{q="Che cos'è il Rapporto sulla Fratellanza dei Defias?",a="È un resoconto ufficiale scritto da Baros Alexston che raccoglie tutte le informazioni ottenute su Edwin VanCleef, il suo esercito sotterraneo e la più ampia cospirazione dei Defias contro Roccavento.",al={"cos'è questo rapporto","oggetto rapporto defias","rapporto di baros alexston"}},{q="Chi ha scritto questo rapporto?",a="Il documento è stato preparato da Baros Alexston, l'Architetto Cittadino di Roccavento, che in passato ha lavorato al fianco degli scalpellini prima che questi si staccassero per formare la Fratellanza dei Defias.",al={"chi ha redatto il rapporto sui defias","autore del rapporto"}},{q="Perché lo sto consegnando al Forte di Roccavento?",a="Baros Alexston ritiene che l'avventuriero che ha svelato la cospirazione meriti l'onore di presentare le scoperte direttamente al trono, ottenendo il riconoscimento reale per aver protetto il regno.",al={"perché lo consegno","consegna udienza con il re"}},{q="Re Varian legge il rapporto?",a="No. Quando arrivi al Forte di Roccavento, Re Varian Wrynn è assente, a quanto si dice impegnato in un viaggio diplomatico segreto. La sua corte reale e la reggenza ricevono il documento al suo posto.",al={"il re lo legge","udienza con varian wrynn"}}},fp="32,331,25.529.0,21.473.1,45.199.1,22.174.1,43.192.0,33.177.0"}
P.entries["item:resonite-crystal"] = {n="Cristallo di Resonite",s="I Cristalli di Resonite sono rari campioni minerali estratti dai coboldi all'interno della Caverna dei Franamassi nelle Vette di Petrartiglio. I loro scavi frenetici hanno attirato la preoccupazione di Mor'rogal al Rifugio Roccia del Sole.",h="I Cristalli di Resonite sono rari campioni minerali estratti dai coboldi all'interno della Caverna dei...",kw={"franamassi","cristallo","terrigeni","coboldo","mor'rogal","resonite","petrartiglio","titani"},ang={["class:Shaman"]="I Cristalli di Resonite recano un'inquietante risonanza per gli sciamani, capaci di riconoscere la magia primordiale e sopita della terra lasciata dalle creazioni dei Titani a lungo sepolte sotto le montagne.",["profession:Mining"]="A differenza dei normali filoni di rame o stagno, la Resonite è una formazione minerale intensamente concentrata la cui estrazione richiede di addentrarsi oltre i coboldi aggressivi nei più profondi strati sotterranei."},sec={{t="Risonanza antica",b="Nascosti nelle profondità della Gola dei Franamassi, i Cristalli di Resonite sono diventati il fulcro di improvvisi e frenetici scavi da parte dei coboldi. Mentre i comuni minatori delle caverne cercano solitamente minerali ordinari o ninnoli lucenti, l'ossessione dei coboldi per queste formazioni specifiche ha immediatamente allarmato gli sciamani del Rifugio Roccia del Sole. A un attento esame, le pietre vibrano di una sottile risonanza magica legata alla creazione primordiale del mondo. Mor'rogal ha identificato queste deboli energie come tracce di magia dei Terrigeni, indicando che le creature scavatrici hanno fatto breccia in un antico strato forgiato dai Titani."},{t="Attingere alla terra",b="La scoperta della Resonite conferma notizie preoccupanti per la Horde Presence a Petrartiglio: gli scavatori coboldi si sono spinti abbastanza in profondità da disturbare gli antichi Terrigeni. Poiché i Terrigeni furono forgiati direttamente dai Titani per scavare e plasmare le fondamenta del mondo, la magia residua aderisce ostinatamente alla roccia circostante. Raccogliendo questi cristalli, gli agenti dell'Orda sperano di decifrare le frenetiche intenzioni dei coboldi e di rivolgere il potere stesso della pietra incantata contro qualsiasi forza sopita sia stata disturbata nel sottosuolo."}},faq={{q="Dove si trovano i Cristalli di Resonite?",a="I Cristalli di Resonite si trovano all'interno della Caverna dei Franamassi, una profonda grotta situata nella Gola dei Franamassi nelle zone sud-orientali delle Vette di Petrartiglio.",al={"posizione resonite","dove trovare la resonite","farming cristalli di resonite"}},{q="Perché i coboldi stanno estraendo i Cristalli di Resonite?",a="I coboldi stanno estraendo freneticamente i rari cristalli, ma Mor'rogal non ne conosce ancora il motivo. Egli richiede dei campioni e un'indagine nelle profondità della caverna per comprenderne l'attività.",al={"perché i coboldi scavano","piano dei cristalli dei coboldi","coboldi dei franamassi"}},{q="Che tipo di potere si trova in un Cristallo di Resonite?",a="Mor'rogal sospetta che i cristalli siano collegati a qualcosa di inquietante sotto le montagne. La loro natura magica viene identificata dopo che campioni e notizie dalla caverna giungono fino a lui.",al={"magia del cristallo di resonite","cos'è la resonite","la resonite è magica"}},{q="Chi sta studiando questi cristalli?",a="Mor'rogal, un tauren di stanza al Rifugio Roccia del Sole nelle Vette di Petrartiglio, indaga sui cristalli per comprendere l'improvvisa impennata dell'attività dei coboldi e trovare un modo per contrastare qualsiasi male sia stato portato alla luce.",al={"chi vuole la resonite","cristalli di mor'rogal","resonite rifugio roccia del sole"}},{q="Cosa sono i Terrigeni menzionati in relazione al cristallo?",a="Si dice che i Terrigeni siano creature create dai Titani per plasmare la terra. Il loro possibile legame con la Resonite viene indagato durante la missione di Mor'rogal.",al={"cosa sono i terrigeni","connessione tra terrigeni e titani"}}},fx={c14b6c8c={q="Cos'è il Cristallo di Resonite?",a="La Resonite è un raro minerale cristallino che si trova nella Caverna dei Franamassi nelle Vette di Petrartiglio. L'estrazione frenetica dei coboldi ha allarmato Mor'rogal, che richiede campioni e notizie dalla caverna per indagare.",al={"cos'è la resonite","storia del cristallo di resonite","minerale di resonite"}},af246400={q="Perché qualcuno vuole il Cristallo di Resonite?",a="Mor'rogal vuole campioni di minerale per comprendere l'estrazione frenetica dei coboldi e scoprire cosa giace sotto la Gola dei Franamassi. Chiede a un avventuriero di esplorare la caverna e di raccogliere i cristalli.",al={"perché raccogliere cristalli di resonite","chi vuole il cristallo di resonite","scopo del cristallo di resonite"}}},fp="16,193,17.587.1,17.518.1,34.159.0,45.182.0,44.176.0,31.214.0,60.164.0"}
P.entries["item:restabilization-cog"] = {n="Ingranaggio Stabilizzatore",s="Gli Ingranaggi Stabilizzatori sono componenti meccanici di precisione recuperati dagli gnomi lebbrosi che vagano all'esterno delle rovine irradiate di Gnomeregan. A Kharanos, gli inventori gnomici necessitano di queste parti intatte per costruire il Recombobulator, un'ambiziosa macchina destinata a invertire la mutazione lebbrosa.",h="Gli Ingranaggi Stabilizzatori sono componenti meccanici di precisione recuperati dagli gnomi lebbrosi che...",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","gnomo lebbroso","operation recombobulation","razzle mollapazza","ingranaggio stabilizzatore"},ang={["profession:Engineering"]="Le tolleranze precise degli Ingranaggi Stabilizzatori evidenziano il classico design gnomico, costruito per resistere all'attrito volatile e bilanciare delicati complessi meccanici come il Recombobulator.",["race:Gnome"]="Per gli gnomi esiliati a Dun Morogh, recuperare questi componenti è un triste dovere: spogliare i macchinari dai fratelli corrotti nella disperata speranza di creare una cura per i caduti di Gnomeregan."},sec={{t="Componenti per una cura",b="Quando le radiazioni inondarono Gnomeregan nel disastroso tentativo di spazzare via i trogg invasori, innumerevoli gnomi furono trasformati in ostili e malati gnomi lebbrosi. Nonostante la loro follia, questi esuli afflitti trasportano ancora complessi macchinari gnomici e raccordi recuperabili. Gli inventori Ozzie Valvotron e Razzle Mollapazza credono che l'orribile trasformazione possa essere sistematicamente annullata. Per completare il prototipo del loro Recombobulation Device, fanno affidamento sugli avventurieri affinché recuperino parti vitali direttamente dagli afflitti fuori dai cancelli di Gnomeregan, compresi Ingranaggi Stabilizzatori intatti per bilanciare i sistemi di combustione interna della macchina."}},faq={{q="A cosa serve un Ingranaggio Stabilizzatore?",a="Gli Ingranaggi Stabilizzatori sono richiesti dall'inventore Razzle Mollapazza a Kharanos. Insieme ai Gyromechanic Gear, fungono da pezzi strutturali cruciali per la costruzione del Recombobulator, un'invenzione sperimentale progettata per curare gli gnomi lebbrosi irradiati.",al={"scopo dell'ingranaggio","cosa fa l'ingranaggio stabilizzatore","perché raccogliere ingranaggi"}},{q="Dove si possono trovare questi ingranaggi?",a="Sono trasportati dai folli gnomi lebbrosi e dallo squilibrato Gibblewilt, che si aggirano nei pressi dei cancelli esterni e delle trincee fuori da Gnomeregan, nella parte occidentale di Dun Morogh.",al={"posizione dell'ingranaggio stabilizzatore","chi rilascia gli ingranaggi","dove trovare ingranaggi"}},{q="Il Recombobulator può davvero curare gli gnomi lebbrosi?",a="Razzle Mollapazza e Ozzie Valvotron confidano che macchinari opportunamente calibrati possano invertire la mutazione. Tuttavia, l'ingegneria gnomica è notoriamente instabile, e se il Recombobulator possa davvero risanare la mente e il corpo della loro gente rimane un'impresa in corso e mai collaudata.",al={"il recombobulator funziona","esiste una cura per gli gnomi lebbrosi"}}},fx={["8ac7e8f1"]={q="Cos'è un Ingranaggio Stabilizzatore?",a="Un Ingranaggio Stabilizzatore è un componente meccanico di precisione recuperato dalle macchine cadute e dai gnomi contaminati lebbrosi che vagano fuori dalla città in rovina di Gnomeregan. Progettati per mantenere l'equilibrio strutturale e rotazionale in complessi dispositivi gnomici, questi ingranaggi sono apprezzati dai meccanici in cerca di parti robuste e pre-lavorate per stabilizzare invenzioni temperamentali come il Ricombobulatore di Ozzie Valvotron.",al={"cos'è un ingranaggio stabilizzatore","storia dell'ingranaggio stabilizzatore","informazioni sull'ingranaggio stabilizzatore"}},ceb0040c={q="Da dove vengono gli Ingranaggi Stabilizzatori?",a="Questi ingranaggi provengono dalle vaste opere meccaniche di Gnomeregan. Quando la città è stata evacuata in seguito allo sfogo di radiazioni disastroso, innumerevoli dispositivi automatizzati e i tragici sopravvissuti che hanno ceduto alla follia lebbroso hanno portato questi componenti standardizzati fuori sulla neve davanti ai cancelli.",al={"chi ha creato l'ingranaggio stabilizzatore","origine dell'ingranaggio stabilizzatore","da dove viene l'ingranaggio stabilizzatore"}}},fp="19,289,21.623.0,39.247.0,30.157.0,54.289.0"}
P.entries["item:ring-of-zoram"] = {n="Anello di Zoram",s="L'Anello di Zoram è un antico cimelio Kaldorei risalente ai giorni di gloria della città sommersa di Zoram prima del Grande Grangorgo. Un tempo indossato dai sovrani della città e chiave per l'antica serratura di una statuetta sommersa, è caduto di recente nelle mani dei naga costieri invasori.",h="L'Anello di Zoram è un antico cimelio Kaldorei risalente ai giorni di gloria della città sommersa di Zoram...",kw={"statuetta antica","valtetra","lady vespia","anello di zoram","ruuzel","talen","spiaggia di zoram"},ang={["faction:Alliance"]="Recuperare l'anello dai naga aiuta lo studioso Elfo della Notte Talen a rivendicare la storia rubata dei kaldorei lungo i confini contesi di Valtetra.",["race:NightElf"]="L'anello rappresenta una testimonianza tangibile del retaggio precedente al Grangorgo, proveniente da un'epoca precedente a quando l'impero Kaldorei fu fatto a pezzi dalla superbia arcana e dai mari che tutto inghiottirono."},sec={{t="Anello della Città Sommersa",b="Prima che il Pozzo dell'Eternità collassasse e gli oceani inghiottissero i confini occidentali di Kalimdor, Zoram era un gioiello costiero dell'impero degli Elfi della Notte. L'Anello di Zoram apparteneva ai sovrani della città, e uno strano codice è inciso sulla sua fascia interna nella lingua degli Elfi della Notte. Quando il Grande Grangorgo sconvolse il continente diecimila anni fa, l'anello sprofondò insieme alla città, perduto sotto le maree impetuose di quella che oggi è la Spiaggia di Zoram."},{t="Rivendicazione da parte dei Naga",b="Per millenni, l'anello rimase sepolto sotto il limo e le rovine finché i naga non iniziarono a perlustrare la costa di Valtetra. Ruuzel, un capo naga che dimora su un isolotto al largo della costa settentrionale, ha scoperto l'artefatto tra i detriti sommersi. Studiosi come l'Elfo della Notte Talen cercano l'anello non solo per la sua antichità, ma perché funge da unica chiave capace di aprire altre reliquie recuperate dalle profondità, incluse statuette antiche sigillate recuperate dal fondo del mare."}},faq={{q="A cosa serve l'Anello di Zoram?",a="L'anello apparteneva ai sovrani di Zoram prima che il Grangorgo sommergesse la città, ed è la chiave per un'antica serratura. Al giorno d'oggi, Talen lo cerca specificamente per aprire una Statuetta Antica chiusa a chiave recuperata dalle rovine sommerse.",al={"scopo dell'anello di zoram","cosa fa l'anello","storia dell'anello di zoram"}},{q="Chi possiede l'Anello di Zoram?",a="L'anello è stato dragato dalle rovine dai naga costieri che hanno invaso la Spiaggia di Zoram. È custodito principalmente dal loro capo, Ruuzel, su un'isola al largo della costa settentrionale, sebbene sia noto che anche un'altra naga di spicco di nome Lady Vespia lo porti con sé.",al={"chi possiede l'anello","bottino anello di zoram","dove trovare l'anello di zoram"}},{q="Perché Talen vuole l'anello?",a="Talen cerca di svelare i segreti della Statuetta Antica recuperata dalla Spiaggia di Zoram. Senza l'Anello di Zoram a fare da chiave, l'antico meccanismo della statuetta non può essere aperto.",al={"perché talen vuole l'anello","missione anello di talen"}},{q="Dov'è finita la città di Zoram?",a="Zoram era un'antica città degli Elfi della Notte situata lungo il confine occidentale di Kalimdor prima del Grande Grangorgo di diecimila anni fa. Quando il Pozzo dell'Eternità implose, la città fu distrutta e annegata sotto le onde, lasciando dietro di sé solo la Spiaggia di Zoram.",al={"cosa è successo a zoram","storia della città di zoram"}}},fx={["7e40c0d5"]={q="Cos'è l'Anello di Zoram?",a="L'Anello di Zoram è un'antica reliquia un tempo indossata dai sovrani della città sommersa di Zoram, prima che le onde del Grande Cataclisma la sommergessero. Uno strano codice è scritto all'interno della fascia nella lingua degli elfi della notte, e l'anello è la chiave dell'antica serratura di una statuetta recuperata dalle rovine.",al={"cos'è l'anello di zoram","storia dell'anello di zoram","oggetto anello di zoram"}},["770adfa7"]={q="Da dove viene l'Anello di Zoram e chi lo ha creato?",a="L'anello proviene dalla città elfica notturna di Zoram, pre-Cataclisma, lungo la costa dell'antica Kalimdor. Apparteneva ai sovrani della città prima che maremoti cataclismatici sommergessero Zoram diecimila anni fa, lasciando la reliquia perduta nel mare finché i naga non l'hanno recentemente dragata dalle rovine.",al={"origine dell'anello di zoram","chi ha creato l'anello di zoram","da dove viene l'anello di zoram"}}},fp="13,286,23.461.0,23.481.0,35.236.0,32.242.0,29.189.0,31.264.0"}
P.entries["item:robo-mechanical-guts"] = {n="Interiora Robomeccaniche",s="Le Interiora Robomeccaniche sono ingranaggi, condotti e viscere di macchine recuperabili, ottenuti dai costrutti malfunzionanti che vagano tra le rovine di Gnomeregan. Gli ingegneri gnomici di Roccavento necessitano di questi componenti specifici per riparare i pesanti veicoli da scavo destinati ad aiutare nella riconquista di Gnomeregan a Dun Morogh.",h="Le Interiora Robomeccaniche sono ingranaggi, condotti e viscere di macchine recuperabili, ottenuti dai...",kw={"meccanico","dun morogh","gnomeregan","gyrodrillmatic excavationators","interiora robomeccaniche","shoni","roccavento"},ang={["profession:Engineering"]="Ogni groviglio di cavi e ingranaggio giroscopico recuperato serve a ricordare l'apice della progettazione automatizzata gnomica, ormai tragicamente inselvatichita dalle radiazioni e dall'isolamento.",["race:Gnome"]="Smantellare le sentinelle meccaniche impazzite della tua dimora perduta lascia l'amaro in bocca, ma riadattare i loro macchinari interni fornisce le parti concrete necessarie per riconquistare Gnomeregan."},sec={{t="Materiale di Recupero per la Flotta",b="Quando il Gran Meccanista Gelbin Meccatork e gli gnomi superstiti evacuarono Gnomeregan, migliaia di meccanismi automatizzati, sentinelle a orologeria e robot industriali furono abbandonati all'interno. All'indomani dell'incidente radioattivo della città, queste macchine continuano a percorrere i corridoi autonomamente. A Roccavento, l'artefice Shoni cerca di assemblare una flotta di Gyrodrillmatic Excavationators per sfondare le difese di Gnomeregan e riconquistare la città perduta. Priva di materie prime fresche, affida ad audaci avventurieri il compito di sfidare le sale contaminate di Gnomeregan per asportare viscere robotiche funzionanti (molle, cavi e componenti giroscopici) con cui riadattare i macchinari da scavo."}},faq={{q="A cosa servono le Interiora Robomeccaniche?",a="Vengono raccolte da Shoni a Roccavento per riparare una flotta di Gyrodrillmatic Excavationators, veicoli specializzati da scavo destinati a sostenere le operazioni per riconquistare Gnomeregan a Dun Morogh.",al={"a cosa servono le interiora di robot","uso delle interiora robomeccaniche","perché raccogliere le interiora meccaniche"}},{q="Dove si trovano questi componenti?",a="Possono essere recuperati dai vari automi a orologeria ostili, dai mech e dai nemici contaminati che vagano sia nei dintorni che nelle profondità di Gnomeregan.",al={"dove trovare le interiora robomeccaniche","luogo di rilascio interiora di robot","parti di robot di gnomeregan"}},{q="Chi è Shoni e perché ha bisogno di così tanti pezzi?",a="Shoni è un'ambiziosa ingegnera gnome di stanza nel Distretto dei Nani di Roccavento. Ha il compito di preparare un'intera divisione di macchine da scavo sotterranee — quasi quattrocento in totale — per fare breccia nelle rovine occupate di Gnomeregan.",al={"chi è shoni","shoni roccavento","flotta di gyrodrillmatic excavationators"}}},fx={b1d0efc3={q="Cosa sono le Interiora Robomeccaniche?",a="Sono i grovigli di macchinari interni, ingranaggi, cablaggi e componenti meccanici recuperabili estratti dagli automi a orologeria che vagano per Gnomeregan. Sebbene per un occhio inesperto non siano altro che rottami, queste interiora funzionali forniscono meccanismi grezzi cruciali che gli ingegnosi ingegneri gnomi possono riutilizzare per complessi progetti di veicoli.",al={"cosa sono le interiora robomeccaniche","oggetto interiora robomeccaniche","cosa sono le robo interiora"}},cf2ae288={q="Da dove vengono le Interiora Robomeccaniche e chi le ha create?",a="Questi assemblaggi hanno avuto origine nelle officine di Gnomeregan, creati da inventori gnomi per alimentare la loro forza lavoro automatizzata e le difese cittadine. Quando il disastro radioattivo colpì e l'Alto Artificiere Mekkatorque ordinò l'evacuazione, innumerevoli costrutti meccanici furono abbandonati all'interno, dove continuano a vagare per i passaggi in rovina con i loro ingranaggi interni ancora intatti.",al={"chi ha creato le interiora robomeccaniche","da dove vengono le interiora robomeccaniche","origine delle interiora robomeccaniche"}},f52d09f9={q="Perché qualcuno vuole le Interiora Robomeccaniche?",a="Shoni la Shilente a Roccavento ne ha un disperato bisogno come componenti di ricambio per riparare un'intera flotta di Gyrodrillmatic Excavationators. Con scorte limitate nella capitale umana, guarda ai mech ribelli di Gnomeregan come a un abbondante deposito di recupero per mantenere operativa la sua flotta ingegneristica.",al={"perché raccogliere le interiora robomeccaniche","chi vuole le interiora robomeccaniche","perché shoni vuole le interiora robomeccaniche"}}},fp="20,315,21.658.0,39.198.0,35.160.0,49.245.0"}
P.entries["item:rocket-car-parts"] = {n="Parti di Razzomacchina",s="Le Parti di Razzomacchina sono i resti metallici contorti e sparsi di collisioni ad alta velocità nelle Distese Salate a Millepicchi. Generati costantemente da spericolati piloti gnomi e goblin che spingono bolidi sperimentali oltre i loro limiti, questi rottami recuperati vengono raccolti da opportunisti desiderosi di trasformare gli incidenti sulla pista da corsa in denaro rapido.",h="Le Parti di Razzomacchina sono i resti metallici contorti e sparsi di collisioni ad alta velocità nelle...",kw={"ingegneria","gnomo","goblin","kravel koalbeard","pista dei miraggi","parti di razzomacchina","recupero","distese salate","millepicchi"},ang={["profession:Engineering"]="La miriade di ingranaggi bruciati e impianti di scarico squarciati sparsi sulle distese salate testimonia gli estremi caotici della filosofia ingegneristica di gnomi e goblin.",["race:Dwarf"]="Mentre a gnomi e goblin importa solo della corsa in sé, nani intraprendenti come Kravel Koalbeard dimostrano che il vero profitto sta nel recuperare i rottami lasciati sulla loro scia."},sec={{t="Velocità, schianti e commercio scaltro",b="La Pista dei Miraggi nelle Distese Salate è il teatro di un'infinita e infiammabile rivalità tra ingegneria gnomesca e goblin. Nella loro ricerca di una velocità su terra senza pari, i piloti subiscono regolarmente guasti catastrofici, detonazioni premature e schianti ad alta velocità che spargono metallo sulle distese salate. Questi resti abbandonati — che spaziano da cilindri deformati e ingranaggi bruciati a lamiere accartocciate — non rimangono incustoditi a lungo. Riciclatori e mercanti, in particolare l'opportunista nano Kravel Koalbeard, assoldano avventurieri di passaggio per setacciare l'accecante distesa bianca e raccogliere i detriti. Poiché entrambe le squadre di corsa hanno costantemente un disperato bisogno di pezzi di ricambio per mettere insieme il loro prossimo prototipo, i rottami recuperati possono essere facilmente rivenduti direttamente alle stesse scuderie che li hanno distrutti."}},faq={{q="Da dove provengono tutte queste parti di razzomacchina?",a="Sono il risultato di continui schianti, esplosioni e guasti meccanici alla Pista dei Miraggi. I piloti gnomi e goblin spingono abitualmente veicoli sperimentali a razzo altamente volatili fino alla distruzione attraverso le vaste distese salate di Millepicchi.",al={"perché ci sono pezzi sulle distese salate","origine dei rottami di razzomacchina","da dove provengono i pezzi"}},{q="Chi compra questi rottami recuperati?",a="Mercanti come il nano Kravel Koalbeard raccolgono i rottami dai viandanti per poi rivendere ingranaggi, lamiere e congegni recuperati agli gnomi e ai goblin, che hanno sempre bisogno di materiali di scorta per riparare e potenziare le loro auto da corsa.",al={"chi vuole le parti di razzomacchina","kravel koalbeard parti di razzo","chi compra i rottami"}},{q="È pericoloso recuperare queste parti?",a="I detriti stessi sono rottami inerti, sebbene a volte rechino truci segni di violenti schianti come arti recisi incastrati nel metallo. Il pericolo principale proviene dalla fauna ostile delle distese salate, inclusi basilischi, scorpioni bruciati e avvoltoi del sale predatori che perlustrano i campi di detriti.",al={"è sicuro raccogliere i pezzi","minacce durante la raccolta dei pezzi"}},{q="Agli gnomi e ai goblin importa che le parti provengano da veicoli distrutti?",a="Per nulla. Né i concorrenti gnomi né quelli goblin hanno remore riguardo ai materiali riciclati. La loro unica priorità è procurarsi marchingegni, ingranaggi e lamiere metalliche utilizzabili per assemblarli abbastanza in fretta da superarsi a vicenda sulla pista.",al={"ai piloti importano i rottami","perché i goblin riutilizzano i rottami"}}},fx={["9a01e74a"]={q="Cosa sono le Parti di Razzomacchina?",a="Sono i detriti sparsi dei disastri delle corse ad alta velocità in tutte le Distese Salate. Composti da ingranaggi allentati, cilindri, piastre metalliche contorte e aggeggi recuperati, questi rottami un tempo erano imbullonati ai ruggenti macchinari sperimentali costruiti da velocisti goblin e gnomi che gareggiavano alla Pista dei Miraggi.",al={"cosa sono le parti di razzomacchina","storia delle parti di razzomacchina","cosa sono queste parti"}}},fp="16,342,34.812.0,46.251.0,31.246.0,36.309.0,68.237.0"}
P.entries["item:rod-of-channeling"] = {n="Verga della Canalizzazione",s="Una Verga della Canalizzazione è un catalizzatore arcano trasportato dagli incantatori del clan Fauce del Drago nelle Wetlands. Gli stregoni che cercano di padroneggiare l'evocazione di un felhunter devono raccogliere diverse di queste verghe affinché gli accoliti di Strahad Farsan possano ancorare in sicurezza il cerchio rituale a Porto Paranco.",h="Una Verga della Canalizzazione è un catalizzatore arcano trasportato dagli incantatori del clan Fauce del...",kw={"accampamento zannarabbiosa","bonewarder","fauce del drago","felhunter","verga della canalizzazione","shadowwarder","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Procurarsi tre Verghe della Canalizzazione è un traguardo fondamentale nel completamento delle prove del Tome of the Cabal, fornendo il contenimento necessario per vincolare il tuo primo felhunter."},sec={{t="Strumenti di Vincolamento",b="Quando uno stregone cerca di vincolare un predatore instabile come un felhunter, la pura forza di volontà è raramente sufficiente. Strahad Farsan richiede tre verghe identiche per consentire ai suoi accoliti di canalizzare la loro magia all'unisono, stabilizzando il cerchio di evocazione mentre l'officiante intraprende il vincolamento. Gli oscuri incantatori del clan Fauce del Drago, inclusi i bonewarder e gli shadowwarder che infestano l'Accampamento Zannarabbiosa e le rovine circostanti nelle Wetlands, trasportano questi strumenti per le proprie nefaste pratiche. Sebbene siano tipicamente usurate e intaccate dal combattimento, le verghe rimangono potenti catalizzatori capaci di incanalare la caotica energia del nether."}},faq={{q="A cosa serve la Verga della Canalizzazione?",a="Le verghe vengono consegnate allo stregone Strahad Farsan sopra Porto Paranco. I suoi accoliti le usano per canalizzare e stabilizzare il cerchio magico necessario per evocare e vincolare un felhunter ostile.",al={"cos'è la verga della canalizzazione","scopo della verga della canalizzazione","perché serve la verga della canalizzazione"}},{q="Dove si possono trovare le Verghe della Canalizzazione?",a="Sono in possesso degli incantatori del clan Fauce del Drago, in particolare Dragonmaw Bonewarder e Shadowwarder, di stanza nelle Wetlands, soprattutto intorno all'Accampamento Zannarabbiosa.",al={"dove trovare le verghe della canalizzazione","chi rilascia la verga della canalizzazione","posizione della verga della canalizzazione"}},{q="Perché Strahad ha bisogno di tre verghe?",a="Strahad impiega molteplici accoliti per assistere nel rituale di evocazione del felhunter. Ciascun assistente necessita di un catalizzatore dedicato per mantenere aperto il condotto in sicurezza mentre lo stregone sottomette la bestia.",al={"perché tre verghe","perché 3 verghe della canalizzazione"}},{q="Perché i Fauce del Drago usano queste verghe?",a="Il clan Fauce del Drago pratica lo sciamanesimo oscuro e retaggi dell'occultismo dell'Old Horde. I loro bonewarder e shadowwarder usano le verghe per canalizzare maledizioni, negromanzia e Shadow Magic nelle loro continue guerre territoriali nelle Wetlands.",al={"verghe fauce del drago","perché i fauce del drago le possiedono"}}},fx={af4e8f1c={q="Cos'è una Verga della Canalizzazione?",a="Una Verga della Canalizzazione è un focus arcano utilizzato dagli incantatori per focalizzare e imbrigliare energie magiche volatili. Sebbene originariamente impugnate dagli incantatori oscuri del clan Fauce del Drago nelle Paludi, queste verghe sono potenti strumenti rituali in grado di stabilizzare evocazioni di alto ordine se maneggiate da stregoni esperti.",al={"cos'è la verga della canalizzazione","storia della verga della canalizzazione","informazioni sulla verga della canalizzazione"}}},fp="17,268,22.603.0,39.175.0,38.165.0,33.188.0,39.236.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Medaglioni di Rolf e Malakai",s="I Medaglioni di Rolf e Malakai sono i distintivi di servizio di due guardie di Roccavento svanite durante una ronda nella Foresta di Elwynn orientale. Con l'insegna del regno, questi oggetti sono cercati dalla Guardia Thomas per determinare il destino dei suoi compagni scomparsi.",h="I Medaglioni di Rolf e Malakai sono i distintivi di servizio di due guardie di Roccavento svanite durante una...",kw={"vallevante","elwynn","guardia thomas","malakai","medaglioni","murloc","rolf","guardia di roccavento"},ang={["faction:Alliance"]="I medaglioni sono un cupo promemoria del fatto che, persino nel cuore dell'Alleanza, le guardie locali affrontano pericoli mortali a difesa delle rotte commerciali rurali.",["race:Human"]="Per gli umani di Elwynn, questi distintivi simboleggiano figli e difensori perduti le cui morti evidenziano la vulnerabilità del regno mentre l'esercito è impegnato altrove."},sec={{t="Una tetra conferma",b="Quando le guardie Rolf e Malakai sono scomparse lungo le rive dei fiumi della Foresta di Elwynn orientale, il comandante della loro postazione, la Guardia Thomas, temeva il peggio. Il ritrovamento dei loro medaglioni personali di guardia fornisce una prova inconfutabile della loro morte per mano dell'avanzata dei murloc. Per il presidio di Roccavento, questi distintivi non sono semplici ninnoli: rappresentano soldati caduti che hanno tenuto la linea contro le crescenti minacce delle terre selvagge quando l'esercito del regno era allo stremo."},{t="Distintivi di servizio",b="Come molti membri della guardia cittadina di Roccavento e delle pattuglie rurali, le guardie umane portano medaglioni di identificazione che testimoniano la loro lealtà e autorità sotto la corona. Riportare questi oggetti alla Guardia Thomas gli permette di registrare ufficialmente i suoi uomini scomparsi, annotare il loro sacrificio nel suo rapporto sul campo e dare l'allarme sulle aggressive tribù di murloc che si insediano vicino alle vie carovaniere."}},faq={{q="Cosa sono i Medaglioni di Rolf e Malakai?",a="Sono i distintivi ufficiali di identificazione di servizio portati dalle guardie Rolf e Malakai, due guardie di Roccavento di stanza nella Foresta di Elwynn orientale che sono state vittime di un'imboscata e uccise dai murloc.",al={"cosa sono i medaglioni","medaglione di rolf","medaglione di malakai"}},{q="A chi appartengono questi medaglioni?",a="Appartenevano alle guardie Rolf e Malakai, commilitoni di stanza sotto il comando della Guardia Thomas per sorvegliare il fiume e le strade tra Borgodoro e il Campo di Taglio di Vallevante.",al={"chi erano rolf e malakai","di chi sono i medaglioni"}},{q="A chi dovrei portare questi medaglioni?",a="Consegnali alla Guardia Thomas, che fa la guardia al ponte orientale lungo la strada che collega Borgodoro al Campo di Taglio di Vallevante.",al={"chi vuole i medaglioni","dove si consegnano","consegna dei medaglioni"}},{q="Perché questi medaglioni sono importanti per la Guardia Thomas?",a="La Guardia Thomas ha inviato entrambe le guardie in pattuglia e temeva che avessero fatto una brutta fine. Ricevere i loro medaglioni conferma la loro morte, permettendogli di documentare il loro sacrificio e di avvertire Roccavento della crescente minaccia dei murloc.",al={"perché thomas li vuole","reazione della guardia thomas"}}},fp="29,250,19.485.0,17.383.0,39.184.1,34.170.0,39.134.0,51.214.1"}
P.entries["item:rot-blossom"] = {n="Fiore Marcio",s="I Fiori Marci sono una flora ripugnante e necrotica che cresce tra le tombe sconsacrate di Boscovespro. Nutriti dal terreno corrotto e dai resti dei non morti, sono ricercati per le loro potenti e malsane proprietà alchemiche.",h="I Fiori Marci sono una flora ripugnante e necrotica che cresce tra le tombe sconsacrate di Boscovespro.",kw={"althea ebonlocke","borgoscuro","boscovespro","fiore marcio","skeletal fiend","skeletal horror","cimitero parcosereno","zombie juice"},ang={["faction:Alliance"]="Avventurarsi nella terra maledetta per raccogliere queste fioriture morbose funge anche da servizio a The Night Watch, contribuendo a mantenere i confini di Borgoscuro liberi da scheletri famelici.",["profession:Herbalism"]="A differenza delle normali erbe nutrite da luce e pioggia, i Fiori Marci sono ripugnanti anomalie botaniche alimentate puramente da marciume necrotico e terra di cimitero, offrendo un macabro esempio di flora corrotta."},sec={{t="Flora delle cripte",b="La corruzione innaturale di Boscovespro genera una vegetazione bizzarra e inquietante, e nulla è più perturbante del Fiore Marcio. Radicate nella terra profanata di cimiteri come il Cimitero Parcosereno, queste fioriture morbose prosperano in prossimità della morte. Voci locali affermano che possano persino attecchire all'interno dei teschi incrinati dei morti che camminano, in particolare di Skeletal Horror e Skeletal Fiend che si aggirano tra i tumuli. Per gli abitanti di Borgoscuro, raccoglierli è al contempo un compito macabro e una pericolosa necessità, poiché disturbare la loro terra significa affrontare i morti senza riposo."},{t="Un ingrediente raccapricciante",b="Nonostante la loro natura ripugnante, i Fiori Marci hanno uno scopo ben preciso nei miscugli locali. I boccioli contengono essenze oscure necessarie per distillare il Zombie Juice, un infuso disgustoso legato ai macabri sforzi di sopravvivenza di Boscovespro. Chi viene inviato a raccogliere i fiori si ritrova spesso ad aiutare involontariamente The Night Watch, abbattendo nel frattempo gli scheletri senza riposo che vagano per i cimiteri infestati."}},faq={{q="Dove si possono trovare i Fiori Marci?",a="I Fiori Marci crescono nel terreno corrotto dei cimiteri di Boscovespro, in particolare all'interno del Cimitero Parcosereno, e sono noti per spuntare dai resti dei mostri scheletrici non morti.",al={"dove cresce il fiore marcio","posizione fiore marcio","trovare fiori marci"}},{q="A cosa servono i Fiori Marci?",a="Sono un ingrediente fondamentale utilizzato dai distillatori e alchimisti locali per creare una miscela potente e disgustosa nota come Zombie Juice.",al={"uso fiore marcio","perché raccogliere fiori marci","a cosa serve il fiore marcio"}},{q="Perché questi fiori crescono negli scheletri?",a="La persistente magia oscura di Boscovespro infetta sia la terra che i morti senza pace. I Fiori Marci si nutrono direttamente di decomposizione e corruzione necrotica, il che consente loro di germogliare all'interno dei teschi e delle gabbie toraciche degli scheletri erranti.",al={"fiori marci nei teschi","fiore di orrore scheletrico","scheletri fiore marcio"}},{q="In che modo raccogliere i Fiori Marci aiuta Borgoscuro?",a="Chiunque si avventuri in luoghi come il Cimitero Parcosereno per raccogliere i fiori deve inevitabilmente abbattere gli Skeletal Horror e i Fiend che infestano l'area, offrendo un sollievo quanto mai necessario ad Althea Ebonlocke e all'assediata The Night Watch.",al={"althea ebonlocke fiore marcio","the night watch fiore marcio","aiutare borgoscuro"}}},fx={["93f3afdd"]={q="Cos'è un Fiore Marcio?",a="Un Fiore Marcio è una morbosa stranezza botanica che mette radici nei cimiteri contaminati di Boscovespro. Piuttosto che germogliare in un terreno sano, questi fiori cupi prosperano tra la decomposizione, germogliando notoriamente all'interno dei teschi cavi di Orrori Scheletrici e Demoni Scheletrici non morti. Infusi di energie impure, sono ricercati dalla gente del posto eccentrica che prepara potenti miscele dal marciume.",al={"cosa sono i fiori marci","oggetto fiore marcio","cos'è il fiore marcio"}}},fp="11,212,19.561.0,21.398.0,32.201.0,31.119.0,40.215.0,47.242.0"}
P.entries["item:rot-hide-ichor"] = {n="Icore di Pellemarcia"}
P.entries["item:rough-quartz"] = {n="Quarzo Grezzo",s="Il Quarzo Grezzo è un'umile pietra elementale donata agli sciamani novizi da una Manifestazione Minore della Terra. Sebbene piccolo e grezzo, funge da vitale nucleo spirituale necessario per fabbricare il primo Earth Totem di uno sciamano.",h="Il Quarzo Grezzo è un'umile pietra elementale donata agli sciamani novizi da una Manifestazione Minore della...",kw={"call of earth","invocatore della terra canaga","earth totem","manifestazione minore della terra","quarzo grezzo","valle delle sfide"},ang={["class:Shaman"]="Il Quarzo Grezzo rappresenta la tua primissima comunione con l'elemento della terra, ancorando i tuoi incantesimi e segnando il tuo cammino come vero tramite degli spiriti."},sec={{t="Cuore del Totem della Terra",b="Agli occhi di un profano, il quarzo grezzo sembra non essere altro che un comune ciottolo del deserto. Eppure, per uno sciamano in comunione con gli spiriti a Durotar o Mulgore, è un dono elementale offerto direttamente da una Manifestazione Minore della Terra. La pietra rappresenta la perseveranza, la pazienza e l'incrollabile forza. Quando viene presentato a un anziano come l'Invocatore della Terra Canaga nella Valle delle Sfide, il quarzo viene incastonato nel legno intagliato di un Earth Totem, fungendo da catalizzatore spirituale che collega direttamente il novizio sciamano alla terra vivente di Azeroth."}},faq={{q="A cosa serve il Quarzo Grezzo?",a="Serve come prova che un novizio sciamano è entrato in comunione con lo spirito elementale della terra. Uno sciamano anziano usa questo ciottolo come nucleo spirituale quando intaglia il primissimo Earth Totem dell'iniziato.",al={"a cosa serve il quarzo grezzo","uso del quarzo grezzo","perché serve il quarzo grezzo"}},{q="Chi ti dà il Quarzo Grezzo?",a="Viene concesso da una Manifestazione Minore della Terra dopo essere entrati in comunione con lo spirito durante il rituale Call of Earth a Durotar o Mulgore.",al={"dove trovare il quarzo grezzo","chi rilascia il quarzo grezzo"}},{q="A chi devo portare questa pietra a Durotar?",a="Portala all'Invocatore della Terra Canaga, l'istruttore degli sciamani che risiede nella Valle delle Sfide, il quale la forgerà nel tuo Earth Totem.",al={"dove consegnare il quarzo grezzo","consegna del quarzo grezzo","chi accetta il quarzo grezzo"}},{q="Questo quarzo viene usato per qualcos'altro?",a="No. È un oggetto rituale puramente sacro destinato unicamente alla creazione di un Earth Totem e non ha alcun utilizzo nel commercio comune.",al={"si può vendere il quarzo grezzo","il quarzo grezzo serve per creare oggetti"}}},fx={f25f16be={q="Cos'è il Quarzo Grezzo?",a="Il Quarzo Grezzo è un piccolo ciottolo elementale dato agli aspiranti sciamani da una Manifestazione Minore della Terra. Sebbene modesto nelle dimensioni e nell'aspetto, la pietra rappresenta il superamento da parte di un iniziato del rito della terra e la comunione con lo spirito elementale, fungendo da prova tangibile del loro legame.",al={"cos'è il quarzo grezzo","oggetto quarzo grezzo","significato del quarzo grezzo"}},["871e2ee1"]={q="Perché l'Invocatore della Terra Canaga vuole il Quarzo Grezzo?",a="L'Invocatore della Terra Canaga richiede il Quarzo Grezzo come prova che hai ascoltato la chiamata e sei entrato in comunione con lo spirito elementale. Usa il ciottolo come cuore del tuo primo Totem della Terra, permettendoti di entrare ulteriormente in comunione con la terra e lanciare incantesimi legati direttamente al suo potere.",al={"perché serve il quarzo grezzo","scopo del quarzo grezzo","perché portare il quarzo grezzo a canaga"}}},fp="12,211,24.543.0,40.192.0,31.136.0,40.127.0,38.114.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Munizioni di Granzuffa",s="Munizioni di Granzuffa è una cassa smarrita di munizioni destinata all'armaiolo Hegnar Granzuffa a Dun Morogh. Perduta quando uno spaventato corriere fuggì da wendigo affamati, la pesante cassa giace abbandonata nella neve vicino alla Tana Selvaggia.",h="Munizioni di Granzuffa è una cassa smarrita di munizioni destinata all'armaiolo Hegnar Granzuffa a Dun Morogh.",kw={"munizioni","cassa","dun morogh","tana selvaggia","hegnar","loslor","granzuffa","wendigo"},ang={["class:Hunter"]="Per i tiratori che vagano nel gelo pungente di Dun Morogh, mantenere asciutta la polvere da sparo di Hegnar e riforniti i suoi proiettili garantisce un approvvigionamento costante di munizioni per le armi da fuoco naniche.",["profession:Engineering"]="Gli ingegneri e gli artigiani nanici fanno grande affidamento su un flusso costante di proiettili e polvere da sparo per collaudare le loro armi da fuoco create e gli armamenti sperimentali."},sec={{t="Una spedizione bloccata",b="Hegnar Granzuffa gestisce un'armeria lungo la strada sul sentiero di montagna che scende dal Passo Crestafredda verso Forgiamara. Con i fucilieri di Forgiardente, i montanari e le squadre di mortai naniche che si addestrano costantemente tra le alture innevate, le sue scorte si consumano quasi alla stessa velocità con cui la polvere prende fuoco. Questa particolare spedizione di proiettili era stata inviata da Loslor da Kharanos, ma non ha mai raggiunto gli scaffali. Il corriere incaricato di trasportarla si accampò troppo vicino ai famelici wendigo della Tana Selvaggia, fu preso dal panico quando venne attaccato e fuggì per salvarsi la vita, lasciando la pesante cassa di rifornimenti nel profondo dei terreni di caccia delle bestie."}},faq={{q="Chi è Hegnar Granzuffa?",a="Hegnar Granzuffa è un armaiolo nano che gestisce un negozio lungo la strada verso Forgiamara. Rifornisce i tiratori, i cacciatori e gli artiglieri militari locali che consumano rapidamente munizioni mentre si addestrano tra i dirupi di Dun Morogh.",al={"granzuffa","chi è hegnar","mercante di armi da fuoco"}},{q="Come è andata perduta la cassa di munizioni?",a="Un corriere incaricato della consegna della cassa commise l'errore di accamparsi vicino all'entrata della Tana Selvaggia. Quando i territoriali wendigo della tana attaccarono il suo accampamento, il corriere terrorizzato scappò, lasciandosi alle spalle la pesante cassa nella neve.",al={"perché le munizioni sono andate perdute","cosa è successo alle munizioni","corriere munizioni"}},{q="Dove si trova la Tana Selvaggia?",a="La Tana Selvaggia è un complesso di caverne scavato nelle montagne a sud-ovest di Kharanos. Funge da famigerato covo per i feroci wendigo di Dun Morogh, rendendo i pendii circostanti pericolosi per i viaggiatori solitari.",al={"posizione tana selvaggia","dove si trova la caverna dei wendigo"}}},fx={["4221fe47"]={q="Cosa sono le Munizioni di Granzuffa?",a="È una cassa di munizioni fresche preparata per il negozio di Hegnar Granzuffa, lungo la strada per Forgiamara. Con i fucilieri e le squadre di mortaio naniche locali che si esercitano costantemente nelle vicinanze, Hegnar dipende da spedizioni regolari come questa per mantenere i suoi scaffali riforniti e i suoi clienti armati.",al={"cosa sono le munizioni di granzuffa","cassa di munizioni di granzuffa","cosa sono queste munizioni"}},["008970c2"]={q="Da dove vengono le Munizioni di Granzuffa?",a="La cassa è stata fornita e spedita da Loslor Rudge da Kharanos. Sfortunatamente, il corriere incaricato di portarla a sud-ovest verso Forgiamara è stato imboscato da feroci wendigo vicino alla Tana Selvaggia ed è fuggito, abbandonando l'intero carico nella neve.",al={"chi ha fabbricato le munizioni di granzuffa","da dove vengono le munizioni di granzuffa","chi ha spedito le munizioni"}},["6d6b5eaa"]={q="Perché Hegnar Granzuffa ha bisogno di queste munizioni?",a="Hegnar è sul punto di esaurire completamente le scorte. I montanari, i fucilieri e le squadre di mortaio nelle vicinanze consumano polvere da sparo e proiettili a un ritmo vertiginoso durante le esercitazioni di tiro, lasciando molti acquirenti impazienti in attesa del momento in cui arriverà la nuova spedizione.",al={"perché servono le munizioni di granzuffa","perché volere le munizioni di granzuffa","chi ha bisogno delle munizioni di granzuffa"}}},fp="17,229,19.631.0,25.224.0,32.242.0,26.212.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Cartapecora con Rune",s="Una missiva scritta consegnata agli aspiranti sciamani orchi nella Valle delle Sfide. Redatta dall'istruttore Shikrik e distribuita da Gornek, chiama gli iniziati ad abbracciare il loro ruolo di guide spirituali e canali per gli spiriti elementali.",h="Una missiva scritta consegnata agli aspiranti sciamani orchi nella Valle delle Sfide.",kw={"durotar","gornek","cartapecora","cartapecora con rune","sciamano","shikrik","valle delle sfide"},ang={["class:Shaman"]="Questo messaggio inciso con rune segna il tuo primissimo passo lungo il sentiero degli elementi, ponendoti sotto la tutela di Shikrik per apprendere il culto degli antenati e la maestria elementale.",["race:Orc"]="La riscoperta della tradizione sciamanica è fondamentale per la New Horde, e questa pergamena rappresenta la continuazione della saggezza ancestrale a Durotar."},sec={{t="Una chiamata agli spiriti",b="All'interno del canyon riarso dal sole della Valle delle Sfide, i nuovi sciamani orchi iniziano il loro addestramento sotto lo sguardo vigile di sorveglianti veterani. Durante lo svolgimento delle prime prove per Gornek, a un iniziato viene consegnato questo documento ricoperto di rune. Inviata direttamente da Shikrik, l'istruttore sciamanico locale, la pergamena funge da convocazione formale verso i misteri più profondi della comunione elementale. La cultura orchesca considera lo sciamano non semplicemente come un incantatore da battaglia, ma come un mediatore essenziale tra i vivi e gli antenati. Questo breve scritto segna il passaggio dalla semplice forza bruta al sentiero disciplinato della venerazione degli antenati."}},faq={{q="Cos'è la Cartapecora con Rune?",a="È un messaggio scritto a mano consegnato ai novizi sciamani orchi da Gornek nella Valle delle Sfide. Ordina al lettore di presentarsi dall'istruttore degli sciamani Shikrik per iniziare l'addestramento formale.",al={"cartapecora runica","cos'è questo oggetto","cartapecora dello sciamano"}},{q="Chi ha scritto la pergamena?",a="La pergamena è stata scritta da Shikrik, l'istruttore degli sciamani di stanza nella Valle delle Sfide, che desiderava istruire i giovani iniziati alle vie degli elementi e degli spiriti ancestrali.",al={"chi ha inviato la cartapecora","autore della cartapecora"}},{q="Perché gli sciamani sono considerati prescelti tra gli orchi?",a="Gli sciamani orchi agiscono come guide spirituali e canali per i loro antenati, ascoltando gli spiriti elementali per guidare il loro popolo. Shikrik ricorda agli apprendisti che il loro dovere include sia il curare gli alleati che lo scatenare la furiosa ira degli elementi contro i loro nemici.",al={"perché essere uno sciamano","ruolo dello sciamano orco"}}},fx={["00232829"]={q="Perché Shikrik vuole che tu legga la Cartapecora con Rune?",a="Shikrik ha inviato questo messaggio tramite Gornek per convocarti direttamente da lei. Avendo riconosciuto che sei stato scelto per guidare la vita spirituale della tua gente, intende iniziare il tuo addestramento formale nella comunione con gli antenati, nella maestria elementale e nei riti di uno sciamano orco.",al={"perché leggere la cartapecora con rune","perché shikrik invia la cartapecora","scopo della cartapecora con rune"}}},fp="24,234,24.631.0,37.182.0,24.181.0,49.263.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Pendente con Rune Inscritte",s="Il Pendente con Rune Inscritte è un ninnolo magico recuperato dalle spedizioni di rifornimenti di Dalaran destinate a Mulino d'Ambra. Molto apprezzati dal Kirin Tor, questi pendenti fungono da condotti per incanalare potenti energie arcane.",h="Il Pendente con Rune Inscritte è un ninnolo magico recuperato dalle spedizioni di rifornimenti di Dalaran...",kw={"allister","mulino d'ambra","dalar tessalba","dalaran","kirin tor","pendente","pendente con rune inscritte","mausolea"},ang={["class:Mage"]="I maghi riconoscono facilmente la maestria artigianale del Kirin Tor; le rune scolpite nel pendente sono progettate per stabilizzare correnti volatili durante la canalizzazione di incantesimi di ordine superiore.",["race:Undead"]="Per i Forsaken a guardia della Selva Pinargento, i catalizzatori intercettati di Dalaran come questo pendente forniscono Vital Intelligence sulla resistenza umana che si raduna dietro le mura di Mulino d'Ambra."},sec={{t="Reliquia del Kirin Tor",b="Scoperto tra casse di forniture cartografiche dirette all'enclave di Dalaran a Mulino d'Ambra, questo pendente reca intricate iscrizioni arcane. I maghi di alto rango del Kirin Tor impiegano frequentemente tali manufatti per focalizzare e amplificare i loro incantesimi. La presenza di numerosi pendenti canalizzatori in arrivo nella regione suscita immediatamente i sospetti dei Forsaken a Mausolea, segnalando un imminente progetto di immenso potere magico."},{t="Un Indizio sui Piani di Mulino d'Ambra",b="Quando viene portato a Mausolea, il Sacerdote dell'Ombra Allister riconosce la minaccia rappresentata dalla posizione fortificata dei maghi di Dalaran, ma cede la reliquia a Dalar Tessalba per un esame più approfondito. Tessalba identifica il pendente come una componente chiave delle operazioni dei maghi, deducendo che il Kirin Tor stia accumulando strumenti di focalizzazione arcana per alimentare imponenti opere difensive o offensive protette dietro i confini di Mulino d'Ambra."}},faq={{q="A cosa serve il Pendente con Rune Inscritte?",a="I maghi del Kirin Tor usano il pendente per canalizzare e dirigere notevoli flussi di energia magica. Funziona come un catalizzatore arcano per complessi incantesimi piuttosto che come un semplice ornamento.",al={"cosa fa il pendente","scopo del pendente","uso del pendente con rune"}},{q="Da dove proviene questo pendente?",a="Viene intercettato da spedizioni di rifornimenti dirette a Mulino d'Ambra nella Selva Pinargento, dove i superstiti del Kirin Tor si sono pesantemente fortificati.",al={"dove trovare il pendente","origine del pendente","dove è stato trovato"}},{q="Chi analizza il pendente a Mausolea?",a="Dopo che il Sacerdote dell'Ombra Allister lo esamina brevemente insieme a mappe catturate, lo invia a Dalar Tessalba, uno specialista dell'arcano a Mausolea che riconosce la fattura del Kirin Tor.",al={"chi studia il pendente","chi vuole il pendente","pendente di dalar"}},{q="Perché i Forsaken ne sono preoccupati?",a="La spedizione di grandi quantità di pendenti canalizzatori suggerisce che il Kirin Tor a Mulino d'Ambra stia preparando un'imponente operazione magica, minacciando la presa dei Forsaken sulla Selva Pinargento.",al={"perché interessa ai reietti","minaccia di mulino d'ambra","perché il pendente è pericoloso"}}},fx={bf28d080={q="Cos'è il Pendente con Rune Inscritte?",a="È un artefatto arcano creato e utilizzato dai potenti maghi di Dalaran. Spesso usato dal Kirin Tor per concentrare e incanalare enormi energie magiche, tali pendenti sono condotti di potente potere arcano piuttosto che semplici ornamenti.",al={"cos'è il pendente con rune inscritte","identità del pendente con rune","cos'è questo pendente di dalaran"}}},fp="22,208,15.444.0,27.417.1,44.182.0,33.141.0,42.180.0,40.188.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Tavoletta con Rune",s="Una Tavoletta con Rune è un messaggio di pietra consegnato ai giovani sciamani Troll Lanciascura nella Valle delle Sfide. Consegnata da Gornek, indirizza i mistici promettenti a iniziare la comunione formale con gli elementi sotto la guida dell'istruttore orco Shikrik.",h="Una Tavoletta con Rune è un messaggio di pietra consegnato ai giovani sciamani Troll Lanciascura nella Valle...",kw={"lanciascura","durotar","gornek","tavoletta con rune","sciamano","shikrik","istruttore","valle delle sfide"},ang={["class:Shaman"]="La tavoletta rappresenta il primo passo ufficiale di uno sciamano verso la padronanza degli elementi di terra, fuoco, acqua e aria, ricordando agli studenti che la loro forza scaturisce dagli spiriti ancestrali.",["race:Troll"]="Per i Troll Lanciascura, rispondere alla convocazione di un istruttore orco evidenzia il legame crescente e il cammino spirituale condiviso tra i troll e i loro nuovi alleati dell'Orda."},sec={{t="Una chiamata agli spiriti",b="Incisa con rune elementali, questa tavoletta funge da invito formale per i nascenti sciamani troll che muovono i loro primi passi a Durotar. Quando un iniziato dimostra il proprio valore nella Valle delle Sfide, il sovrintendente Gornek presenta la pietra, inviata dallo sciamano troll Ishi-yo per indirizzare l'iniziato all'istruttore degli sciamani Shikrik. Per i Troll Lanciascura, che possiedono profonde tradizioni spirituali proprie, la tavoletta segna l'inizio del loro cammino condiviso con gli orchi, unendo l'antico misticismo dei troll con il rinnovato retaggio sciamanico promosso dal Warchief Thrall."}},faq={{q="A cosa serve la Tavoletta con Rune?",a="La tavoletta è un messaggio introduttivo consegnato da Gornek ai giovani sciamani troll nella Valle delle Sfide. Istruisce l'iniziato a presentarsi da Shikrik, l'istruttore locale degli sciamani, per iniziare la propria istruzione spirituale formale.",al={"scopo della tavoletta","cosa fa la tavoletta","uso della tavoletta con rune"}},{q="Chi invia la tavoletta?",a="La tavoletta è firmata da Ishi-yo, lo sciamano troll che ha impartito all'iniziato le sue prime lezioni. Lo invia da Shikrik, l'istruttore degli sciamani orco di stanza appena fuori dall'Antro del Tirocinio nella Valle delle Sfide, che sa già del suo arrivo.",al={"chi ha scritto la tavoletta","mittente della tavoletta","chi l'ha incisa"}},{q="Chi riceve questa tavoletta?",a="Solo i nuovi sciamani Troll Lanciascura appena giunti ricevono questa specifica tavoletta da Gornek come convocazione iniziale della loro classe a Durotar.",al={"chi riceve la tavoletta con rune","quale classe riceve la tavoletta"}}},fx={cd2cca59={q="Cos'è la Tavoletta con Rune?",a="La Tavoletta con Rune è una convocazione scritta diretta agli aspiranti sciamani troll che si addestrano nella Valle delle Sfide. Contrassegnata da rune sciamaniche, funge da messaggio personale trasmesso tramite Gornek per presentare le promettenti reclute direttamente al loro istruttore locale.",al={"cos'è la tavoletta con rune","storia della tavoletta con rune","cos'è questa tavoletta"}},["33b46b09"]={q="Perché Shikrik vuole che tu riceva la Tavoletta con Rune?",a="La tavoletta in realtà proviene da Ishi-yo, lo sciamano troll che ti ha dato le prime lezioni; Gornek ipotizza solo che provenga da Shikrik. Ishi-yo ti manda da Shikrik, che ti sta già aspettando. Lei vuole radicarti negli elementi e negli spiriti dei tuoi antenati, affinché un giorno tu possa guidare e proteggere i villaggi e le città dell'Orda proprio come Thrall guida l'Orda stessa.",al={"perché shikrik invia la tavoletta","perché mi serve questa tavoletta","tavoletta con rune di shikrik"}}},fp="21,253,24.578.0,43.234.0,21.237.0,25.126.0"}
P.entries["item:rune-of-nesting"] = {n="Runa della Nidificazione",s="La Runa della Nidificazione è una delle quattro sacre Relics of Wakening custodite all'interno dell'Eremo di Ban'ethil su Teldrassil. È un componente essenziale nel delicato rituale druidico necessario per richiamare in sicurezza i Druids of the Talon dormienti dal Sogno di Smeraldo.",h="La Runa della Nidificazione è una delle quattro sacre Relics of Wakening custodite all'interno dell'Eremo di...",kw={"athridas orsomanto","eremo di ban'ethil","chest of nesting","druids of the talon","sogno di smeraldo","relics of wakening","runa della nidificazione"},ang={["class:Druid"]="Per i druidi, la Runa della Nidificazione rappresenta i sacri rituali del Circolo Cenariano, evidenziando la vulnerabilità dei fratelli dormienti quando i santuari sacri vengono violati.",["race:NightElf"]="La profanazione degli eremi e la perdita di queste reliquie del risveglio sottolineano la crescente corruzione che affligge la fauna selvatica e i furbolg di Teldrassil."},sec={{t="Un catalizzatore sacro per il risveglio",b="I druidi elfi della notte affrontano lunghi letarghi ciclici all'interno degli eremi sotterranei per comunicare con la natura attraverso il Sogno di Smeraldo. Risvegliarsi da questa profonda trance non è semplicemente una questione di scuotersi; richiede un rituale preciso guidato da strumenti sacri. La Runa della Nidificazione, custodita al sicuro all'interno della Chest of Nesting nelle profondità delle tortuose camere dell'Eremo di Ban'ethil, ancora questo processo. Insieme al Talismano Artiglio del Corvo, alla Piuma Nera e allo Zaffiro del Cielo, la runa funge da tramite per richiamare i Druids of the Talon nel mondo della veglia."},{t="Crisi a Ban'ethil",b="Quando i corrupted Gnarlpine furbolg invasero l'Eremo di Ban'ethil, i difensori dormienti dell'eremo furono messi in pericolo immediato. Senza accesso alle loro reliquie, i druidi rischiavano di rimanere intrappolati nel Sogno di Smeraldo a tempo indefinito mentre gli invasori profanavano il loro santuario. Recuperare la Runa della Nidificazione e i manufatti che l'accompagnano permette ad Athridas Orsomanto a Dolanaar di preparare il rituale necessario per risvegliare in sicurezza i druidi in pericolo."}},faq={{q="A cosa serve la Runa della Nidificazione?",a="È una delle quattro Relics of Wakening richieste da Athridas Orsomanto per condurre il rituale che ridesta in sicurezza i Druids of the Talon dal loro profondo sonno nel Sogno di Smeraldo.",al={"cosa fa la runa della nidificazione","scopo della runa della nidificazione"}},{q="Dove si trova la Runa della Nidificazione?",a="È custodita all'interno della Chest of Nesting, situata nei tunnel sotterranei dell'Eremo di Ban'ethil, a ovest di Dolanaar su Teldrassil.",al={"dove si trova la runa della nidificazione","posizione della chest of nesting"}},{q="Perché i druidi dormienti non possono semplicemente svegliarsi da soli?",a="Entrare nel Sogno di Smeraldo in letargo è uno stato delicato, simile a una trance. Senza la guida di sacre reliquie e di un rituale di risveglio, il ritorno può rivelarsi impossibile, lasciando le loro menti alla deriva mentre i loro corpi fisici sono esposti al pericolo.",al={"perché i druidi hanno bisogno del rituale del risveglio","perché i druidi non possono svegliarsi"}},{q="Quali altre reliquie sono necessarie insieme alla Runa della Nidificazione?",a="Il rituale completo richiede quattro Relics of Wakening: la Runa della Nidificazione, il Talismano Artiglio del Corvo, la Piuma Nera e lo Zaffiro del Cielo.",al={"altre relics of wakening","oggetti relics of wakening"}}},fx={["375c0565"]={q="Cos'è la Runa della Nidificazione?",a="La Runa della Nidificazione è una delle quattro sacre Reliquie del Risveglio custodite dai Druidi del Talone a Teldrassil. Conservata all'interno di un forziere dedicato nell'Eremo di Ban'ethil, porta gli incantesimi specializzati necessari per eseguire correttamente il rituale di risveglio per i druidi che riposano in profonda comunione con il Sogno di Smeraldo.",al={"runa della nidificazione","cos'è la runa della nidificazione","storia della runa della nidificazione"}}},fp="15,260,28.574.0,19.448.0,37.183.0,35.142.0,58.245.0,59.145.0"}
P.entries["item:runes-of-summoning"] = {n="Rune dell'Evocazione",s="Le Rune dell'Evocazione sono un oggetto rituale fornito dall'istruttore dei warlock Carendin Halgar nel Magic Quarter di Undercity. Vengono utilizzate per richiamare un voidwalker non vincolato all'interno di un cerchio di evocazione, affinché un aspirante warlock possa piegarlo alla propria volontà.",h="Le Rune dell'Evocazione sono un oggetto rituale fornito dall'istruttore dei warlock Carendin Halgar nel Magic...",kw={"carendin halgar","magic quarter","rune dell'evocazione","the binding","undercity","voidwalker","warlock"},ang={["class:Warlock"]="I warlock dei Forsaken usano le rune per dimostrare il proprio dominio sul Void, trasformando un'ombra caotica in un servitore duraturo e leale.",["race:Undead"]="Nelle profondità sotterranee di Undercity, i praticanti dei Forsaken aggirano antichi tabù per vincolare entità del void direttamente sotto le Rovine di Lordaeron."},sec={{t="Sottomissione nel Magic Quarter",b="All'interno dei recessi oscuri del Magic Quarter di Undercity, i praticanti dei Forsaken delle arti oscure studiano la manipolazione del Nether. Carendin Halgar affida le Rune dell'Evocazione solo ai warlock che si sono preparati a prendere il comando di un voidwalker. Lanciando le rune all'interno del cerchio di evocazione attivo situato sotto la postazione di Halgar, il praticante squarcia il tessuto del Void, attirando una creatura che deve essere sopraffatta e vincolata alla servitù."}},faq={{q="A cosa servono le Rune dell'Evocazione?",a="Vengono utilizzate all'interno del cerchio di evocazione nel Magic Quarter di Undercity per attirare un voidwalker non vincolato dal Nether nel mondo fisico, permettendo a un warlock di sconfiggerlo e sottometterlo.",al={"scopo delle rune dell'evocazione","a cosa servono le rune dell'evocazione","come usare le rune dell'evocazione"}},{q="Chi fornisce le Rune dell'Evocazione?",a="Carendin Halgar, l'istruttore dei warlock dei Forsaken situato nel Magic Quarter di Undercity, le fornisce durante la fase finale dell'addestramento per vincolare un voidwalker.",al={"chi fornisce le rune dell'evocazione","istruttore rune dell'evocazione","carendin halgar rune"}},{q="Dove devono essere attivate le rune?",a="Devono essere portate al cerchio di evocazione viola situato direttamente sotto la piattaforma di Carendin Halgar nel Magic Quarter.",al={"dove si usano le rune dell'evocazione","posizione delle rune dell'evocazione","cerchio di evocazione undercity"}},{q="Cosa succede dopo che l'entità è stata evocata?",a="Il voidwalker attacca immediatamente. Il warlock deve sottometterlo con la forza della magia e delle armi. Una volta sconfitto, l'entità viene vincolata al servizio, e Carendin Halgar conferisce l'incantesimo permanente per evocarlo.",al={"cosa succede dopo aver usato le rune","voidwalker sottomesso","dopo aver evocato il voidwalker"}}},fx={["1ce5479a"]={q="Cosa sono le Rune dell'Evocazione?",a="Le Rune dell'Evocazione sono un catalizzatore rituale specializzato dato agli aspiranti stregoni Reietti nella Città Bassa. Quando portate al circolo di evocazione nel Magic Quarter, le rune concentrano le energie magiche per aprire un passaggio e richiamare un vuoto abissale scatenato dal Nether.",al={"cosa sono le rune dell'evocazione","rune dell'evocazione","oggetto rune dell'evocazione"}},["0508549c"]={q="Perché Carendin Halgar vuole che le Rune dell'Evocazione vengano restituite?",a="Carendin Halgar fornisce le rune specificamente come prova di maestria. Una volta attivate e sottomesso il vuoto abissale evocato in combattimento, restituire le rune gli dimostra che hai dominato la creatura, permettendogli di insegnarti correttamente l'incantesimo permanente per evocare e comandare i vuoti abissali.",al={"perché restituire le rune dell'evocazione","perché carendin vuole le rune","restituzione rune dell'evocazione"}}},fp="18,256,32.474.0,41.192.0,36.163.0,34.124.0,42.193.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Sacco di Teste di Murloc",s="Il Sacco di Teste di Murloc è un macabro fagotto raccolto lungo le spiagge delle Alture di Colletorto. Radunato come prova di un'azione militare contro i parassiti della costa locale, viene rifilato dal Tenente Farren Orinelle agli avventurieri di passaggio affinché lo consegnino al Maresciallo Tracciarossa a Riva del Sud.",h="Il Sacco di Teste di Murloc è un macabro fagotto raccolto lungo le spiagge delle Alture di Colletorto.",kw={"taglia","farren orinelle","teste","colletorto","maresciallo tracciarossa","murloc","riva del sud"},ang={["faction:Alliance"]="La consegna illustra la logistica logorata e gli ingrati fardelli quotidiani sopportati dai difensori di Riva del Sud mentre tengono unita l'enclave settentrionale dell'Alleanza."},sec={{t="Burocrazia e parassiti costieri",b="Riva del Sud è costantemente sotto assedio da parte dei fuorilegge del Sindacato, schermagliatori dei Reietti e murloc selvaggi che affollano la costa. Per ottenere finanziamenti e il favore della dirigenza cittadina, gli ufficiali locali devono dimostrare che le minacce costiere vengono attivamente abbattute. Il Tenente Farren Orinelle raccoglie le prove sotto forma di teste mozzate, ma la natura disgustosa del carico — e la sua stessa ritrosia — lo spinge a cedere il sacco grondante ai viaggiatori anziché consegnare di persona le macabre prove al Maresciallo Tracciarossa."}},faq={{q="Cos'è il Sacco di Teste di Murloc?",a="È un sacco di iuta pieno di teste mozzate di murloc raccolte dalle spiagge occidentali di Colletorto. Serve come prova tangibile della pacificazione costiera per il comandante della guarnigione di Riva del Sud.",al={"sacco di teste","sacco di murloc","cos'è questo oggetto"}},{q="Perché il Tenente Farren non lo consegna di persona?",a="Farren trova ripugnante trasportare una sacca maleodorante di teste putrescenti di uomini-pesce. Preferendo mantenere puliti uniforme e mani, delega la spiacevole incombenza attraverso Riva del Sud a un compiacente avventuriero.",al={"perché farren te lo fa portare","la scusa di farren","farren pigro"}},{q="Chi riceve il sacco?",a="La consegna viene effettuata al Maresciallo Tracciarossa, il comandante che supervisiona le difese di Riva del Sud, il quale valuta la sicurezza della cittadina ed esige prove tangibili degli sforzi difensivi.",al={"chi riceve le teste","dove lo porto","consegna al maresciallo tracciarossa"}},{q="Perché Riva del Sud richiede teste di murloc come prova?",a="I murloc compiono continue incursioni sulle coste e minacciano il porto. Ci si aspetta che gli ufficiali verifichino che le pattuglie mantengano la sicurezza perimetrale, e i trofei tangibili assicurano che nessun soldato si prenda semplicemente il merito per turni di guardia trascorsi a oziare.",al={"perché raccogliere teste di murloc","prova dell'uccisione"}}},fx={["3f14ed35"]={q="Da dove viene il Sacco di Teste di Murloc e chi l'ha fatto?",a="Il sacco è assemblato con le teste mozzate dei murloc che hai cacciato lungo la costa meridionale delle Alture di Colletorto. Il Tenente Farren Orinelle li ha impacchettati insieme per presentarli al suo ufficiale in comando, anche se ti restituisce rapidamente il ripugnante pacchetto affinché tu lo consegni al suo posto.",al={"chi ha fatto il sacco di teste di murloc","da dove viene il sacco di teste","chi ha dato il sacco di teste di murloc"}}},fp="20,285,29.515.0,33.189.0,47.208.0,22.171.0,50.226.0"}
P.entries["item:sack-of-supplies"] = {n="Sacca di Provviste",s="Questi sacchi di rifornimenti appartengono a un carico di una carovana destinato all'ingegnere goblin Rezlak, fuori da Orgrimmar. Trasportate attraverso Durotar, le merci sono state intercettate dalle arpie Dustwind che nidificano tra i dirupi del Canyon Brezza Aguzza.",h="Questi sacchi di rifornimenti appartengono a un carico di una carovana destinato all'ingegnere goblin Rezlak...",kw={"durotar","arpie dustwind","sparachiodi","canyon brezza aguzza","rezlak","sacca di provviste"},ang={["faction:Horde"]="Recuperare i rifornimenti perduti dai predatori locali assicura che le costruzioni di frontiera attorno alla nascente capitale di Orgrimmar procedano senza costosi ritardi."},sec={{t="Una carovana saccheggiata",b="Rezlak, un ingegnere ingaggiato a Porto Paranco da Sparachiodi, fa affidamento su carovane regolari attraverso Durotar per rifornire le sue attività di costruzione per l'Orda. Le distese selvagge di Durotar, tuttavia, sono tutt'altro che docili. Quando un carico promesso è transitato vicino alla strada del canyon a sud di Orgrimmar, ha subìto un'imboscata ed è stato saccheggiato dalle locali arpie Dustwind. Le feroci creature hanno trascinato il carico nel profondo dei loro posatoi all'interno del Canyon Brezza Aguzza, disperdendo i sacchi tra la terra e i detriti accanto ai nidi delle arpie."}},faq={{q="Cosa c'è dentro questi sacchi di rifornimenti?",a="I sacchi contengono materiali da costruzione e merci commerciali spediti per conto delle operazioni ingegneristiche di Sparachiodi, destinati a supportare i progetti edilizi orcheschi vicino a Orgrimmar. Senza di essi, Rezlak rimane bloccato senza rifornimenti per portare a termine il suo lavoro.",al={"contenuto del sacco di rifornimenti","cosa c'è nei sacchi","rifornimenti di rezlak"}},{q="Chi ha rubato i rifornimenti?",a="I rifornimenti sono stati rubati dalle arpie Dustwind, una selvaggia razza aviaria che infesta gli alti anfratti e le gole del Canyon Brezza Aguzza.",al={"chi ha preso i rifornimenti","chi ha rubato i sacchi"}},{q="Chi è Rezlak?",a="Rezlak è un ingegnere goblin inviato da Sparachiodi da Porto Paranco per assistere l'Orda con le infrastrutture edilizie e viarie a Durotar.",al={"chi è rezlak","storia di rezlak"}}},fx={["812e6d27"]={q="Da dove vengono questi sacchi di provviste?",a="Questi sacchi facevano parte di una spedizione inviata a Durotar per conto di Gazlowe e dei suoi ingegneri goblin. Destinati ad aiutare gli orchi a costruire e mantenere i loro insediamenti, la carovana che li trasportava è stata imboscata e saccheggiata lungo la strada prima che potesse raggiungere la sua destinazione.",al={"origine del sacco di provviste","da dove vengono le provviste","chi ha fatto il sacco di provviste"}},["55ee41bd"]={q="Perché Rezlak vuole questi sacchi di provviste?",a="Rezlak non può svolgere i lavori di costruzione assegnatigli da Gazlowe senza l'attrezzatura e i materiali adeguati. Le arpie del Canyon Brezza Aguzza hanno saccheggiato la carovana che trasportava i suoi attrezzi e le sue provviste, lasciando il caposquadra goblin completamente bloccato finché qualcuno non recupera il carico rubato.",al={"perché rezlak vuole le provviste","perché servono i sacchi di provviste","provviste nel deserto perché"}}},fp="16,228,19.496.0,34.232.0,23.133.0,14.132.0"}
P.entries["item:salty-scorpid-venom"] = {n="Veleno Salato di Scorpide",s="Il Veleno Salato di Scorpide è un fluido caustico ricavato dagli scorpidi che si aggirano per le Distese Salate a Millepicchi. Ricco di sali naturali provenienti dal suolo desertico, è molto apprezzato dai piloti di razzi gnomici nel tentativo di progettare un carburante volatile e caldissimo.",h="Il Veleno Salato di Scorpide è un fluido caustico ricavato dagli scorpidi che si aggirano per le Distese...",kw={"fizzle brassbolts","pista dei miraggi","veleno salato di scorpide","scorpid reaver","scorpid terror","veleno di scorpide","distese salate","millepicchi"},ang={["profession:Engineering"]="Gli inventori che armeggiano nelle Distese Salate guardano costantemente oltre il petrolio e il carbone convenzionali, testando le tossine organiche come acceleranti di combustione volatili.",["race:Gnome"]="Solo l'ingegno gnomico penserebbe di prendere il letale veleno del deserto, combinarlo con nega-catalizzatori e iniettarlo in un motore a razzo solo per limare qualche secondo dal tempo sul giro."},sec={{t="Un agente di combustione volatile",b="Gli scorpidi che strisciano nell'arida distesa delle Distese Salate si sono adattati a un ambiente intensamente ricco di minerali. Nel corso delle generazioni, il veleno di bestie come gli Scorpid Reaver e gli Scorpid Terror ha assorbito enormi quantità di sale locale. Invece di preparare antidoti o veleni standard, gli inventori gnomici come Fizzle Brassbolts apprezzano questo composto caustico come potenziale additivo per il carburante ad alta combustione dei motori."},{t="Alimentare la rivalità della pista",b="Presso la Pista dei Miraggi, la rivalità ingegneristica tra gnomi e goblin spinge gli inventori a testare materiali sempre più pericolosi nelle loro auto a razzo. Fizzle Brassbolts ritiene che far bollire il veleno salato, trattarlo con catalizzatori specializzati e mescolarlo nei serbatoi del propellente fornirà il calore ardente necessario per superare i piloti goblin sulle distese di sale."}},faq={{q="Quali creature producono il Veleno Salato di Scorpide?",a="Viene raccolto dai pericolosi scorpidi che vagano per le distese salate a Millepicchi, in particolare Scorpid Reaver e Scorpid Terror.",al={"chi rilascia il veleno salato di scorpide","dove trovare il veleno di scorpide","fonte del veleno di scorpide"}},{q="Perché il veleno è così salato?",a="Gli scorpidi vivono interamente sul terreno incrostato di minerali delle Distese Salate. La loro fisiologia assorbe i fitti sali del letto del lago prosciugato, infondendo nelle loro ghiandole velenifere una marcata concentrazione salina.",al={"perché è salato","spiegazione del salt flat venom","storia del sale dello scorpide"}},{q="Chi vuole questo veleno e perché?",a="Fizzle Brassbolts, un ingegnere gnomo di stanza alla Pista dei Miraggi, cerca il veleno per formulare una miscela di carburante sperimentale che bruci abbastanza calda da spingere la sua auto a razzo verso la vittoria.",al={"chi ha bisogno del veleno di scorpide","perché fizzle vuole il veleno","oggetto di missione di fizzle brassbolts"}}},fx={["9840b612"]={q="Cos'è il Veleno Salato di Scorpide?",a="È un fluido potente e ricco di minerali raccolto dagli scorpidi che si aggirano per le Distese Salate. Il duro bacino salino prosciugato ha causato agli orrori e ai saccheggiatori scorpidi locali lo sviluppo di un veleno insolitamente saturo di sale. Sebbene letale come tossina naturale, le sue proprietà chimiche reattive lo rendono molto più interessante per gli armaioli come reagente grezzo volatile che come semplice veleno.",al={"cos'è il veleno salato di scorpide","veleno salato di scorpide","veleno di scorpide distese salate"}}},fp="19,253,27.425.0,27.377.0,43.138.0,26.212.0,29.185.0"}
P.entries["item:samophlange-item"] = {n="Samophlange (item)",s="Il samophlange è un enigmatico componente meccanico recuperato dalle profondità di una console di controllo automatizzata nelle Barrens. Nonostante il suo aspetto complesso, la sua precisa funzione rimane un mistero ingegneristico perfino per i meccanici goblin che lo cercavano.",h="Il samophlange è un enigmatico componente meccanico recuperato dalle profondità di una console di controllo...",kw={"the barrens","console","porto paranco","samophlange","sputavalvole","tinkers' union","undermine"},ang={["profession:Engineering"]="Gli ingegneri apprezzeranno il samophlange come un esempio per eccellenza di progettazione ipercomplicata, in cui una facciata intricata nasconde un meccanismo così fragile che si rompe nel momento in cui tocca il pavimento."},sec={{t="Un marchingegno sconcertante",b="Nascosto dietro un labirinto di cablaggi superflui e tubi vuoti all'interno di una console di controllo nelle Barrens si trova il samophlange. Ci vuole un po' di ricerca attraverso macchinari volutamente confusi solo per rimuoverlo dal suo alloggiamento. Agli occhi di un profano, sembra un nesso essenziale di ingranaggi e tecnologia a vapore. Per gli inventori goblin, è un irresistibile rompicapo meccanico destinato a essere spedito alla Tinkers' Union a Undermine, sebbene la sua struttura fragile significhi che raramente sopravvive a una manipolazione casuale abbastanza a lungo da essere compreso."},{t="Curiosità e catastrofe",b="Una volta recuperato e portato a Sputavalvole a Porto Paranco, l'ingegnere intende spedire il pezzo per farlo analizzare e studiare dalle menti di alto rango dell'Unione. Tuttavia, la curiosità dei goblin ha inevitabilmente la meglio sulla discrezione professionale. Il semplice appoggiare a terra il delicato dispositivo per ispezionarne i meccanismi interni è spesso sufficiente a ridurlo in frantumi."}},faq={{q="Cos'è un samophlange?",a="È un bizzarro componente meccanico estratto dal cuore di una console di controllo nelle Barrens. Il suo scopo effettivo è sconosciuto, poiché i macchinari circostanti sono stipati di tubi e cavi che sembrano non avere alcuna utilità pratica.",al={"cosa fa un samophlange","scopo del samophlange","cos'è questo oggetto"}},{q="Chi vuole il samophlange?",a="Sputavalvole, un ingegnere di stanza nella città portuale di Porto Paranco, chiede ai viaggiatori di recuperare il componente per poterlo studiare ed eventualmente inviare alla Tinkers' Union.",al={"a chi serve il samophlange","a chi devo dare il samophlange"}},{q="Cosa ne fa Sputavalvole?",a="Sebbene pianifichi di inviarlo a Undermine per un esame approfondito da parte dei ricercatori della Tinkers' Union, cerca prima di dare un'occhiata più da vicino lui stesso. Dopo averlo posato a terra per ispezionarlo, il fragile meccanismo si rompe immediatamente.",al={"sputavalvole samophlange","cosa succede al samophlange"}},{q="Da dove viene il samophlange?",a="È alloggiato all'interno di un'elaborata console operativa situata nelle distese settentrionali delle Barrens, nascosto dietro strati di ingegneria confusa e apparentemente inutile.",al={"posizione del samophlange","dove si trova"}}},fp="18,261,22.542.0,25.355.1,22.241.0,26.178.0,34.231.1,36.167.0"}
P.entries["item:samophlange-manual"] = {n="Manuale per Samoflago",s="Il Manuale per Samoflago è una guida operativa tecnica che illustra il funzionamento interno dell'elusivo samoflago. Custodite sotto stretta sorveglianza dalla S.P.R. & Co., le sue pagine sparse contengono le istruzioni necessarie agli ingegneri goblin per riparare e azionare questo bizzarro congegno.",h="Il Manuale per Samoflago è una guida operativa tecnica che illustra il funzionamento interno dell'elusivo...",kw={"the barrens","boss copperplug","miniera di pietravera","ingegneria","manuale","rilli greasygob","samoflago","sputavalvole","s.p.r. & co."},ang={["faction:Horde"]="Recuperare il manuale consente ai goblin allineati con l'Orda a Orgrimmar di studiare e riutilizzare i macchinari di trivellazione aziendali proprio sotto il naso della S.P.R. & Co.",["profession:Engineering"]="Il manuale rappresenta la tecnologia proprietaria della S.P.R. & Co., mostrando come gli inventori goblin custodiscano ossessivamente i segreti commerciali e gli schemi funzionali dai loro colleghi."},sec={{t="I segreti del congegno",b="Gli schemi ingegneristici e i manuali operativi sono custoditi come oro tra le imprese goblin, e il Manuale per Samoflago non fa eccezione. Mentre lavorava all'interno della S.P.R. & Co., un ambizioso sovrintendente di nome Boss Copperplug accumulò gelosamente le conoscenze relative al dispositivo, distribuendo solo pagine sparse ai suoi subordinati più fedeli per mantenere il controllo sui macchinari. Quando il dispositivo sfuggì alla presa della S.P.R. & Co., ripararlo si rivelò impossibile senza raccogliere la documentazione strappata e distribuita dal sovrintendente e dalla sua squadra presso la Miniera di Pietravera."},{t="L'ambizione di un rivale",b="Dopo aver interrotto i rapporti con la S.P.R. & Co., l'ingegnere goblin Rilli Greasygob si è stabilito a Orgrimmar con la speranza di padroneggiare la costruzione del samoflago. Privo del favore di Copperplug durante il suo precedente impiego, Rilli si affida a viaggiatori intraprendenti per recuperare la copertina e i fogli sciolti del manuale. Ricostruire il manuale offre agli inventori goblin che lavorano a fianco dell'Orda una rara finestra sull'ingegneria proprietaria della S.P.R. & Co."}},faq={{q="Che cos'è il Manuale per Samoflago?",a="È un manuale di ingegneria che descrive in dettaglio come azionare e riparare il samoflago, un complesso ed eccentrico dispositivo meccanico utilizzato dalla S.P.R. & Co. a The Barrens.",al={"cos'è il manuale per samoflago","libro del samoflago","guida al samoflago"}},{q="Chi possedeva originariamente il manuale?",a="Era custodito gelosamente da Boss Copperplug, un sovrintendente della S.P.R. & Co. di stanza alla Miniera di Pietravera nella parte nord-orientale di The Barrens. Copperplug ne proteggeva attentamente i segreti, razionando le singole pagine solo ai suoi lavoratori più fidati.",al={"chi ha il manuale","manuale di boss copperplug","chi ha scritto il manuale"}},{q="Perché il manuale è diviso in pagine?",a="Boss Copperplug ha intenzionalmente diviso il libro per impedire a rivali o subordinati non fidati di comprendere l'intero dispositivo. Ha tenuto la copertina del manuale distribuendo cinque pagine specifiche tra i suoi minatori e operatori.",al={"perché trovare le pagine del manuale","pagine del manuale sparse","perché mancano le pagine"}},{q="Chi vuole leggere il manuale completo?",a="Rilli Greasygob, un ingegnere che opera da Orgrimmar, ha bisogno del manuale ricomposto per comprendere e riparare il Samoflago Rotto recuperato da The Barrens.",al={"a chi serve il manuale","rilli greasygob","chi vuole il manuale per samoflago"}},{q="A cosa serve un samoflago?",a="Nessuno al di fuori della S.P.R. & Co. sembra saperlo. La compagnia ne stava sperimentando uno in un piccolo sito di ricerca a sud-ovest della Palude Fangosa a The Barrens, e persino gli ingegneri che lo hanno studiato non sono riusciti a cavarne molto.",al={"cosa fa il samoflago","scopo del samoflago"}}},fp="18,280,26.574.0,18.455.0,31.166.0,32.230.0,34.226.0,39.162.0,31.226.0"}
P.entries["item:sample-ichor"] = {n="Icore Campione"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Campione di Mistura di Zanzil Alterata",s="Questa fiala contiene un potente campione di un intruglio preparato dal fattucchiere Zanzil, recuperato durante un'infiltrazione segreta nei The Barrens. Trasportato da un agente che soffre dei suoi effetti debilitanti, il campione viene inviato oltre il mare a Mulino di Tarren nella speranza di scoprire sia un antidoto sia i letali segreti della creazione di veleni.",h="Questa fiala contiene un potente campione di un intruglio preparato dal fattucchiere Zanzil, recuperato...",kw={"mistura alterata","colletorto","veleni","ladro","serge hinott","palude fangosa","mulino di tarren","zanzil"},ang={["class:Rogue"]="Consegnare questo vile campione è un rito di passaggio per i ladri dell'Orda, che conduce direttamente alle lezioni avanzate di Serge Hinott sulla preparazione, la gestione e l'applicazione di veleni letali.",["faction:Horde"]="Il trasporto di questo pericoloso intruglio richiede un viaggio intercontinentale, facendo affidamento sulle torri degli zeppelin e sulle strade consolidate che collegano Kalimdor ai territori dei Reietti a Lordaeron."},sec={{t="Un pegno tossico",b="Dopo essersi infiltrato nella torre della S.P.R. & Co. vicino alla Palude Fangosa e aver depredato la scorta di mistura di Zanzil dalla cassetta di sicurezza di Gallywix, un agente finisce per essere colpito dall'infame tocco di Zanzil. Shenthul ordina all'agente colpito di attraversare il Grande Mare con un campione dell'intruglio in mano. Trovare una cura significa rintracciare Serge Hinott, uno speziale di stanza a Mulino di Tarren nelle Alture di Colletorto, che possiede le rare competenze necessarie per isolare la tossina e decifrarne i componenti."},{t="Segreti della creazione di veleni",b="Il campione serve a qualcosa di più di una semplice urgenza medica; è un reperto inestimabile per i ladri dell'Orda desiderosi di padroneggiare le arti più oscure del loro mestiere. Serge Hinott analizza la mistura alterata non solo per curare il corriere afflitto, ma per dimostrare la precisa arte chimica necessaria per preparare e maneggiare potenti avvelenamenti sul campo."}},faq={{q="Cos'è questa mistura?",a="È un campione di un intruglio alchemico legato al fattucchiere Zanzil, recuperato durante una missione alla torre della S.P.R. & Co. vicino alla Palude Fangosa nei The Barrens. Contiene una potente tossina che infligge effetti debilitanti e persistenti a chiunque entri in contatto diretto con essa.",al={"cos'è la mistura di zanzil","campione di mistura alterata di zanzil","campione di veleno di zanzil"}},{q="Perché devo portarla a Serge Hinott?",a="Serge Hinott è un abile speziale di stanza a Mulino di Tarren nelle Alture di Colletorto. Possiede le conoscenze specialistiche necessarie per neutralizzare gli effetti dell'intruglio e produrre una cura affidabile prima che la tossina causi danni permanenti.",al={"chi è serge hinott","perché portare a mulino di tarren","cura per la mistura di zanzil"}},{q="Chi è Zanzil?",a="Zanzil il Reietto è un famigerato fattucchiere troll della giungla noto per la creazione di elisir, veleni e mutageni che inducono alla follia. Le sue ricette tossiche si sono diffuse ben oltre le sue giungle natie, facendosi strada in operazioni mercenarie e industriali come la S.P.R. & Co.",al={"chi è zanzil","zanzil il reietto","storia di zanzil"}},{q="Come si raggiunge Mulino di Tarren per consegnarla?",a="I viaggiatori devono salire sullo zeppelin da Durotar a Sepulcro nelle Radure di Tirisfal. Da lì, si segue la strada principale verso sud attraverso la Selva Pinargento, seguendo le indicazioni verso est nelle Alture di Colletorto fino a raggiungere la cittadina di Mulino di Tarren.",al={"come raggiungere mulino di tarren","viaggiare verso colletorto","indicazioni per mulino di tarren"}}},fp="34,334,13.478.0,22.344.1,21.277.0,41.236.0,14.274.0,43.245.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Campione di Carapace di Tartarabbia",s="Un Campione di Carapace di Tartarabbia è un resistente carapace di testuggine raccolto dalle oasi d'acqua dolce di The Barrens. Notevole per la sua persistente vitalità, viene inviato attraverso il Grande Mare per aiutare le ricerche druidiche volte a ringiovanire i boschi devastati della Selva Pinargento.",h="Un Campione di Carapace di Tartarabbia è un resistente carapace di testuggine raccolto dalle oasi d'acqua...",kw={"the barrens","mura runetotem","oasi","campione di carapace di tartarabbia","mausolea","selva pinargento","tartarabbia","guscio di tartaruga"},ang={["class:Druid"]="Per i druidi del Circolo Cenariano, studiare la resiliente vitalità delle tartarabbie delle oasi fornisce insegnamenti cruciali su come la vita perseveri e su come una terra devastata possa un giorno essere guarita.",["race:Tauren"]="La consegna di questo carapace evidenzia la devozione dei tauren verso la Madre Terra, dimostrando la loro volontà di offrire aiuto e guarigione naturale persino ai loro alleati non morti al di là del mare."},sec={{t="Una scintilla di vita dall'oasi",b="Le tartarughe azzannatrici che dimorano nelle rigogliose oasi di The Barrens, toccate da anomalie, possiedono carapaci di sorprendente vigore. A differenza della comune materia dei gusci, un fresco Campione di Carapace di Tartarabbia conserva una tenue radiosità interiore e una pulsazione energica molto tempo dopo essere stato separato dalla creatura. Per i druidi tauren che osservano i rapidi mutamenti ecologici della regione, questi carapaci incarnano la scintilla resiliente e adattiva delle terre selvagge di Kalimdor, suggerendo che la natura possa prosperare persino tra aridi e aspri territori."},{t="Curare terre lontane",b="Riconoscendo la vitalità latente all'interno del carapace, i naturalisti tauren inviano corrieri attraverso il mare per consegnare campioni a Mura Runetotem a Mausolea. Stazionata tra le distese devastate della Selva Pinargento, Mura cerca di aiutare i Reietti trovando modi per guarire le afflitte terre del nord. Esaminando l'imperitura forza vitale preservata all'interno della corazza della tartarabbia, spera di isolare segreti in grado di rivitalizzare una foresta morente e incoraggiare una nuova crescita nel terreno esausto."}},faq={{q="Cosa rende speciale questo carapace di tartarabbia?",a="A differenza delle fragili ossa comuni, questo carapace conserva un bagliore interiore e sembra pulsare ancora di vita dopo essere stato raccolto. Proviene dalle tartarabbie che prosperano intorno alle insolite oasi d'acqua dolce di The Barrens, dove le energie naturali scorrono eccezionalmente elevate.",al={"perché il carapace è speciale","cos'è il carapace di tartarabbia","carapace luminoso"}},{q="Chi ha bisogno di questo campione?",a="Il carapace è destinato a Mura Runetotem, una druida tauren che risiede a Mausolea nella Selva Pinargento. Ha viaggiato verso i Regni Orientali per assistere i Reietti e studiare come ridare vita a terre morenti.",al={"chi vuole il carapace","dove porto il carapace","missione mura runetotem"}},{q="Perché inviare un carapace di The Barrens fino alla Selva Pinargento?",a="La Selva Pinargento è un bosco morente e corrotto, mentre le oasi di The Barrens sono improvvisamente esplose con una vita ostinata e persistente. I druidi credono che studiare la robusta vitalità racchiusa nelle bestie di Kalimdor possa offrire spunti per guarire il suolo devastato di Lordaeron.",al={"perché inviare a selva pinargento","collegamento del carapace con selva pinargento"}},{q="Il carapace è pericoloso o contaminato?",a="No. Il carapace irradia pura vitalità piuttosto che magia oscura. Sebbene l'improvvisa proliferazione nelle oasi di The Barrens sia misteriosa, i druidi percepiscono questa persistente energia come una resilienza naturale degna di essere coltivata.",al={"il carapace è malvagio","il carapace è corrotto"}}},fx={["6161673b"]={q="Cos'è il Campione di Carapace di Tartarabbia?",a="È un esemplare prelevato dal carapace di una tartaruga tartarabbia trovata nelle aride distese delle Barrens. Infuso di una strana vitalità pulsante, questo guscio viene conservato con cura in modo che la sua insolita energia vitale possa essere esaminata lontano dalle pianure di Kalimdor.",al={"cos'è il campione di carapace di tartarabbia","oggetto carapace di tartarabbia","identità campione di carapace di tartarabbia"}},c3ef5b23={q="Da dove proviene il Campione di Carapace di Tartarabbia?",a="Proviene dalle tartarabbia selvatiche che dimorano attorno alle oasi e ai corsi d'acqua delle Barrens. Il guscio naturale è stato raccolto dagli avventurieri dell'Orda a Kalimdor e scelto dai druidi tauren come campione rappresentativo della fiorente forza vitale presente all'interno della terra desolata baciata dal sole.",al={"origine carapace di tartarabbia","da dove proviene il carapace di tartarabbia","chi ha fatto il campione di carapace di tartarabbia"}}},fp="20,263,21.492.0,21.481.0,38.251.0,22.213.0,51.261.0,34.210.0"}
P.entries["item:samuel-s-remains"] = {n="Resti di Samuel",s="I Resti di Samuel sono le spoglie mortali recuperate di Samuel Fipps, un ex abitante delle Radure di Tirisfal caduto vittima del Flagello. Raccolti da avventurieri vicino ad Albamorta, vengono sepolti accanto a sua moglie Marla per esaudire il suo ultimo desiderio.",h="I Resti di Samuel sono le spoglie mortali recuperate di Samuel Fipps, un ex abitante delle Radure di Tirisfal...",kw={"albamorta","marla fipps","tomba di marla","marla's last wish","novizia elreth","samuel fipps","resti di samuel"},ang={["race:Undead"]="Seppellire i resti di Samuel è una delle prime lezioni sull'identità dei Reietti: rispettare i tragici defunti segna il cruciale confine morale tra i non morti liberi e i ciechi schiavi del Flagello."},sec={{t="Una tragica riunione",b="Prima che la piaga della non morte si abbattesse su Lordaeron, Samuel Fipps viveva serenamente con sua moglie, Marla. Quando il contagio colpì, Samuel soccombette e fu vincolato a servire ciecamente il Flagello. Marla scampò alla non morte solo per essere uccisa proprio dal marito che amava. Nonostante questa fine brutale, il suo ultimo desiderio non fu la vendetta, bensì l'eternità insieme: implorò di essere sepolta accanto a Samuel una volta che la sua forma maledetta avesse trovato riposo. La Novizia Elreth ad Albamorta recluta i Reietti appena risvegliati per rintracciare la forma errante di Samuel a nord-est dell'insediamento, recuperare le sue ossa e seppellirle nella prima fila del cimitero locale."}},faq={{q="Chi era Samuel Fipps?",a="Samuel Fipps era un umano che viveva nelle Radure di Tirisfal prima della Terza Guerra. Quando la piaga del Flagello invase la regione, perì e risorse come schiavo non morto del Re dei Lich. Spinto da una brama cieca, finì per uccidere la sua stessa moglie, Marla.",al={"samuel fipps","chi è samuel","storia di samuel"}},{q="Dove si trovano i resti di Samuel?",a="Vengono recuperati da Samuel Fipps in persona, che vaga tra l'accampamento in rovina lungo la strada a nord-est di Albamorta. Porre fine alla sua cieca esistenza permette di recuperare le sue spoglie mortali.",al={"trovare i resti di samuel","dove si trova samuel fipps","posizione di samuel"}},{q="Perché i Reietti lo seppelliscono accanto a sua moglie?",a="L'ultimo desiderio di Marla era riposare accanto al suo amato marito, nonostante fosse stato proprio lui a ucciderla. La Novizia Elreth onora questa richiesta per dimostrare che i Reietti appena liberati possiedono ancora compassione, rispetto per i defunti e un'umanità che li distingue dal Flagello.",al={"perché seppellire samuel","tomba di marla","ultimo desiderio di marla"}}},fx={["29aac9a9"]={q="Da dove vengono i Resti di Samuel?",a="Questi sono i resti fisici mortali di Samuel Fipps, un ex residente delle Radure di Tirisfal che cadde vittima della piaga della non morte e divenne una pedina senza mente del Flagello. Dopo aver vagato per la natura selvaggia a nord-est di Albamorta, il suo corpo non morto viene abbattuto in modo che i suoi resti possano finalmente essere raccolti e sepolti.",al={"origine resti di samuel","da dove vengono i resti di samuel","chi ha fatto i resti di samuel"}}},fp="16,242,16.635.0,21.233.0,33.202.0,45.279.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Zaffiro di Aku'mai",s="Gli Zaffiri di Aku'mai sono agglomerati minerali luminescenti, infusi d'acqua, che crescono lungo le gallerie sotterranee degli Abissi di Fondocupo. I naga invasori hanno iniziato a estrarre queste gemme, spingendo il Circolo della Terra a cercarle prima che il loro potente potere arcano possa essere sfruttato.",h="Gli Zaffiri di Aku'mai sono agglomerati minerali luminescenti, infusi d'acqua, che crescono lungo le gallerie...",kw={"aku'mai","abissi di fondocupo","cristalli","je'neu sancrea","naga","zaffiro","spiriti dell'acqua","spiaggia di zoram"},ang={["class:Mage"]="L'innata saturazione d'acqua rende questi zaffiri grezzi molto apprezzati come condotti per potenti componenti arcani.",["class:Shaman"]="Gli sciamani del Circolo della Terra come Je'neu Sancrea percepiscono chiaramente gli spiriti dell'acqua vincolati all'interno di queste gemme, considerando la raccolta da parte dei naga come una minaccia elementale."},sec={{t="Gemme degli Abissi",b="Scoperti all'interno degli accessi cavernosi e allagati degli Abissi di Fondocupo lungo la Spiaggia di Zoram a Valtetra, gli Zaffiri di Aku'mai sono formazioni cristalline ricche di energia elementale. Gli spiriti dell'acqua vi sono strettamente legati, rendendoli eccezionali catalizzatori per opere magiche. Quando gli esploratori hanno riferito che i naga sotterranei avevano iniziato a estrarre attivamente questi agglomerati dalle pareti della caverna, lo Sciamano Je'neu Sancrea ha cercato l'aiuto di avventurieri per confiscarli. Lasciate nelle grinfie del popolo serpente, le pietre potrebbero facilmente alimentare devastanti riti arcani."}},faq={{q="Cos'è uno Zaffiro di Aku'mai?",a="Sono vibranti cristalli di zaffiro che rivestono le pareti degli Abissi di Fondocupo. Strettamente legati agli spiriti elementali dell'acqua, possiedono una profonda risonanza arcana ed elementale.",al={"cos'è questo cristallo","storia dello zaffiro di aku'mai","cosa sono queste gemme"}},{q="Perché i naga stanno raccogliendo questi zaffiri?",a="Le loro esatte intenzioni restano incerte, ma Je'neu Sancrea sospetta che i naga intendessero sfruttare le ricche energie arcane e acquatiche dei cristalli per compiere pericolose stregonerie all'interno del tempio sommerso.",al={"perché i naga vogliono gli zaffiri","raccolta dei cristalli da parte dei naga"}},{q="Chi sta cercando questi zaffiri?",a="Je'neu Sancrea, uno sciamano del Circolo della Terra di stanza all'Avamposto di Zoram'gar lungo la Spiaggia di Zoram a Valtetra, incarica i viaggiatori di raccoglierli per sottrarli alle mani dei naga.",al={"chi vuole gli zaffiri di aku'mai","chi consegna essenza di aku'mai"}},{q="Questi cristalli sono direttamente collegati alla bestia Aku'mai?",a="Sebbene prendano il nome da Aku'mai, la mostruosa idra che abita le profondità, i cristalli crescono naturalmente nelle pareti della caverna. Il loro nome riflette la vicinanza all'oscura presenza che si annida tra le rovine.",al={"legame con aku'mai","proviene da aku'mai"}}},fx={["12f03799"]={q="Da dove vengono gli Zaffiri di Aku'mai e chi li ha creati?",a="Questi grandi grappoli di zaffiri crescono naturalmente lungo le pareti delle caverne all'interno dei tunnel iniziali degli Abissi di Fondocupo. Non sono creati da mani mortali; piuttosto, sono formazioni minerali naturali intrise delle energie ambientali della caverna. Gli spiriti dell'acqua si aggrappano naturalmente ai cristalli, conferendo loro un'intrinseca potenza elementale.",al={"origine dello zaffiro di aku'mai","chi ha fatto lo zaffiro di akumai","da dove vengono gli zaffiri di aku'mai"}}},fp="19,275,16.557.0,30.177.0,44.193.0,35.174.0,54.202.0"}
P.entries["item:sapphire-of-sky"] = {n="Zaffiro del Cielo",s="Lo Zaffiro del Cielo è una delle quattro sacre Relics of Wakening custodite dai nelfi della notte all'interno dell'Eremo di Ban'ethil. È un catalizzatore essenziale utilizzato per richiamare in sicurezza i Druidi dell'Unghia dormienti dal Sogno di Smeraldo.",h="Lo Zaffiro del Cielo è una delle quattro sacre Relics of Wakening custodite dai nelfi della notte all'interno...",kw={"athridas orsomanto","eremo di ban'ethil","chest of the sky","druido dell'unghia","sogno di smeraldo","relics of wakening","zaffiro del cielo"},ang={["class:Druid"]="Lo zaffiro esemplifica gli attenti rituali richiesti quando si proietta il proprio spirito nel Sogno di Smeraldo, a dimostrazione di come una comunione possa facilmente diventare fatale senza punti di ancoraggio sacri.",["race:NightElf"]="Preservare i sacri manufatti nell'Eremo di Ban'ethil è fondamentale per salvaguardare il fragile ordine di Teldrassil tra la crescente corruzione."},sec={{t="Il Rituale del Risveglio",b="Nelle profondità delle radici di Teldrassil, i Druidi dell'Unghia comunicano con la natura mentre riposano in letargo all'interno dell'Eremo di Ban'ethil. Risvegliarsi da stati di trance così profondi per tornare nel mondo della veglia è un processo fragile e pericoloso. Per salvaguardare la transizione, i druidi si affidano a quattro manufatti consacrati noti come Relics of Wakening: la Piuma Nera, il Talismano Artiglio del Corvo, la Runa della Nidificazione e lo Zaffiro del Cielo. Senza questa gemma risonante, l'armonia necessaria per richiamare gli spiriti dormienti dal Sogno di Smeraldo resta incompleta, lasciandoli vulnerabili a un'eterna prigionia."},{t="La Minaccia a Ban'ethil",b="Quando i furbolg Gnarlpine corrotti invasero l'eremo, i sacri manufatti vennero lasciati indietro nei loro elaborati ricettacoli. Lo Zaffiro del Cielo si trova custodito al sicuro all'interno del Chest of the Sky, tra i tortuosi corridoi sotterranei. Con i druidi ancora addormentati mentre i furbolg imperversano intorno a loro, recuperare questo gioiello insieme alle altre reliquie è una questione urgente per Athridas Orsomanto a Dolanaar prima che i dormienti siano perduti per sempre."}},faq={{q="Cos'è lo Zaffiro del Cielo?",a="È una pietra preziosa sacra e una delle quattro Relics of Wakening conservate all'interno dell'Eremo di Ban'ethil. Agisce in sinergia con tre talismani aviari per guidare in sicurezza i Druidi dell'Unghia fuori dal Sogno di Smeraldo.",al={"storia dello zaffiro del cielo","cos'è questa gemma","zaffiro del cielo"}},{q="Dove è custodito lo Zaffiro del Cielo?",a="È custodito all'interno del Chest of the Sky, situato nel labirinto sotterraneo dell'Eremo di Ban'ethil, nella parte centrale di Teldrassil.",al={"dove trovare lo zaffiro del cielo","posizione del chest of the sky","posizione dello zaffiro"}},{q="Perché lo zaffiro è necessario proprio ora?",a="I furbolg Gnarlpine corrotti hanno invaso l'Eremo di Ban'ethil, mettendo in grave pericolo i druidi dormienti. I druidi in profonda trance non possono svegliarsi da soli; Athridas Orsomanto necessita dello zaffiro e delle altre reliquie per compiere il delicato rituale del risveglio prima che i dormienti siano perduti per sempre.",al={"perché recuperare lo zaffiro","scopo delle relics of wakening"}},{q="Chi usa questo manufatto?",a="I Druidi dell'Unghia e i custodi dei rituali come Athridas Orsomanto lo usano durante i riti comunitari per risvegliare i fratelli dormienti dalla loro profonda comunione con la natura.",al={"chi usa lo zaffiro del cielo","gemma rituale dei druidi"}}},fp="15,218,19.602.0,23.453.0,28.211.0,34.132.0,37.303.0,23.172.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Supplica di Sara Balloo",s="La Supplica di Sara Balloo è una missiva scritta a mano da una vedova in lutto a Forgiardente. Incapace di affrontare direttamente il monarca nel suo dolore, affida questa lettera a un fidato campione dell'Alleanza affinché la porti al cospetto di Re Magni Barbabronzea.",h="La Supplica di Sara Balloo è una missiva scritta a mano da una vedova in lutto a Forgiardente.",kw={"a king's tribute","high seat","forgiardente","magni barbabronzea","sara balloo","supplica di sara balloo"},ang={["faction:Alliance"]="Sara affida la sua petizione solo a campioni riconosciuti per il loro servizio all'Alleanza, confidando nella loro reputazione affinché il suo appello ottenga un'udienza dinanzi ai reali.",["race:Dwarf"]="Per i nani, portare il messaggio di Sara all'High Seat è un atto di profonda vicinanza, che garantisce che, anche nel dolore, nessun furiere o cittadino resti inascoltato da Re Magni."},sec={{t="L'appello di una vedova",b="Scritta all'ombra di una profonda tragedia personale, la Supplica di Sara Balloo rappresenta un umile appello rivolto direttamente al trono di Forgiardente. Invece di recarsi personalmente all'High Seat nelle sue condizioni di profondo dolore, Sara cerca un avventuriero che abbia dimostrato lealtà e valore all'Alleanza affinché consegni le sue parole. Il messaggio chiede l'attenzione di Re Magni Barbabronzea, attirando lo sguardo del sovrano sul lutto privato e sui sacrifici compiuti dalle ordinarie famiglie naniche al servizio del regno."}},faq={{q="Cos'è la Supplica di Sara Balloo?",a="È una lettera scritta a mano da Sara Balloo, indirizzata a Re Magni Barbabronzea, che chiede la sua attenzione reale mentre lei vive il proprio lutto in privato.",al={"supplica di sara balloo","nota della vedova forgiardente","nota di sara"}},{q="Perché Sara Balloo ha bisogno che qualcun altro la consegni?",a="Sara si sente sopraffatta dal dolore e ritiene che presentarsi davanti al Re di Forgiardente in un tale stato emotivo possa ostacolare la sua supplica, spingendola invece ad affidarsi a un campione dell'Alleanza.",al={"perché consegnare la nota","perché sara non può andare","dolore di sara"}},{q="Chi riceve questo messaggio?",a="La lettera è indirizzata e consegnata direttamente a Re Magni Barbabronzea nell'High Seat di Forgiardente.",al={"chi riceve la supplica","a chi consegnare","lettera per magni"}},{q="A cosa porta la consegna della lettera?",a="Presentare la lettera a Re Magni attira la sua attenzione sul lutto di Sara Balloo e avvia una risposta reale in onore della sua famiglia caduta.",al={"serie di missioni della supplica","collegamento a kings tribute","cosa succede dopo"}}},fx={["2b83ea9f"]={q="Da dove proviene la Supplica di Sara Balloo e chi l'ha scritta?",a="Questa nota scritta è stata redatta direttamente da Sara Balloo, una donna nana in lutto a Forgiardente. Devastata dalla perdita, ha preparato personalmente il messaggio per presentare petizione al trono di Forgiardente, affidandolo a un campione dell'Alleanza invece di tentare da sola l'emotivo viaggio verso l'High Seat.",al={"chi ha scritto la supplica di sara balloo","da dove viene la supplica di sara balloo","chi ha fatto la supplica di sara balloo"}},["4ac5e6cf"]={q="Perché qualcuno vuole la Supplica di Sara Balloo?",a="Re Magni Barbabronzea necessita della lettera per ascoltare la petizione di uno dei suoi sudditi in lutto. Sara Balloo non riesce a presentarsi davanti al monarca nel suo stato di dolore, quindi conta su di te per presentare l'appello direttamente nelle mani del sovrano di Forgiardente.",al={"perché serve la supplica di sara balloo","chi vuole la supplica di sara balloo","perché consegnare la supplica di sara balloo"}}},fp="18,238,16.491.0,27.146.0,53.187.0,26.103.0,40.143.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Testa di Sarilus Malonato",s="La Testa di Sarilus Malonato è un macabro trofeo ottenuto da uno stregone non morto che ha contaminato le acque di Kalimdor settentrionale. Riportata oltre il confine da The Barrens a Valtetra, serve come prova innegabile che l'intrigante mago ha trovato la fine per mano delle Sentinelle.",h="La Testa di Sarilus Malonato è un macabro trofeo ottenuto da uno stregone non morto che ha contaminato le...",kw={"the barrens","picco di brumafunesta","testa","mage summoner","sarilus foulborne","rifugio vento argentato","velene tagliastelle","water elementals"},ang={["faction:Alliance"]="Compiere questo attacco richiede di infiltrarsi in profondità nelle ostili terre dell'Orda all'interno di The Barrens per eliminare un pericoloso incantatore rinnegato.",["race:NightElf"]="Prendere la testa di Foulborne appaga la vendetta delle Sentinelle contro uno sconsiderato profanatore arcano che ha dissacrato gli spiriti della terra."},sec={{t="Un Profanatore Messo a Tacere",b="Arroccato sulla cima del Picco di Brumafunesta a The Barrens settentrionale, l'incantatore dei Reietti Sarilus Foulborne ha scatenato l'ira degli elfi della notte corrompendo e assoggettando sciami di Water Elementals. Dalla sua postazione al Rifugio Vento Argentato, la Sentinella Velene Tagliastelle ha riconosciuto la sua nefasta opera e ha inviato campioni oltre la frontiera in territorio dell'Orda per porre fine ai suoi sconsiderati esperimenti. Mozzare la testa del mago era l'unica prova che Tagliastelle avrebbe accettato per verificare che il suo beffardo ghigno fosse cancellato per sempre, garantendo un minimo di pace alle tormentate acque di Valtetra."}},faq={{q="Chi era Sarilus Foulborne?",a="Sarilus Foulborne era un mago non morto che si stabilì in cima al Picco di Brumafunesta a The Barrens settentrionale. Si attirò l'ira degli elfi della notte piegando ed evocando enormi quantità di Water Elementals, spingendo la Sentinella Velene Tagliastelle a ordinarne la morte.",al={"chi è sarilus","storia di sarilus foulborne","chi è foulborne"}},{q="Perché la Sentinella Velene Tagliastelle vuole la sua testa?",a="Velene Tagliastelle voleva l'assoluta certezza che l'arrogante stregone fosse morto. Sarilus l'aveva apertamente derisa mentre profanava gli spiriti dell'acqua della regione, e riportare la sua testa mozzata era l'unica prova che avrebbe accettato per considerare eliminata la minaccia.",al={"perché prendere la sua testa","testa velene tagliastelle","prova della morte"}},{q="Dove si trova Sarilus Foulborne?",a="Ha la sua tana proprio in cima al Picco di Brumafunesta, una montagna rocciosa situata nelle propaggini settentrionali di The Barrens, appena a sud del confine con Valtetra.",al={"dove trovare foulborne","posizione di sarilus","mago di picco di brumafunesta"}},{q="Perché Foulborne stava profanando i Water Elementals?",a="Foulborne ha utilizzato evocazioni arcane per piegare numerosi Water Elementals al proprio volere, corrompendoli nel processo. La sua sconsiderata manipolazione ha sconvolto l'equilibrio naturale delle acque che scorrono vicino a Valtetra, provocando una rapida ritorsione da parte delle Sentinelle.",al={"perché corrompere gli elementali","corruzione degli elementali dell'acqua","motivazioni di foulborne"}}},fx={a996e76e={q="Da dove proviene la Testa di Sarilus Malonato?",a="Questa testa mozzata è presa direttamente da Sarilus Malonato, un mago Reietti che si è stabilito in cima al Picco di Brumafunesta nelle Barrens settentrionali. Operando vicino ai confini di Valtetra, Malonato passava le sue giornate a profanare i Water Elementals e a provocare gli elfi della notte finché la Sentinella Velene Tagliastelle non ha inviato un avventuriero nel territorio nemico per porre fine alla sua derisione.",al={"origine della testa di sarilus","origine della testa di malonato","da dove viene la testa di malonato"}}},fp="24,286,18.570.1,26.261.1,50.261.0,35.146.1,44.251.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Chela Mutilata di Sarkoth",s="La Chela Mutilata di Sarkoth è la chela recisa di Sarkoth, un mostruoso scorpide che si aggira sui dirupi meridionali della Valle delle Sfide. Pesantemente segnato dal troll Hana'zua, gravemente ferito, il trofeo funge sia da prova della morte della bestia, sia da consolazione finale per l'orgoglio del cacciatore ferito.",h="La Chela Mutilata di Sarkoth è la chela recisa di Sarkoth, un mostruoso scorpide che si aggira sui dirupi...",kw={"chela","durotar","hana'zua","chela mutilata","sarkoth","scorpide","valle delle sfide"},ang={["faction:Horde"]="Per gli iniziati nella Valle delle Sfide, reclamare questo trofeo rappresenta una delle prime prove di coraggio e forza marziale nelle aspre terre selvagge di Durotar.",["race:Troll"]="Portare la chela mutilata ad Hana'zua dona a un morente compagno Darkspear un briciolo di dignità, facendogli sapere che il suo colpo finale ha segnato la bestia prima della fine."},sec={{t="Un trofeo di vendetta",b="Mentre cacciava nella Valle delle Sfide, un giovane troll Darkspear di nome Hana'zua affrontò un enorme scorpide noto come Sarkoth. Prima che il pungiglione velenoso di Sarkoth gli trafiggesse il petto lasciandolo sanguinante sotto un albero vicino, Hana'zua assestò un colpo devastante contro la massiccia chela della creatura. Recidere questo arto martoriato offre una prova innegabile dell'uccisione del mostruoso scorpide. Per Hana'zua, stringere la chela mutilata conferma che il suo colpo disperato ha lasciato un segno duraturo, infondendogli un fugace barlume di onore guerriero mentre il veleno gli scorre nelle vene."}},faq={{q="Perché la chela è mutilata?",a="La chela è stata frantumata durante un disperato duello tra Sarkoth e il cacciatore troll Hana'zua. Sebbene Sarkoth abbia sferrato una puntura mortale al petto di Hana'zua, il troll ha assestato un colpo feroce contro la chela della bestia prima che questa si serrasse attorno alla sua gamba.",al={"perché la chela è rotta","chi ha frantumato la chela di sarkoth","storia della chela mutilata"}},{q="Chi vuole la Chela Mutilata di Sarkoth?",a="Hana'zua chiede la chela. Giace gravemente ferito sotto un albero nella Valle delle Sfide, temendo di morire lì, e desidera che lo scorpide venga ucciso affinché il suo onore sia preservato. Vedere l'impresa compiuta gli dà la forza di resistere finché Gornek non invierà soccorsi.",al={"a chi serve la chela di sarkoth","a chi si consegna","chela di hanazua"}},{q="Da dove proviene questa chela?",a="Viene presa da Sarkoth, un grande e aggressivo scorpide che si aggira sull'altopiano elevato lungo le scogliere meridionali della Valle delle Sfide a Durotar.",al={"posizione di sarkoth","dove si trova sarkoth","dove trovare la chela mutilata"}}},fx={["5a9dc5fc"]={q="Cos'è la Chela Mutilata di Sarkoth?",a="È la chela mozzata di Sarkoth, uno scorpide insolitamente grande e feroce che si aggira sull'altopiano meridionale sopra la Valle delle Sfide. La chela presenta gravi danni, con schegge inflitte dal troll dei Durepi Hana'zua, gravemente ferito, durante il loro disperato scontro, servendo come prova innegabile che la bestia mostruosa è stata finalmente uccisa.",al={"cos'è la chela mutilata di sarkoth","identità della chela di sarkoth","chela mutilata"}}},fp="22,290,21.559.0,24.245.0,33.234.0,30.148.0"}
P.entries["item:sarltooth-s-talon"] = {n="Artigli di Dentesauro",s="Artigli di Dentesauro è un artiglio mozzato ottenuto dal raptor alfa in agguato sopra gli Scavi di Whelgar nelle Wetlands. Serve come prova tangibile per il nano Ormer Trecciaferro che la feroce bestia responsabile dell'invasione dello scavo archeologico è stata uccisa.",h="Artigli di Dentesauro è un artiglio mozzato ottenuto dal raptor alfa in agguato sopra gli Scavi di Whelgar...",kw={"scavo","ormer trecciaferro","raptor","dentesauro","artiglio","wetlands","whelgar"},ang={["class:Hunter"]="Rintracciare un astuto capobranco come Dentesauro e reclamarne un artiglio come trofeo è una classica prova di precisione balistica e maestria con le bestie.",["race:Dwarf"]="Recuperare questo artiglio compie la tanto attesa vendetta per i nani archeologi caduti, che persero la vita al servizio della Lega degli Esploratori per volere di Re Magni Barbabronzea."},sec={{t="Un trofeo di vendetta",b="Quando i raptor invasero gli Scavi di Whelgar e massacrarono la spedizione nanica, Ormer Trecciaferro osservò dalla cresta soprastante, incapace di impedire il massacro. Individuò un raptor massiccio e minaccioso, Dentesauro, come il probabile capobranco dietro l'assalto. In cerca di vendetta per i suoi congiunti caduti, Ormer ha preteso la morte della bestia e ha richiesto uno dei suoi feroci artigli come prova dell'impresa. Mozzare questo artiglio segna la fine del regno del terrore di Dentesauro sulle antiche rovine naniche."}},faq={{q="Da dove provengono gli Artigli di Dentesauro?",a="L'artiglio viene reciso da Dentesauro, un grande raptor alfa che si aggira sulle creste occidentali che sovrastano gli Scavi di Whelgar nelle Wetlands.",al={"chi rilascia gli artigli di dentesauro","posizione di dentesauro","come ottenere l'artiglio"}},{q="Chi vuole gli Artigli di Dentesauro?",a="Ormer Trecciaferro, un nano appostato sull'Osservatorio sopra gli Scavi di Whelgar, chiede l'artiglio per confermare che la bestia che ha massacrato la sua squadra sia stata abbattuta.",al={"chi accetta l'artiglio","dove consegnare l'artiglio","missione di ormer trecciaferro"}},{q="Perché Ormer Trecciaferro ha bisogno di una prova della morte di Dentesauro?",a="Ormer crede che Dentesauro abbia guidato il branco di raptor che ha scacciato e ucciso gli scavatori nani. Considera l'artiglio un segno di giustizia e di conforto per i suoi colleghi caduti.",al={"perché uccidere dentesauro","cosa ha fatto dentesauro"}},{q="Cosa è successo ai nani al sito di scavo?",a="Lo scavo dei nani avrebbe dovuto portare alla luce antichi manufatti per la Lega degli Esploratori, ma alcuni raptor selvaggi hanno teso un'imboscata ai lavoratori, massacrandone la maggior parte e spingendo i superstiti verso la cresta vicina.",al={"storia degli scavi di whelgar","perché ci sono raptor allo scavo"}}},fx={["28fc0e8a"]={q="Cos'è l'Artiglio di Dentesauro?",a="È un artiglio mozzato preso da Dentesauro, il feroce raptor sospettato di guidare il branco selvaggio che ha invaso gli Scavi di Whelgar. Ormer Trecciaferro richiede l'artiglio come prova innegabile che la bestia è stata uccisa e che i nani scavatori caduti sono stati vendicati.",al={"cos'è l'artiglio di dentesauro","lore dell'artiglio di dentesauro"}}},fp="17,268,21.498.0,39.139.0,28.173.0,57.175.0,52.193.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Sacrificio di Sathrah",s="Il Sacrificio di Sathrah è costituito dalla Filatura Argentea prelevata da Lady Sathrah, un possente ragno che dimora a Teldrassil. Affidata agli avventurieri dalla Sacerdotessa A'moora, questa offerta viene presentata alla fontana del Temple of the Moon per purificare la corruzione della creatura e concedere il riposo al suo spirito.",h="Il Sacrificio di Sathrah è costituito dalla Filatura Argentea prelevata da Lady Sathrah, un possente ragno...",kw={"darnassus","elune","lady sathrah","sacerdotessa a'moora","sacrificio di sathrah","filatura argentea","ragno","teldrassil","temple of the moon"},ang={["class:Priest"]="I sacerdoti al servizio di The Sisterhood of Elune osservano questo rituale come un solenne atto di divina misericordia, utilizzando acque sacre per purificare la contaminazione piuttosto che limitarsi a gettare via una bestia uccisa.",["race:NightElf"]="Per gli elfi della notte, abbattere la fauna corrotta è un triste dovere; restituire lo spirito di Lady Sathrah a Elune's Grace assicura che la vita su Teldrassil possa infine rinascere libera dalla follia."},sec={{t="Purificazione nelle Acque Sacre",b="Lady Sathrah era un tempo una venerabile creatura di Teldrassil caduta preda della follia strisciante e della corruzione che affliggeva i rami del Grande Albero. Incaricati da The Sisterhood of Elune, gli avventurieri recuperano la sua Filatura Argentea non come semplice trofeo, ma come offerta consacrata. Immergendo questi resti nella fontana sacra del Temple of the Moon, la nefasta contaminazione che avvelenava la mente di Sathrah viene lavata via. Il rito libera la sua anima tormentata, permettendo al suo spirito di manifestarsi serenamente all'interno del santuario e concedendole la promessa della rinascita sotto Elune's Grace."}},faq={{q="Cos'è il Sacrificio di Sathrah?",a="Il Sacrificio di Sathrah è l'offerta rituale ricavata dalla Filatura Argentea di Lady Sathrah, un gigantesco ragno corrotto ucciso a Teldrassil. The Sisterhood of Elune la utilizza in un rito purificatore per mondare l'anima della creatura.",al={"cosa sono le filiere","oggetto sacrificio di sathrah","offerta di lady sathrah"}},{q="Perché la filatura dev'essere posta nella fontana?",a="La fontana centrale all'interno del Temple of the Moon di Darnassus contiene acque sacre consacrate a Elune. Immergere i resti di Sathrah nella vasca lava via la nefasta corruzione che l'ha resa folle, liberando il suo spirito dall'agonia.",al={"perché la fontana del tempio","perché sacrificare sathrah","cosa fa la fontana"}},{q="Cosa succede quando viene presentata l'offerta?",a="Una volta immersa nelle acque sacre, la corruzione viene epurata e la forma spettrale di Lady Sathrah appare, camminando serenamente attorno alla vasca a significare che la sua anima è in pace.",al={"cosa accade alla fontana","apparizione dello spirito di sathrah","evento della fontana"}},{q="Chi sovrintende a questo rituale?",a="La Sacerdotessa A'moora, una servitrice di The Sisterhood of Elune di stanza all'interno del Temple of the Moon, guida gli avventurieri affinché diano pace alla creatura e offrano i suoi resti alla dea.",al={"chi affida sacrificio di sathrah","missione sacerdotessa a'moora","chi purifica sathrah"}}},fx={c7289e92={q="Da dove proviene il Sacrificio di Sathrah?",a="La Sacerdotessa A'moora ha preparato questa offerta direttamente dalle filatura argentea prese da Lady Sathrah, un grande ragno abbattuto a Teldrassil dopo essere caduto nella follia e nella corruzione.",al={"origine del sacrificio di sathrah","da dove viene il sacrificio di sathrah","chi ha creato il sacrificio di sathrah"}},b18748b3={q="Perché la Sacerdotessa A'moora vuole il Sacrificio di Sathrah?",a="La Sacerdotessa A'moora richiede il sacrificio affinché possa essere adagiato nelle acque sacre del The Temple of the Moon. Attraverso questa offerta a Elune, la corruzione che ha distorto Lady Sathrah in vita può finalmente essere purificata, dando pace alla grande bestia e permettendo al suo spirito di rinascere rinnovato.",al={"perché è richiesto il sacrificio di sathrah","perché offrire il sacrificio di sathrah","a cosa serve il sacrificio di sathrah"}}},fp="19,300,31.580.0,28.222.0,50.227.0,44.178.1,25.182.0"}
P.entries["item:satyr-horns"] = {n="Corna di Satiro",s="Le Corna di Satiro sono macabri trofei ottenuti dai satiri corrotti che infestano gli antichi boschi di Valtetra. Ambite sia dagli abitanti della foresta in lutto in cerca di vendetta, sia da mercanti opportunisti che commerciano da Porto Paranco, fungono da prova innegabile della caduta di un altro servitore della Legione Infuocata.",h="Le Corna di Satiro sono macabri trofei ottenuti dai satiri corrotti che infestano gli antichi boschi di...",kw={"anilia","cantaselva","illiyana","jorxian","pixel","corna di satiro","satirnaar","avamposto di troncorotto","xavian"},ang={["faction:Horde"]="Operando dall'Avamposto di Troncorotto, i guerrieri dell'Orda eliminano i disgustosi satiri che minacciano le loro attività di legname, traendo profitto dagli acquirenti goblin diretti a Porto Paranco.",["race:NightElf"]="Per i kaldorei, prendere le corna dei satiri è un amaro dovere, purificando la loro foresta ancestrale da cugini che hanno barattato volontariamente la propria stirpe per la servitù demoniaca."},sec={{t="Trofei di vendetta e commercio",b="Le corna ricurve dei satiri di Valtetra sono chiari simboli della corruzione demoniaca radicatasi nella foresta sacra. Per la driade Illiyana presso il Santuario di Aessina, raccogliere queste corna mozzate è una questione di dolore e vendetta per la sua perduta sorella Anilia. Per i mercanti esterni come la goblin viaggiatrice Pixel, che riposa all'Avamposto di Troncorotto, le corna rappresentano invece una pura opportunità. La richiesta di corna di satiro è aumentata vertiginosamente nel porto neutrale di Porto Paranco, trasformando questi macabri resti di demoni uccisi in merci redditizie per chiunque sia abbastanza audace da cacciarne i portatori."},{t="L'epurazione delle enclavi corrotte",b="Le Corna di Satiro non possono essere acquistate dai normali fornitori; devono essere recise direttamente dalle bestie in agguato negli angoli bui dei boschi. I satiri mantengono roccaforti in tutta Valtetra, in particolare nei boschetti corrotti di Xavian, nelle cavità ombrose di Satirnaar e tra le rovine di Jorxian. Ripulire queste enclavi libera la terra dalla persistente contaminazione demoniaca, fornendo al tempo stesso sia ai guardiani in lutto che agli avidi mercanti la prova dell'epurazione."}},faq={{q="Perché Illiyana vuole le Corna di Satiro?",a="Illiyana cerca le Corna di Satiro per vendicare la sorella caduta, Anilia, assassinata dai satiri di Valtetra. Prendere le corna dai demoni uccisi le fornisce la prova che il loro numero si sta riducendo e porta pace allo spirito di sua sorella.",al={"corna illiyana","satiri anilia","missione cantaselva"}},{q="Perché Pixel raccoglie le Corna di Satiro?",a="Pixel è un'intraprendente viaggiatrice che sosta all'Avamposto di Troncorotto mentre è diretta a Porto Paranco. Ha scoperto che le corna di satiro fruttano un prezzo elevato nel porto dei goblin e assolda avventurieri per svolgere la pericolosa caccia al suo posto prima di partire.",al={"pixel troncorotto","perché pixel vuole le corna","corna di satiro porto paranco"}},{q="Quali sono i posti migliori per trovare satiri con queste corna?",a="I satiri dimorano in diverse aree corrotte in tutta Valtetra. Notevoli concentrazioni si trovano a Xavian e Satirnaar a nord-est, e a Jorxian nella parte centro-orientale della foresta.",al={"posizioni satiri valtetra","dove sono i satiri","accampamenti di satiri"}},{q="Cosa sono i satiri e perché hanno le corna?",a="I satiri sono antichi elfi della notte trasformati in esseri bestiali e demoniaci attraverso i patti demoniaci stipulati durante La Guerra degli Antichi. I loro zoccoli caprini, le code e le malvagie corna sono i segni fisici della corruzione demoniaca concessa dalla Legione Infuocata.",al={"cos'è un satiro","perché i satiri hanno le corna"}}},fx={["2131c67f"]={q="Cosa sono le Corna di Satiro?",a="Le Corna di Satiro sono le corna ricurve e diaboliche mozzate dalle teste dei satiri uccisi che si nascondono a Valtetra. Come corruzioni demoniache degli antichi elfi della notte, i satiri portano queste escrescenze minacciose come segni della loro afflizione maledetta. Nelle mani degli avventurieri, servono principalmente come macabra prova della morte di un satiro o come pregiate curiosità esotiche scambiate in tutta Kalimdor.",al={"cosa sono le corna di satiro","oggetto corna di satiro","identità delle corna di satiro"}},["8a39621c"]={q="Perché qualcuno vuole le Corna di Satiro?",a="Diverse fazioni cercano le corna di satiro per ragioni molto diverse. Per la driade Illiyana a Cantaselva, servono come innegabili trofei di vendetta contro i demoni corrotti che hanno ucciso sua sorella Anilia. Nel frattempo, mercanti opportunisti come Pixel le collezionano per venderle nel vivace porto di Porto Paranco, dove la domanda prospera per reagenti alchemici esotici, curiosità e parti di bestie.",al={"chi vuole le corna di satiro","perché raccogliere corna di satiro","perché sono richieste le corna di satiro"}}},fp="11,308,34.573.0,30.461.0,35.245.0,36.240.0,58.180.0,44.256.0"}
P.entries["item:savannah-lion-tusk"] = {n="Zanna di Leone delle Savane",s="Le Zanne di Leone delle Savane sono pesanti canini ricavati dai grandi felini predatori che si aggirano per le aride pianure di The Barrens. Sebbene siano comuni trofei di caccia per i viaggiatori, servono a uno scopo esotico come ingrediente di birrificazione per la leggendaria birra forte di Chen Stormstout.",h="Le Zanne di Leone delle Savane sono pesanti canini ricavati dai grandi felini predatori che si aggirano per...",kw={"the barrens","mastro birraio drohn","chen stormstout","dishu","humar","porto paranco","zanna di leone delle savane"},ang={["class:Hunter"]="Cacciare i feroci branchi attraverso le sterpaglie dorate di The Barrens offre una vera prova di tracciamento, fruttando zanne pericolose che si dimostrano sia letali in battaglia che preziose per i mastri birrai locali."},sec={{t="Un curioso ingrediente di birrificazione",b="I grandi felini di The Barrens—dai predatori e le cacciatrici ai maestosi branchi guidati da patriarchi e bestie come Humar the Pridelord—sono armati di zanne affilate e pesanti. Mentre la maggior parte di coloro che abbattono questi predatori ne prendono i denti come semplice prova di destrezza, il Mastro Birraio Drohn a Porto Paranco li cerca per un'arte molto più spiritosa. Drohn usa le zanne insieme a reni di falcatore e corni di lucertola del tuono per ricreare la celebre bevanda omonima di Chen Stormstout, conferendole una forza leggendaria che poche gole mortali possono sopportare facilmente."}},faq={{q="Perché il Mastro Birraio Drohn ha bisogno di Zanne di Leone delle Savane?",a="Il Mastro Birraio Drohn a Porto Paranco sta ricreando la ricetta della birra omonima di Chen Stormstout, che gli è stata tramandata dal suo mentore. Le zanne sono uno dei tre reagenti indigeni di The Barrens necessari per replicare il sapore e la forza distintivi della birra scura.",al={"perché zanne per la birra","zanne di leone drohn","ricetta mastro birraio drohn"}},{q="Quali bestie possiedono le Zanne di Leone delle Savane?",a="Possono essere estratte da qualsiasi membro dei branchi di leoni delle savane che si aggirano per The Barrens, inclusi Savannah Highmanes, Patriarchs, Matriarchs, Huntresses, Prowlers e bestie rare come Dishu e Humar the Pridelord.",al={"dove si trovano le zanne di leone","chi rilascia le zanne di leone","fonte zanna di leone delle savane"}},{q="I leoni hanno davvero le zanne?",a="Nelle aspre terre selvagge di Kalimdor, i canini sovradimensionati dei grandi felini delle savane crescono abbastanza sporgenti e spessi da indurre i cacciatori e i coloni locali a definirli colloquialmente zanne.",al={"perché i denti di leone sono chiamati zanne","zanne di leone vs zanne","anatomia della zanna di leone"}}},fx={["98d362c4"]={q="Cos'è una Zanna di Leone delle Savane?",a="Una Zanna di Leone delle Savane è un dente canino affilato raccolto dai felini predatori che si aggirano nelle pianure bruciate dal sole delle The Barrens. Sebbene chiamate zanne, sono le formidabili zanne dei leoni delle savane che dominano i terreni di caccia locali. Oltre a servire come macabri trofei di sopravvivenza nel deserto, queste parti resistenti trovano usi peculiari tra i locali che sanno come estrarne le qualità essenziali.",al={"cos'è la zanna di leone delle savane","lore zanna di leone delle savane","zanna di leone"}},ea601034={q="Da dove proviene una Zanna di Leone delle Savane?",a="Queste zanne vengono prese direttamente dai feroci felini del branco che cacciano le savane centrali di Kalimdor. Ogni razza di leone che si aggira per le The Barrens, dai vagabondi e cacciatrici ai potenti patriarchi e ai crini alti, possiede queste zanne affilate, affidandosi a esse per abbattere gli striduli delle pianure e difendere il proprio territorio contro i predatori concorrenti.",al={"da dove vengono le zanne di leone","chi lascia le zanne di leone","fonte della zanna di leone"}}},fp="18,251,28.529.0,51.251.0,39.212.0,29.185.0"}
P.entries["item:scaber-stalk"] = {n="Gambo Scabro",s="I Gambi Scabri sono rari funghi che prosperano nell'umida e appartata caverna nascosta dietro le Cascate di Altafonte a Darkshore. Apprezzati da erboristi e alchimisti per le loro insolite proprietà, sono ricercati da Barithras Ombraluna per i suoi intrugli.",h="I Gambi Scabri sono rari funghi che prosperano nell'umida e appartata caverna nascosta dietro le Cascate di...",kw={"auberdine","barithras ombraluna","cave mushrooms","cascate di altafonte","darkshore","cappella mortifera","gambo scabro"},ang={["profession:Herbalism"]="Sebbene non siano un'erba comunemente commerciata, questi gambi sotterranei offrono preziose informazioni su come i climi unici delle caverne e le ombre incombenti alterino la biologia fungina locale.",["race:NightElf"]="Dando ascolto agli avvertimenti del Bosco degli Antichi, gli elfi della notte affrontano la raccolta di questi Cave Mushrooms con grande cautela, a causa della presenza corruttrice che imperversa vicino alle Cascate di Altafonte."},sec={{t="Un raro esemplare di fungo",b="I Gambi Scabri sono funghi oscuri che si trovano nelle profondità della caverna annidata dietro le Cascate di Altafonte, situate lungo le montagne nord-orientali di Darkshore. A differenza della comune flora boschiva, questi pallidi gambi prosperano esclusivamente nell'umidità appartata della rete di caverne sotterranee. Il loro habitat remoto e pericoloso rende la loro raccolta estremamente rara, spingendo alchimisti come Barithras Ombraluna ad Auberdine a incaricare audaci esploratori disposti a sfidare l'oscurità."},{t="Un'ombra nelle cascate",b="La raccolta dei Gambi Scabri comporta molti più pericoli rispetto a una normale ricerca di erbe. I venerabili spiriti degli alberi del Bosco degli Antichi hanno lanciato avvertimenti agli elfi della notte locali, avendo percepito un male oscuro e crescente che si sta insediando all'interno della caverna delle Cascate di Altafonte. Sebbene gli alchimisti apprezzino i gambi insieme alle rare Cappelle Mortifere per le loro pozioni sperimentali, raccoglierli porta inevitabilmente chi li cerca faccia a faccia con qualsiasi malvagità abbia messo radici sotto le montagne."}},faq={{q="Dove crescono i Gambi Scabri?",a="I Gambi Scabri crescono esclusivamente all'interno dell'umida caverna nascosta dietro le Cascate di Altafonte, situata nella parte nord-orientale di Darkshore lungo la dorsale montuosa.",al={"posizione del gambo scabro","dove si trovano i gambi scabri","caverna dei gambi scabri"}},{q="Chi vuole i Gambi Scabri?",a="Barithras Ombraluna, un erudito elfo della notte che risiede ad Auberdine, cerca i Gambi Scabri insieme a una Cappella Mortifera per preparare una pozione specializzata.",al={"chi usa il gambo scabro","funghi di barithras ombraluna","chi ha bisogno dei gambi scabri"}},{q="Perché Barithras Ombraluna non ha raccolto i gambi da solo?",a="Barithras è stato diffidato dall'avvicinarsi alla caverna dal Bosco degli Antichi, i cui spiriti hanno percepito che un nuovo e pericoloso male si era rifugiato dietro la cascata.",al={"perché non li raccoglie lui stesso","avvertimento per barithras","avvertimento sulla caverna di altafonte"}},{q="Cos'altro cresce insieme ai Gambi Scabri?",a="La caverna ospita anche il letale fungo Cappella Mortifera, un altro raro esemplare richiesto da Barithras per le sue ricerche alchemiche.",al={"altri funghi nella caverna","cappella mortifera e gambo scabro","funghi di altafonte"}}},fx={f5b84e96={q="Cos'è un Gambo Scabro?",a="Un Gambo Scabro è una rara specie di fungo cavernicolo nativo della caverna ombrosa nascosta dietro le Cascate di Altafonte a Darkshore. Sebbene i funghi sotterranei siano comuni in tutta la Kalimdor settentrionale, questa particolare varietà prospera in grotte umide e scure che ospitano energie sinistre.",al={"cos'è un gambo scabro","informazioni sul gambo scabro","fungo gambo scabro"}},["053fa90e"]={q="Perché qualcuno vuole i Gambi Scabri?",a="Barithras Ombraluna ad Auberdine cerca Gambi Scabri come ingrediente vitale per preparare pozioni specializzate. Poiché questi funghi potenti crescono solo nella grotta appartata vicino alle Cascate di Altafonte, gli erboristi e gli alchimisti devono affidarsi ai viaggiatori avventurosi per raccoglierli.",al={"perché raccogliere il gambo scabro","uso del gambo scabro","a cosa servono i gambi scabri"}}},fp="12,247,22.463.0,21.462.1,28.147.0,24.136.0,58.155.0,40.128.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Scaglia di Vecchio Occhiobuio",s="La Scaglia di Vecchio Occhiobuio viene presa dal famigerato capo murloc che terrorizza la costa delle Marche Occidentali. Strappata dalla pelle della bestia, funge da prova inconfutabile della sua morte per il Capitano Grayson, il fantasma che infesta il Faro delle Marche Occidentali.",h="La Scaglia di Vecchio Occhiobuio viene presa dal famigerato capo murloc che terrorizza la costa delle Marche...",kw={"capitano grayson","minaccia costiera","murloc","vecchio occhiobuio","scaglia di vecchio occhiobuio","marche occidentali","faro delle marche occidentali"},ang={["faction:Alliance"]="Per i marinai dell'Alleanza che navigano nel Grande Mare verso le acque di Roccavento, porre fine al Vecchio Occhiobuio aiuta a garantire che il faro delle Marche Occidentali rimanga acceso, evitando che le future imbarcazioni si schiantino contro gli scogli."},sec={{t="Trofeo di un flagello costiero",b="La costa delle Marche Occidentali è già abbastanza pericolosa tra secche nascoste e tempeste incessanti, ma la presenza del Vecchio Occhiobuio ha trasformato il pericolo da rischio di navigazione a vero e proprio massacro. Secondo il Capitano Grayson, il fantasma vincolato al Faro delle Marche Occidentali, questo particolare murloc possedeva un'astuzia superiore a quella dei suoi simili feroci, radunando i murloc dalla mente più debole per compiere incursioni sulla costa. Occhiobuio mise in fuga la famiglia del guardiano, lasciando il faro spento la notte in cui la nave di Grayson si schiantò contro gli scogli, e quando la famiglia tornò per riaccendere la fiamma, compì un'altra incursione e li massacrò. Prendere una scaglia dalla creatura è l'unico modo per placare lo spirito vendicativo e dimostrare che la costa è stata ripulita dal suo predatore più feroce."}},faq={{q="A cosa serve la Scaglia di Vecchio Occhiobuio?",a="La scaglia funge da prova della morte per il Capitano Grayson, il fantasma che infesta l'isola rocciosa del Faro delle Marche Occidentali. Grayson cerca vendetta contro il Vecchio Occhiobuio per aver lasciato il faro spento la notte del fatale naufragio del capitano e per aver successivamente massacrato la famiglia del guardiano del faro.",al={"chi vuole la scaglia","consegna scaglia di occhiobuio","uso della scaglia di vecchio occhiobuio"}},{q="Chi è il Vecchio Occhiobuio?",a="Il Vecchio Occhiobuio è un capo murloc notoriamente feroce e astuto che si aggira per le rive sabbiose delle Marche Occidentali. A differenza dei comuni murloc, ha dimostrato la capacità di organizzare e costringere i suoi simili a compiere incursioni coordinate e letali contro gli avamposti costieri.",al={"chi è occhiobuio","storia di occhiobuio","vecchio occhiobuio"}},{q="Perché il Vecchio Occhiobuio ha preso di mira il faro?",a="Il Vecchio Occhiobuio ha inizialmente assalito il faro per scacciare il guardiano e la sua famiglia, facendo sprofondare la costa nell'oscurità. Quando i guardiani sono tornati per riaccendere la fiamma, Occhiobuio ha radunato i suoi simili per un secondo assalto, uccidendo l'intera famiglia e lasciando le navi cieche di fronte alle insidiose secche costiere.",al={"perché attaccare il faro","incursione al faro","occhiobuio faro"}}},fx={["6e72b95e"]={q="Cos'è la Scaglia di Vecchio Occhiobuio?",a="È una scaglia dura e distintiva presa direttamente dalla pelle di Vecchio Occhiobuio, il famigerato capo murloc che terrorizza la costa delle Marche Occidentali. Portarla serve come prova inconfutabile che il mortale predatore costiero è stato finalmente ucciso.",al={"cos'è la scaglia di vecchio occhiobuio","oggetto scaglia di vecchio occhiobuio","scaglia di occhiobuio"}},["383f15e9"]={q="Da dove proviene la Scaglia di Vecchio Occhiobuio?",a="La scaglia proviene dalla pelle naturale di Vecchio Occhiobuio, un murloc insolitamente astuto e feroce che si aggira sulla costa delle Marche Occidentali. Non è stata forgiata o creata da mani mortali, ma raccolta dalla sua carcassa dopo averlo sconfitto in battaglia.",al={"origine della scaglia di vecchio occhiobuio","dove trovare la scaglia di vecchio occhiobuio","chi ha creato la scaglia di vecchio occhiobuio"}},e7059369={q="Perché il Capitano Grayson vuole la Scaglia di Vecchio Occhiobuio?",a="Il Capitano Grayson, il fantasma di un capitano di mare che indugia presso il Faro delle Marche Occidentali, cerca vendetta e chiusura. Vecchio Occhiobuio ha spaventato la famiglia del guardiano del faro, lasciando il faro al buio la notte in cui la nave di Grayson ha colpito le rocce, e quando la famiglia è tornata, ha fatto un'altra incursione e li ha massacrati. Grayson richiede la scaglia come prova innegabile che la bestia è morta e la costa è più sicura.",al={"perché grayson vuole la scaglia","perché è richiesta la scaglia di vecchio occhiobuio","chi vuole la scaglia di vecchio occhiobuio"}}},fp="21,250,27.728.0,43.293.0,20.256.0,43.305.0"}
P.entries["item:scarlet-armband"] = {n="Bracciali Scarlatti",s="I Bracciali Scarlatti sono insegne indossate dai membri della Crociata Scarlatta, a testimonianza della loro fanatica devozione allo sterminio di tutti i non morti. Ad Albamorta, l'Esecutore Arren li richiede come prova che i novelli Forsaken hanno risposto all'avanzata degli zeloti che invadono il loro territorio.",h="I Bracciali Scarlatti sono insegne indossate dai membri della Crociata Scarlatta, a testimonianza della loro...",kw={"albamorta","esecutore arren","bracciali scarlatti","scarlet convert","crociata scarlatta","scarlet initiate","radure di tirisfal"},ang={["race:Undead"]="Per i Forsaken appena risorti, raccogliere questi bracciali è una cupa introduzione all'odio del mondo dei vivi, a dimostrazione che la sopravvivenza richiede una difesa spietata contro la Crociata."},sec={{t="Un emblema di fanatismo",b="Indossati sulle maniche sia dagli Scarlet Initiate che dai nuovi convertiti, i Bracciali Scarlatti sono l'inconfondibile marchio della Crociata Scarlatta. Per i novelli Forsaken appena risorti ad Albamorta, queste strisce di stoffa rossa rappresentano una minaccia letale proprio alle porte di casa. La Crociata non fa alcuna distinzione tra i servi senza senno dello Scourge e i liberi sudditi della Dark Lady; ai loro occhi, qualsiasi cadavere che cammina deve essere dato alle fiamme. L'Esecutore Arren impiega la raccolta di questi bracciali come un cupo rito di passaggio, che conferma l'uccisione degli esploratori nemici a sudest dell'insediamento e dimostra che i nuovi Forsaken sono in grado di difendere la loro neonata nazione."}},faq={{q="Perché l'Esecutore Arren vuole i Bracciali Scarlatti?",a="L'Esecutore Arren richiede i bracciali come prova dell'eliminazione delle forze dell'accampamento della Crociata Scarlatta che incombe a sudest di Albamorta. La Crociata costituisce un'immediata minaccia esistenziale per i Forsaken appena risvegliati, e la raccolta di questi pegni garantisce che i loro esploratori avanzati e le reclute siano stati abbattuti.",al={"perché raccogliere i bracciali","missione bracciali arren","scopo bracciali scarlatti"}},{q="Chi indossa questi bracciali?",a="I bracciali sono indossati dai membri di rango inferiore della Crociata Scarlatta di stanza vicino ad Albamorta, nello specifico gli Scarlet Initiate, gli Scarlet Convert e il messaggero Meven Korgal.",al={"chi rilascia bracciali scarlatti","dove trovare i bracciali"}},{q="Perché la Crociata Scarlatta odia i Forsaken?",a="Spinta da un fanatismo estremo, la Crociata Scarlatta rifiuta di vedere alcuna differenza tra lo Scourge privo di senno del Lich King e i Forsaken liberi. Considera tutti i non morti come abominazioni che devono essere eradicate per sempre.",al={"perché gli scarlatti attaccano i non morti","crociata contro reietti","zeloti scarlatti"}},{q="Dov'è l'accampamento in cui si possono trovare questi bracciali?",a="L'accampamento si trova appena a sudest di Albamorta nelle Radure di Tirisfal, annidato tra le colline oltre il perimetro dell'insediamento.",al={"posizione accampamento scarlatto","accampamento scarlatto albamorta","dove sono i convertiti scarlatti"}}},fx={["365b2391"]={q="Cos'è un Bracciale Scarlatto?",a="Un Bracciale Scarlatto è un pezzo di stoffa cremisi indossato dagli iniziati e dai convertiti della Crociata Scarlatta. Serve come insegna identificativa per l'ordine umano zelante, segnando i suoi membri come crociati votati dedicati a sradicare tutti i non morti da Lordaeron, indipendentemente dal fatto che quei non morti servano il Flagello o possiedano il libero arbitrio come i Reietti.",al={"cos'è il bracciale scarlatto","significato del bracciale scarlatto","lore del bracciale scarlatto"}}},fp="15,281,21.661.0,46.309.0,25.178.0,47.222.0,52.125.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Documenti della Crociata Scarlatta",s="Questi documenti intercettati erano trasportati da un messaggero della Crociata Scarlatta presso l'accampamento della Crociata vicino ad Albamorta. Contenendo ordini per i comandanti sul campo della Crociata attraverso le Radure di Tirisfal, forniscono ai Reietti le informazioni militari precise necessarie per colpire i vertici regionali della Crociata.",h="Questi documenti intercettati erano trasportati da un messaggero della Crociata Scarlatta presso...",kw={"brill","albamorta","esecutore arren","esecutore zygand","meven korgal","documenti della crociata scarlatta","the red messenger","vital intelligence"},ang={["race:Undead"]="Portare con sé questi documenti intercettati segna il passaggio di un Reietto risvegliato dalle prove del cimitero di Albamorta al più vasto sforzo bellico diretto da Brill."},sec={{t="Ordini Intercettati",b="Il corriere Meven Korgal trasportava questi documenti all'accampamento della Crociata a sudest di Albamorta. Emanate per ordine dell'Highlord, le direttive sono indirizzate ai capitani del Tirisfal Regional Command della Crociata: Captain Perrine deve fortificare ulteriormente la torre sud-occidentale e raccogliere informazioni sui non morti a Brill, Captain Vachon deve schiacciare i movimenti dei non morti vicino alla torre settentrionale, e Captain Melrose deve sorvegliare i confini delle Plaguelands. I documenti rivelano i nomi, le postazioni e gli ordini degli ufficiali sul campo Scarlatti di stanza nelle Radure di Tirisfal, trasformando quella che altrimenti sarebbe stata una normale corsa di corriere in una catastrofica violazione di informazioni per i fanatici."},{t="Consegna a Brill",b="L'Esecutore Arren si rese subito conto che le forze locali ad Albamorta non potevano sfruttare appieno la portata di queste informazioni. Il dossier catturato serve invece come lasciapassare per un Reietto appena risvegliato per lasciare Albamorta. Trasportati verso nord-est oltre Maniero Cuorduro fino a Brill, i documenti vengono consegnati direttamente all'Esecutore Zygand all'esterno del Municipio di Brill. Con questi ordini in mano, i vertici militari dei Reietti pianificano rapidi attacchi mirati per decapitare i comandanti Scarlatti trincerati nelle Radure."}},faq={{q="Chi trasportava questi documenti?",a="Erano trasportati da Meven Korgal, un corriere della Crociata Scarlatta trovato all'accampamento della Crociata a sudest di Albamorta.",al={"chi li ha lasciati cadere","messaggero scarlatto","meven korgal"}},{q="Quali informazioni ci sono nei documenti?",a="Il plico contiene direttive, per ordine dell'Highlord, indirizzate ai capitani del Tirisfal Regional Command della Crociata: Captain Perrine deve fortificare la torre sud-occidentale e perlustrare i non morti a Brill, Captain Vachon deve occuparsi dei movimenti dei non morti vicino alla torre settentrionale, e Captain Melrose deve sorvegliare i confini delle Plaguelands.",al={"cosa dicono i documenti","contenuto dei documenti"}},{q="Chi deve vedere questi documenti?",a="Dopo essere stati recuperati per l'Esecutore Arren ad Albamorta, ti vengono affidati per essere consegnati all'Esecutore Zygand, che sovrintende agli sforzi militari regionali all'esterno del Municipio di Brill.",al={"dove li porto","a chi consegno i documenti"}},{q="Perché questi documenti sono importanti per i Reietti?",a="Gli ordini catturati individuano con precisione lo schieramento degli ufficiali della Crociata in tutte le Radure di Tirisfal, dando ai Reietti un netto vantaggio per eliminare il comando nemico e infrangere il morale regionale dei fanatici.",al={"perché i reietti li vogliono","importanza dei documenti scarlatti"}}},fx={b6ac443b={q="Cosa sono i Documenti della Crociata Scarlatta?",a="Sono un fascicolo di documenti militari riservati, rapporti di battaglia e ordini portati da un corriere della Crociata Scarlatta. Sebbene gran parte del fascicolo consista in normali resoconti di esplorazione e propaganda sulle scaramucce con i Reietti, contiene anche istruzioni operative dettagliate destinate agli ufficiali della Crociata di stanza in tutte le Radure di Tirisfal.",al={"cosa sono i documenti","info documenti crociata scarlatta","oggetto documenti scarlatti"}},["5f5d9cee"]={q="Da dove provengono i Documenti della Crociata Scarlatta?",a="Sono direttive emesse per ordine dell'Alto Lord della Crociata ai capitani del suo Comando Regionale di Tirisfal. Sono stati affidati a un corriere di nome Meven Korgal, che i Reietti hanno trovato al campo della Crociata a sud-est di Albamorta.",al={"chi ha scritto i documenti della crociata scarlatta","fonte dei documenti scarlatti","da dove vengono i documenti"}}},fp="25,299,18.662.0,17.502.0,33.119.0,41.325.0,33.178.0,50.191.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Anello con Fregi Scarlatto",s="Un Anello con Fregi Scarlatto è una fascia con sigillo indossata dai membri della Crociata Scarlatta di guarnigione nelle Radure di Tirisfal. Per i difensori Reietti di Brill, questi anelli fungono da macabra prova che un altro zelota è stato eliminato dal suolo di Lordaeron.",h="Un Anello con Fregi Scarlatto è una fascia con sigillo indossata dai membri della Crociata Scarlatta di...",kw={"brill","guardiamorte burgess","esecutore zygand","proof of demise","crociata scarlatta","anello con fregi scarlatto","radure di tirisfal","varimathras"},ang={["faction:Horde"]="Raccogliere questi anelli aiuta la neonata Orda a consolidare la propria presenza nei Regni Orientali indebolendo i fanatici crociati che circondano Sepulcro.",["race:Undead"]="Per i Reietti, strappare questi anelli dalle mani dei Crociati morti è una dichiarazione diretta che Tirisfal appartiene ai morti, compiendo gli ordini della Dama Oscura e di Varimathras."},sec={{t="Emblemi dello Zelotismo",b="Ogni combattente della Crociata Scarlatta nelle Radure di Tirisfal—dai neofiti appena arruolati e frati zelanti fino a capitani veterani come Melrache e Perrine—porta con sé un anello con fregi. Contraddistinti dal sigillo fiammeggiante della Crociata, gli anelli identificano fratelli e sorelle all'interno di un'organizzazione consumata dalla paranoia. Per gli estranei e i nemici, tuttavia, questi ninnoli servono a scopi del tutto diversi: sono segni distintivi inconfondibili del più fanatico residuo umano di Lordaeron."},{t="Taglia del Signore del Terrore",b="Sotto il diretto mandato di Varimathras, luogotenente signore del terrore di Dama Sylvanas, la Guardiamorte Burgess a Brill raccoglie attivamente questi anelli. I Reietti considerano la Crociata Scarlatta una pestilenza intollerabile che striscia attraverso la loro terra natia appena reclamata. Per le reclute dei Reietti, riportare pile di questi anelli a Brill è considerato un'innegabile prova di morte (Proof of Demise) e una diretta affermazione di lealtà al trono di Sepulcro."}},faq={{q="Chi indossa questi anelli con fregi?",a="Quasi tutti i membri della Crociata Scarlatta di stanza nelle Radure di Tirisfal ne indossano uno. Tra questi figurano soldati semplici come neofiti, missionari, zeloti e avanguardie, nonché ufficiali sul campo come il Capitano Perrine, il Capitano Melrache e il Capitano Vachon.",al={"chi rilascia gli anelli","quali crociati hanno gli anelli","proprietari degli anelli"}},{q="Perché la Guardiamorte Burgess vuole gli Anelli con Fregi Scarlatto?",a="La Guardiamorte Burgess raccoglie gli anelli come prova fisica dell'abbattimento dei Crociati Scarlatti. Agendo in base ai decreti emanati da Varimathras e dalla Dama Oscura, la guarnigione dei Reietti a Brill usa gli anelli per misurare la lealtà e l'efficacia di una recluta nell'eliminare gli umani da Lordaeron.",al={"perché raccogliere gli anelli","motivo di proof of demise","anelli burgess"}},{q="Cosa rappresenta il fregio sull'anello?",a="L'anello reca il marchio della Crociata Scarlatta, a simboleggiare la loro guerra santa per sradicare ogni forma di non-morte da Lordaeron. I Crociati lo indossano con fiero orgoglio, considerandolo un distintivo di rettitudine, anche se la loro ossessione li spinge a massacrare chiunque non appartenga al loro ordine.",al={"simbolo scarlatto","cos'è il fregio","emblema dell'anello"}},{q="Quale ruolo ha Varimathras nella raccolta di questi anelli?",a="Varimathras funge da luogotenente capo di Sylvanas Ventolesto a Sepulcro. Sovrintende agli sforzi militari strategici per annientare gli umani viventi ostili nelle Radure di Tirisfal, rendendo l'eradicazione della Crociata Scarlatta una priorità assoluta per i comandanti dei Reietti come l'Esecutore Zygand e la Guardiamorte Burgess.",al={"ordini di varimathras","perché varimathras vuole gli anelli","coinvolgimento del signore del terrore"}}},fx={d4097e42={q="Cos'è un Anello con Fregi Scarlatto?",a="Un Anello con Fregi Scarlatto è una fascia identificativa portata dai membri della Crociata Scarlatta attraverso le Radure di Tirisfal. Portando l'emblema dell'ordine militante, segna l'alleanza di chi lo indossa con la loro crociata fanatica per sradicare la non morte. Per i Reietti che difendono i loro nuovi confini, questi anelli servono come prova indiscutibile che un soldato o un ufficiale nemico è stato eliminato.",al={"cos'è l'anello con fregi scarlatto","lore anello con fregi scarlatto","cosa sono questi anelli"}}},fp="21,254,18.466.0,23.428.0,31.260.0,56.292.0,45.282.0,58.301.0"}
P.entries["item:scavenged-goods"] = {n="Beni Recuperati",s="I Beni Recuperati sono vari pezzi di equipaggiamento e provviste scartati, stipati in casse di equipaggiamento nei dintorni di Albamorta. I Reietti appena risorti li recuperano per garantire che il flusso incessante di nuove reclute possa essere armato e vestito.",h="I Beni Recuperati sono vari pezzi di equipaggiamento e provviste scartati, stipati in casse di...",kw={"guardiamorte saltain","albamorta","casse di equipaggiamento","provviste dei reietti","beni recuperati","scavenging deathknell"},ang={["race:Undead"]="Per i Reietti, recuperare l'equipaggiamento dismesso è una necessità di sopravvivenza, che consolida la dura verità secondo cui i vivi non concederanno loro alcun aiuto né pietà."},sec={{t="Cavarsela da soli",b="Quando i nuovi Reietti emergono dalla terra nel cimitero di Albamorta, si risvegliano con poco più che sudari funebri marcescenti. Gli insediamenti e i regni circostanti non offrono alcun aiuto ai non morti, lasciandoli del tutto dipendenti da ciò che riescono a recuperare. Il Guardiamorte Saltain coordina la raccolta di armi, attrezzi e indumenti scartati e nascosti in casse di scorte in tutto il villaggio, distribuendoli direttamente al successivo gruppo di reclute risorte."}},faq={{q="A cosa servono i beni recuperati?",a="Il Guardiamorte Saltain li raccoglie per equipaggiare le nuove reclute dei Reietti che risorgono dal cimitero. Senza recuperare i rimasugli dalle casse vicine, i non morti appena risorti dovrebbero avventurarsi nelle Radure di Tirisfal completamente disarmati e svestiti.",al={"scopo dei beni recuperati","perché raccogliere beni recuperati","cosa fa saltain con i beni recuperati"}},{q="Dove si trovano questi beni?",a="Vengono recuperati da casse di equipaggiamento situate fuori dai casolari e attorno agli edifici in rovina in tutta Albamorta.",al={"dove trovare beni recuperati","posizione beni recuperati","dove si trovano le casse di equipaggiamento"}},{q="Chi richiede i beni recuperati?",a="Il Guardiamorte Saltain, un ufficiale di stanza ad Albamorta, ordina ai Reietti appena risvegliati di raccogliere queste provviste per insegnare loro l'autosufficienza e prepararli all'arrivo di nuove coorti.",al={"chi vuole i beni recuperati","missione guardiamorte saltain"}}},fx={f565021a={q="Cosa sono i Beni Recuperati?",a="Si tratta di pezzi assortiti di equipaggiamento, vestiario e attrezzature riutilizzabili, recuperati da vecchie casse sparse per Albamorta. Piuttosto che armamenti immacolati, sono resti scartati della vita passata della città che possono ancora servire a uno scopo pratico per i Forsaken appena risvegliati.",al={"beni recuperati cosa sono","cosa sono i beni recuperati"}},["0b2267aa"]={q="Da dove provengono i Beni Recuperati?",a="Provengono da casse di equipaggiamento abbandonate tra le strutture in rovina di Albamorta. Appartenute un tempo agli abitanti vivi di Lordaeron prima che il regno cadesse sotto la piaga, queste provviste sono rimaste dimenticate tra le rovine finché i Forsaken non hanno iniziato a reclamare la città come propria base operativa.",al={"origine beni recuperati","chi ha creato i beni recuperati","da dove provengono i beni recuperati"}},["36f8df02"]={q="Perché il Guardiamorte Saltain vuole i Beni Recuperati?",a="I Forsaken continuano a risvegliare i nuovi morti dal cimitero e queste nuove reclute entrano nel mondo con poco o nulla. Il Guardiamorte Saltain raccoglie questi oggetti recuperati in modo che i non morti appena emersi abbiano vestiti ed equipaggiamento di base, invece di iniziare il servizio disarmati ed esposti.",al={"perché saltain vuole i beni recuperati","perché raccogliere beni recuperati","perché servono i beni recuperati"}}},fp="15,225,22.454.0,34.236.0,28.111.0,33.178.0"}
P.entries["item:scavenger-paw"] = {n="Zampa di Saprofago",s="Le Zampe di Saprofago sono arti mozzati raccolti dai lupi giovani e cenciosi che si aggirano per le colline di Albamorta. I Reietti appena risvegliati le raccolgono per i custodi locali affinché le cuciano insieme per creare equipaggiamento protettivo rudimentale.",h="Le Zampe di Saprofago sono arti mozzati raccolti dai lupi giovani e cenciosi che si aggirano per le colline...",kw={"albamorta","novizia elreth","ragged scavenger","zampa di saprofago","the damned","young scavenger"},ang={["profession:Tailoring"]="Il rudimentale assemblaggio di zampe di lupo e ali di pipistrello da parte della Novizia Elreth mostra come l'arte della cucitura improvvisata sostenti i nascenti insediamenti dei Reietti.",["race:Undead"]="Risvegliandosi con la carne in decomposizione e poco equipaggiamento, raccogliere parti dai predatori locali è spesso il primo passo per assemblare armature sufficienti a sopravvivere ai pericoli di Tirisfal."},sec={{t="Armature rabberciate ad Albamorta",b="Le risorse scarseggiano per i ritornati da poco ad Albamorta. Con il Flagello e la Crociata Scarlatta che incombono su Tirisfal, ogni scarto di pelle e ossa viene impiegato per usi pratici. La Novizia Elreth, assistente del Sacerdote dell'Ombra Sarvis, raccoglie zampe dai lupi saprofagi locali insieme ad ali di pipistrello per confezionare indumenti e armature utilizzabili per i Reietti disorientati che escono freschi dalle loro tombe."}},faq={{q="A cosa servono le Zampe di Saprofago?",a="Vengono raccolte dalla Novizia Elreth ad Albamorta, che confeziona parti grezze di animali per creare armature basilari e indumenti cuciti per i nuovi iniziati Reietti.",al={"scopo zampa di saprofago","uso delle zampe","perché raccogliere zampe"}},{q="Dove si trovano?",a="Si ottengono da Young Scavenger e Ragged Scavenger, i lupi feroci che si aggirano per i boschi e i campi che circondano direttamente Albamorta.",al={"luogo rilascio zampe","dove trovare le zampe","quali lupi rilasciano zampe"}},{q="Chi richiede queste zampe?",a="La Novizia Elreth, che assiste il Sacerdote dell'Ombra Sarvis curando le reclute ferite, confezionando equipaggiamento e vestendo coloro che vengono inviati sul campo.",al={"chi vuole le zampe di saprofago","chi assegna la missione delle zampe","zampe novizia elreth"}}},fx={["41bb56d4"]={q="Cos'è una Zampa di Saprofago?",a="Una Zampa di Saprofago è la zampa mozzata di un lupo saprofago che vaga per i boschi infestati delle Radure di Tirisfal attorno ad Albamorta. Sebbene sembrino trofei macabri, queste parti animali resistenti servono come materia prima per i Forsaken appena risvegliati, che devono utilizzare ogni frammento della fauna locale per creare ciò che è necessario e sopravvivere.",al={"identità zampa di saprofago","cosa sono le zampe di saprofago","cos'è la zampa di saprofago"}},["366465d3"]={q="Da dove proviene una Zampa di Saprofago?",a="Queste zampe vengono raccolte dai giovani e spelacchiati lupi saprofagi che si aggirano per il perimetro di Albamorta. Aggirandosi per le radure avvizzite appena oltre le mura del villaggio, queste bestie feroci setacciano la campagna flagellata in cerca di carogne, diventando facili prede per le nuove reclute Forsaken che cercano di dimostrare la propria forza.",al={"fonte zampa di saprofago","dove trovare la zampa di saprofago","zampe di lupo saprofago"}},f83538b8={q="Perché qualcuno vuole le Zampe di Saprofago?",a="La Novizia Elreth ad Albamorta le raccoglie per confezionare armature e vestiti robusti per i soldati Forsaken appena risvegliati. Le risorse sono disperatamente scarse per i non morti liberi appena nati ed Elreth unisce pelli, ali e zampe per rattoppare equipaggiamento che possa proteggerti dai non morti senza cervello e dalla Crociata Scarlatta che minacciano il rifugio.",al={"perché raccogliere zampe di saprofago","chi ha bisogno di zampe di saprofago","uso zampe di saprofago lore"}}},fp="13,213,27.397.0,33.148.0,23.144.0,24.140.0"}
P.entries["item:scorched-spider-fang"] = {n="Zanna di Ragno Bruciata",s="Le Zanne di Ragno Bruciate sono materiali di fabbricazione specializzati raccolti da aracnidi predatori in agguato nelle caverne fradice delle Wetlands. Il corazzaio nanico Furen Barbalunga richiede una quantità considerevole di queste zanne temprate dal calore per forgiare una resistente maglia temprata dal fuoco per guerrieri esperti.",h="Le Zanne di Ragno Bruciate sono materiali di fabbricazione specializzati raccolti da aracnidi predatori in...",kw={"cave stalker","fire hardened mail","furen barbalunga","leech stalker","zanna di ragno bruciata","roccavento","wetlands"},ang={["class:Warrior"]="Raccogliere cinquanta di queste zanne è una delle ardue prove assegnate da Furen Barbalunga per mettere alla prova la tua resistenza e procurare i componenti grezzi per la tua caratteristica armatura di maglia.",["profession:Blacksmithing"]="Il metodo di Furen di incorporare chitina e zanne bruciate nelle maglie di ferro offre uno sguardo sulle rare tradizioni naniche di fabbricazione delle armature, che guardano ben oltre la fusione convenzionale."},sec={{t="La formula di un fabbro nanico",b="Forgiare armature in grado di deflettere lame e resistere a traumi violenti richiede più del ferro ordinario. Nel trafficato quartiere di Roccavento, l'abile fabbro Furen Barbalunga utilizza oscure tecniche metallurgiche che fondono parti di bestie con reagenti rari. Furen richiede cinquanta zanne bruciate dai giganteschi aracnidi degli Acquitrini Selvaggi, sfruttando la loro composizione densa, velenosa e naturalmente indurita per rinforzare le maglie durante il processo di tempra."},{t="Predatori delle Wetlands",b="Queste zanne vengono raccolte direttamente dai letali aracnidi che popolano le valli sprofondate e le tane delle Wetlands, in particolare Cave Stalker e Leech Stalker. Nonostante l'ambiente umido e putrescente della palude, questi predatori possiedono mandibole bruciate e singolarmente indurite. Raccoglierle nelle quantità richieste da Furen impone di avventurarsi in profonde cavità e sterminare interi sciami di mostruosi parassiti."}},faq={{q="A cosa servono le Zanne di Ragno Bruciate?",a="Vengono raccolte per Furen Barbalunga, un corazzaio situato a Roccavento. Ne richiede cinquanta, insieme a componenti provenienti da Stonetalon e dalle Gallerie di Lamaspina, per forgiare una corazza eccezionalmente resistente per i guerrieri dell'Alleanza.",al={"cosa fare con le zanne di ragno bruciate","scopo della zanna di ragno bruciata","chi ha bisogno di zanne di ragno bruciate"}},{q="Dove posso trovare le Zanne di Ragno Bruciate?",a="Si ricavano dagli aracnidi all'interno delle Wetlands, nello specifico Leech Stalker e Cave Stalker che si annidano nelle umide tane, sui fianchi delle colline e nelle caverne degli scavi della regione.",al={"posizione di rilascio zanna di ragno bruciata","quali ragni rilasciano la zanna di ragno bruciata","dove trovare zanne di ragno bruciate"}},{q="Perché un fabbro ha bisogno di così tante zanne di ragno per creare un'armatura?",a="Furen Barbalunga impiega metodi di forgiatura nanica poco ortodossi. Le proprietà ricche di minerali e resistenti al fuoco di queste zanne indurite fungono da agente indurente non convenzionale, rinforzando le maglie dell'armatura quando vengono trattate insieme a flogisto e corna di bestia.",al={"perché 50 zanne","perché furen ha bisogno di zanne di ragno"}},{q="Qualsiasi avventuriero può raccogliere e consegnare queste zanne?",a="Sebbene chiunque viaggi attraverso le Wetlands possa uccidere i ragni e raccoglierne le mandibole, Furen Barbalunga commissiona il progetto di forgiatura soltanto agli aspiranti guerrieri che desiderano ottenere la loro maglia temprata dal fuoco.",al={"zanna di ragno bruciata solo per guerrieri","chi può consegnare le zanne di ragno bruciate"}}},fx={a7a99cbb={q="Cos'è una Zanna di Ragno Bruciata?",a="Una Zanna di Ragno Bruciata è un dente velenoso indurito e trattato termicamente, raccolto dagli aracnidi predatori come i Cacciatori delle Caverne e i Cacciatori Sanguisuga che si annidano nelle Wetlands. Il loro aspetto annerito e fragile cela una straordinaria densità, rendendole ambite tra gli armaioli esperti che cercano componenti rari per tecniche di forgiatura avanzate.",al={"cos'è la zanna di ragno bruciata","zanne di ragno bruciate","zanna bruciata"}},c6d8f632={q="Da dove provengono le Zanne di Ragno Bruciate?",a="Queste zanne non sono create da mani mortali; sono raccolte direttamente dagli aracnidi giganti delle Wetlands, specificamente dai Cacciatori Sanguisuga e dai Cacciatori delle Caverne. La costante esposizione agli elementi sotterranei e l'alchimia naturale del loro veleno conferisce a queste zanne la loro resistenza annerita e trattata col fuoco.",al={"da dove provengono le zanne di ragno bruciate","origine zanna di ragno bruciata","fonte zanna di ragno bruciata"}}},fp="20,292,25.454.0,24.414.0,40.225.0,39.175.0,62.250.0,51.211.0"}
P.entries["item:scroll-of-messaging"] = {n="Pergamena Scritta",s="La Pergamena Scritta è una pergamena incantata che racchiude un incantesimo di trasmissione magico specifico. Ottenuta per lo gnomo ingegnere Gaxim Scoppiarame nelle Vette di Petrartiglio, serve a uno scopo insolito: fornire l'innesco magico necessario per far detonare esplosivi a distanza.",h="La Pergamena Scritta è una pergamena incantata che racchiude un incantesimo di trasmissione magico specifico.",kw={"esplosivi","gaxim scoppiarame","ng-5","detonatore a distanza","pergamena scritta","vette di petrartiglio","s.p.r. & co."},ang={["faction:Alliance"]="La pergamena gioca un ruolo fondamentale nell'aiutare gli agenti dell'Alleanza a sabotare i macchinari della S.P.R. & Co. e frenare la loro devastazione ambientale a Petrartiglio.",["profession:Engineering"]="Fedele all'innovazione gnomesca, questa pergamena dimostra come la magia arcana teorica possa essere riconvertita in un ricevitore a distanza per demolizioni meccaniche."},sec={{t="Un messaggio volatile",b="Sebbene all'apparenza sia uno scritto arcano destinato alla comunicazione a lunga distanza, Gaxim Scoppiarame ha in mente un'applicazione ben più distruttiva per la Pergamena Scritta. Combinando il suo incantesimo di trasmissione con le volatili cariche NG-5, lo gnomo progetta di creare un esplosivo a detonazione a distanza. L'esplosione che ne risulterà è pensata per provocare un enorme diversivo presso le operazioni di disboscamento della S.P.R. & Co. a Petrartiglio, offrendo agli agenti l'occasione di oltrepassare le guardie e sottrarre schemi ingegneristici brevettati e corrispondenza riservata."}},faq={{q="A cosa serve la Pergamena Scritta?",a="Sebbene sia redatta come incantesimo di messaggistica, Gaxim Scoppiarame ne usa la magia di trasmissione per fabbricare un innesco a distanza. Se combinata con l'esplosivo NG-5, gli consente di innescare una deflagrazione da distanza di sicurezza.",al={"uso pergamena scritta","cosa fa la pergamena scritta","perché gaxim vuole la pergamena"}},{q="Chi riceve questa pergamena?",a="La pergamena viene consegnata a Gaxim Scoppiarame, uno gnomo ingegnere affiliato all'Alleanza che opera nelle Vette di Petrartiglio.",al={"chi riceve la pergamena scritta","dove portare la pergamena scritta","destinatario pergamena"}},{q="Perché Gaxim ha bisogno di un esplosivo a distanza?",a="Gaxim ha bisogno di un grande diversivo presso le operazioni locali della S.P.R. & Co. Il caos generato fornirà la copertura per infiltrarsi nel loro complesso, rubare preziosi progetti ingegneristici e recuperare documenti per fermare il loro aggressivo disboscamento della foresta.",al={"motivo esplosivo gaxim","perché far saltare in aria la s.p.r. & co.","distrazione vette di petrartiglio"}},{q="Cos'è l'NG-5?",a="L'NG-5 è una carica chimica esplosiva utilizzata da Gaxim Scoppiarame. Abbinata al segnale magico impresso sulla Pergamena Scritta, costituisce un dispositivo improvvisato di detonazione a distanza.",al={"ng-5","cos'è ng-5","esplosivo ng5"}}},fx={["2071477e"]={q="Cos'è la Pergamena Scritta?",a="La Pergamena Scritta è una pergamena incantata che porta con sé un incantesimo arcano. Gaxim Scoppiarame l'ha cercata come catalizzatore non convenzionale da combinare con il suo composto esplosivo volatile, NG-5, permettendogli di creare una carica innescata a distanza contro le operazioni della S.P.R. & Co. a Stonetalon.",al={"cos'è la pergamena scritta","lore pergamena scritta","informazioni sulla pergamena scritta"}}},fp="19,268,18.543.0,41.200.0,25.118.0,39.244.0,13.186.0"}
P.entries["item:sea-creature-bones"] = {n="Ossa di Creature Marine",s="Le Ossa di Creature Marine sono campioni scheletrici raccolti dalle enormi carcasse marine che si arenano lungo la costa avvolta dalla nebbia di Darkshore. Inviati direttamente al Temple of the Moon a Darnassus, questi resti sono al centro di un'indagine in corso per scoprire cosa spinga queste grandi bestie a spiaggiarsi sulle rive.",h="Le Ossa di Creature Marine sono campioni scheletrici raccolti dalle enormi carcasse marine che si arenano...",kw={"auberdine","beached sea creature","darkshore","murloc foscarovina","gwennyth bly'leggonde","costa bruma","ossa di creature marine","temple of the moon"},ang={["class:Druid"]="Le inspiegabili morti di antichi predatori marini segnalano un profondo turbamento nelle acque al largo di Kalimdor, preoccupando qualsiasi guardiano devoto al mantenimento dell'equilibrio ecologico.",["race:NightElf"]="Gli improvvisi spiaggiamenti di massa lungo Darkshore turbano profondamente gli elfi della notte, che venerano l'armonia del mondo naturale e vedono queste creature arenate come un oscuro presagio che richiede l'attenzione del Temple of the Moon."},sec={{t="Un presagio sulla riva",b="Le spiagge coperte di nebbia di Darkshore hanno recentemente assistito a un allarmante aumento di enormi creature marine — inclusi giganteschi trebbiatori di gran lunga più grandi di quelli originari dei bassifondi locali — che si gettano nelle secche fino a morire. La vista è considerata un presagio nefasto dagli elfi della notte. Gwennyth Bly'leggonde, un'investigatrice inviata dal Temple of the Moon ad Auberdine, raccoglie campioni di ossa da questi leviatani spiaggiati per spedirli tramite ippogrifo a Darnassus per un esame approfondito."},{t="Carogne e spazzini",b="Recuperare queste ossa è irto di pericoli, poiché le immense carcasse attirano inevitabilmente gli spazzini locali. I murloc Greymist costieri sciamano frequentemente attorno ai leviatani morti e morenti, nutrendosi dei resti e difendendo aggressivamente le zone di pascolo. Sebbene i murloc siano troppo deboli per cacciare tali colossali creature da soli, la loro presenza opportunistica lungo Costa Bruma costringe investigatori e avventurieri a farsi strada tra i branchi di spazzini per assicurarsi frammenti ossei utilizzabili per lo studio."}},faq={{q="Perché queste creature si spiaggiano?",a="La causa esatta rimane sconosciuta. Sebbene gli spiaggiamenti occasionali siano un rischio naturale, il loro improvviso e drammatico aumento è considerato innaturale e allarmante dalle sacerdotesse di Elune, spingendole ad avviare un'indagine formale.",al={"perché i trebbiatori si spiaggiano","balene morte a darkshore","perché le creature si spiaggiano a darkshore"}},{q="Chi vuole queste ossa?",a="Gwennyth Bly'leggonde, un'investigatrice di stanza ad Auberdine, raccoglie le ossa per conto del Temple of the Moon a Darnassus, dove studiosi e sacerdotesse sperano di determinare cosa stia disturbando il mare.",al={"chi prende le ossa","a chi consegnare le ossa di creature marine","gwennyth darkshore"}},{q="I murloc hanno ucciso queste bestie giganti?",a="No. I murloc Greymist locali sono troppo deboli per abbattere bestie marine di quelle dimensioni. Sono semplicemente spazzini che si radunano in gran numero per nutrirsi delle carcasse una volta che si sono spiaggiate.",al={"i murloc hanno ucciso il trebbiatore","i murloc foscarovina hanno ucciso il mostro marino"}},{q="Da dove vengono recuperate le ossa?",a="Vengono recuperate direttamente dalle massicce carcasse rimaste arenate lungo la costa di Darkshore, in particolare sulle sabbie a sud di Auberdine e lungo Costa Bruma.",al={"dove trovare le ossa di creature marine","posizioni di beached sea creature"}}},fx={["90a4db20"]={q="Cosa sono queste Ossa di Creature Marine?",a="Sono resti scheletrici recuperati dalla carcassa massiccia di una creatura marina spiaggiata—nello specifico uno squalo trebbiatore insolitamente grande—arenatosi lungo la nebbiosa costa di Darkshore. Saccheggiati dai murloc Nebbiagrigia locali, questi resti massicci servono come prova fisica vitale per i ricercatori che cercano di capire perché i behemoth dell'oceano stiano morendo a riva.",al={"cosa sono le ossa di creature marine","lore ossa di creature marine","ossa giganti darkshore"}},cb40613a={q="Da dove provengono le Ossa di Creature Marine?",a="Queste ossa provengono da un colossale squalo trebbiatore, molto più grande di chiunque si aspettasse nelle acque di Darkshore, che si è inspiegabilmente gettato sulle spiagge di Costa Bruma a sud di Auberdine. Piuttosto che essere state create o uccise dai predatori locali, le ossa appartengono naturalmente a bestie di acque profonde che si sono misteriosamente spinte a riva per morire.",al={"da dove provengono le ossa di creature marine","origine ossa di creature marine","origine creatura marina spiaggiata"}}},fp="18,328,22.507.0,22.505.0,39.221.0,22.208.0,40.195.0,35.165.0"}
P.entries["item:sea-turtle-remains"] = {n="Resti di Tartaruga di Mare",s="I Resti di Tartaruga di Mare sono campioni scheletrici recuperati dalle carcasse di gigantesche tartarughe di mare lungo la costa di Darkshore. Fungono da campioni vitali per i ricercatori elfi della notte ad Auberdine che indagano su un allarmante aumento di spiaggiamenti marini.",h="I Resti di Tartaruga di Mare sono campioni scheletrici recuperati dalle carcasse di gigantesche tartarughe di...",kw={"auberdine","beached sea turtle","darkshore","gwennyth bly'leggonde","resti di tartaruga di mare","teldrassil","temple of the moon","washed ashore"},ang={["class:Druid"]="La morte innaturale di selvaggi leviatani marini segnala una corruzione più profonda che sconvolge l'equilibrio della natura lungo la costa di Kalimdor.",["race:NightElf"]="Lo spiaggiamento di massa della fauna marina proprio al largo della tua costa ancestrale è un presagio nefasto, soprattutto con i sospetti che riconducono alle acque che circondano Teldrassil."},sec={{t="Uno spiaggiamento inquietante",b="Gigantesche creature marine hanno iniziato a spiaggiarsi lungo tutte le coste avvolte dalla nebbia di Darkshore, mentre altre giacciono sommerse appena al largo della costa vicino a relitti affondati. Gwennyth Bly'leggonde, di stanza ad Auberdine, supervisiona la raccolta di frammenti scheletrici e tessuti da questi cadaveri. The Temple of the Moon a Darnassus richiede con urgenza questi campioni, preoccupato dalle teorie secondo cui le bestie potrebbero fuggire da una perturbazione innaturale nelle acque che circondano l'albero del mondo cresciuto di recente, Teldrassil."},{t="Spazzini dei bassifondi",b="Recuperare questi resti è un lavoro pericoloso. Le tribù costiere di murloc si radunano abitualmente attorno alle enormi carcasse, spolpando le ossa e nidificando accanto ad esse. Gli studiosi necessitano di frammenti ossei e tessuti freschi prima che gli spazzini distruggano qualsiasi prova superstite che possa spiegare la fatale migrazione delle creature."}},faq={{q="A cosa servono questi resti?",a="I resti vengono raccolti da Gwennyth Bly'leggonde ad Auberdine. Li prepara per gli studiosi e le sacerdotesse presso The Temple of the Moon a Darnassus, che stanno tentando di capire perché così tante creature oceaniche stiano morendo lungo Darkshore.",al={"perché raccogliere i resti di tartaruga","uso delle ossa di tartaruga","missione tartarughe di mare darkshore"}},{q="Perché le tartarughe di mare si stanno spiaggiando a Darkshore?",a="La causa esatta rimane oggetto di indagine, ma i ricercatori temono che la vita marina stia fuggendo da qualcosa di inquietante nelle acque attorno a Teldrassil. Gli spiaggiamenti non sono incidenti isolati, il che indica un diffuso disagio ecologico.",al={"perché le tartarughe stanno morendo","spiaggiamenti di tartarughe darkshore","creature marine spiaggiate"}},{q="Dove si trovano queste carcasse?",a="Gigantesche tartarughe di mare scheletriche sono sparse lungo la costa di Darkshore, con alcune adagiate in acque poco profonde vicino a navi affondate a ovest di Auberdine e altre disseminate sulle spiagge circondate da accampamenti di murloc.",al={"posizioni dei resti di tartaruga","dove trovare tartaruga di mare scheletrica"}},{q="Chi sta studiando questi resti?",a="Gwennyth Bly'leggonde, una ricercatrice ad Auberdine, raccoglie i reperti e invia rapporti dettagliati direttamente a The Sisterhood of Elune presso The Temple of the Moon a Darnassus.",al={"chi vuole i resti","gwennyth blyleggonde"}}},fx={dfe0d6c5={q="Cosa sono questi Resti di Tartaruga di Mare?",a="Questi resti sono campioni scheletrici recuperati da tartarughe di mare giganti che sono state spinte a riva lungo la costa di Darkshore o che sono morte nelle sue acque poco profonde. Sebbene saccheggiati da predatori locali e murloc, rimangono ossa e tessuti recuperabili, che offrono indizi fisici sugli ultimi momenti delle creature.",al={"cosa sono i resti di tartaruga di mare","lore resti di tartaruga di mare","cos'è il resto di tartaruga di mare"}},be90da46={q="Da dove provengono i Resti di Tartaruga di Mare?",a="Vengono raccolti direttamente da enormi carcasse scheletriche giacenti lungo le coste e le acque costiere di Darkshore, inclusi esemplari vicino ad Auberdine. Sono resti naturali di bestie marine piuttosto che oggetti creati, lasciati lì quando le tartarughe morenti nuotano verso terra e periscono.",al={"da dove provengono i resti di tartaruga di mare","origine resti di tartaruga di mare","fonte resti di tartaruga di mare"}}},fp="18,241,19.497.0,26.321.0,32.236.0,53.229.0,32.204.0,30.176.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Descrizione Sigillata del Visitatore di Thredd",s="La Descrizione Sigillata del Visitatore di Thredd è un rapporto confidenziale redatto dal Custode Cuorsaldo riguardo a un uomo enigmatico che ha fatto visita al capo dei Defias imprigionato, Bazil Thredd, all'interno delle Segrete di Roccavento. I suoi contenuti aiutano a rintracciare un agente segreto che si muove invisibile tra le sfere politiche e criminali di Roccavento.",h="La Descrizione Sigillata del Visitatore di Thredd è un rapporto confidenziale redatto dal Custode Cuorsaldo...",kw={"baros alexston","bazil thredd","maelik","mathias shaw","descrizione sigillata","segrete di roccavento","custode cuorsaldo"},ang={["class:Rogue"]="Trasportare questo dossier è una lezione diretta di spionaggio: falsi nomi, documenti contraffatti e visite in cella vengono tutti smascherati quando Mathias Shaw confronta le descrizioni fisiche con le informazioni dell'intelligence del SI:7.",["faction:Alliance"]="Il documento rivela preoccupanti crepe nella sicurezza interna di Roccavento, dimostrando che i cospiratori possono varcare indisturbati i cancelli delle Segrete di Roccavento usando credenziali contraffatte."},sec={{t="Un Patrono Misterioso",b="Per anni, all'interno delle Segrete di Roccavento, il prigioniero Bazil Thredd è rimasto nella sua cella senza alcun visitatore. Quella routine è cambiata quando un uomo poco comunicativo ha iniziato a passare una o due volte a settimana con documenti d'identità del tutto validi. Notando questi insoliti arrivi, il Custode Cuorsaldo ha redatto un resoconto fisico dell'uomo, che portava con sé documenti che lo identificavano come 'Maelik'. Il custode ha sigillato il profilo per evitare che occhi indiscreti lo leggessero prima che investigatori qualificati potessero agire."},{t="Dai Muratori alle Spie",b="Quando è stata portata all'architetto cittadino Baros Alexston, la descrizione non ha suscitato alcun riconoscimento immediato, a parte il vago sospetto che il visitatore potesse essere un operativo legato alla ribellione dei Defias. Alexston ha rapidamente reindirizzato la busta sigillata al Maestro Mathias Shaw, capo del servizio di intelligence di Roccavento, il SI:7. Shaw ha immediatamente smascherato l'inganno: la descrizione corrispondeva a un letale mercenario che opera sotto vari pseudonimi, tra cui Marzon, attualmente impegnato nel lavoro sporco per conto di Lord Gregor Lescovar."}},faq={{q="Chi ha scritto questa descrizione?",a="Il Custode Cuorsaldo, il capo custode delle Segrete di Roccavento, ha scritto e sigillato il documento. Si è insospettito quando una figura sconosciuta ha iniziato a fare visite regolari al capo dei Defias imprigionato, Bazil Thredd.",al={"chi l'ha scritto","autore della descrizione","chi ha redatto la nota"}},{q="Chi è il visitatore descritto nel documento?",a="Ha presentato documenti con il nome di Maelik. Il Custode Cuorsaldo ha annotato il suo aspetto affinché gli investigatori potessero stabilirne l'identità.",al={"chi faceva visita a thredd","chi è maelik","identità del visitatore"}},{q="Perché il visitatore si incontrava con Bazil Thredd?",a="Cuorsaldo si è insospettito quando Thredd ha iniziato a ricevere visite regolari dopo anni passati senza alcuna visita. Lo scopo del visitatore viene indagato attraverso la descrizione sigillata.",al={"perché visitare thredd","scopo del visitatore di thredd"}},{q="Dove deve essere portato questo documento sigillato?",a="Il documento viene prima portato all'architetto cittadino Baros Alexston a Roccavento. Dopo averlo esaminato e non riconoscendo la descrizione, Alexston ti ordina di consegnarlo direttamente al Maestro Mathias Shaw presso il quartier generale del SI:7 a Città Vecchia.",al={"dove portarlo","chi vuole la descrizione"}}},fx={["7193ccc9"]={q="Perché la descrizione del visitatore di Thredd è così importante?",a="Per anni, Bazil Thredd è rimasto abbandonato nelle Segrete di Roccavento senza un singolo visitatore. Quando una figura misteriosa che portava documenti sotto il nome di 'Maelik' ha iniziato improvvisamente a visitarlo ogni settimana, il Custode Cuorsaldo è diventato sospettoso di una cospirazione più profonda. Smascherare questo visitatore è vitale per scoprire chi a Roccavento stia attivamente coordinandosi con la leadership incarcerata della Fratellanza dei Defias, spingendo gli investigatori a cercare la rete di intelligence di Mathias Shaw per identificare l'oscuro intermediario.",al={"perché vogliono la descrizione","descrizione sigillata thredd perché richiesta","perché la descrizione del visitatore è importante"}}},fp="38,322,19.481.0,25.494.1,27.212.0,42.130.2,46.163.2,49.244.1"}
P.entries["item:sealed-envelope"] = {n="Busta Sigillata",s="Questo plico sigillato accuratamente contiene documenti tecnici riservati e schemi rubati della S.P.R. & Co. Preparato dall'ingegnere goblin esiliato Fizziks, racchiude progetti proprietari destinati a essere consegnati a Sputavalvole a Porto Paranco.",h="Questo plico sigillato accuratamente contiene documenti tecnici riservati e schemi rubati della S.P.R.",kw={"progetti","fizziks","porto paranco","busta sigillata","sputavalvole","petrartiglio","super reaper 6000","s.p.r. & co."},ang={["faction:Horde"]="Trasportare queste carte a sud da Petrartiglio aiuta i goblin neutrali di Porto Paranco a minare le aggressive e spietate operazioni di disboscamento della S.P.R. & Co.",["profession:Engineering"]="La busta custodisce i disegni tecnici del Super Reaper 6000, che rappresentano una delle automazioni meccaniche più distruttive e redditizie mai ideate da mani goblin."},sec={{t="Spionaggio industriale",b="Quando l'ingegnere goblin Fizziks fu bruscamente cacciato dalle operazioni di disboscamento della S.P.R. & Co. nelle Vette di Petrartiglio, non se ne andò a mani vuote. Infilando in questa busta manuali interni, procedure operative e specifiche tecniche, riuscì a contrabbandare segreti aziendali sotto il naso dei suoi ex sovrintendenti. Il reperto più prezioso tra questi documenti rubati sono gli schemi tecnici del Super Reaper 6000, un devastante macchinario industriale per il disboscamento totale."},{t="Consegna a Porto Paranco",b="Invece di tenere sepolti questi pericolosi segreti commerciali, Fizziks invia il plico a sud a Sputavalvole, un ingegnere che risiede nel porto goblin neutrale di Porto Paranco. Sebbene i rivali commerciali del Cartello degli Spargifumo provino ben poco affetto o fiducia personale per Fizziks, il valore ingegneristico dei progetti all'interno della busta è innegabile. I documenti offrono una chiara visione dell'ingegno meccanico della S.P.R. & Co. e danno agli ingegneri indipendenti l'opportunità di sfruttare le avanzate tecnologie di disboscamento della S.P.R. & Co."}},faq={{q="Cosa c'è all'interno della Busta Sigillata?",a="La busta contiene documenti interni della S.P.R. & Co., manuali operativi tecnici e i progetti per la macchina da disboscamento Super Reaper 6000, tutti sottratti da Fizziks durante la sua frettolosa partenza.",al={"contenuto della busta","cosa c'è nella busta sigillata","oggetti della busta sigillata"}},{q="Chi ha preparato questo plico?",a="La busta è stata preparata da Fizziks, uno scontento ingegnere goblin che è stato cacciato dalla S.P.R. & Co. durante le sue operazioni di disboscamento nelle Vette di Petrartiglio.",al={"chi ha preparato la busta","chi ha dato la busta sigillata","busta di fizziks"}},{q="Chi dovrebbe riceverlo?",a="È indirizzato a Sputavalvole, un inventore goblin che risiede nella città portuale di Porto Paranco all'interno di The Barrens.",al={"chi riceve la busta","dove va la busta","consegna a sputavalvole"}},{q="Perché Sputavalvole vuole questi documenti?",a="Sebbene Sputavalvole non veda di buon occhio la S.P.R. & Co. e diffidi di Fizziks, i documenti contengono preziosi miglioramenti e schemi che consentono agli inventori esterni di comprendere e adottare i potenti progetti meccanici della compagnia.",al={"perché sputavalvole la vuole","tecnologia della s.p.r. & co. porto paranco"}}},fp="15,232,19.494.0,19.515.0,35.206.0,25.165.0,30.107.0,43.227.0"}
P.entries["item:sealed-note-to-elling"] = {n="Messaggio Sigillato per Elling",s="Il Messaggio Sigillato per Elling è un dispaccio confidenziale redatto dal pescatore di Roccavento Jorgen. Destinato a Elling Trias, proprietario di Trias' Cheese, funge da collegamento iniziale nella discreta indagine riguardante la scomparsa di un diplomatico.",h="Il Messaggio Sigillato per Elling è un dispaccio confidenziale redatto dal pescatore di Roccavento Jorgen.",kw={"elling trias","jorgen","messaggio sigillato per elling","roccavento","the missing diplomat","distretto commerciale","formaggi di trias"},ang={["class:Rogue"]="I ladri che conoscono le reti clandestine di Roccavento sanno bene che Elling Trias è molto più di un semplice mercante di cheddar, rendendo questa corrispondenza riservata una comune operazione del mestiere.",["faction:Alliance"]="Recapitare il messaggio di Jorgen è un servigio diretto alla Corona, che fa avanzare un'indagine fondamentale per la stabilità politica di Roccavento."},sec={{t="Un passaggio di consegne discreto",b="Portare un messaggio sigillato attraverso le trafficate vie di Roccavento potrebbe sembrare un compito banale, ma le rigide istruzioni di Jorgen ne chiariscono la posta in gioco: consegnare la pergamena direttamente nelle mani di Elling Trias e mantenere il silenzio. Sebbene all'apparenza Trias si presenti come un mite mercante di formaggi nel Distretto Commerciale, questo messaggio clandestino indirizza le indagini sul diplomatico scomparso dritto al suo bancone, lasciando intuire reti ben più profonde del commercio caseario."}},faq={{q="Cosa c'è scritto all'interno del messaggio sigillato?",a="Il messaggio rimane sigillato fino alla consegna a Elling Trias. Contiene il rapporto di Jorgen e un'introduzione che indirizza il corriere verso Trias per approfondire le indagini sulla scomparsa del diplomatico.",al={"contenuto del messaggio","cosa dice il messaggio","testo della lettera"}},{q="Perché un venditore di formaggi riceve informazioni segrete?",a="Elling Trias gestisce un modesto negozio di formaggi nel Distretto Commerciale come copertura pubblica. Sotto il grembiule, Trias dispone di un'estesa rete clandestina di occhi e orecchie in tutta la città, che lo rende una risorsa preziosa per indagini delicate.",al={"perché elling trias","perché negozio di formaggi","trias è una spia"}},{q="Chi è Jorgen?",a="Jorgen è un pescatore che si trova vicino all'acqua nella Valle degli Eroi di Roccavento. Ha dei trascorsi con Elling Trias e con il Vescovo DeLavey, e il vescovo si rivolge a lui per questioni discrete da tenere lontane da occhi indiscreti.",al={"chi ha scritto il messaggio","storia di jorgen","guardiano jorgen"}},{q="Di cosa tratta il caso del diplomatico scomparso?",a="Un diplomatico di Roccavento inviato a Theramore per incontrare Jaina Marefiero non è mai giunto a destinazione, e le autorità reali stanno indagando con discrezione su ogni pista sospetta per non scatenare il panico tra le strade.",al={"storia del diplomatico scomparso","chi è il diplomatico","perché diplomatico scomparso"}}},fx={["76232759"]={q="Cos'è il Messaggio Sigillato per Elling?",a="È un messaggio riservato che ti è stato dato da Jorgen, destinato specificamente alle orecchie—e agli occhi—di Elling Trias. Sigillato con cera per garantire la segretezza, trasporta informazioni urgenti riguardanti l'indagine sulla Diplomatica scomparsa, affidato a te per una consegna a mano sicura attraverso Roccavento.",al={"cos'è il messaggio sigillato per elling","oggetto messaggio sigillato per elling","cos'è il messaggio di jorgen"}},["2cd529f3"]={q="Da dove proviene il Messaggio Sigillato per Elling?",a="Il messaggio è stato scritto e sigillato da Jorgen. Dopo aver interrogato e valutato le tracce riguardanti la Diplomatica scomparsa del regno, Jorgen scrive questo dispaccio discreto e lo mette direttamente nelle tue mani affinché tu lo porti a Elling Trias.",al={"chi ha scritto il messaggio sigillato per elling","da dove proviene il messaggio sigillato","chi ha dato il messaggio sigillato per elling"}},["92e95eae"]={q="Perché serve il Messaggio Sigillato per Elling?",a="La scomparsa della Diplomatica è una questione di massima delicatezza e sicurezza di stato. Jorgen non può parlare apertamente per strada, quindi il messaggio funge da introduzione silenziosa e consegna di informazioni a Elling Trias, coinvolgendo Trias nell'indagine senza allertare occhi indiscreti.",al={"perché consegnare il messaggio sigillato","perché elling trias ha bisogno del messaggio","perché il messaggio di jorgen è importante"}}},fp="21,244,16.451.0,39.188.0,53.251.0,14.221.0,40.191.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Messaggio Sigillato per il Guardiano Backus",s="Il Messaggio Sigillato per il Guardiano Backus è un dispaccio confidenziale scritto dal mastro mercante di formaggi e informatore Elling Trias. Indirizzato a un membro della The Night Watch di pattuglia lungo la strada fuori Borgoscuro, richiede un favore personale per raccogliere informazioni sulle attività dei Defias a Boscovespro.",h="Il Messaggio Sigillato per il Guardiano Backus è un dispaccio confidenziale scritto dal mastro mercante di...",kw={"borgoscuro","boscovespro","elling trias","the night watch","messaggio sigillato","the missing diplomat","guardiano backus"},ang={["class:Rogue"]="Il fatto che Trias utilizzi una guardia qualunque come informatore locale è una dimostrazione da manuale di come raccogliere informazioni riservate ben al di fuori delle mura cittadine.",["faction:Alliance"]="La missiva illustra come lo spionaggio informale e i legami personali mantengano uniti i territori sfilacciati dell'Alleanza quando i canali ufficiali falliscono."},sec={{t="Una parola per i Guardiani",b="Quando il messaggio sigillato di Jorgen lo trascina nella caccia al diplomatico scomparso, il mercante di formaggi Elling Trias accetta a malincuore di mettere al lavoro i propri contatti. Redige questa missiva sigillata con la ceralacca per il Guardiano Backus, una guardia della The Night Watch di stanza a Boscovespro. Trias manda un avventuriero a sud attraverso la tetra foresta per consegnarla a mano, sfruttando il suo rapporto di lunga data con Backus per ottenere qualsiasi rapporto sulla presenza di Defias che si aggirano nei pressi di Borgoscuro."},{t="Gli occhi lungimiranti di Trias",b="Sebbene sia apparentemente solo un mercante che vende formaggi pregiati nel Distretto Commerciale, la corrispondenza di Trias con una guardia cittadina a Boscovespro rivela la straordinaria ampiezza della sua rete di informatori. La The Night Watch di Borgoscuro è notoriamente chiusa e diffidente verso gli estranei, sopravvivendo sotto la costante minaccia di non morti e bestie feroci. Eppure, la calorosa accoglienza di Backus al messaggio di Trias dimostra che l'apparentemente umile negoziante riscuote autentica lealtà e rispetto ben oltre le mura di Roccavento."}},faq={{q="Chi ha scritto questo messaggio?",a="Il messaggio è stato scritto da Elling Trias, il proprietario di Trias' Cheese nel Distretto Commerciale di Roccavento, che opera segretamente come abile spia e informatore.",al={"chi ha scritto il messaggio sigillato per il guardiano backus","autore del messaggio","chi consegna il messaggio"}},{q="Perché viene inviato al Guardiano Backus?",a="Il Guardiano Backus è un membro della The Night Watch di Borgoscuro e un contatto fidato di Elling Trias. Trias ha bisogno che condivida qualsiasi avvistamento locale o voce riguardante le attività della Fratellanza dei Defias nei dintorni di Boscovespro.",al={"chi è il guardiano backus","perché inviare a backus","qual è il ruolo di backus"}},{q="Dove si trova il Guardiano Backus?",a="Il Guardiano Backus pattuglia la strada che conduce a nord appena fuori Borgoscuro a Boscovespro, sorvegliando gli accessi boscosi alla cittadina.",al={"dove si trova backus","posizione del guardiano backus","trovare il guardiano backus"}},{q="Cosa succede dopo che il messaggio viene consegnato?",a="Riconoscendo il nome e la fiducia di Trias, Backus abbandona la sua consueta cautela nei confronti degli avventurieri erranti e accetta di aiutare le indagini sulle attività sospette nei boschi circostanti.",al={"cosa dice backus","dopo aver consegnato il messaggio"}}},fx={["8647b8fc"]={q="Cos'è il Messaggio Sigillato per il Guardiano Backus?",a="È un messaggio riservato scritto da Elling Trias, il mastro mercante di formaggi di Roccavento, destinato al Guardiano Backus a Boscovespro. Trias lo manda tramite te per richiedere l'aiuto di Backus nel raccogliere informazioni sull'attività locale della Fratellanza dei Defias come parte dell'indagine in corso sulla Diplomatica scomparsa.",al={"cos'è il messaggio sigillato per il guardiano backus","scopo messaggio sigillato per il guardiano backus","messaggio di trias per backus"}}},fp="29,286,20.438.0,25.489.1,20.167.0,39.203.0,34.140.0,41.187.0"}
P.entries["item:searing-collar"] = {n="Collare Rovente",s="I Collari Roventi sono torque rituali indossati dai membri della setta delle Lame Ardenti nascosti all'interno di Roccia del Teschio a Durotar. Riscaldati per bruciare la carne di chi li indossa, vengono usati dai cultisti per sintonizzarsi con i poteri demoniaci.",h="I Collari Roventi sono torque rituali indossati dai membri della setta delle Lame Ardenti nascosti...",kw={"lame ardenti","demone","durotar","vilmagia","margoz","collare rovente","roccia del teschio"},ang={["class:Warlock"]="Gli stregoni riconoscono i Collari Roventi come condotti grezzi ma efficaci per incanalare la corruzione della vilmagia direttamente nella carne mortale.",["race:Orc"]="Per gli orchi che lottano per liberare il loro popolo dall'eredità della servitù demoniaca, trovare cultisti che usano questi collari alle porte di Durotar è un cupo promemoria del fatto che l'ombra persiste ancora."},sec={{t="Strumenti di corruzione",b="All'interno dell'oscura caverna di Roccia del Teschio, appena a est di Orgrimmar, le Lame Ardenti si radunano per compiere oscuri rituali. Cultisti, neofiti e sgherri della setta indossano Collari Roventi attorno al collo, sottomettendosi volontariamente a un calore bruciante che marchia e ustiona la loro pelle. L'eremita Margoz studia questi crudeli dispositivi, teorizzando che la sensazione di bruciore e gli oscuri incantamenti legati al metallo servano a sintonizzare chi li indossa direttamente con le energie demoniache. L'analisi dei collari rivela che sono un importante condotto di corruzione demoniaca che si insinua nella società degli orchi proprio sotto il naso dell'Orda."}},faq={{q="Che cos'è un Collare Rovente?",a="Un Collare Rovente è una fascia rituale indossata attorno al collo dai cultisti delle Lame Ardenti. Brucia la carne di chi lo indossa e incanala energia demoniaca per sintonizzare il cultista con la magia oscura.",al={"cosa sono i collari roventi","lore del collare rovente","cosa fa il collare"}},{q="Chi indossa questi collari?",a="Sono indossati dai membri della setta delle Lame Ardenti che si nascondono all'interno di Roccia del Teschio, inclusi cultisti, fanatici, sgherri, apprendisti e neofiti.",al={"chi li usa","chi rilascia i collari roventi","collari delle lame ardenti"}},{q="Perché i cultisti si bruciano la carne?",a="Le Lame Ardenti usano il metallo rovente come tramite rituale. Sopportando le bruciature e l'incantamento demoniaco, i cultisti sintonizzano i propri corpi fisici e spiriti con il potere demoniaco.",al={"perché bruciarsi le carni","perché indossare il collare rovente","scopo del collare"}},{q="Chi vuole esaminare i Collari Roventi?",a="Margoz, un investigatore accampato a Durotar, raccoglie i collari per studiarne gli incantamenti e svelare i segreti dietro l'oscura influenza delle Lame Ardenti.",al={"a chi servono i collari roventi","chi sta studiando i collari","collari di margoz"}}},fp="14,216,25.614.0,25.179.0,24.141.0,41.175.0,41.159.0"}
P.entries["item:searing-coral"] = {n="Corallo Rovente",s="Il Corallo Rovente è una sostanza minerale rara e resistente raccolta dai coralli di Iron Coral viventi al largo delle coste delle Wetlands. Molto apprezzato da inventori e fabbri, possiede notevoli proprietà termiche che ne consentono la fusione e la forgiatura in armature protettive.",h="Il Corallo Rovente è una sostanza minerale rara e resistente raccolta dai coralli di Iron Coral viventi al...",kw={"furen barbalunga","iron coral","forgiardente","klockmort spannerspan","porto di menethil","corallo rovente","armatura da guerriero","wetlands"},ang={["class:Warrior"]="Raccogliere il Corallo Rovente è un passo fondamentale per dimostrare la tua dedizione ai maestri forgiatori d'armature di Forgiardente, facendoti guadagnare una corazza forgiata su misura progettata per resistere ai pesanti combattimenti in prima linea.",["profession:Blacksmithing"]="L'integrazione del Corallo Rovente dimostra l'inventiva fusione tra l'ingegno gnomico e la classica lavorazione dei metalli nanica, trasformando i minerali oceanici in piastre temprate."},sec={{t="Una rara risorsa costiera",b="Il Corallo Rovente cresce esclusivamente nelle gelide acque oceaniche lungo la costa a sud di Porto di Menethil, nelle Wetlands. Nonostante prosperi nell'acqua salata fredda, questo singolare organismo marino produce un materiale ricco di minerali capace di resistere a un calore estremo. I raccoglitori sfidano la risacca insidiosa e i predatori costieri delle Wetlands per staccare le formazioni indurite."},{t="Applicazione nella forgiatura",b="Sebbene sia tradizionalmente estraneo alla metallurgia nanica standard, il Corallo Rovente ha attirato l'attenzione delle menti curiose di Forgiardente. Artigiani gnomi come Klockmort Spannerspan adattano le tecniche del veterano forgiatore d'armature Furen Barbalunga, fondendo e martellando il corallo direttamente nelle leghe metalliche per produrre armature leggere ed eccezionalmente resistenti per aspiranti guerrieri."}},faq={{q="Dove cresce il Corallo Rovente?",a="Il Corallo Rovente viene raccolto dal fondale marino lungo la costa a sud di Porto di Menethil, nelle Wetlands. Cresce all'interno di banchi naturali di Iron Coral sommersi sotto le poco profonde acque costiere.",al={"posizione del corallo rovente","dove trovare il corallo rovente","posizione di iron coral"}},{q="Chi vuole il Corallo Rovente a Forgiardente?",a="Klockmort Spannerspan, un artefice gnomo che risiede a Tinkertown a Forgiardente, cerca il Corallo Rovente. Lo usa per sperimentare metodi di forgiatura appresi dal leggendario armaiolo nano Furen Barbalunga.",al={"chi usa il corallo rovente","corallo di klockmort spannerspan","corallo di furen barbalunga"}},{q="Come si può forgiare il corallo in un'armatura?",a="Il Corallo Rovente possiede una struttura insolitamente densa e resistente al calore. Quando viene fuso in una forgia e martellato in leghe metalliche, rinforza la corazza composita, dando vita a un equipaggiamento protettivo eccezionalmente resistente.",al={"forgiatura del corallo","si può fondere il corallo","metallurgia del corallo rovente"}},{q="È pericoloso raccogliere il Corallo Rovente?",a="Il corallo in sé è sicuro da raccogliere una volta individuato, ma per farlo è necessario nuotare nelle acque aperte al largo della costa delle Wetlands, dove si aggirano murloc selvaggi e aggressive bestie acquatiche.",al={"il corallo rovente è caldo","raccolta di iron coral"}}},fx={["3e3d13aa"]={q="Cos'è il Corallo Rovente?",a="Il Corallo Rovente è una rara crescita marina ricca di minerali raccolta dalle formazioni di Iron Coral sotto le onde lungo la costa delle Wetlands, a sud di Porto di Menethil. Nonostante sia un esemplare oceanico, le sue proprietà dense e peculiari gli permettono di essere fuso, martellato e lavorato come metallo da esperti fabbri.",al={"cos'è il corallo rovente","informazioni corallo rovente","lore corallo rovente"}},["1c0d8f00"]={q="Da dove proviene il Corallo Rovente?",a="Il Corallo Rovente è una crescita acquatica naturale piuttosto che un manufatto creato. Cresce esclusivamente in un unico luogo conosciuto al mondo: tra i letti di corallo ferroso sommersi lungo le acque costiere a sud di Porto di Menethil nelle Wetlands.",al={"origine corallo rovente","da dove proviene il corallo rovente","chi ha creato il corallo rovente"}}},fp="13,254,23.353.0,23.367.0,30.193.0,37.206.0,35.213.0,38.188.0"}
P.entries["item:secure-crate"] = {n="Cassa Sicura",s="La Cassa Sicura è un pacco ben sigillato, pieno di pozioni, reagenti alchemici e altre merci varie destinate ai Regni Orientali. Affidata a viaggiatori nelle Barrens, deve essere trasportata fino al vivace porto di Porto Paranco per prendere la marea in partenza.",h="La Cassa Sicura è un pacco ben sigillato, pieno di pozioni, reagenti alchemici e altre merci varie destinate...",kw={"the barrens","baia degli acquanera","pozioni","porto paranco","reagenti","cassa sicura","spedizione","wharfmaster dizzywig"},ang={["faction:Horde"]="Gestire le spedizioni attraverso Porto Paranco ricorda ai viaggiatori dell'Orda i collegamenti commerciali neutrali e vitali che i porti dei goblin offrono tra Kalimdor e i Regni Orientali.",["profession:Herbalism"]="L'imballaggio sicuro dei reagenti sottolinea quanto gli alchimisti e gli erboristi d'oltremare dipendano dalle rotte commerciali della frontiera per scambiarsi materie prime."},sec={{t="Il carico di un corriere",b="Le rotte commerciali tra Kalimdor e i Regni Orientali si basano su una fragile catena di corrieri, carovane nel deserto e navi mercantili dei goblin. Quando le carovane di terra attraverso le Barrens perdono le loro partenze programmate, carichi fragili come questa Cassa Sicura devono essere trasportati da viaggiatori indipendenti fino alla costa. All'interno si trovano merci alchemiche, pozioni e vari reagenti destinati ad associati oltre il Grande Mare. Data la natura delicata e preziosa del contenuto, la cassa è sigillata saldamente per garantire che sopravviva sia ai sentieri aridi delle Barrens sia agli spruzzi salmastri della traversata oceanica."},{t="Attraverso Porto Paranco",b="La destinazione della tratta terrestre della cassa è il molo di Porto Paranco, sorvegliato da Wharfmaster Dizzywig. Il porto di Porto Paranco funge da principale imbuto neutrale attraverso il quale le provviste attraversano il mare verso destinazioni come la Baia degli Acquanera. Operando sotto il registro del Cartello degli Spargifumo, Dizzywig si assicura che sia i piccoli pacchi sia le merci pesanti siano adeguatamente registrati nel manifesto e caricati a bordo della prossima nave in partenza, fornendo un vitale collegamento commerciale tra il Vecchio Mondo e la frontiera."}},faq={{q="Cosa c'è dentro la Cassa Sicura?",a="La cassa contiene un delicato assortimento di pozioni, reagenti alchemici e altre provviste destinate ad associati nei Regni Orientali.",al={"contenuto della cassa","cosa c'è nella cassa","oggetti della cassa sicura"}},{q="Dove viene inviata la cassa?",a="A piedi, deve essere consegnata a Wharfmaster Dizzywig sui moli di Porto Paranco. Da lì, Dizzywig la imbarca su una nave mercantile in rotta attraverso il mare verso la Baia degli Acquanera nel Vecchio Mondo.",al={"destinazione della cassa","dove va la cassa sicura"}},{q="Perché la cassa è stata affidata a un avventuriero invece che a una carovana?",a="Il mittente non aveva il tempo di recarsi personalmente a Porto Paranco e la carovana commerciale programmata era già partita, rendendo necessario assumere un corriere per sfruttare la marea.",al={"perché ho la cassa","carovana persa"}},{q="Chi prende la cassa a Porto Paranco?",a="Wharfmaster Dizzywig riceve la cassa sui moli di Porto Paranco, annotandola nel suo registro di spedizione prima di stivarla a bordo della prossima nave che salperà con la marea.",al={"chi riceve la cassa","cassa di dizzywig"}}},fx={e5dd21c1={q="Cos'è la Cassa Sicura?",a="La Cassa Sicura è una spedizione imballata ermeticamente contenente un assortimento di pozioni, reagenti e altre provviste di valore. È imballata in modo sicuro affinché il suo delicato contenuto sopravviva a un lungo viaggio su carovana e nave attraverso il mare fino ai Regni Orientali.",al={"cos'è la cassa sicura","storia cassa sicura","informazioni cassa sicura"}},["4df2d75b"]={q="Da dove proviene la Cassa Sicura e chi l'ha realizzata?",a="La cassa ha origine nelle The Barrens, imballata e sigillata da uno speziale o uno studioso che aveva urgente bisogno di esportare le proprie provviste alchemiche. Non avendo il tempo di recarsi personalmente alla costa dopo aver perso la carovana commerciale regolare, ha preparato la cassa affinché venisse trasportata a mano direttamente al porto di Porto Paranco.",al={"chi ha creato la cassa sicura","da dove viene la cassa sicura","origine cassa sicura"}},b7ad6ca4={q="Perché la Cassa Sicura è ricercata?",a="Alcuni associati nei Regni Orientali, al di là del mare, attendono questi reagenti e pozioni essenziali. Il Wharfmaster Dizzywig a Porto Paranco deve consegnare la cassa ai suoi moli per poterla registrare sul suo libro mastro commerciale e stivarla a bordo della prossima nave in partenza per Baia degli Acquanera.",al={"perché cercare la cassa sicura","chi ha bisogno della cassa sicura","perché dizzywig vuole la cassa sicura"}}},fp="12,268,17.595.0,27.488.0,32.138.0,30.191.0,62.176.0,31.159.0"}
P.entries["item:senir-s-report"] = {n="Rapporti di Senir",s="Rapporti di Senir è un documento inviato e redatto dal Montanaro Senir Barbabianca che illustra nel dettaglio la minaccia dei troll Frostmane a Dun Morogh. Riporta le scoperte commissionate sotto direttiva reale ed è destinato al Senatore Barin Pietrarossa a Forgiardente.",h="Rapporti di Senir è un documento inviato e redatto dal Montanaro Senir Barbabianca che illustra nel dettaglio...",kw={"barin pietrarossa","frostmane","forgiardente","magni barbabronzea","senato","senir barbabianca","rapporti di senir","i rapporti"},ang={["faction:Alliance"]="Occuparsi di Rapporti di Senir contribuisce alla difesa di Dun Morogh mentre si naviga tra le spinose politiche interne della classe dirigente di Forgiardente.",["race:Dwarf"]="Portare Rapporti di Senir mette in luce la netta divisione politica tra i decreti reali di Re Magni Barbabronzea e l'autorità tradizionale rivendicata dal Senato a Forgiardente."},sec={{t="Una direttiva reale",b="Redatto dopo missioni di ricognizione contro i troll Frostmane rintanati nei dirupi di Dun Morogh, questo rapporto sul campo contiene le osservazioni del montanaro destinate al Senato nanico. Senir Barbabianca, di stanza nelle fredde pendici, ha redatto il documento e vi ha allegato il Rapporto di Grelin, suo fratello, sulla Valle Crestafredda, in cui si dichiara che Grelin ha agito con l'approvazione di Re Magni Barbabronzea. Senir incarica gli avventurieri di portare le scoperte direttamente al Senatore Barin Pietrarossa nell'High Seat di Forgiardente, raccomandando con cautela ai corrieri di omettere quanto aiuto esterno gli sia servito per compilarlo."},{t="Attriti nell'High Seat",b="Al momento della consegna alla corte reale, il documento suscita un immediato clamore. Leggendo il resoconto di Barbabianca, il Senatore Barin Pietrarossa è indignato non solo per i contenuti riguardanti la minaccia dei troll, ma anche per l'autorità esecutiva impresavi. Il fatto che Magni abbia scavalcato la supervisione legislativa e che Barbabianca abbia agito in base a ordini reali incontrollati alimenta un risentimento a lungo covato all'interno del Senato nanico, illustrando la tensione politica tra il governo risoluto di Re Magni e i senatori indignati che esigono il controllo procedurale."}},faq={{q="Cos'è Rapporti di Senir?",a="È un dispaccio scritto ufficiale redatto dal Montanaro Senir Barbabianca che riassume le sue indagini sui troll Frostmane a Dun Morogh, scritto per essere consegnato direttamente al Senato nanico a Forgiardente.",al={"rapporti di senir","cos'è questo rapporto","il rapporto"}},{q="Chi dovrebbe ricevere il rapporto?",a="Il rapporto è indirizzato al Senatore Barin Pietrarossa, un arcigno politico nanico situato vicino al trono di Re Magni Barbabronzea nell'High Seat di Forgiardente.",al={"chi riceve il rapporto","a chi consegno il rapporto","destinatario del rapporto"}},{q="Perché il Senatore Pietrarossa si arrabbia così tanto quando lo legge?",a="Il Senatore Pietrarossa è furioso perché il rapporto allegato del fratello di Senir, Grelin Barbabianca, rivela che Grelin ha agito sotto l'autorità di Re Magni anziché consultare il Senato nanico. Pietrarossa mal digerisce il fatto che la corona intraprenda azioni unilaterali su questioni di difesa senza l'approvazione senatoriale.",al={"perché barin è arrabbiato","perché il senatore è arrabbiato","reazione di pietrarossa"}},{q="Perché Senir ti chiede di non menzionare di averlo aiutato?",a="Senir Barbabianca preferisce che i suoi superiori credano che abbia svolto il pericoloso lavoro di ricognizione sulle colline innevate del tutto da solo, volendo proteggere la propria reputazione di montanaro diligente e capace.",al={"perché tacere","segreto di senir","merito di senir"}}},fx={["078e838e"]={q="Da dove provengono i Rapporti di Senir e chi li ha scritti?",a="Senir Barbabianca ha redatto questo dispaccio di persona a Dun Morogh dopo aver esplorato le minacce locali dei troll Mantogelido e aver ottenuto aiuto per gestire il Covo dei Mantogelido. Insieme alle sue scoperte, include il Rapporto di Grelin sulla Valle Crestafredda, che Grelin ha scritto sotto la sanzione di Re Magni Barbabronzea, e trasporta entrambi dai confini innevati fino alle grandi sale della capitale.",al={"chi ha scritto i rapporti di senir","da dove vengono i rapporti di senir","autore dei rapporti di senir"}},e0c0da53={q="Perché qualcuno vuole i Rapporti di Senir?",a="Il Senatore Barin Pietrarossa e il Senato di Forgiardente richiedono valutazioni ufficiali sul campo per seguire gli sviluppi regionali e le azioni militari a Dun Morogh. Tuttavia, poiché questo specifico dispaccio afferma l'autorità unilaterale di Re Magni sulle manovre locali, ha un peso politico notevole, informando il Senato di azioni della corona che ritengono aggirino la loro supervisione.",al={"perché consegnare i rapporti di senir","perché pietrarossa ha bisogno dei rapporti di senir","scopo dei rapporti di senir"}}},fp="14,242,17.601.0,25.516.1,23.216.0,38.153.0,56.296.1,50.201.0"}
P.entries["item:serena-s-head"] = {n="Testa di Serena",s="La Testa di Serena è il macabro trofeo strappato alla matriarca delle arpie dei Colli Aridi nelle Barrens settentrionali. Darsok Dagalesta di Crocevia l'ha pretesa come prova della sua fine, con l'intenzione di esporla sui carri di rifornimento dell'Orda come severo deterrente contro ulteriori incursioni aeree.",h="La Testa di Serena è il macabro trofeo strappato alla matriarca delle arpie dei Colli Aridi nelle Barrens...",kw={"crocevia","darsok dagalesta","colli aridi","arpia","rexxar","serena bloodfeather","testa di serena","witchwing"},ang={["class:Rogue"]="Darsok Dagalesta apprezza il lavoro pulito e spietato, lodando i mercenari capaci di scivolare dietro i posatoi nemici e abbattere un bersaglio senza esitare.",["faction:Horde"]="Le carovane sono la linfa vitale che collega Durotar a Mulgore e agli avamposti remoti; montare la testa di Serena sui carri di rifornimento trasmette un inequivocabile messaggio sul dominio dell'Orda sulle lande selvagge."},sec={{t="Un avvertimento sulla strada",b="Le arpie Witchwing dei Colli Aridi tormentano da tempo i commerci che attraversano le Barrens settentrionali, ma sotto la guida di Serena Bloodfeather i loro assalti sono diventati particolarmente spietati. Le sue incursioni contro le linee di rifornimento dell'Orda erano guidate da una vendetta personale per sua sorella, caduta per mano del signore delle bestie Rexxar. Per spezzare definitivamente il morale dello stormo, il ladro orco Darsok Dagalesta ha ordinato di dare la caccia a Serena. Piuttosto che lasciare che la sua morte passasse inosservata, ha preteso la sua testa mozzata per poterla montare sulla prossima carovana in partenza, facendone un chiaro e sanguinoso monito per qualsiasi arpia in osservazione dai dirupi sovrastanti."}},faq={{q="Perché Darsok Dagalesta vuole la testa di Serena?",a="Darsok vuole una prova inconfutabile della morte di Serena Bloodfeather, e intende montare la sua testa sopra una carovana di rifornimenti dell'Orda. Spera che l'esposizione dei resti della matriarca terrorizzi le superstiti arpie Witchwing e le scoraggi dall'attaccare i viaggiatori.",al={"perché prendere la testa di serena","darsok testa serena","cosa fa darsok con la testa"}},{q="Perché Serena Bloodfeather attaccava le carovane dell'Orda?",a="Gli attacchi di Serena erano motivati da una vendetta contro l'Orda. Sua sorella, Bloodfeather, era stata uccisa dal campione mezzorco Rexxar, e Serena cercava vendetta colpendo le linee di rifornimento e i viandanti dell'Orda attraverso le Barrens.",al={"perché serena attaccava le carovane","movente di serena bloodfeather","attacchi arpie the barrens"}},{q="Da dove proviene questo trofeo?",a="Viene mozzato da Serena Bloodfeather, la matriarca che si annida tra i dirupi dei Colli Aridi nell'estrema parte nord-occidentale di The Barrens.",al={"dove trovare la testa di serena","posizione serena bloodfeather","come ottenere la testa di serena"}}},fx={["29e11954"]={q="Cos'è la Testa di Serena?",a="La Testa di Serena è la testa mozzata di Serena Bloodfeather, la vendicativa matriarca dello stormo di arpie Witchwing nelle The Barrens settentrionali. Prenderla segna la fine delle sue incursioni contro le rotte di rifornimento di Crossroads e serve come prova inconfutabile che la minaccia delle arpie è stata colpita alla radice.",al={"cos'è la testa di serena","testa di serena bloodfeather","oggetto testa di serena"}}},fp="13,282,21.609.1,47.263.0,53.227.1,33.145.0"}
P.entries["item:serpentbloom"] = {n="Bocciolo di Serpente",s="Il Bocciolo di Serpente è una rara erba sotterranea che cresce solo nelle oscure profondità della Caverna dei Lamenti. Le sue potenti proprietà naturali hanno suscitato il vivo interesse della Royal Apothecary Society dei Forsaken.",h="Il Bocciolo di Serpente è una rara erba sotterranea che cresce solo nelle oscure profondità della Caverna dei...",kw={"apothecary zamah","the barrens","erba","royal apothecary society","bocciolo di serpente","picco del tuono","caverna dei lamenti"},ang={["profession:Herbalism"]="Gli erboristi esperti possiedono lo sguardo attento necessario a scovare queste rare fioriture cavernose là dove gli altri vedono solo pietra umida.",["race:Undead"]="Procurare il Bocciolo di Serpente aiuta direttamente Apothecary Zamah e la Royal Apothecary Society mentre esplorano terre straniere in cerca di risorse botaniche per rafforzare i Forsaken."},sec={{t="Una rara flora sotterranea",b="Il Bocciolo di Serpente cresce esclusivamente all'interno dei cunicoli umidi e ombrosi della Caverna dei Lamenti sotto The Barrens. Radicata in un ecosistema distorto dalle energie incontrollate del Sogno di Smeraldo, la pianta prospera lontana dalla luce solare e spesso ospita serpenti velenosi che nidificano tra i suoi steli. Poiché il complesso di caverne è invaso da bestie ostili e druidi corrotti, pochi tra coloro che si avventurano all'interno riescono a tornare con campioni utilizzabili."},{t="L'interesse degli speziali",b="Operando dalle Pozze delle Visioni sotto Picco del Tuono, Apothecary Zamah raccoglie il Bocciolo di Serpente per conto della Royal Apothecary Society di Undercity. I Forsaken cercano continuamente vegetazione virulenta, insolita e chimicamente potente in tutta Kalimdor per alimentare le loro ricerche a beneficio della Dark Lady. Zamah ritiene che raccogliere il Bocciolo di Serpente in quantità significative potrebbe portare a preziose scoperte per l'alchimia dei Forsaken."}},faq={{q="Dove cresce il Bocciolo di Serpente?",a="Il Bocciolo di Serpente si trova solo nelle profondità della Caverna dei Lamenti, un labirintico sistema di caverne situato a sud-ovest di Crocevia in The Barrens. Cresce aggrappato al terreno negli anfratti bui e umidi della grotta.",al={"dove trovare il bocciolo di serpente","posizione del bocciolo di serpente","erba della caverna dei lamenti"}},{q="Perché la Royal Apothecary Society vuole il Bocciolo di Serpente?",a="Apothecary Zamah, un'agente della Royal Apothecary Society di stanza a Picco del Tuono, cerca la pianta a fini di ricerca. I Forsaken esaminano la flora insolita e pericolosa proveniente da tutta Kalimdor per sviluppare nuovi intrugli chimici e supportare gli obiettivi più ampi di Sylvanas Ventolesto.",al={"chi vuole il bocciolo di serpente","erba di apothecary zamah","perché raccogliere il bocciolo di serpente"}},{q="Perché la raccolta del Bocciolo di Serpente è pericolosa?",a="Oltre ai pericoli generali della Caverna dei Lamenti — infestata da raptor, crocolisk e druidi corrotti — l'erba stessa offre frequentemente riparo a serpenti velenosi. Disturbare la pianta induce spesso questi serpenti nascosti ad attaccare.",al={"pericolo del bocciolo di serpente","serpente del bocciolo di serpente"}},{q="Gli erboristi possono trovare il Bocciolo di Serpente più facilmente?",a="Sì. Coloro che sono addestrati nell'erboristeria hanno una naturale predisposizione a individuare la crescita vegetale e possono seguire le tracce delle chiazze di Bocciolo di Serpente negli angoli oscuri del pavimento della caverna.",al={"trovare il bocciolo di serpente con erboristeria","tracciare il bocciolo di serpente"}}},fx={bee22cd2={q="Cos'è il Bocciolo di Serpente?",a="Il Bocciolo di Serpente è un esemplare estremamente raro di flora nativa dei recessi più oscuri della Caverna dei Lamenti nelle The Barrens. Radicata all'interno delle umide profondità sotterranee, quest'erba insolita si distingue per le sue qualità serpentine: disturbarla spesso attira serpenti aggressivi annidati attorno alle sue radici.",al={"cos'è il bocciolo di serpente","erba bocciolo di serpente","info bocciolo di serpente"}}},fp="12,206,25.409.0,19.424.0,29.205.0,56.276.0,41.232.0,45.164.0"}
P.entries["item:sethir-s-journal"] = {n="Diario di Sethir",s="Il Diario di Sethir è un registro personale portato dall'elusivo satiro Sethir the Ancient a Teldrassil. Recuperato tramite l'occultamento, il suo contenuto conferma l'allarmante diffusione della corruzione dalla terraferma di Kalimdor all'Albero del Mondo.",h="Il Diario di Sethir è un registro personale portato dall'elusivo satiro Sethir the Ancient a Teldrassil.",kw={"darkshore","destiny calls","radura dell'oracolo","satiro","sethir the ancient","diario di sethir","syurna","teldrassil"},ang={["class:Rogue"]="Il recupero del diario dimostra che l'infiltrazione furtiva e il borseggio possono scoprire informazioni critiche laddove i guerrieri in prima linea e i diplomatici hanno fallito del tutto.",["race:NightElf"]="Il diario fornisce prove angoscianti del fatto che Teldrassil non sia immune all'antica corruzione demoniaca che si insinua attraverso la terraferma di Kalimdor."},sec={{t="Indizio sulla Corruzione",b="Teldrassil fu innalzato nella speranza di riconquistare l'immortalità elfica, ma una malattia invisibile ha sempre più messo radici tra i suoi rami. Syurna a Darnassus sospettava che Sethir the Ancient, un satiro solitario in agguato su un ramo periferico vicino alla Radura dell'Oracolo, avesse delle risposte. Quando la diplomazia diretta e la forza aperta portarono solo alla morte dei ricognitori del passato, un silenzioso borseggio permise di ottenere il Diario di Sethir. Gli scritti rivelano una cupa verità: la misteriosa piaga che avvelena i boschi e le acque oltre il mare a Darkshore si è estesa a Teldrassil stessa."}},faq={{q="Cos'è il Diario di Sethir?",a="È un diario portato da Sethir the Ancient, un satiro ostile che vive lungo i rami esterni vicino alla Radura dell'Oracolo a Teldrassil. Contiene note che descrivono in dettaglio la crescente corruzione che affligge la regione.",al={"cos'è il diario di sethir","lore diario di sethir","a chi appartiene il diario di sethir"}},{q="Come si ottiene il diario?",a="Poiché i precedenti tentativi di negoziare o combattere contro Sethir si sono conclusi con il fallimento e la morte, il diario deve essere sottratto direttamente dalle sue bisacce usando l'occultamento.",al={"come ottenere il diario di sethir","dove trovare il diario di sethir","borseggiare sethir"}},{q="Cosa rivela il diario?",a="Secondo l'istruttrice dei ladri Syurna, il diario dimostra che la strana malattia che devasta le foreste e le acque di Darkshore si è insinuata con successo a Teldrassil.",al={"cosa dice il diario di sethir","cosa c'è nel diario di sethir"}},{q="Chi è Sethir the Ancient?",a="Sethir è un satiro solitario che si annida su un ramo isolato lungo i confini della Radura dell'Oracolo. Noto per trattare violentemente con gli intrusi, possiede informazioni vitali sulla strisciante corruzione dell'Albero del Mondo.",al={"chi è sethir","sethir the ancient"}}},fx={["3d18c972"]={q="Da dove proviene il Diario di Sethir e chi lo ha scritto?",a="Il diario appartiene a Sethir the Ancient, un satiro ostile in agguato su un alto ramo ai margini della Radura dell'Oracolo a Teldrassil. Portando con sé i suoi scritti e registri personali tra i suoi averi, ha tenuto il diario finché dei furfanti a Darnassus non hanno cercato di sottrarglielo silenziosamente per scoprire quale corruzione si stia diffondendo attraverso l'albero del mondo.",al={"chi ha scritto il diario di sethir","origine del diario di sethir","origine diario sethir"}}},fp="16,226,19.554.1,25.205.0,28.154.0,29.169.0,26.217.0"}
P.entries["item:sevren-s-orders"] = {n="Ordini di Sevren",s="Gli Ordini di Sevren sono dispacci scritti redatti dal Magistrato Sevren di Brill. Essi ordinano a un collaudato agente dei Forsaken di presentarsi da Bethor Scheggiafredda, un formidabile mago di stanza nel Magic Quarter di Undercity.",h="Gli Ordini di Sevren sono dispacci scritti redatti dal Magistrato Sevren di Brill.",kw={"bethor scheggiafredda","brill","magic quarter","magistrato sevren","lich prodigo","ordini di sevren","undercity"},ang={["class:Mage"]="Per i praticanti dell'arcano, la consegna di questi ordini concede un'udienza con Bethor Scheggiafredda, uno dei più eminenti incantatori del regno dei Forsaken.",["race:Undead"]="Portare il sigillo di Sevren segna la transizione di un operativo dal servizio locale a Tirisfal all'aiuto diretto dell'élite arcana di Undercity."},sec={{t="Convocazione nella capitale",b="Mentre i Forsaken consolidano la propria presa sulle Rovine di Lordaeron, abili agenti che hanno dimostrato il proprio valore contro la Scourge nelle Radure di Tirisfal vengono convocati a sud nella capitale. Emessi dal Magistrato Sevren, questi ordini scritti fungono da presentazione ufficiale e credenziali per Bethor Scheggiafredda, uno dei principali praticanti dell'arcano della Dama Oscura nel Magic Quarter. Sebbene Sevren sappia poco al di là del fatto che l'incarico prevede di contattare un lich errante, la convocazione porta con sé l'assoluta autorità degli alti maghi di Undercity."}},faq={{q="Chi ha scritto questi ordini?",a="Il Magistrato Sevren, il sovrintendente dei Forsaken che amministra gli affari della cittadina di Brill nelle Radure di Tirisfal, ha redatto gli ordini.",al={"autore degli ordini di sevren","chi è sevren","chi dà gli ordini di sevren"}},{q="Chi è destinato a ricevere questi ordini?",a="Sono indirizzati a Bethor Scheggiafredda, un mago dei Forsaken di alto rango situato nel Magic Quarter di Undercity.",al={"chi riceve gli ordini","dove porto gli ordini di sevren","chi è bethor scheggiafredda"}},{q="Qual è la missione menzionata negli ordini?",a="La missione prevede il reclutamento di un lich ribelle per aiutare i Forsaken, un compito pericoloso che richiede un agente che si sia già dimostrato capace contro la Scourge.",al={"qual è la missione del lich","cosa vuole bethor","missione del lich prodigo"}},{q="Perché sono stato scelto per consegnarli?",a="Bethor ha richiesto un operativo di provata capacità contro la Scourge. Il Magistrato Sevren ha ritenuto i tuoi sforzi nelle Radure di Tirisfal sufficienti per gestire il pericoloso compito di Bethor.",al={"perché io","perché sevren ha scelto me"}}},fx={["59d8f724"]={q="Cosa sono gli Ordini di Sevren?",a="Gli Ordini di Sevren sono un dispaccio ufficiale scritto dal Magistrato Sevren di Brill. Fungono da credenziali formali, identificandoti come un agente di provato valore che ha combattuto efficacemente contro il Flagello ed è pronto a intraprendere un incarico delicato.",al={"cosa sono gli ordini di sevren","oggetto ordini di sevren","cos'è questo documento"}},["680dc8a1"]={q="Perché Bethor Scheggiafredda vuole gli Ordini di Sevren?",a="Bethor Scheggiafredda, un importante mago nel Magic Quarter di Undercity, ha chiesto che Sevren fornisca un agente capace di gestire un compito pericoloso che coinvolge un lich rinnegato. Presentare questi ordini dimostra che sei l'operativo scelto da Sevren e che la tua interruzione del potente mago è giustificata.",al={"perché consegnare gli ordini di sevren","perché bethor vuole gli ordini","chi ha bisogno degli ordini di sevren"}}},fp="15,204,22.555.0,23.127.0,40.114.0,44.154.0,33.174.0"}
P.entries["item:shadowhide-pendant"] = {n="Pendente dei Mantombroso",s="I Pendenti dei Mantombroso sono grezzi amuleti ornamentali portati dagli gnoll Mantombroso che si aggirano per le Montagne Crestarossa. Raccolti come prova legale dell'esecuzione di una taglia, testimoniano che i difensori locali hanno applicato la legge di Borgolago contro gli gnoll che collaborano con il mago rinnegato Morganth.",h="I Pendenti dei Mantombroso sono grezzi amuleti ornamentali portati dagli gnoll Mantombroso che si aggirano...",kw={"bailiff conacher","gnoll","borgolago","lieutenant fangore","morganth","pendente","crestarossa","mantombroso","solomon's law"},ang={["class:Warrior"]="Gli gnoll Mantombroso sono avversari aggressivi e fisicamente imponenti, i cui ranghi mettono alla prova i difensori di prima linea che proteggono le strade verso Borgolago.",["faction:Alliance"]="Gli insediamenti di frontiera come Borgolago ricevono scarsi aiuti dalla guarnigione di Roccavento, costringendo i magistrati locali a fare affidamento sui leali avventurieri dell'Alleanza per far rispettare la legge del regno."},sec={{t="Simboli di sfida",b="Portati da guerrieri, bruti e incantatori del clan Mantombroso, questi pendenti fungono da grezzi totem personali o da insegne di rango. Nel profondo delle colline di Crestarossa, il clan si è radunato sotto il Lieutenant Fangore ed è caduto sotto l'influenza di Morganth, un manipolatore rinnegato dell'Arcano. Per gli abitanti di Borgolago, questi amuleti non sono semplici monili primitivi; sono i segni distintivi di una minaccia organizzata che perseguita gli insediamenti della regione per conto di un nemico della Corona."},{t="La giustizia di Borgolago",b="Sotto l'autorità del Magistrato Solomon e le leggi di Roccavento, aiutare attivamente un noto criminale del regno comporta la pena di morte. Privo di sufficienti rinforzi reali, Bailiff Conacher nel Lakeshire Town Hall fa affidamento su avventurieri indipendenti per mantenere la pace. Presentare dieci Pendenti dei Mantombroso fornisce la prova tangibile che gli gnoll che obbediscono agli ordini di Morganth hanno affrontato la giustizia della frontiera."}},faq={{q="Che cos'è un Pendente dei Mantombroso?",a="È un amuleto indossato dai membri del clan di gnoll Mantombroso nelle Montagne Crestarossa. Il magistrato locale li accetta come prova che gli gnoll invasori sono stati uccisi in difesa della cittadina.",al={"cosa sono i pendenti dei mantombroso","storia del pendente dei mantombroso","pendente di crestarossa"}},{q="Perché Bailiff Conacher vuole questi pendenti?",a="Bailiff Conacher li raccoglie come prova dell'applicazione delle taglie secondo la Solomon's Law. Poiché il clan Mantombroso collabora con il mago rinnegato Morganth per terrorizzare la popolazione locale, la cittadina considera ogni gnoll affiliato un nemico passibile di pena capitale.",al={"perché raccogliere pendenti","taglia di bailiff conacher","missione di conacher"}},{q="Chi porta questi pendenti?",a="Vengono portati a ogni livello della gerarchia del clan Mantombroso, dai comuni briganti, bruti e gnoll rabbiosi fino a figure come Rohh the Silent e il Lieutenant Fangore nelle terre selvagge di Crestarossa.",al={"chi rilascia i pendenti","quali gnoll hanno i pendenti","fonte del pendente dei mantombroso"}},{q="Qual è il rapporto tra il clan Mantombroso e Morganth?",a="Morganth, un praticante rinnegato dell'Arcano in agguato sulle pendici orientali, ha usato i suoi oscuri poteri per piegare gli gnoll Mantombroso al proprio volere, impiegandoli come fanti per terrorizzare Borgolago e attuare i suoi piani.",al={"gnoll e morganth","perché gli gnoll collaborano con morganth","mantombroso morganth"}}},fp="18,282,18.485.0,19.409.0,29.196.0,46.276.0,27.193.0,66.230.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Talismano Sciamanico Vudù",s="Il Talismano Sciamanico Vudù è un oscuro monile rituale trasportato dagli sciamani furbolg Gnarlpine nelle profondità dell'Eremo di Ban'ethil. Emanando un'aura nefasta, questo talismano canalizza una magia innaturale capace di recidere lo spirito di un druido dormiente dalla sua carne mortale.",h="Il Talismano Sciamanico Vudù è un oscuro monile rituale trasportato dagli sciamani furbolg Gnarlpine nelle...",kw={"eremo di ban'ethil","sogno di smeraldo","furbolg","pino nodoso","oben malartiglio","talismano sciamanico vudù","druido addormentato","teldrassil"},ang={["class:Druid"]="Per un druido, il talismano rappresenta un'orribile perversione del sacro sonno, poiché usa la magia oscura per intrappolare il sognatore nel Sogno di Smeraldo mentre manovra come una marionetta la sua forma fisica.",["race:NightElf"]="La scoperta di questi talismani all'interno dell'Eremo di Ban'ethil rivela quanto profondamente gli Gnarlpine abbiano profanato uno dei luoghi di riposo comune più sacri dei kaldorei."},sec={{t="Una magia perversa",b="La tribù Gnarlpine di Teldrassil è caduta nella follia e nella corruzione, ma all'interno dell'Eremo di Ban'ethil i suoi sciamani brandiscono poteri che vanno ben oltre la normale stregoneria delle terre selvagge. Utilizzando questi strani talismani vudù, gli sciamani hanno scoperto un modo per strappare la coscienza di un druido dormiente dal regno mortale e intrappolarla inerme nel Sogno di Smeraldo. Recidendo l'anima dal suo involucro, i furbolg sono in grado di animare la forma fisica vuota, trasformando venerabili protettori elfi della notte in guardiani privi di senno che massacrano chiunque si avventuri nei tumuli."},{t="Spezzare la maledizione",b="Quando il druido Oben Malartiglio cadde vittima di questo rituale, il suo spirito si ritrovò intrappolato nel Sogno mentre il suo corpo animato terrorizzava le profondità dei tumuli. Allungandosi oltre il velo, Oben incaricò gli avventurieri di uccidere gli sciamani Gnarlpine e recuperare uno dei loro talismani vudù. Esaminando il vile incantamento infuso nel monile, Oben sperava di decifrare l'arte contorta dei furbolg e trovare un modo per spezzare The Binding sulla sua carne rubata."}},faq={{q="A cosa serve il Talismano Sciamanico Vudù?",a="Gli sciamani Gnarlpine usano il talismano per compiere un potente rituale che recide lo spirito di un druido dormiente dal suo corpo fisico, intrappolando la mente nel Sogno di Smeraldo e animando la carne vuota per attaccare gli intrusi.",al={"scopo del talismano vudù","cosa fa il talismano","uso del talismano sciamanico"}},{q="Chi trasporta questi talismani?",a="I talismani sono trasportati dagli sciamani Gnarlpine che abitano le tortuose profondità dell'Eremo di Ban'ethil a Teldrassil.",al={"chi rilascia il talismano","dove trovare il talismano sciamanico vudù","talismano sciamano pino nodoso"}},{q="Perché Oben Malartiglio ne ha bisogno?",a="Oben Malartiglio è attualmente intrappolato nel Sogno di Smeraldo mentre il suo corpo animato semina il caos. Ha bisogno di ispezionare l'aura nefasta del talismano e la sua trama magica per capire come spezzare l'incantamento dei furbolg.",al={"perché oben lo vuole","talismano di oben malartiglio","oggetto del druido addormentato"}},{q="Perché i furbolg possiedono la magia vudù?",a="Mentre i tradizionali sciamani furbolg venerano gli spiriti della natura e gli elementi, la corruzione che stringe Teldrassil ha spinto gli Gnarlpine a praticare magie oscure e perverse. Il talismano possiede un'aura innaturale e nefasta, del tutto diversa dal tradizionale culto della natura.",al={"perché i furbolg usano il vudù","storia del vudù dei furbolg"}}},fx={["6bf5e1a6"]={q="Cos'è il Talismano Sciamanico Vudù?",a="È un talismano incantato dei furbolg brandito dagli sciamani Gnarlpine corrotti all'interno dell'Eremo di Ban'ethil. Emanando una vile aura magica, il talismano imbriglia oscuri rituali capaci di separare lo spirito di un druido Elfo della Notte addormentato dalla sua forma fisica, lasciando lo spirito indifeso mentre i furbolg animano e controllano il corpo dormiente.",al={"cos'è il talismano sciamanico vudù","storia talismano vudù","cosa sono questi talismani"}}},fp="19,260,17.570.0,20.458.1,41.215.0,25.117.0,32.213.0,34.254.0"}
P.entries["item:shard-of-water"] = {n="Scheggia d'Acqua",s="La Scheggia d'Acqua è un residuo elementale raccolto durante la comunione di uno sciamano con gli spiriti dell'acqua. Consegnata a Islen Scruta Lagune lungo la costa di The Barrens, funge da prova tangibile che un iniziato ha compreso la natura vivificante dell'acqua e ne ha sconfitto la corruzione.",h="La Scheggia d'Acqua è un residuo elementale raccolto durante la comunione di uno sciamano con gli spiriti...",kw={"the barrens","call of water","islen scruta lagune","scheggia d'acqua","selva pinargento","totem dell'acqua"},ang={["class:Shaman"]="Ottenere questa scheggia segna il passo finale nella sintonia con gli spiriti dell'acqua, concludendo il lungo viaggio per ottenere il tuo Totem dell'Acqua."},sec={{t="Simbolo di Purezza Elementale",b="Per gli sciamani in cerca di maestria sugli elementi, entrare in comunione con l'acqua richiede una profonda comprensione dell'equilibrio, della vita e della preservazione. Nelle prove di Call of Water, gli sciamani sono guidati ad affrontare la corruzione infiltratasi nelle sorgenti naturali, viaggiando persino attraverso il mare verso terre contaminate come Selva Pinargento. La Scheggia d'Acqua viene conferita dopo aver purificato queste acque corrotte. Riportare questo simbolo di cristallo a Islen Scruta Lagune sulle rive rocciose di The Barrens dimostra il valore dell'iniziato, fornendo la chiave finale necessaria per forgiare il proprio Totem dell'Acqua."}},faq={{q="A cosa serve la Scheggia d'Acqua?",a="Serve come prova della tua prova per Islen Scruta Lagune lungo la costa orientale di The Barrens. Presentarle la scheggia completa la tua comunione con l'acqua e ti fa ottenere il tuo Totem dell'Acqua.",al={"scopo scheggia d'acqua","a cosa serve la scheggia d'acqua","perché ho la scheggia d'acqua"}},{q="Chi richiede questo oggetto?",a="Islen Scruta Lagune, una sciamana che dimora in una capanna a sud di Porto Paranco lungo la Costa dei Mercanti, richiede la scheggia per confermare che hai purificato con successo l'acqua contaminata.",al={"chi vuole la scheggia d'acqua","dove consegnare la scheggia d'acqua","scheggia islen scruta lagune"}},{q="Perché la prova è stata ambientata fino a Selva Pinargento?",a="L'acqua rappresenta la guarigione e la preservazione, eppure la corruzione arresta la vita. Le acque contaminate di Selva Pinargento offrono una dura prova dell'abilità di uno sciamano nel ripristinare l'armonia elementale in mezzo a una profonda decadenza.",al={"missione acqua selva pinargento","perché selva pinargento","sciamano selva pinargento"}}},fx={aaf07767={q="Cos'è la Scheggia d'Acqua?",a="La Scheggia d'Acqua è un frammento elementale sacro concesso agli sciamani che intraprendono le prove dell'acqua. Serve come prova tangibile che hai eseguito il rituale per purificare le acque corrotte e comprendere la vera natura dell'acqua come fonte e protettrice della vita.",al={"cos'è la scheggia d'acqua","oggetto scheggia d'acqua","cos'è questa scheggia"}},["47314211"]={q="Da dove proviene la Scheggia d'Acqua e chi l'ha creata?",a="Ricevi la scheggia al termine del tuo viaggio spirituale nella Selva Pinargento, donata dopo aver completato il rituale per purificare le acque corrotte della regione. Incarna il potere elementale dell'acqua pura risvegliato attraverso quel rito.",al={"dove si ottiene la scheggia d'acqua","chi dà la scheggia d'acqua","origine della scheggia d'acqua"}}},fp="14,277,25.555.0,36.188.0,23.157.0,48.194.0"}
P.entries["item:shaw-s-report"] = {n="Rapporto di Shaw",s="Il Rapporto di Shaw è un dispaccio confidenziale scritto dal Maestro Mathias Shaw del SI:7 per Gryan Stoutmantle nelle Marche Occidentali. Delinea le informazioni dell'agenzia di spionaggio riguardo alla Stonemasons Guild, al suo capo Edwin VanCleef e alla loro rimostranza contro la corona in seguito alla ricostruzione di Roccavento.",h="Il Rapporto di Shaw è un dispaccio confidenziale scritto dal Maestro Mathias Shaw del SI:7 per Gryan...",kw={"defias","edwin vancleef","gryan stoutmantle","mathias shaw","rapporto di shaw","si:7","stonemasons guild","marche occidentali"},ang={["class:Rogue"]="Il rapporto evidenzia la portata e i metodi del Maestro Mathias Shaw, l'indiscusso maestro della rete di spionaggio di Roccavento e capo del SI:7.",["faction:Alliance"]="Il documento svela il marciume interno a Roccavento, descrivendo dettagliatamente come un debito non pagato verso gli architetti del regno abbia dato origine a un'insurrezione che minaccia i terreni agricoli del reame."},sec={{t="Informazioni sulla Stonemasons Guild",b="Trasportato dal quartier generale segreto del SI:7 a Roccavento fino a Guardiacolle, il Rapporto di Shaw fornisce alla People's Militia la prima chiara spiegazione su chi comandi i banditi che devastano le Marche Occidentali. Il documento spiega nei dettagli come la Stonemasons Guild, sotto Edwin VanCleef, abbia minuziosamente ricostruito Roccavento dopo la sua distruzione nella Prima Guerra. Quando la corona e la nobiltà rifiutarono di compensare equamente i muratori al completamento dell'opera, un amaro risentimento covò sotto la cenere. Le informazioni di Shaw stabiliscono il collegamento fondamentale tra gli artigiani scontenti e sfollati e la rivolta criminale che sta travolgendo i territori periferici del regno."}},faq={{q="Cos'è il Rapporto di Shaw?",a="È un dossier di informazioni sigillato compilato dal Maestro Mathias Shaw, capo dell'agenzia segreta del SI:7 di Roccavento, indirizzato a Gryan Stoutmantle. Contiene le informazioni della corona riguardanti la Stonemasons Guild e la storia di Edwin VanCleef.",al={"rapporto di shaw","cosa scrive shaw","contenuto del rapporto di shaw"}},{q="Cosa rivela il rapporto su Edwin VanCleef?",a="Identifica VanCleef come l'ex capo della Stonemasons Guild che ha supervisionato la ricostruzione di Roccavento dopo la Prima Guerra. Spiega che VanCleef e i suoi artigiani si sono ribellati dopo che i sovrani del regno hanno negato loro un pagamento adeguato.",al={"vancleef nel rapporto","cosa dice su vancleef"}},{q="Perché Gryan Stoutmantle ha bisogno di questo rapporto?",a="Stoutmantle guida la People's Militia nella difesa delle Marche Occidentali dalle incursioni coordinate dei banditi. Senza truppe regolari del regno ad assisterlo, fa affidamento sullo spionaggio di Mathias Shaw per scoprire chi dirige i fuorilegge e quali siano i loro veri motivi.",al={"perché inviare il rapporto a gryan","perché stoutmantle ha bisogno del rapporto"}},{q="Come reagisce Stoutmantle al rapporto?",a="Stoutmantle è profondamente turbato. Riconosce Edwin VanCleef come un artigiano laborioso e abile, trovando difficile credere che un costruttore così rispettato possa cadere nella malvagità senza ulteriori prove concrete.",al={"reazione di gryan","reazione di stoutmantle"}}},fx={c86c6e50={q="Da dove proviene il Rapporto di Shaw e chi lo ha scritto?",a="Il rapporto è stato redatto dal Maestro Mathias Shaw, il capo del servizio di intelligence di Roccavento, l'SI:7. Lavorando dal suo quartier generale nella Città Vecchia, Shaw ha compilato le informazioni raccolte dall'SI:7 riguardanti la storia della Gilda dei Muratori e Edwin VanCleef per rimandarle a Gryan Stoutmantle a Guardiacolle.",al={"chi ha scritto il rapporto di shaw","chi ha creato il rapporto di shaw","da dove viene il rapporto di shaw"}}},fp="13,296,31.642.1,22.241.0,49.242.0,44.242.0,41.224.0"}
P.entries["item:shimmering-frond"] = {n="Fronda Scintillante",s="Una Fronda Scintillante è un esemplare raccolto da una strana pianta luminosa che cresce all'interno della Radura dell'Oracolo di Teldrassil. La sua insolita luminescenza e la sua aura contorta rivelano che si tratta di una specie esotica del tutto estranea ai rami dell'Albero del Mondo.",h="Una Fronda Scintillante è un esemplare raccolto da una strana pianta luminosa che cresce all'interno della...",kw={"botanica","denalan","lago al'ameth","radura dell'oracolo","fronda scintillante","pianta frondosa bizzarra","palude del dolore","teldrassil"},ang={["class:Druid"]="La comparsa di una pianta palustre invasiva che prospera sui rami appena nati di Teldrassil è una curiosa anomalia ecologica degna dell'attenzione di qualsiasi druido.",["profession:Herbalism"]="Gli erboristi che vagano per Teldrassil possono apprezzare la rara resilienza necessaria a una specie originaria della Palude del Dolore per attraversare l'oceano e prosperare in un terreno straniero."},sec={{t="Un esemplare da lontano",b="Mentre vagano tra le verdeggianti chiome intorno alla Radura dell'Oracolo, i viaggiatori possono imbattersi in una strana vegetazione che vanta un'aura pulsante e radiosa. Le fronde colte da questa pianta catturano la luce filtrata del bosco in modi innaturali, scintillando di vibrante vitalità. Denalan, un botanico che si prende cura delle sue fioriere vicino al Lago Al'ameth, riconosce immediatamente il fogliame come una specie originaria della lontana Palude del Dolore nei Regni Orientali. Come i semi di una palude situata così lontano al di là del Grande Mare siano riusciti ad attecchire e a prosperare sul Teldrassil sorto di recente rimane un mistero intrigante, che spinge Denalan a far germogliare e a studiare degli esemplari nel proprio terreno."}},faq={{q="Da dove proviene la Fronda Scintillante?",a="La fronda viene raccolta da una strana pianta frondosa situata all'interno della Radura dell'Oracolo su Teldrassil. La pianta si distingue per il bagliore contorto e pulsante che risplende sulle sue foglie alla luce della foresta.",al={"dove posso ottenere la fronda scintillante","posizione fronda scintillante","pianta frondosa bizzarra"}},{q="Chi è interessato alla Fronda Scintillante?",a="Denalan, un naturalista elfo della notte che conduce ricerche botaniche accanto al Lago Al'ameth, è ansioso di esaminare l'esemplare. Mostra grande interesse per la strana vegetazione che attecchisce su Teldrassil.",al={"chi vuole la fronda scintillante","a chi dare la fronda scintillante","denalan fronda scintillante"}},{q="Cosa rende questa pianta così insolita su Teldrassil?",a="La pianta non è originaria di Kalimdor o dell'Albero del Mondo. Denalan la riconosce come una specie indigena delle acque torbide della Palude del Dolore, situata molto lontano al di là del Grande Mare nei Regni Orientali, rendendo la sua fiorente presenza su Teldrassil del tutto inaspettata.",al={"perché la fronda scintillante è speciale","origine della pianta","pianta della palude del dolore"}},{q="Cosa succede dopo aver consegnato la fronda a Denalan?",a="Denalan pianta e coltiva immediatamente l'esemplare nelle sue fioriere vicino al Lago Al'ameth per condurre test sulla sua rapida crescita e sulle sue proprietà esotiche.",al={"cosa ne fa denalan","storia delle fronde germogliate"}}},fx={["7be1ca60"]={q="Cos'è la Fronda Scintillante?",a="È una foglia presa da un'insolita flora ricoperta di vegetazione nota come Strange Fronded Plant trovata nella Radura dell'Oracolo. La fronda brilla costantemente sotto la volta della foresta, irradiando un'aura contorta e pulsante non comune ai rami di Teldrassil.",al={"cos'è la fronda scintillante","oggetto fronda scintillante","cos'è questa fronda"}}},fp="16,244,20.650.0,42.208.0,42.194.0,47.264.0,47.151.0"}
P.entries["item:shimmerweed"] = {n="Erbaluce",s="La Shimmerweed è un'erba particolare coltivata dai troll Frostmane su Cresta Brillante, tra le vette innevate di Dun Morogh. Mentre i troll la raccolgono per i propri rituali tribali, i birrai nani locali ne bramano il sapore aspro e unico per birre sperimentali.",h="La Shimmerweed è un'erba particolare coltivata dai troll Frostmane su Cresta Brillante, tra le vette innevate...",kw={"borgo luppolo","dun morogh","frostmane","stout perfetta","rejold maltorzo","cresta brillante","shimmerweed"},ang={["profession:Herbalism"]="Sebbene non faccia parte della dotazione standard di un botanico sul campo, la shimmerweed mostra come la flora regionale venga spesso adattata tanto per le tradizioni birrarie locali quanto per l'alchimia rituale.",["race:Dwarf"]="Fedele all'ingegno nanico: se una strana pianta cresce su una rupe vicina, prima o poi qualcuno cercherà di fermentarla per farne birra."},sec={{t="Una coltura dei troll",b="Molto al di sopra dei bassopiani di Dun Morogh, i troll Frostmane coltivano ciuffi di shimmerweed lungo i picchi ghiacciati di Cresta Brillante. I troll raccolgono e conservano la pianta in cesti intrecciati sparsi nei loro accampamenti, affidandosi a essa per alimentare i loro rituali sacri ed enigmatici. Al di fuori della società dei troll, pochi montanari badano a quest'erba, sebbene le sue potenti proprietà abbiano attirato lo sguardo di forestieri ingegnosi."},{t="Un ingrediente segreto",b="Nel vicino Borgo Luppolo, il mastro birraio Rejold Maltorzo ha mostrato un vivo interesse per l'erba. Convinto di avere l'arte birraria nel sangue, Rejold cerca di creare l'autentica Birra Scura Nanica definitiva e sospetta che il sapore pungente e inconfondibile della shimmerweed possa essere il pezzo mancante. Ingaggia spesso viaggiatori avventurosi affinché si intrufolino negli accampamenti dei Frostmane, schivino i troll ostili e riportino staia da riversare nei suoi tini di fermentazione."}},faq={{q="Dove cresce la shimmerweed?",a="La Shimmerweed si trova in cima a Cresta Brillante, un'altura ghiacciata a nord-ovest di Borgo Luppolo a Dun Morogh. Viene coltivata e raccolta dai troll Frostmane, che la conservano in cesti attorno ai loro accampamenti.",al={"posizione di shimmerweed","dove trovare shimmerweed","pianta di cresta brillante"}},{q="Per cosa usano la shimmerweed i troll Frostmane?",a="I troll Frostmane utilizzano la shimmerweed nei loro misteriosi riti e cerimonie tribali. Sebbene i dettagli precisi dei loro rituali rimangano oscuri agli estranei, l'erba gioca un ruolo attivo nelle loro pratiche culturali e spirituali su Cresta Brillante.",al={"uso di shimmerweed dei troll","perché i troll vogliono shimmerweed"}},{q="Perché Rejold Maltorzo vuole la shimmerweed?",a="Rejold Maltorzo sta cercando di brassare la Birra Scura Nanica perfetta a Borgo Luppolo. Avendo riscontrato un gusto unico nell'erba selvatica, vuole gettare staia fresche di shimmerweed nel suo ammostamento sperimentale per vedere se conferisce il profilo audace di cui la sua ricetta ha bisogno.",al={"missione di rejold maltorzo","chi vuole shimmerweed","perché brassare con shimmerweed"}},{q="La shimmerweed cresce da qualche parte al di fuori di Dun Morogh?",a="Varietà di shimmerweed sono state raccolte in terre aride come Durotar, dove chiaroveggenti come Drek'Thar apprezzano la pianta per potenti intrugli d'erbe e infusi medicinali, dimostrando che l'erba può adattarsi oltre le vette ghiacciate di Khaz Modan.",al={"shimmerweed durotar","shimmerweed fuori da dun morogh"}}},fx={["1978b4f9"]={q="Cos'è lo Shimmerweed?",a="Lo Shimmerweed è una pianta distintiva coltivata in alto sulle vette innevate di Dun Morogh dai troll Mantogelido, in particolare attorno a Cresta Brillante. Rilevante per il suo sapore e le sue proprietà insolite, l'erba viene raccolta in cesti dai troll e gioca un ruolo nei rituali tribali locali, sebbene ambiziosi birrai nanici abbiano recentemente mostrato interesse a testare le sue potenti qualità in birre sperimentali.",al={"cos'è lo shimmerweed","pianta shimmerweed","informazioni su shimmerweed"}},d2fd1cd1={q="Da dove proviene lo Shimmerweed e chi lo coltiva?",a="Lo Shimmerweed viene coltivato naturalmente dai troll Mantogelido a Dun Morogh, che curano e raccolgono la pianta in cesti su Cresta Brillante. Mentre i Mantogelido ne mantengono le coltivazioni per i loro rituali, varietà selvatiche della potente erba sono note per crescere anche in terre lontane come Durotar, dove erboristi e sciamani delle terre selvagge la apprezzano per la preparazione di pozioni.",al={"da dove viene lo shimmerweed","chi coltiva lo shimmerweed","origine shimmerweed"}}},fp="11,252,15.413.0,19.442.0,28.203.0,49.250.0,44.263.0,50.237.0"}
P.entries["item:shindrell-s-note"] = {n="Messaggio di Shindrell",s="Il Messaggio di Shindrell è una missiva scritta che descrive recenti osservazioni sulla corruzione attorno ad Astranaar e lungo la costa di Valtetra. Redatto dalla Sentinella della Notte Shindrell Fuocolesto, funge da rapporto informativo inviato a est attraverso la foresta al druido Kayneth Stillwind.",h="Il Messaggio di Shindrell è una missiva scritta che descrive recenti osservazioni sulla corruzione attorno ad...",kw={"valtetra","astranaar","cantaselva","kayneth stillwind","boschi del canto notturno","shindrell fuocolesto","messaggio di shindrell"},ang={["class:Druid"]="Portare le osservazioni di Shindrell a Kayneth Stillwind aiuta gli altri druidi a scoprire le origini della piaga innaturale che affligge la foresta.",["race:NightElf"]="La missiva illustra la continua cooperazione tra le Sentinelle a difesa degli insediamenti di Valtetra e i druidi di Cenarion che ne studiano i disturbi ecologici."},sec={{t="Una missiva attraverso i boschi",b="Mentre i disordini si diffondono in tutta Valtetra, le sentinelle e i druidi degli Elfi della Notte si coordinano per sorvegliare i confini della foresta. Redatto dalla Sentinella Shindrell Fuocolesto ad Astranaar, questo rapporto descrive preoccupanti perturbazioni avvistate lungo la costa occidentale e tra le chiome centrali. È indirizzato a Kayneth Stillwind, un druido di stanza presso il santuario di Cantaselva all'interno dei Boschi del Canto Notturno a est. Inviando corrieri con le sue osservazioni dirette, Shindrell supporta le indagini di Kayneth sulla sottile corruzione che serpeggia nei boschi sacri."}},faq={{q="Che cos'è il Messaggio di Shindrell?",a="È un rapporto sul campo scritto dalla Sentinella Shindrell Fuocolesto, che descrive disordini e una presunta corruzione avvistata vicino ad Astranaar e lungo la costa di Valtetra.",al={"cos'è questo messaggio","messaggio di shindrell","cosa dice il messaggio"}},{q="Chi dovrebbe ricevere il messaggio?",a="Il messaggio è indirizzato a Kayneth Stillwind, un druido degli Elfi della Notte situato a Cantaselva, nei territori orientali di Valtetra noti come i Boschi del Canto Notturno.",al={"a chi lo devo dare","dove va consegnato","per chi è il messaggio"}},{q="Perché è stato scritto il messaggio?",a="Kayneth Stillwind ha richiesto informazioni su eventi insoliti nelle foreste occidentali, temendo che un'insidiosa corruzione stia mettendo radici all'interno dei boschi. Shindrell ha raccolto i suoi avvistamenti per aiutarlo a valutare la minaccia.",al={"perché è stato scritto il messaggio","di quale corruzione parla shindrell","scopo del rapporto"}},{q="Dove risiede Shindrell Fuocolesto?",a="Shindrell Fuocolesto è una Sentinella della Notte di stanza presso l'insediamento di Astranaar, situato al centro di Valtetra.",al={"dove si trova shindrell","posizione di shindrell fuocolesto","chi ha inviato questo"}}},fx={ed6c40b2={q="Da dove proviene il Messaggio di Shindrell e chi lo ha scritto?",a="Il messaggio è stato scritto dalla Sentinella Shindrell Fuocolesto ad Astranaar. Scritto come un rapporto ufficiale sul campo, descrive dettagliatamente gli eventi inquietanti che ha osservato lungo la costa di Valtetra e in tutti i boschi circostanti.",al={"chi ha scritto il messaggio di shindrell","chi ha creato il messaggio di shindrell","origine del messaggio di shindrell"}}},fp="16,283,26.562.0,25.166.0,33.150.0,25.226.0,38.115.0"}
P.entries["item:shipment-of-boots"] = {n="Spedizione di Stivali",s="Una cassa di calzature spedita da Baia del Bottino dal mercante Drizzlik, destinata alla rete commerciale di Sparachiodi a Porto Paranco. È stata intercettata al largo della costa dai Southsea Freebooters e nascosta nel loro accampamento a sud del porto.",h="Una cassa di calzature spedita da Baia del Bottino dal mercante Drizzlik, destinata alla rete commerciale di...",kw={"baia del bottino","drizzlik","sparachiodi","porto paranco","spedizione di stivali","southsea freebooters","stolen booty"},ang={["class:Rogue"]="Infiltrarsi negli accampamenti dei Southsea lungo la costa richiede di evitare fitte pattuglie di pirati, rendendo un approccio silenzioso il modo più sicuro per recuperare il carico rubato di Sparachiodi."},sec={{t="Un carico saccheggiato",b="Gestire un porto commerciale goblin richiede rifornimenti continui, e Sparachiodi ha organizzato una nuova consegna di stivali da Drizzlik, un fornitore di abbigliamento con sede a Baia del Bottino. La spedizione non ha mai raggiunto i moli di Porto Paranco. I Southsea Freebooters che si aggiravano lungo la Costa dei Mercanti hanno teso un'imboscata alla nave da trasporto, portando le casse nei loro accampamenti sulla spiaggia a sud del porto. I pirati hanno disseminato il carico rubato tra le loro tende e baracche, lasciando Sparachiodi senza le merci attese fino a quando non è stato possibile assoldare mercenari intraprendenti per perlustrare il litorale."}},faq={{q="Chi ha inviato questa spedizione di stivali?",a="Gli stivali sono stati inviati da Baia del Bottino da Drizzlik, un mercante goblin che gestisce un emporio di abbigliamento e rifornimenti nel porto meridionale.",al={"chi ha fatto gli stivali","da dove arrivano gli stivali","stivali di drizzlik"}},{q="Chi avrebbe dovuto ricevere gli stivali?",a="Sparachiodi, il capo ingegnere e sovrintendente di Porto Paranco, ha ordinato le calzature per sostenere la propria manodopera locale e le operazioni mercantili.",al={"a chi appartengono gli stivali","spedizione di stivali di sparachiodi"}},{q="Come sono finiti gli stivali ai pirati?",a="I Southsea Freebooters hanno intercettato la nave da carico lungo la costa di The Barrens, saccheggiando l'imbarcazione e trasportando le casse nei loro accampamenti a sud di Porto Paranco.",al={"perché i pirati dei mari del sud hanno gli stivali","chi ha rubato gli stivali"}},{q="Dove si può trovare la spedizione?",a="La cassa si trova all'interno dell'accampamento dei pirati Southsea situato lungo la costa a sud di Porto Paranco, nascosta tra le loro merci saccheggiate.",al={"posizione degli stivali","dov'è la spedizione di stivali","trova la spedizione di stivali"}}},fx={["06b396e7"]={q="Cos'è la Spedizione di Stivali?",a="La Spedizione di Stivali è una cassa di calzature inviata attraverso il Grande Mare da Baia del Bottino a Porto Paranco. Spedita dal mercante goblin Drizzlik, era destinata direttamente a Sparachiodi prima che i Southsea Freebooters intercettassero la nave cargo che trasportava la sua merce.",al={"cos'è la spedizione di stivali","oggetto spedizione di stivali","cosa sono gli stivali"}}},fp="17,233,17.555.0,32.141.0,38.131.0,42.161.0,32.140.0"}
P.entries["item:shipment-of-iron"] = {n="Spedizione di Ferro",s="Una cassa di metallo grezzo conservata presso la fucina umana nei Campi di Colletorto. Funge da riserva vitale per la produzione bellica locale, rendendola un bersaglio prioritario per le forze dei Reietti che mirano a tagliare le linee di rifornimento che armano i cittadini di Colletorto.",h="Una cassa di metallo grezzo conservata presso la fucina umana nei Campi di Colletorto.",kw={"battle of hillsbrad","darthalia","campi di colletorto","spedizione di ferro","mulino di tarren","verringtan"},ang={["faction:Horde"]="Negare i rifornimenti a Colletorto paralizza la resistenza armata dei contadini prima che la campagna muova contro Riva del Sud.",["profession:Blacksmithing"]="La scorta rappresenta la linfa vitale della produzione bellica umana nella valle; senza lingotti di ferro grezzo, la forgia di Verringtan rimane del tutto inutile."},sec={{t="Alimentare la Resistenza",b="Nel conflitto in corso attraverso le Alture di Colletorto, i contadini umani hanno opposto una resistenza sorprendentemente tenace contro Mulino di Tarren. Gran parte di questa capacità combattiva proviene direttamente dalla fucina situata al margine sud-occidentale dei Campi di Colletorto, dove il Fabbro Verringtan e i suoi apprendisti lavorano giorno e notte producendo armi e armature a partire da pesanti spedizioni di ferro. Per spezzare la determinazione dei contadini, i comandanti dei Reietti ordinarono di spegnere la forgia, eliminare i suoi fabbri e requisire le scorte di metallo per lo sforzo bellico dell'Orda."}},faq={{q="Dove è custodita la spedizione di ferro?",a="La spedizione si trova direttamente all'interno dell'officina del fabbro, situata al margine sud-occidentale dei Campi di Colletorto, pesantemente sorvegliata dal Fabbro Verringtan e dai suoi apprendisti.",al={"posizione spedizione di ferro","dove si trova il ferro","posizione ferro colletorto"}},{q="Perché i Reietti vogliono questo ferro?",a="Impossessarsi del ferro interrompe la linea di rifornimento di armi destinata alla milizia umana locale. La Gran Esecutrice Darthalia intende inoltre reimpiegare le scorte di metallo per sostenere la macchina bellica dell'Orda, una volta che l'offensiva si sposterà per radere al suolo Riva del Sud.",al={"perché rubare il ferro","ferro mulino di tarren","scopo ferro battle of hillsbrad"}},{q="Chi stava usando originariamente questo ferro?",a="Il Fabbro Verringtan e i suoi quattro apprendisti fabbri utilizzavano il ferro per equipaggiare i cittadini e i braccianti, trasformando semplici contadini in una forza di difesa locale armata contro i non morti.",al={"chi possiede il ferro","ferro di verringtan","fabbri di colletorto"}},{q="Chi ordina il recupero della spedizione di ferro?",a="La Gran Esecutrice Darthalia, al comando delle operazioni dei Reietti da Mulino di Tarren, impartisce l'ordine diretto di uccidere i fabbri e reclamare il ferro durante la Battle of Hillsbrad.",al={"chi assegna la missione","missione del ferro di darthalia"}}},fx={["8a003d21"]={q="Cos'è la Spedizione di Ferro?",a="La Spedizione di Ferro è una scorta di metallo grezzo immagazzinata presso la bottega del fabbro umano nei Campi di Colletorto. Serve come materiale primario che il Fabbro Verringtan e i suoi apprendisti usano per forgiare armi e armature per la gente del posto di Colletorto che resiste ai Forsaken.",al={"cos'è la spedizione di ferro","spedizione di ferro","spedizione di ferro colletorto"}}},fp="16,240,22.546.0,35.179.0,37.231.0,35.193.0,46.173.0"}
P.entries["item:shipping-schedule"] = {n="Programma delle Spedizioni",s="Il Programma delle Spedizioni è un documento logistico custodito dal capomolo della Fratellanza dei Defias presso il Molo di Jerod. Delinea le spedizioni di carico illecito che transitano attraverso la Foresta di Elwynn tra Redridge e le Marche Occidentali, attirando l'attenzione vigile dell'agenzia di spionaggio di Roccavento.",h="Il Programma delle Spedizioni è un documento logistico custodito dal capomolo della Fratellanza dei Defias...",kw={"defias","capomolo","foresta di elwynn","molo di jerod","mathias shaw","programma delle spedizioni","si:7","contrabbando"},ang={["class:Rogue"]="Procurarsi il programma dalle tasche del capomolo è una prova determinante di furtività e borseggio per gli aspiranti agenti che cercano di entrare nei ranghi del SI:7."},sec={{t="Contrabbando al Molo di Jerod",b="A sud di Borgodoro, sulla sponda della Foresta di Elwynn del Fiume Nazferiti, la Fratellanza dei Defias ha preso il controllo del Molo di Jerod per utilizzarlo come snodo per il proprio traffico fluviale. Attraverso questo molo segreto, la Fratellanza trasporta grandi quantità di contrabbando tra Redridge e le Marche Occidentali, scivolando lungo i corsi d'acqua proprio sotto il naso delle Guardie di Roccavento. Il Programma delle Spedizioni registra questi movimenti clandestini, sorvegliati da vicino addosso al capomolo."},{t="Nel mirino del SI:7",b="Il Maestro Mathias Shaw, leader del SI:7, ha commissionato il furto del programma per mappare le catene di approvvigionamento dei Defias e mettere alla prova le nuove reclute. Infiltrarsi nella casa del molo e sottrarre il documento dalle tasche del capomolo serve sia come informazione operativa per la corona sia come prova d'iniziazione. Se l'agente viene catturato, il SI:7 nega ogni legame, senza lasciare alcuna traccia che conduca alla caserma di Roccavento."}},faq={{q="Cos'è il Programma delle Spedizioni?",a="È un registro operativo tenuto dal capomolo della Fratellanza dei Defias presso il Molo di Jerod. Dettaglia il movimento di contrabbando e rifornimenti traghettati tra Redridge e le Marche Occidentali attraverso le acque interne della Foresta di Elwynn.",al={"programma delle spedizioni defias","cos'è questo documento","programma del capomolo"}},{q="Chi vuole recuperare questo programma?",a="Il Maestro Mathias Shaw, a capo del servizio segreto di Roccavento, il SI:7. Utilizza queste informazioni per monitorare l'apparato di contrabbando dei Defias e per valutare i ladri promettenti sul campo.",al={"chi ha bisogno del programma","programma mathias shaw","chi prende il programma delle spedizioni"}},{q="Dove si trova il programma?",a="Il documento è trasportato dal Defias Dockmaster all'interno della casa del molo al Molo di Jerod, situato sul Fiume Nazferiti a sud di Borgodoro nella Foresta di Elwynn. Un agente deve intrufolarsi nell'edificio e borseggiarlo o depredarlo da lui.",al={"posizione programma delle spedizioni","dov'è il capomolo","come ottenere il programma"}},{q="A cosa serve il Molo di Jerod?",a="Il Molo di Jerod è stato occupato dai Banditi Defias per fungere da punto di transito. Utilizzano il suo accesso fluviale per contrabbandare carichi illeciti attraverso il regno, collegando le loro operazioni a Redridge direttamente alle loro roccaforti nelle Marche Occidentali.",al={"molo di jerod defias","perché i defias hanno il molo di jerod","molo defias elwynn"}}},fx={["45ccd8c3"]={q="Da dove viene il Programma delle Spedizioni e chi l'ha redatto?",a="Il programma è custodito dal maestro di porto della Fratellanza dei Defias, di stanza al Molo di Jerod, a sud di Borgodoro. Descrive le operazioni fluviali del sindacato fuorilegge e tiene traccia del movimento di merci illecite e contrabbando tra le Montagne Crestarossa e le Marche Occidentali.",al={"chi ha scritto il programma delle spedizioni","origine del programma delle spedizioni","chi ha redatto il programma delle spedizioni dei defias"}}},fp="17,271,28.453.0,25.408.0,30.224.0,34.184.0,28.235.0,33.225.0"}
P.entries["item:sida-s-bag"] = {n="Sacca di Sida",s="La Sacca di Sida è la borsa personale di Sida, una residente di Porto di Menethil. Inghiottita per intero da una melma strisciante durante una sua escursione al Sepolcro di Barbaferrea, la sacca e i suoi misteriosi contenuti richiedono una meticolosa caccia tra le melme acide delle Wetlands per essere recuperati.",h="La Sacca di Sida è la borsa personale di Sida, una residente di Porto di Menethil.",kw={"dun modr","sepolcro di barbaferrea","porto di menethil","melma","sida","sacca di sida","paludi dell'aspra roccia"},ang={["faction:Alliance"]="I profughi e i cittadini provati di Porto di Menethil fanno interamente affidamento sui viaggiatori di passaggio per affrontare gli orrori predatori che strisciano fuori dalle allagate Wetlands."},sec={{t="Una difesa disperata",b="Durante la sua consueta visita settimanale al Sepolcro di Barbaferrea nei pressi di Dun Modr, Sida è caduta vittima di un'imboscata da parte delle terribili melme gocciolanti che infestano l'area. In preda al panico di fronte alla melma che avanzava, ha scagliato la sua borsa personale direttamente contro una delle creature. Invece di scacciare la bestia, la melma ha semplicemente assorbito la borsa nel suo corpo gelatinoso. Questo diversivo ha concesso a Sida abbastanza tempo prezioso per fuggire e mettersi in salvo a Porto di Menethil, lasciando i suoi averi intrappolati all'interno di una melma sconosciuta."},{t="Recuperata dalla melma",b="Poiché le ondeggianti melme che si aggirano attorno al Sepolcro di Barbaferrea — dalle varianti cremisi a quelle mostruose — sembrano sostanzialmente identiche, trovare la sacca richiede l'abbattimento delle melme della palude finché la borsa inghiottita non riemerge intatta. Nonostante sia rimasta immersa nella fanghiglia digestiva acida, la resistente sacca preserva il suo contenuto. Una volta restituitale, Sida reclama con entusiasmo i suoi beni e getta via l'esterno rovinato e ricoperto di melma, offrendo il contenitore ripulito a chiunque abbia sfidato la palude per conto suo."}},faq={{q="Perché la sacca di Sida era dentro una melma?",a="Sida è stata presa dal panico quando è stata attaccata da melme gocciolanti durante una visita al Sepolcro di Barbaferrea. Nel disperato tentativo di fuggire, ha scagliato la sua borsa contro uno dei mostri, che l'ha immediatamente inglobata e inghiottita per intero.",al={"come ha fatto la melma a prendere la sacca","perché la sacca è nella melma","come ha perso la sacca sida"}},{q="Quali melme contengono la Sacca di Sida?",a="Sida non è in grado di distinguere le melme l'una dall'altra, quindi una qualsiasi delle melme predatrici che circondano il Sepolcro di Barbaferrea nelle Wetlands nordorientali — inclusi Crimson Oozes, Black Oozes o Monstrous Oozes — potrebbe averla inghiottita.",al={"dove trovare la sacca di sida","chi rilascia la sacca di sida","quale melma ha la sacca"}},{q="Perché Sida visita il Sepolcro di Barbaferrea?",a="Sida compie un viaggio settimanale partendo da Porto di Menethil per visitare l'antica cripta nanica vicino a Dun Modr, sebbene tenga per sé i motivi personali dietro le sue visite di routine.",al={"collegamento sida barbaferrea","perché sepolcro di barbaferrea"}},{q="Cosa c'era dentro la sacca di Sida?",a="Sida svuota rapidamente sul terreno gli oggetti recuperati e li raccoglie senza mostrare di cosa si tratti, limitandosi a far notare che il contenuto era fin troppo importante per lasciarlo dissolvere dentro una melma.",al={"cosa tira fuori dalla sacca sida","contenuto della sacca"}}},fx={["113113dd"]={q="Che cos'è la Sacca di Sida?",a="La Sacca di Sida è una borsa personale appartenente a Sida, una residente di Porto di Menethil. Durante una delle sue visite abituali al Sepolcro di Barbaferrea nelle Paludi, è stata assalita da alcuni fanghi e ha lanciato il suo zaino contro uno di loro nel disperato tentativo di fuggire. La creatura l'ha inghiottito intero, intrappolandolo nel suo corpo gelatinoso.",al={"che cos'è la sacca di sida","sacca di sida","di chi è la sacca di sida"}},afbd2451={q="Perché Sida rivuole la sua sacca?",a="Sida ha un disperato bisogno del contenuto chiuso nella sua sacca smarrita, non della sacca in sé. Dopo averla estratta dai resti dei fanghi al Sepolcro di Barbaferrea e avergliela riportata a Porto di Menethil, rovescia subito a terra il contenuto viscido, lo raccoglie e ti consegna la borsa vuota, macchiata di melma.",al={"perché sida rivuole la sua sacca","perché la sacca di sida","perché qualcuno vuole la sacca di sida"}}},fp="10,265,18.532.0,24.496.0,34.209.0,29.208.0,37.175.0,27.196.0"}
P.entries["item:signed-recruitment-letter"] = {n="Lettera di Reclutamento Firmata",s="La Lettera di Reclutamento Firmata è un dispaccio ufficiale emesso da Kargal Sfregiofondo al Presidio Lungosguardo. Recando il marchio di Kargal, trasferisce le nuove reclute più all'interno nell'arido entroterra di The Barrens per presentarsi in servizio a Crocevia.",h="La Lettera di Reclutamento Firmata è un dispaccio ufficiale emesso da Kargal Sfregiofondo al Presidio...",kw={"coscrizione","crocevia","presidio lungosguardo","kargal sfregiofondo","sergra darkthorn","lettera di reclutamento firmata","the barrens","thrall"},ang={["class:Shaman"]="Il documento ti pone al servizio di Sergra Darkthorn, un'importante sciamana orca incaricata da Thrall di aiutare a mettere in sicurezza The Barrens.",["faction:Horde"]="La lettera di reclutamento rappresenta il tuo passaggio dal servizio di base a Durotar al più ampio apparato militare della frontiera dell'Orda."},sec={{t="Il trasferimento di un coscritto",b="Rappresentando la soglia orientale di The Barrens, il Presidio Lungosguardo valuta i nuovi arrivati che attraversano il Fiume Furialunga da Durotar. Una volta che un coscritto dimostra a Kargal Sfregiofondo di essere pronto, questi timbra e firma questa lettera di presentazione. Funge da ordine militare che indirizza le reclute a ovest lungo la strada verso Crocevia, dove Sergra Darkthorn coordina le operazioni logistiche e la difesa territoriale attraverso le pianure aride."},{t="Tensione agli avamposti",b="Sebbene la lettera sia un documento ufficiale dell'Orda, Kargal non nasconde il suo personale disprezzo per l'ufficiale che attende la recluta. Considera Sergra Darkthorn come una sciamana caustica che confonde i soldati con le sue chiacchiere, mettendo apertamente in discussione l'alta considerazione che il Warchief Thrall ha di lei. Nonostante le sue riserve, il dispaccio deve essere consegnato direttamente nelle mani di Sergra prima che possa essere concesso qualsiasi ulteriore incarico a Crocevia."}},faq={{q="Qual è lo scopo della Lettera di Reclutamento Firmata?",a="La lettera funge da documento militare ufficiale di trasferimento. Dimostra a Sergra Darkthorn a Crocevia che Kargal Sfregiofondo ti ha esaminato al Presidio Lungosguardo e ti ha ritenuto pronto per il servizio a The Barrens.",al={"a cosa serve questa lettera","uso lettera di reclutamento","lettera firmata the barrens"}},{q="Chi ha firmato la lettera?",a="Kargal Sfregiofondo, un veterano orco che sovrintende al Presidio Lungosguardo sul confine tra Durotar e The Barrens. Firma la lettera dopo che una recluta ha completato i doveri iniziali al confine.",al={"chi ha scritto la lettera","lettera di kargal","chi l'ha firmata"}},{q="A chi consegno la lettera?",a="La consegni a Sergra Darkthorn, un'influente sciamana orca di stanza all'incrocio centrale di Crocevia.",al={"dove porto la lettera","a chi va la lettera","destinatario della lettera"}},{q="Perché Kargal parla male di Sergra Darkthorn?",a="Kargal considera Sergra un'ufficiale dalla lingua tagliente e difficile, che perde tempo a parlare quando c'è del lavoro da fare. Sebbene il Warchief Thrall la tenga in grande considerazione, Kargal rimane scettico sulla sua leadership.",al={"faida tra kargal e sergra","perché kargal odia sergra"}}},fx={ea3ee62a={q="Che cos'è la Lettera di Reclutamento Firmata?",a="È un documento ufficiale di coscrizione dell'Orda consegnato alle reclute che arrivano a The Barrens da Durotar. Redatto e approvato da Kargal Sfregiofondo al Presidio Lungosguardo, certifica formalmente che sei stato esaminato, arruolato e inviato ad aiutare l'insediamento di Crocevia.",al={"che cos'è la lettera di reclutamento firmata","lettera di reclutamento","che cos'è questa lettera"}},ea22ddb8={q="Perché Sergra Darkthorn vuole la Lettera di Reclutamento Firmata?",a="Sergra Darkthorn dirige le operazioni a Crocevia e conta sui rinforzi in arrivo per assicurare The Barrens all'Orda. La lettera conferma il tuo arruolamento sotto l'autorità di Kargal, dimostrando che sei pronto a ricevere ordini, a dimostrare il tuo valore e ad affrontare le urgenti minacce e i lavori che gravano sull'insediamento.",al={"perché sergra vuole la lettera","perché consegnare la lettera di reclutamento","chi ha bisogno della lettera di reclutamento"}}},fp="25,236,22.437.0,23.422.0,53.209.0,22.186.0,31.118.0,49.214.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Silithid Egg (The Barrens)",s="Le Uova di Silitide sono la covata in sviluppo delle creature insettoidi che nidificano nelle Savane Meridionali. Trovate sepolte all'interno di tumuli di terra attorno al Field of Giants, queste covate vengono raccolte dai ricercatori dell'Orda nel tentativo di scoprire le origini e l'intelligenza dello sciame invasore.",h="Le Uova di Silitide sono la covata in sviluppo delle creature insettoidi che nidificano nelle Savane...",kw={"crocevia","artiglio scavatore","egg hunt","field of giants","korran","tumuli","silitide","uovo di silitide","the barrens"},ang={["faction:Horde"]="La comparsa di sciami di insetti intelligenti così vicino al Crocevia rappresenta un pericolo inquietante per le rotte commerciali e il territorio dell'Orda nel centro di Kalimdor."},sec={{t="Uno Sciame Misterioso",b="Nel bacino arido del Field of Giants, bizzarri esseri simili a insetti hanno iniziato a scavare la terra formando imponenti tumuli. Nelle profondità di questi nidi giacciono le loro uova, sepolte sotto il terreno indurito e sorvegliate da covate territoriali. L'Orda sa ben poco sui silitidi, ma gli esploratori di stanza al Crocevia hanno notato segni di comportamento coordinato e un intelletto straordinario che supera di gran lunga quello delle normali bestie selvatiche. Raccogliere le uova non ancora schiuse offre agli studiosi di Orgrimmar la migliore opportunità di studiare il ciclo vitale e la natura di questa minaccia emergente."},{t="Scavo e Pericolo",b="Raggiungere le uova richiede di fare leva nei tumuli dei silitidi con speciali artigli scavatori. Disturbare queste covate è un'opera pericolosa: i silitidi reagiscono ferocemente alle intrusioni vicino ai loro vivai sotterranei, scagliandosi in sciami contro chiunque minacci i loro piccoli non ancora nati. Per ricercatori come il troll Korran, recuperare esemplari intatti e integri è fondamentale per l'analisi prima che lo sciame si diffonda ulteriormente attraverso Kalimdor."}},faq={{q="Cosa sono le Uova di Silitide?",a="Sono le covate non ancora schiuse dei silitidi insettoidi che nidificano all'interno di tumuli di terra nelle Savane Meridionali, in particolare in tutto il Field of Giants.",al={"uovo di silitide","cos'è un uovo di silitide","tumuli di silitidi"}},{q="Chi richiede la raccolta di queste uova?",a="Korran, un ricercatore troll di stanza al Crocevia, le raccoglie per conto dei suoi superiori a Orgrimmar per studiare la strana biologia e il comportamento dei silitidi.",al={"chi ha bisogno delle uova","missione di korran","assegnatore della missione egg hunt"}},{q="Perché i silitidi vengono studiati?",a="L'Orda sa pochissimo sui silitidi. Korran nota che mostrano segni di intelligenza e coordinazione di gran lunga superiori rispetto ai tipici animali selvatici, sollevando preoccupazione tra i capi dell'Orda riguardo alla loro improvvisa presenza nelle Barrens.",al={"perché studiare i silitidi","minaccia dei silitidi","i silitidi sono intelligenti"}},{q="Come vengono raccolte le uova?",a="Devono essere dissotterrate con cura dai tumuli dei silitidi usando un artiglio scavatore adattato, respingendo al contempo l'aggressivo sciame che difende i nidi.",al={"come ottenere le uova","artiglio scavatore","raccogliere uova di silitide"}}},fx={["04f05afd"]={q="Da dove vengono le uova di silitide?",a="Queste uova vengono deposte dalle strane silitidi simili a insetti, nelle profondità dei loro tumuli di terra nelle Savane Meridionali, in particolare nel Field of Giants. Le silitidi seppelliscono e proteggono con cura le covate all'interno di questi imponenti tumuli, attaccando ferocemente chiunque osi disturbare i nidi.",al={"origine dell'uovo di silitide","da dove vengono le uova di silitide","chi ha deposto le uova di silitide"}}},fp="26,282,18.552.0,21.406.0,23.163.0,31.165.0,35.230.0,26.145.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Silixiz's Tower Key",s="La Silixiz's Tower Key è una piccola chiave custodita dal Caposquadra Silixiz all'esterno della torre della S.P.R. & Co. vicino alla Palude Fangosa. Gli agenti dell'Orda appartenenti alla The Shattered Hand hanno il compito di sfilarla direttamente dalle tasche del caposquadra nell'ambito di un incarico di sabotaggio sotto copertura.",h="La Silixiz's Tower Key è una piccola chiave custodita dal Caposquadra Silixiz all'esterno della torre della...",kw={"the barrens","caposquadra silixiz","the shattered hand","shenthul","silixiz","palude fangosa","chiave della torre","s.p.r. & co."},ang={["class:Rogue"]="Ottenere la Silixiz's Tower Key costituisce una prova fondamentale per i ladri dell'Orda che entrano nei ranghi della The Shattered Hand, richiedendo la padronanza del muoversi furtivamente e del borseggio.",["faction:Horde"]="La chiave è un trofeo essenziale per contrastare lo sfruttamento e gli esperimenti chimici della S.P.R. & Co. che minacciano i The Barrens settentrionali."},sec={{t="Una Prova di Scaltrezza",b="L'operazione della S.P.R. & Co. a nord della Palude Fangosa si svolge sotto stretta sorveglianza, incentrata su una torre di vedetta isolata supervisionata dal Gran Caposquadra Puzik Gallywix. All'esterno dell'avamposto pattugliato da mercenari goblin, il Caposquadra Silixiz porta con sé la chiave della torre che l'agente della The Shattered Hand ha l'ordine di rubare e tenere per sé. Per la rete di ladri della The Shattered Hand attiva da Orgrimmar, ottenere questa chiave non è una questione di forza bruta; gli agenti sul campo devono scivolare nell'accampamento senza farsi notare e borseggiare il caposquadra in modo pulito, dimostrando la propria padronanza del furtivismo prima di salire ai livelli superiori tossici."}},faq={{q="Dove trovo il Caposquadra Silixiz?",a="Il Caposquadra Silixiz è posizionato all'esterno della torre della S.P.R. & Co. situata direttamente a nord della Palude Fangosa, nella parte nordorientale dei The Barrens.",al={"posizione di silixiz","dove si trova il caposquadra silixiz","trovare silixiz"}},{q="Posso ottenere la chiave uccidendo il Caposquadra Silixiz?",a="No. La chiave non può essere recuperata dal suo cadavere. Gli agenti sono tenuti a usare il furtivismo e a borseggiarlo direttamente mentre è vivo per ottenere l'oggetto.",al={"bottino chiave di silixiz","posso uccidere silixiz","depredare la chiave di silixiz"}},{q="Chi richiede questa chiave?",a="La chiave è un obiettivo assegnato dai contatti della The Shattered Hand da consegnare a Shenthul, l'addestratore dei ladri di stanza tra le ombre di Orgrimmar.",al={"chi vuole la chiave","consegnare la chiave di silixiz","missione silixiz's tower key"}},{q="A cosa serve la chiave?",a="La chiave funge da prova dell'infiltrazione nella torre della S.P.R. & Co. vicino alla Palude Fangosa e viene consegnata alla The Shattered Hand insieme alla Testa di Gallywix del Gran Caposquadra Puzik e alla Cassa di Mistura di Zanzil Alterata.",al={"cosa apre la chiave di silixiz","scopo della chiave di silixiz","usare la chiave della torre"}}},fx={["163c94d7"]={q="Che cos'è Silixiz's Tower Key?",a="È una chiave custodita dal caposquadra Silixiz, fuori dalla torre della S.P.R. & Co. a nord della Palude Fangosa. All'agente è stato ordinato di rubarla e tenerla con sé, nel caso il contatto della Shattered Hand ne avesse bisogno in seguito.",al={"che cos'è silixiz's tower key","chiave di silixiz","chiave della torre della s.p.r. & co."}}},fp="19,274,18.618.0,32.149.0,48.155.0,22.146.0,25.221.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Scrigno dell'Alba d'Argento",s="Lo Scrigno dell'Alba d'Argento è un robusto forziere adagiato tra i resti sommersi del vascello Silver Dawning al largo delle coste di Darkshore. Contiene gli effetti personali e il diario di bordo del capitano caduto del vascello, perito durante un'imboscata tesa da murloc costieri.",h="Lo Scrigno dell'Alba d'Argento è un robusto forziere adagiato tra i resti sommersi del vascello Silver...",kw={"auberdine","darkshore","gorbold mandacciaio","scrigno","murloc","naufragio","alba d'argento"},ang={["race:Dwarf"]="Gorbold Mandacciaio si prende l'onere di far sì che i capitani caduti siano onorati e che i loro effetti personali siano restituiti ai loro compagni superstiti.",["race:NightElf"]="Lo scrigno conserva gli ultimi scritti e le reliquie di un capitano kaldorei morto difendendo il proprio vascello proprio al largo delle coste del nord di Kalimdor."},sec={{t="Resti sommersi",b="La nave Silver Dawning stava attraversando il mare diretta verso il porto di Auberdine quando si verificò il disastro. Murloc costieri presero d'assalto il vascello, trascinandolo giù tra i flutti oscuri a nord del porto. Il capitano perì nell'assalto, lasciando il relitto sommerso sotto le onde come un tetro monumento reclamato da quelle creature. All'interno dello scafo allagato si trova ancora lo scrigno personale del capitano, che custodisce il diario di bordo e i suoi effetti privati. Recuperare questi oggetti offre un'ultima forma di sollievo ai membri dell'equipaggio superstiti a terra."}},faq={{q="Dove si trova lo Scrigno dell'Alba d'Argento?",a="Lo scrigno si trova all'interno del relitto sommerso della Silver Dawning, un vascello capovolto adagiato sul fondo dell'oceano a nord di Auberdine, al largo delle coste di Darkshore.",al={"posizione dello scrigno","dove si trova lo scrigno dell'alba d'argento","relitto dell'alba d'argento"}},{q="Cosa è successo alla Silver Dawning?",a="Mentre la Silver Dawning navigava verso Auberdine attraverso l'oceano, subì un'imboscata da parte dei murloc locali. Il vascello venne sopraffatto, distrutto e affondò sotto le onde, costando la vita al suo capitano.",al={"perché è affondata l'alba d'argento","storia dell'alba d'argento","come è avvenuto il naufragio"}},{q="Cosa c'è dentro lo scrigno?",a="Il forziere contiene gli effetti personali e il diario di bordo tenuto dal capitano della Silver Dawning, preservati dalle profondità oceaniche.",al={"contenuto dell'alba d'argento","cosa c'è nella scatola"}},{q="Chi sta cercando lo scrigno?",a="Gorbold Mandacciaio, un nano di stanza ad Auberdine, chiede a nuotatori coraggiosi di tuffarsi tra i relitti e recuperare lo scrigno affinché l'equipaggio superstite del capitano caduto possa onorarne degnamente la memoria.",al={"chi cerca lo scrigno","chi assegna la missione","consegnare lo scrigno"}}},fx={["9cc39920"]={q="Che cos'è lo Scrigno dell'Alba d'Argento?",a="È il forziere personale del defunto capitano dell'Alba d'Argento. Quando la nave fu assalita e affondata dai murloc al largo della costa settentrionale di Rivafosca, lo scrigno colò a picco insieme al relitto. Contiene il diario di bordo del capitano e gli effetti personali rimasti, sul fondo del mare, tra le creature in agguato.",al={"che cos'è lo scrigno dell'alba d'argento","storia dello scrigno dell'alba d'argento","scrigno del capitano dell'alba d'argento"}}},fp="24,255,15.531.0,46.161.0,36.193.0,27.130.0,27.191.0"}
P.entries["item:silvery-spinnerets"] = {n="Filatura Argentea",s="La Filatura Argentea viene raccolta dal grande ragno Lady Sathrah nel nord di Teldrassil. Un tempo utilizzata per tessere tele che catturavano la rugiada serale curativa per The Temple of the Moon, è ricercata dalle sacerdotesse di Elune per onorare l'anima della creatura caduta attraverso un sacro rituale di rinascita.",h="La Filatura Argentea viene raccolta dal grande ragno Lady Sathrah nel nord di Teldrassil.",kw={"lady sathrah","sacerdotessa a'moora","sacrificio di sathrah","filatura argentea","tears of the moon","temple of the moon","lago di buonpozzo"},ang={["class:Priest"]="Per i servitori di Elune, recuperare la filatura non è un contratto di sterminio, ma un sacro rito funebre volto a implorare la Madre Luna per la redenzione di una creatura.",["race:NightElf"]="La tragica fine di Lady Sathrah ricorda con amarezza ai Kaldorei che persino le creature amate da Elune sono vulnerabili alla crescente afflizione che affligge Teldrassil."},sec={{t="Tessitura sacra e corruzione",b="Lady Sathrah un tempo era annoverata tra le creature predilette di Elune, celebre per tessere tele scintillanti al chiaro di luna vicino al Lago di Buonpozzo. La sua seta argentata raccoglieva la foschia serale, formando rugiade curative molto apprezzate da The Sisterhood of Elune a Darnassus. Sfortunatamente, la corruzione che strisciava tra i rami di Teldrassil non la risparmiò. Caduta in una violenta follia, Sathrah divenne un pericolo per la sua stessa prole e per la foresta circostante. La Sacerdotessa A'moora chiede ai viaggiatori di porre fine alle sofferenze del ragno e di recuperare le sue filiere come atto di pietà, portando pace a una venerata abitante dei grandi rami."},{t="Un sacrificio per la rinascita",b="La filatura recuperata non viene cercata come un semplice trofeo o materiale d'artigianato. Al contrario, The Sisterhood of Elune la offre direttamente alla Dea della Luna presso la fontana centrale all'interno di The Temple of the Moon. Attraverso questa consacrazione, nota come Sacrificio di Sathrah, le sacerdotesse pregano affinché Elune accolga lo spirito della creatura, purifichi la follia che si è impadronita del suo corpo mortale e le conceda la pace nella rinascita."}},faq={{q="Dove si ottiene la Filatura Argentea?",a="Si recupera da Lady Sathrah, un grande ragno che si trova lungo i confini settentrionali di Teldrassil, vicino al Lago di Buonpozzo.",al={"dove trovare la filatura argentea","bottino filatura argentea","chi rilascia la filatura argentea"}},{q="Perché la Sacerdotessa A'moora vuole la filatura?",a="La Sacerdotessa A'moora cerca di offrirla a Elune come sacro sacrificio. Questo rituale onora l'antica purezza di Lady Sathrah e implora la dea di purificare lo spirito della bestia e di concederle pace e rinascita.",al={"perché amoora vuole la filatura argentea","scopo di tears of the moon"}},{q="Perché le tele di Lady Sathrah erano speciali?",a="Lady Sathrah tesseva una luminosa seta d'argento che catturava la foschia serale al chiaro di luna. La rugiada raccolta dalle sue tele possedeva una potente magia ristoratrice, che The Sisterhood of Elune conservava in The Temple of the Moon per scopi curativi.",al={"tele di lady sathrah","cosa faceva lady sathrah"}},{q="Perché Lady Sathrah è stata uccisa se era sacra?",a="È sprofondata in una follia incurabile insieme ad altre creature corrotte di Teldrassil. La sua aggressività metteva in pericolo la foresta e minacciava le sue future nidiate, portando le sacerdotesse a considerare la sua uccisione come un doloroso atto di misericordia.",al={"perché uccidere lady sathrah","perché sathrah è impazzita"}}},fx={["6e94bdc8"]={q="Che cosa sono le Filature Argentee?",a="Le Filature Argentee sono gli organi produttori di seta prelevati dal ragno sacro Lady Sathrah, nel nord di Teldrassil. In tempi più sereni, li usava per tessere fili d'argento scintillanti al chiaro di luna. Queste ragnatele catturavano la nebbia serale, producendo una rugiada miracolosa dalle potenti proprietà curative, molto apprezzata dalle Sacerdotesse di Elune.",al={"che cosa sono le filature argentee","informazioni sulle filature argentee","filature di lady sathrah"}},["48fdca9c"]={q="Da dove provengono le Filature Argentee?",a="Vengono raccolte da Lady Sathrah, un ragno gigante che vive vicino al Lago di Buonpozzo, lungo i confini settentrionali di Teldrassil. Un tempo venerata come creatura aggraziata e pura, benedetta da Elune, Sathrah è recentemente impazzita. Gli elfi della notte hanno dovuto porre fine alle sue sofferenze e recuperare i suoi resti sacri.",al={"origine delle filature argentee","chi ha prodotto le filature argentee","dove trovare le filature argentee"}}},fp="18,293,29.621.0,23.405.1,40.121.0,47.206.0,37.233.0,46.227.0"}
P.entries["item:simple-memorandum"] = {n="Promemoria Semplice",s="Il Promemoria Semplice è un avviso ufficiale consegnato ai guerrieri gnomi novizi che si addestrano a Valle Crestafredda. Con una concisa direttiva gnomesca, ordina alle reclute di presentarsi all'istruttore dei guerrieri Thran Khorman a Forgiamara per prepararsi alla guerra per riconquistare Gnomeregan.",h="Il Promemoria Semplice è un avviso ufficiale consegnato ai guerrieri gnomi novizi che si addestrano a Valle...",kw={"forgiamara","valle crestafredda","dun morogh","gnomeregan","promemoria semplice","thran khorman","addestramento dei guerrieri"},ang={["class:Warrior"]="Questa nota rappresenta il primo passo di un guerriero dalle scaramucce rudimentali all'addestramento al combattimento formale sotto la guida di Thran Khorman a Forgiamara.",["race:Gnome"]="Per gli esuli gnomi, il promemoria ricorda il loro obiettivo condiviso: affinare le abilità belliche al fianco dei loro alleati nani per prepararsi all'eventuale liberazione di Gnomeregan."},sec={{t="Una convocazione a Forgiamara",b="I novizi avventurieri a Valle Crestafredda si vedono spesso affidare lettere di presentazione man mano che dimostrano il proprio valore contro la fauna selvatica locale e le minacce dei trogg. Per i giovani combattenti gnomi, questo promemoria funge da ordine formale di fare rapporto a Thran Khorman, l'istruttore dei guerrieri residente a Forgiamara. I nani veterani riconoscono che, sebbene gli gnomi possano affidarsi all'intelletto e ai congegni, riconquistare Gnomeregan richiederà pura determinazione fisica e disciplina marziale. Il promemoria ordina a chi lo porta di mettere da parte i compiti preliminari e cercare un addestramento personalizzato nell'arte della guerra."}},faq={{q="Che cos'è il Promemoria Semplice?",a="È un messaggio scritto consegnato ai guerrieri gnomi novizi che operano a Valle Crestafredda, con l'ordine di fare rapporto all'istruttore dei guerrieri nano all'interno di Forgiamara.",al={"promemoria semplice","cos'è questa nota","oggetto promemoria"}},{q="Chi ha scritto il Promemoria Semplice?",a="Non reca alcuna firma. Sten Braccioforte presume provenga da Thran Khorman, ma parla di riconquistare la nostra patria di Gnomeregan, quindi è una direttiva gnomesca che ti ordina di fare rapporto a Thran, l'istruttore dei guerrieri nano a Forgiamara.",al={"chi ha scritto il promemoria","chi ha inviato la nota","autore del promemoria semplice"}},{q="Cosa succede dopo aver letto il Promemoria Semplice?",a="Una volta letto il documento, lo porti a Thran Khorman all'interno di Forgiamara. Egli riconosce la tua determinazione nel reclamare la tua patria perduta e si offre di addestrarti nelle tecniche fondamentali da guerriero.",al={"cosa faccio con il promemoria","dove lo porto","consegnare promemoria semplice"}},{q="Perché un nano addestra guerrieri gnomi?",a="In seguito alla caduta di Gnomeregan, i profughi gnomi si sono stabiliti sotto l'ospitalità di Forgiardente e Forgiamara. I nani veterani come Thran Khorman hanno messo a disposizione la propria esperienza marziale per aiutare i loro alleati esiliati ad addestrarsi e, infine, a riconquistare la loro città irradiata.",al={"perché thran addestra gli gnomi","nani che addestrano gnomi"}}},fx={b027c55a={q="Perché mi è stato consegnato il Promemoria Semplice?",a="Il promemoria è una direttiva degli gnomi che ti ordina di presentarti a Thran Khorman, l'addestratore di guerrieri nani a Forgiamara. In quanto guerriero gnomo sfollato, il tuo compito principale è prepararti alla guerra per riconquistare Gnomeregan, e Thran ha promesso di preparare te e il tuo popolo. Sten Braccioforte ti ha passato il messaggio mentre lo aiutavi nella Valle Crestafredda.",al={"perché il promemoria semplice","scopo del promemoria semplice","perché mi serve il promemoria semplice"}}},fp="17,266,21.605.0,30.160.0,32.230.0,49.194.0,39.260.0"}
P.entries["item:simple-rune"] = {n="Runa Semplice",s="Una Runa Semplice è un contrassegno di pietra inciso consegnato ai guerrieri nani alle prime armi che si addestrano nella Valle Crestafredda. Funge da convocazione da parte dell'istruttore dei guerrieri Thran Khorman, indicando alle reclute di cercare istruzione all'interno di Forgiamara.",h="Una Runa Semplice è un contrassegno di pietra inciso consegnato ai guerrieri nani alle prime armi che si...",kw={"forgiamara","valle crestafredda","dun morogh","runa dei nani","runa semplice","thran khorman","addestramento dei guerrieri"},ang={["class:Warrior"]="Per i guerrieri nani, questa pietra incisa segna il primo passo verso l'addestramento militare formale sotto la guida del veterano istruttore Thran Khorman.",["race:Dwarf"]="La runa di Thran Khorman promette a un giovane nano le basi del combattimento: l'impugnatura di un'ascia, il peso dell'armatura e il sudore della vera battaglia."},sec={{t="Una chiamata alle armi",b="Incisa con semplici segni marziali, la Runa Semplice viene consegnata alle reclute promettenti che hanno iniziato a eliminare le minacce nei dintorni della Valle Crestafredda. Più che un amuleto magico, funge da formale pietra di richiamo da parte di Thran Khorman, l'istruttore dei guerrieri residente a Forgiamara. Dopo aver letto la guida incisa, ci si aspetta che un giovane combattente si presenti direttamente da Thran per apprendere le tecniche di combattimento di base e ascoltare consigli pratici su come sopravvivere nelle lande ostili di Dun Morogh."}},faq={{q="Qual è lo scopo della Runa Semplice?",a="La Runa Semplice è una tavoletta didattica consegnata ai guerrieri novizi nella Valle Crestafredda. Leggerla ordina alla recluta di presentarsi a Thran Khorman all'interno di Forgiamara per l'addestramento formale.",al={"uso della runa semplice","cosa fa la runa","oggetto di missione runa semplice"}},{q="Chi invia la Runa Semplice?",a="Viene inviata da Thran Khorman, l'istruttore dei guerrieri nani di stanza all'interno di Forgiamara, che tiene d'occhio i combattenti promettenti che offrono aiuto nella valle.",al={"chi ha scritto la runa","chi mi ha dato la runa semplice","mittente della runa"}},{q="Dove porto la Runa Semplice?",a="Portala a Thran Khorman all'interno della grande sala della forgia di Forgiamara, situata nel centro della Valle Crestafredda.",al={"dove devo andare","consegna della runa","posizione di thran khorman"}}},fx={["0f0eb9fb"]={q="Che cos'è la Runa Semplice?",a="La Runa Semplice è una pietra nanica incisa, affidata ai guerrieri promettenti nella Valle Crestafredda. Non porta incantamenti mistici: è un ordine scritto di Thran Khorman, che convoca i combattenti novizi a Forgiamara per iniziare il loro addestramento marziale ufficiale.",al={"che cos'è la runa semplice","storia della runa semplice","oggetto runa semplice"}},["2d1fc984"]={q="Perché Thran Khorman vuole che tu abbia la Runa Semplice?",a="Thran Khorman ti invia la runa per reclutarti nell'addestramento formale dei guerrieri. Avendo intravisto il tuo potenziale nelle prime imprese nella Valle Crestafredda, vuole insegnarti la corretta disciplina marziale nanica e mostrarti cosa serve davvero per combattere per Forgiardente, mentre le minacce locali aumentano.",al={"perché thran invia la runa","perché mi serve la runa semplice","perché vogliono la runa semplice"}}},fp="11,227,17.463.0,39.198.0,26.145.0,32.102.0"}
P.entries["item:simple-sigil"] = {n="Sigillo Semplice",s="Un Sigillo Semplice è un modesto pegno di addestramento consegnato ai novizi guerrieri Elfi della Notte a Vallombra. Portato come convocazione da parte dell'istruttrice dei guerrieri Alyissia, segna l'introduzione formale di un giovane combattente alla difesa marziale di Teldrassil.",h="Un Sigillo Semplice è un modesto pegno di addestramento consegnato ai novizi guerrieri Elfi della Notte a...",kw={"alyissia","ilthalaine","guerriero kaldorei","vallombra","sigillo semplice","teldrassil","addestramento dei guerrieri"},ang={["class:Warrior"]="Per i guerrieri kaldorei, questo semplice pegno è la tua primissima credenziale, introducendoti alle tradizioni marziali necessarie a salvaguardare Teldrassil.",["race:NightElf"]="Il sigillo evidenzia l'urgenza che affrontano i kaldorei, mentre gli istruttori come Alyissia reclutano qualsiasi mano abile per arginare la crescente corruzione tra i rami dell'Albero del Mondo."},sec={{t="Una chiamata alle armi",b="Tra i rami riparati di Vallombra, i giovani Elfi della Notte vengono guidati dal Conservatore Ilthalaine a trovare la propria vocazione. Ai guerrieri alle prime armi, Ilthalaine consegna un Sigillo Semplice inviato tramite un messaggero dall'istruttrice dei guerrieri Alyissia. Recante un'iscrizione che ordina alla recluta di presentarsi per l'istruzione, questo pegno rappresenta l'inizio di un addestramento marziale disciplinato in tempi difficili per l'Albero del Mondo."},{t="Il fardello della difesa",b="Quando viene portato ad Alyissia, il sigillo apre un dialogo sullo stato critico dei kaldorei. La recente crescita di Teldrassil, la corruzione strisciante che contamina le bestie della foresta e la riscoperta di terre lontane come Feralas hanno ridotto all'estremo i difensori Elfi della Notte. Il sigillo non è un manufatto di potere, ma una credenziale pratica che accoglie la recluta tra i guardiani incaricati di proteggere il proprio popolo dalle minacce emergenti."}},faq={{q="Cos'è il Sigillo Semplice?",a="È un pegno introduttivo inciso consegnato ai novizi guerrieri Elfi della Notte dal Conservatore Ilthalaine a Vallombra. Ordina al portatore di presentarsi ad Alyissia per l'addestramento formale da guerriero.",al={"oggetto sigillo semplice","cosa fa il sigillo semplice","cos'è questo sigillo"}},{q="Chi invia il Sigillo Semplice?",a="Il sigillo viene spedito da un messaggero per conto di Alyissia, l'istruttrice dei guerrieri di Vallombra, che desidera iniziare a istruire nuovi guerrieri per la difesa di Teldrassil.",al={"chi ha creato il sigillo","chi ha inviato il sigillo semplice"}},{q="Cosa dovrei farne?",a="Leggi il testo inciso e consegnalo ad Alyissia vicino alla base di Aldrassil a Vallombra per iniziare il tuo addestramento da guerriero.",al={"dove consegnare il sigillo semplice","chi accetta il sigillo semplice"}},{q="Il sigillo conferisce abilità speciali?",a="No. È semplicemente un avviso scritto e una credenziale intesa a presentare gli aspiranti guerrieri al loro mentore.",al={"poteri del sigillo","statistiche del sigillo semplice"}}},fp="12,238,17.413.0,21.439.0,25.188.0,27.178.0,25.126.0,43.102.0"}
P.entries["item:simple-tablet"] = {n="Tavoletta Semplice",s="La Tavoletta Semplice è una missiva scritta consegnata ai novizi guerrieri troll che giungono nella Valle delle Sfide. Consegnata da Gornek, indirizza il combattente alle prime armi a presentarsi a Frang, l'istruttore dei guerrieri locale.",h="La Tavoletta Semplice è una missiva scritta consegnata ai novizi guerrieri troll che giungono nella Valle...",kw={"lanciascura","durotar","frang","gornek","tavoletta semplice","antro del tirocinio","valle delle sfide","istruttore dei guerrieri"},ang={["class:Warrior"]="La tavoletta segna la presentazione formale di un guerriero troll a Frang, dando inizio al suo addestramento al combattimento all'interno dell'Orda.",["race:Troll"]="Per i Troll Lanciascura che si ritagliano il proprio posto a fianco degli orchi a Durotar, ricevere la convocazione simboleggia il dovere di rinforzare i ranghi in prima linea."},sec={{t="Una Chiamata alla Battaglia",b="Tra i duri confini rossi della Valle delle Sfide, le nuove reclute vengono rapidamente messe al lavoro. Ai giovani troll che intraprendono la via del guerriero, Gornek consegna questa semplice lastra o pergamena. Scritta dal troll Tar'sere e indirizzata a Frang, il maestro d'armi che riposa vicino all'Antro del Tirocinio, funge da presentazione ufficiale per l'addestramento marziale a Durotar. Esorta la recluta a farsi avanti, presentarsi e dimostrare la propria volontà di impugnare le armi sotto lo stendardo dell'Orda."}},faq={{q="Che cos'è la Tavoletta Semplice?",a="È un messaggio scritto introduttivo consegnato da Gornek agli aspiranti guerrieri troll nella Valle delle Sfide. Li invita a leggerlo e a cercare Frang per ricevere un addestramento al combattimento professionale.",al={"tavoletta semplice","cos'è questa tavoletta","tavoletta guerriero troll"}},{q="Chi invia la tavoletta?",a="Il messaggio è firmato dal troll Tar'sere, che manda la recluta da Frang, l'istruttore dei guerrieri di stanza fuori dall'Antro del Tirocinio nella Valle delle Sfide.",al={"chi ha inviato la tavoletta semplice","chi ha scritto la tavoletta","mittente della tavoletta"}},{q="Dove porto la tavoletta?",a="Portala a Frang, che si trova a riposare all'ombra fuori dall'ingresso dell'Antro del Tirocinio nella Valle delle Sfide.",al={"a chi consegno la tavoletta semplice","dove portare la tavoletta","posizione di frang"}},{q="Chi riceve questa tavoletta?",a="La Tavoletta Semplice viene fornita nello specifico ai guerrieri troll che iniziano i loro riti di passaggio nella Valle delle Sfide.",al={"chiunque può ottenere la tavoletta semplice","quale classe riceve la tavoletta semplice"}}},fx={["219776b3"]={q="Perché Frang ti manda la Tavoletta Semplice?",a="In realtà Frang non l'ha scritta. Gornek suppone che venga da Frang, ma la tavoletta è firmata dal troll Tar'sere, che ti manda da Frang, fuori dall'Antro del Tirocinio. Frang ha bisogno di astuti guerrieri troll che mostrino agli orchi come combattere anche con l'ingegno, non solo con la forza, e può addestrarti per le battaglie future dell'Orda.",al={"perché la tavoletta semplice","perché frang mi vuole","scopo della tavoletta semplice"}}},fp="13,219,19.491.0,26.186.0,21.147.0,27.113.0,25.118.0"}
P.entries["item:singed-scale"] = {n="Scaglia Strinata"}
P.entries["item:skeleton-finger"] = {n="Dito di Scheletro",s="Un dito osseo reciso, recuperato dai morti viventi che si aggirano nei boschetti e nei cimiteri maledetti di Boscovespro. Dama Eva di Borgoscuro raccoglie questi macabri resti insieme a zanne di ghoul e veleno di ragno per creare talismani protettivi.",h="Un dito osseo reciso, recuperato dai morti viventi che si aggirano nei boschetti e nei cimiteri maledetti di...",kw={"borgoscuro","boscovespro","zanna di ghoul","dama eva","predone scheletrico","dito di scheletro","totem del castigo"},ang={["class:Mage"]="I maghi che studiano la divinazione popolare troveranno nel metodo di Dama Eva di trasformare dita scheletriche e veleni naturali in un incantamento di ritorsione un insolito connubio di stregoneria agreste e magia simpatica.",["class:Paladin"]="I paladini potrebbero rabbrividire all'idea di profanare resti scheletrici e trasportarne le parti recise, eppure nella cupa desolazione di Boscovespro, riutilizzare le ossa degli empi per proteggere i vivi è una cupa necessità."},sec={{t="Ossa degli Irrequieti",b="I boschi maledetti di Boscovespro sono invasi dai resti irrequieti dei morti, che spaziano da predoni e guerrieri scheletrici a maghi necrotici e immondi. Mentre i comuni viaggiatori evitano di toccare i nauseanti resti dei morti risorti, cartomanti e mistici apprezzano la loro fredda essenza. Dama Eva, la veggente residente a Borgoscuro, raccoglie queste dita ossee per vincolare le loro persistenti energie necrotiche in un'interdizione di magia di ritorsione nota come Totem del Castigo."}},faq={{q="Quali creature rilasciano un Dito di Scheletro?",a="Le Dita di Scheletro si ottengono dai vari non morti scheletrici presenti in tutta Boscovespro, tra cui Skeletal Raider, Healer, Warder, Warrior, Horror, Fiend e Skeletal Mage.",al={"dove si trovano le dita di scheletro","cosa rilascia dita di scheletro","fonte dito di scheletro"}},{q="Chi vuole le Dita di Scheletro a Boscovespro?",a="Dama Eva, la divinatrice che risiede a Borgoscuro, le richiede come parte dei componenti rituali necessari per incantare un'interdizione protettiva.",al={"chi ha bisogno di dita di scheletro","chi assegna la missione dito di scheletro","a cosa servono le dita di scheletro"}},{q="Cos'è il Totem del Castigo?",a="È un'interdizione incantata creata da Dama Eva usando dita di scheletro, zanne di ghoul e veleno di ragno. Intreccia le loro oscure energie in un'aura progettata per infliggere danni di ritorsione a chiunque tenti di fare violenza al portatore.",al={"scopo del totem del castigo","cosa crea dama eva"}},{q="Perché Dama Eva ha bisogno di resti di non morti per un amuleto protettivo?",a="I rituali di Dama Eva incanalano la corruzione latente e l'aggressività che risiedono nei mostri locali. Vincolando insieme le essenze violente di scheletri, ghoul e bestie velenose di Boscovespro, trasforma la loro stessa persistente malvagità in un'interdizione che punisce gli aggressori ostili.",al={"perché la magia delle ossa","perché dita di scheletro per il totem"}}},fx={["7c732e26"]={q="Che cos'è un Dito di Scheletro?",a="Un Dito di Scheletro è un frammento osseo reciso e disseccato, prelevato da uno degli orrori scheletrici animati che vagano per le foreste corrotte e le cripte di Boscovespro. Preservate dalla corruzione necromantica che ha invaso la regione, queste dita conservano tracce della magia oscura che mantiene gli inquieti non morti in movimento.",al={"che cos'è un dito di scheletro","che cosa sono le dita di scheletro","identificare un dito di scheletro"}},a7de6990={q="Da dove viene un Dito di Scheletro?",a="Queste dita provengono dai resti scheletrici risvegliati nei cimiteri infestati e tra le rovine di Boscovespro. Non vengono create né fabbricate: sono raccolte direttamente dai cadaveri animati, come guerrieri, demoni, custodi e razziatori scheletrici, che strisciano nell'oscurità, animati dalla misteriosa corruzione che si diffonde nei boschi.",al={"origine del dito di scheletro","da dove vengono le dita di scheletro","chi ha prodotto il dito di scheletro"}}},fp="15,234,21.460.0,38.179.0,39.130.0,32.235.0,63.269.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Borraccia di Rum Dolce",s="Una Borraccia di Rum Dolce è un liquore speciale proveniente dalla Locanda del Fiero Leone a Borgodoro. È ricercata da Daniels l'Oste a Borgolago, che cerca disperatamente di rifornire la sua taverna mentre gli orchi Roccianera tagliano fuori Crestarossa dalle normali rotte commerciali.",h="Una Borraccia di Rum Dolce è un liquore speciale proveniente dalla Locanda del Fiero Leone a Borgodoro.",kw={"daniels l'oste","dry times","borgodoro","borgolago","locanda del fiero leone","borraccia di rum dolce","rum dolce"},ang={["faction:Alliance"]="Procurarsi questo rum evidenzia la pressione logistica che l'invasione degli orchi Roccianera ha imposto ai piccoli insediamenti che difendono i confini orientali del regno di Roccavento."},sec={{t="Un raro conforto per Borgolago",b="Nella cittadina di Borgolago, stremata dalla guerra, le scorte della taverna stanno scarseggiando pericolosamente. L'invasione degli orchi Roccianera ha bloccato le vie di rifornimento dirette alle Montagne Crestarossa, costringendo Daniels l'Oste ad affannarsi per placare la sete delle guardie cittadine in difficoltà e dei rifugiati. Per rifornire i suoi scaffali ormai vuoti, Daniels invia i viaggiatori attraverso il regno a raccogliere specialità regionali, tra cui un otre pieno del caratteristico rum dolce distillato e servito nella Locanda del Fiero Leone di Borgodoro."}},faq={{q="Dove posso trovare una Borraccia di Rum Dolce?",a="Una Borraccia di Rum Dolce può essere acquistata direttamente dal locandiere o barista presso la Locanda del Fiero Leone a Borgodoro, situata nella Foresta di Elwynn.",al={"posizione del rum dolce","dove comprare il rum dolce","chi vende il rum dolce"}},{q="Chi vuole questo rum?",a="Daniels l'Oste, il proprietario della taverna di Borgolago, richiede una borraccia di rum dolce insieme a diverse altre bevande regionali per rifornire le sue scorte esaurite durante la missione Dry Times.",al={"chi ha bisogno del rum dolce","consegna del rum dolce","missione del rum dolce"}},{q="Perché Borgolago sta esaurendo gli alcolici?",a="L'improvvisa escalation dell'invasione degli orchi Roccianera a Crestarossa ha interrotto le linee commerciali e ritardato le spedizioni verso la cittadina. Con i normali carri mercantili impossibilitati a percorrere le strade in sicurezza, le scorte locali sono quasi del tutto vuote.",al={"perché sono a corto di alcolici","perché borgolago è a secco","motivo di dry times"}},{q="Quali altri alcolici servono oltre al rum?",a="Oltre alla Borraccia di Rum Dolce di Borgodoro, Daniels l'Oste necessita anche di un barilotto di Thunderbrew Lager dalle Marche Occidentali, un Barile di Merlot da Roccavento e una Bottiglia di Torcibudella da Borgoscuro.",al={"bevande di dry times","lista bevande di daniels","altri alcolici necessari"}}},fx={efbd5e13={q="Che cos'è una Borraccia di Rum Dolce?",a="La Borraccia di Rum Dolce è una borraccia di pelle piena di liquore zuccherino, venduta a Borgodoro, nella Foresta di Elwynn. È una delle specialità alcoliche regionali apprezzate nei regni umani dell'Azeroth meridionale.",al={"che cos'è il rum dolce","informazioni sulla borraccia di rum dolce","rum dolce"}}},fp="17,252,28.488.0,37.140.0,19.186.0,39.216.0,48.196.0"}
P.entries["item:skittering-blood"] = {n="Sangue Brulicante",s="Il Sangue Brulicante è un reagente alchemico raccolto dagli aracnidi che dimorano nell'Oscurità Brulicante di Selva Pinargento. Serve come ingrediente tossico vitale per le ricerche della Società degli Speziali Reali su The New Plague progettata per sradicare sia il Flagello che l'umanità.",h="Il Sangue Brulicante è un reagente alchemico raccolto dagli aracnidi che dimorano nell'Oscurità Brulicante di...",kw={"faranell","the new plague","renferrel","società degli speziali reali","selva pinargento","sangue brulicante","oscurità brulicante","skitterweb"},ang={["faction:Horde"]="Gli speziali dei Reietti accolgono con favore le materie prime per rendere sicura Lordaeron, combattendo la loro guerra contro il Flagello con armi di propria fabbricazione.",["race:Undead"]="Contribuire con il Sangue Brulicante aiuta direttamente la Regina Sylvanas e la Società degli Speziali Reali a progettare l'arma biologica definitiva contro Arthas e l'umanità vivente."},sec={{t="Un distillato tossico",b="Estratta dai predatori Skitterweb, dagli assalitori e dalla loro matriarca Krethis la Filatrice d'Ombre, questa emolinfa velenosa possiede proprietà virulente molto apprezzate dagli alchimisti dei Reietti. Lo Speziale Renferrel scoprì che, se raffinato insieme alle tossine estratte dai cuori di orso brizzolato, il sangue forma la base di un elisir eccezionalmente letale. I composti all'interno del fluido dimostrano gravi agenti contaminanti, rendendolo un catalizzatore biologico ideale per gli esperimenti chimici dell'Apothecarium."},{t="Alimentare The New Plague",b="Sotto la direzione del Maestro Speziale Faranell a Sepulcra, la Società degli Speziali Reali raccoglie reagenti come il Sangue Brulicante per progettare una devastante New Plague. Di fronte alle soverchianti orde del Flagello e ai resti ostili dell'umanità, i Reietti ricorrono alla guerra biologica come mezzo di riscatto. Faranell analizza la potenza tossica del sangue per sviluppare un contagio abbastanza potente da spegnere sia la non-morte che la carne vivente."}},faq={{q="A cosa serve il Sangue Brulicante?",a="La Società degli Speziali Reali utilizza il Sangue Brulicante per sviluppare la New Plague dei Reietti. Quando viene miscelato con tossine derivate da cuori d'orso, produce una miscela volatile che il Maestro Speziale Faranell studia per sradicare sia i non morti del Flagello che gli umani viventi.",al={"uso del sangue brulicante","perché raccogliere sangue di ragno","cosa fa faranell con il sangue brulicante"}},{q="Dove si trova il Sangue Brulicante?",a="Si raccoglie dai corpi dei ragni Skitterweb (inclusi predatori, assalitori e Krethis la Filatrice d'Ombre) in agguato dentro e intorno all'Oscurità Brulicante, un bosco tetro e soffocato da ragnatele situato nella parte nord-occidentale di Selva Pinargento.",al={"dove trovare sangue brulicante","posizione sangue brulicante","chi rilascia sangue brulicante"}},{q="Chi richiede questi campioni?",a="Lo Speziale Renferrel a Mausolea, a Selva Pinargento, commissiona la raccolta del sangue, ordinando agli avventurieri di consegnare il fluido raccolto direttamente al Maestro Speziale Faranell nell'Apothecarium di Sepulcra.",al={"chi richiede sangue brulicante","chi assegna la missione per il sangue brulicante"}},{q="Perché i Reietti hanno bisogno del veleno delle bestie locali?",a="La Società degli Speziali Reali isola costantemente le tossine naturali dalla fauna corrotta di Lordaeron. Il veleno intrinseco degli aracnidi giganti di Selva Pinargento fornisce agenti patogeni biologici grezzi che possono essere concentrati e trasformati in armi biologiche sotto forma di piaghe sintetiche.",al={"perché il veleno di ragno","ricerca degli speziali sulle bestie"}}},fx={["8eea8a63"]={q="Che cos'è il Sangue Brulicante?",a="Il Sangue Brulicante è un icore virulento estratto dai ragni giganteschi che vivono nell'Oscurità Brulicante della Selva Pinargento. Le sue proprietà naturalmente velenose e contaminanti lo rendono un reagente biologico prezioso per gli esperimenti alchemici.",al={"che cos'è il sangue brulicante","oggetto sangue brulicante","informazioni sul sangue brulicante"}},f7d32240={q="Da dove viene il Sangue Brulicante e chi l'ha prodotto?",a="Non viene prodotto: si estrae naturalmente dagli aracnidi predatori che vivono nella zona nordoccidentale della Selva Pinargento, tra cui gli agguatatori e gli assalitori di Ragnatele Brulicanti e la matriarca Krethis Tessombra. Il sangue viene estratto direttamente dalle loro carcasse dai cacciatori che raccolgono materiali per i Reietti.",al={"da dove viene il sangue brulicante","chi ha prodotto il sangue brulicante","origine del sangue brulicante"}}},fp="16,277,18.498.0,22.420.0,34.266.0,32.226.0,27.229.0,49.251.0"}
P.entries["item:sleepers-key"] = {n="Chiave dei Dormienti",s="La Chiave dei Dormienti è una delle tre chiavi incantate create dai druidi elfi della notte per sigillare la loro sacra cripta all'interno dell'Eremo Grinfialunga, in cima al Picco di Petrartiglio. Custodita al sicuro dentro un nascondiglio segreto apribile con la Chiave del Custode del Portale, è una delle tre chiavi necessarie per aprire il tesoro dei druidi.",h="La Chiave dei Dormienti è una delle tre chiavi incantate create dai druidi elfi della notte per sigillare la...",kw={"chiave del custode del portale","scrigno dei dormienti","chiave dei dormienti","picco di petrartiglio","eremo grinfialunga","tesoro dell'eremo grinfialunga","antro del tirocinio"},ang={["class:Druid"]="Le chiavi e i nascondigli dell'Eremo Grinfialunga mostrano le difese a più livelli dei druidi elfi della notte, che utilizzavano nascondigli segreti e serrature con chiave per sigillare reliquie di potere.",["faction:Horde"]="L'acquisizione della Chiave dei Dormienti fa parte di un'incursione orchestrata nel cuore del Picco di Petrartiglio, volta a infrangere le barriere difensive degli elfi della notte per rivendicare le reliquie sigillate nel loro tesoro."},sec={{t="Una misura di sicurezza druidica",b="Scavato nelle alture del Picco di Petrartiglio, l'Eremo Grinfialunga funge da ridotto e santuario per i druidi di Kalimdor. Consapevoli che le loro sacre reliquie e i loro potenti tesori avrebbero potuto attirare attenzioni indesiderate, i custodi elfi della notte idearono un intricato sistema di serrature e nascondigli segreti per proteggere il loro tesoro. La Chiave dei Dormienti costituisce un terzo di tale barriera protettiva. Collocata all'interno di un nascondiglio appartato nelle profondità dell'antro, può essere recuperata solo usando la Chiave del Custode del Portale, nascosta vicino alla soglia. Assieme alla Chiave del Bivalve e alla Chiave del Tumulo, la Chiave dei Dormienti deve essere inserita nelle serrature di pietra del Talon Den Hoard per dissolvere la barriera e rivelare gli antichi oggetti custoditi al suo interno."}},faq={{q="A cosa serve la Chiave dei Dormienti?",a="La Chiave dei Dormienti viene usata assieme alla Chiave del Tumulo e alla Chiave del Bivalve per aprire il Talon Den Hoard, una cripta di pietra protetta da una barriera e nascosta nelle profondità dell'antro del tumulo presso il Picco di Petrartiglio.",al={"a cosa serve la chiave dei dormienti","scopo della chiave dei dormienti","chiavi del tesoro dell'eremo grinfialunga"}},{q="In che modo è stata rinchiusa la Chiave dei Dormienti?",a="I druidi la collocarono all'interno della Sleepers' Cache nelle gallerie nordoccidentali dell'Eremo Grinfialunga. L'apertura di quel nascondiglio richiede la Chiave del Custode del Portale, che i druidi occultarono all'interno di una modesta lanterna vicino all'ingresso dell'antro.",al={"dove si trova la chiave dei dormienti","aprire lo scrigno dei dormienti","requisito chiave del custode del portale"}},{q="Perché i druidi hanno nascosto le loro reliquie con più chiavi?",a="I druidi elfi della notte idearono complesse misure di sicurezza affinché i loro potenti oggetti e le loro sacre reliquie non cadessero mai in mano nemica qualora l'antro venisse attaccato. Distribuire le chiavi in nascondigli segreti garantiva che gli intrusi non potessero saccheggiare facilmente il loro tesoro.",al={"perché così tante chiavi","difesa dell'eremo grinfialunga","enigma del tesoro dei druidi"}},{q="Perché si chiama Chiave dei Dormienti?",a="I druidi non spiegano mai questo nome. La chiave lo condivide semplicemente con la Sleepers' Cache, il forziere nascosto nell'Eremo Grinfialunga dove è custodita.",al={"chi sono i dormienti","significato nome chiave dei dormienti"}}},fx={["0a862a33"]={q="Che cos'è la Chiave dei Dormienti?",a="La Chiave dei Dormienti è una delle tre chiavi speciali forgiate dai druidi elfi della notte del Picco di Petrartiglio. Nascosta in un deposito chiuso a chiave, nel cuore dell'Eremo Grinfialunga, è una componente essenziale del sistema di protezione che custodisce il tesoro centrale dei druidi, composto da reliquie sacre.",al={"cos'è la chiave dei dormienti","storia della chiave dei dormienti","informazioni sulla chiave dei dormienti"}},["8275ad63"]={q="Da dove proviene la Chiave dei Dormienti e chi l'ha creata?",a="La chiave fu forgiata dai druidi che fondarono l'Eremo Grinfialunga sul Picco di Petrartiglio. Per proteggere i loro potenti artefatti dagli intrusi, idearono un elaborato sistema di sicurezza e chiusero la chiave in uno scrigno apposito chiamato Cassa dei Dormienti.",al={"chi ha creato la chiave dei dormienti","origine della chiave dei dormienti","da dove viene la chiave dei dormienti"}},["3884172c"]={q="Perché qualcuno vuole la Chiave dei Dormienti?",a="L'Orda cerca la chiave per aggirare le difese dei druidi e aprire il Tesoro dell'Eremo Grinfialunga. Insieme alla Chiave del Bivalve e alla Chiave del Tumulo, apre il caveau di pietra che custodisce le potenti reliquie riposte dai druidi sul Picco di Petrartiglio.",al={"perché cercare la chiave dei dormienti","perché serve la chiave dei dormienti","chi vuole la chiave dei dormienti"}}},fp="13,274,19.668.0,35.167.0,38.224.0,56.258.0,35.137.0"}
P.entries["item:smoky-iron-ingot"] = {n="Lingotto di Ferro Fumoso",s="I Lingotti di Ferro Fumoso sono barre di metallo lavorate rozzamente, fuse dai coboldi dei siti di scavo di Windshear nelle Vette di Petrartiglio. Gli armaioli orcheschi apprezzano questi lingotti come materia prima per forgiare robusti equipaggiamenti di maglia adatti ai guerrieri dell'Orda.",h="I Lingotti di Ferro Fumoso sono barre di metallo lavorate rozzamente, fuse dai coboldi dei siti di scavo di...",kw={"brutal armor","coboldo","lingotto di ferro fumoso","petrartiglio","thun'grim firegaze","guerriero","tagliavento"},ang={["class:Warrior"]="Per i guerrieri dell'Orda, ottenere questi lingotti è una prova di resistenza a Petrartiglio, fungendo da componente essenziale per forgiare la Brutal Hauberk.",["profession:Blacksmithing"]="La qualità grezza di questi lingotti illustra i metodi primitivi di fusione degli scavatori coboldi rispetto alle tecniche raffinate praticate dai fabbri addestrati."},sec={{t="Metallurgia Grezza dei Coboldi",b="All'interno dei cunicoli anneriti dalla fuliggine della Landa di Tagliavento nelle Vette di Petrartiglio, i coboldi scavano in profondità nella terra rocciosa, estraendo minerale grezzo dai pendii e fondendolo su rudimentali fuochi fumanti. I Lingotti di Ferro Fumoso che ne risultano sono tutt'altro che perfetti — densi di residui e carbone vegetale — eppure abbastanza compatti da mantenere una notevole resistenza alla trazione."},{t="Forgiare la Brutal Armor",b="L'armaiolo orco quasi cieco Thun'grim Firegaze, che lavora in un accampamento aspro affacciato su The Barrens, richiede specificamente questi lingotti per creare armature destinate ai guerrieri provati dell'Orda. Unito a barre di ferro raffinato, Azurite Polverosa e volatile phlogiston, il metallo fumoso funge da nucleo resistente per fabbricare Brutal Hauberk."}},faq={{q="Da dove provengono i Lingotti di Ferro Fumoso?",a="I Lingotti di Ferro Fumoso sono trasportati dai coboldi che abitano i siti di scavo e le gallerie di Windshear nelle Vette di Petrartiglio orientali, inclusi scavatori, tagliapietre, parassiti, geomanti e i loro sovrintendenti.",al={"dove trovare il lingotto di ferro fumoso","posizione lingotto di ferro fumoso","chi rilascia i lingotti di ferro fumoso"}},{q="A cosa servono i Lingotti di Ferro Fumoso?",a="Vengono raccolti dai guerrieri che rispondono alla chiamata di Thun'grim Firegaze, un maestro armaiolo che risiede sulle vette vicino a Crossroads in The Barrens. Richiede quindici di questi lingotti per forgiare l'iconica Brutal Hauberk.",al={"uso lingotto di ferro fumoso","a cosa serve il lingotto di ferro fumoso","oggetto missione brutal armor"}},{q="Perché i lingotti sono descritti come \\\"fumosi\\\"?",a="I coboldi impiegano tecniche di fusione rozze e a bassa combustione nelle loro buie gallerie. Il metallo risultante trattiene fuliggine, polvere di carbone e cenere dalle loro fumose fornaci sotterranee invece di essere raffinato fino a una lucentezza pulita.",al={"perché è fumoso","storia del ferro fumoso"}},{q="Qualsiasi fabbro può creare oggetti con questi lingotti?",a="No. I Lingotti di Ferro Fumoso sono barre irregolari e incrostate di fuliggine, inutilizzabili nella forgiatura commerciale standard. Solo fabbri specializzati come Thun'grim Firegaze sanno come integrarli in equipaggiamenti da combattimento personalizzati.",al={"i giocatori possono forgiare il ferro fumoso","il ferro fumoso è un bene commerciale"}}},fx={["18404e72"]={q="Che cos'è un Lingotto di Ferro Fumoso?",a="I Lingotti di Ferro Fumoso sono barre di ferro scuro, grezzamente fuse e striate di fuliggine, che si trovano in possesso dei koboldi di Tagliavento, intenti a scavare nelle profondità delle Vette di Petrartiglio. Sono rozzi rispetto ai metalli lavorati con cura, ma possiedono comunque la robustezza necessaria ai fabbri esperti che vogliono forgiare armature pesanti e resistenti.",al={"cos'è un lingotto di ferro fumoso","informazioni sul lingotto di ferro fumoso","parlami del lingotto di ferro fumoso"}},["9ee5c553"]={q="Da dove proviene il Lingotto di Ferro Fumoso e chi lo ha creato?",a="Questi lingotti vengono estratti e fusi dai koboldi della Landa di Tagliavento, nelle Vette di Petrartiglio. Nelle loro gallerie sotterranee, minatori e parassiti dissotterrano il minerale grezzo e lo fondono in lingotti di ferro utilizzabili, per rafforzare le loro attività nel sottosuolo e armare le loro bande di guerra.",al={"provenienza del lingotto di ferro fumoso","da dove provengono i lingotti di ferro fumoso","chi produce il lingotto di ferro fumoso"}},["8ab45f92"]={q="Perché qualcuno vuole il Lingotto di Ferro Fumoso?",a="Thun'grim Firegaze, il maestro fabbro orco quasi cieco che vive in cima alle scogliere delle Savane, ne richiede quindici per forgiare Brutal Armor per i guerrieri dell'Orda che se ne dimostrano degni. Combinato con altri rari agenti alchemici e minerali, questo metallo grezzo è il materiale di base per un'armatura progettata per resistere a una guerra brutale.",al={"perché procurarsi il lingotto di ferro fumoso","chi vuole il lingotto di ferro fumoso","storia dell'uso del lingotto di ferro fumoso"}}},fp="16,233,23.354.0,24.338.0,37.202.0,36.215.0,40.215.0,43.196.0"}
P.entries["item:smoldering-embers"] = {n="Braci Infuocate",s="Le Braci Infuocate sono i resti incandescenti e arroventati recuperati dai furiosi elementali del fuoco della Valle Bruciata. Le Sentinelle degli Elfi della Notte cercano queste ceneri come prova tangibile che i terrori infuocati che invadono il bosco devastato vengono sottomessi.",h="Le Braci Infuocate sono i resti incandescenti e arroventati recuperati dai furiosi elementali del fuoco della...",kw={"burning destroyer","burning ravager","valle bruciata","enraged spirits","kaela freccianera","rogue flame spirit","braci infuocate","petrartiglio","s.p.r. & co."},ang={["class:Druid"]="I druidi considerano le braci come la tragica prova della natura sbilanciata dall'avidità industriale, dove la furia incontrollata degli elementali impedisce al suolo soffocato dalla cenere di rigenerarsi.",["race:NightElf"]="Per gli Elfi della Notte, vedere la Valle Bruciata in fiamme è una ferita straziante su Kalimdor. Raccogliere queste braci è un solenne dovere per purificare la profanazione straniera e riportare la pace sotto lo sguardo di Elune."},sec={{t="Resti della Valle Bruciata",b="Il disboscamento implacabile e la devastazione industriale della S.P.R. & Co. hanno squarciato la Valle Bruciata, incendiando la foresta e scatenando una furia distruttiva dalle viscere della terra. Sulla loro scia, elementali di fuoco vivente — Burning Ravagers, Burning Destroyers e Rogue Flame Spirits erranti — sono sciamati attraverso il bacino bruciato. Queste Braci Infuocate sono i nuclei persistenti e coperti di cenere lasciati quando un elementale viene estinto, a testimonianza del fatto che gli incendi divampanti della valle vengono sistematicamente soppressi."}},faq={{q="Da dove provengono le Braci Infuocate?",a="Le Braci Infuocate vengono raccolte dagli elementali del fuoco che infestano la Valle Bruciata nelle Vette di Petrartiglio meridionali, compresi Burning Ravagers, Burning Destroyers e Rogue Flame Spirits.",al={"dove trovare le braci infuocate","chi rilascia le braci infuocate","fonte delle braci infuocate"}},{q="Perché Kaela Freccianera vuole queste braci?",a="Kaela Freccianera le cerca come prova inconfutabile che i dilaganti elementali del fuoco nella Valle Bruciata vengono abbattuti. Crede che la terra ferita non potrà mai guarire sotto Elune's Grace finché questi spiriti violenti vagheranno indisturbati.",al={"perché raccogliere le braci infuocate","braci di kaela freccianera","obiettivo enraged spirits"}},{q="Cosa ha causato la comparsa degli elementali del fuoco nella Valle Bruciata?",a="La S.P.R. & Co. ha utilizzato macchinari aggressivi e incendi indiscriminati per disboscare l'antica foresta. Il loro sfruttamento sconsiderato ha destabilizzato la terra, dissotterrando e scatenando ostili elementali di fiamma e pietra che alla fine hanno scacciato i goblin.",al={"cosa è successo alla valle bruciata","perché ci sono elementali del fuoco a petrartiglio","spiriti del fuoco s.p.r. & co."}}},fx={["4d13fc7e"]={q="Che cosa sono le Braci Infuocate?",a="Le Braci Infuocate sono i resti materiali ardenti lasciati dagli elementali del fuoco distruttivi che infestano la Valle Bruciata. Questi residui incandescenti rimangono dopo aver ucciso creature come Devastatori Ardenti, Spiriti della Fiamma Vaganti e Distruttori Ardenti, e sono la prova tangibile che la loro furia di fuoco nella foresta devastata è stata domata.",al={"cosa sono le braci infuocate","storia delle braci infuocate","cos'è una brace infuocata"}}},fp="17,253,28.538.0,37.189.0,45.228.0,62.255.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Scatola di Tabacco di Snellig",s="La Scatola di Tabacco di Snellig è un ricordo personale recuperato dall'inquieto non morto Primo Ufficiale Snellig tra i relitti della Flotta Perduta. Riportare questo gingillo al Primo Ufficiale Fitzsimmons a Porto di Menethil serve come prova che il suo ex compagno di ciurma maledetto ha finalmente trovato la pace.",h="La Scatola di Tabacco di Snellig è un ricordo personale recuperato dall'inquieto non morto Primo Ufficiale...",kw={"ciurma maledetta","fitzsimmons","kul tiras","flotta perduta","snellig","scatola di tabacco","the third fleet","wetlands"},ang={["faction:Alliance"]="Recuperare i beni dei marinai caduti di Kul Tiras e concedere il riposo ai loro spiriti maledetti è un cupo dovere al servizio di un antico alleato navale dell'Alleanza."},sec={{t="Un ricordo della The Third Fleet",b="Quando la The Third Fleet di Kul Tiras si arenò lungo le coste settentrionali delle Wetlands, i suoi marinai e ufficiali non trovarono una morte serena. Legata da un potere misterioso e oscuro vincolato a un tesoro nascosto a bordo delle navi, la ciurma annegata risorse sotto forma di spiriti tormentati e non morti scheletrici. Tra di loro c'era il Primo Ufficiale Snellig, che infesta ancora la stiva marcescente del relitto più vicino alla costa. Persino nella morte è rimasto aggrappato alla sua scatola di tabacco: un piccolo, ordinario ricordo della sua vita mortale sul mare. Per l'unico superstite vivente del disastro, il Primo Ufficiale Fitzsimmons, recuperare questo piccolo possesso offre la prova tangibile che almeno uno dei suoi compagni di bordo perduti è stato liberato da un'eternità di tormento."}},faq={{q="Cos'è la Scatola di Tabacco di Snellig?",a="È un piccolo contenitore personale un tempo appartenuto al Primo Ufficiale Snellig, un ufficiale della sfortunata The Third Fleet di Kul Tiras. È trasportato dal suo residuo non morto a bordo dei relitti al largo della costa settentrionale delle Wetlands.",al={"cos'è questo oggetto","scatola di tabacco di snellig","scatola di tabacco"}},{q="Dove posso trovare la Scatola di Tabacco di Snellig?",a="La scatola di tabacco viene sottratta al Primo Ufficiale Snellig, che infesta la stiva del relitto più vicino alla riva presso la Flotta Perduta nelle Wetlands nord-occidentali.",al={"dove snellig rilascia la scatola di tabacco","trovare snellig","posizione del primo ufficiale snellig"}},{q="Chi desidera questa scatola di tabacco?",a="Il Primo Ufficiale Fitzsimmons, l'unico superstite vivente della The Third Fleet, chiede agli avventurieri di portargli la scatola di tabacco a Porto di Menethil come prova che Snellig ha finalmente trovato la pace.",al={"chi prende la scatola di tabacco","a chi devo consegnarlo","missione di fitzsimmons"}},{q="Perché il Primo Ufficiale Snellig è maledetto?",a="Secondo Fitzsimmons, un oscuro e terribile tesoro nascosto a bordo di uno dei vascelli della The Third Fleet condannò gli equipaggi al momento del naufragio, intrappolando le loro anime tra i legnami marcescenti e negando loro il riposo.",al={"perché snellig è un non morto","maledizione della flotta perduta","maledizione della the third fleet"}}},fp="18,283,29.710.0,27.215.0,35.148.0,24.174.0,33.204.0"}
P.entries["item:snufflenose-command-stick"] = {n="Vincastro per Tartasniffo",s="Il Vincastro per Tartasniffo è una verga da addestramento fornita dall'imprenditore goblin Mebok Ghignofolle a Porto Paranco. Viene utilizzato per dirigere i citelli tartasniffo addestrati a localizzare e dissotterrare preziosi tuberi di foglia blu sepolti nelle profondità delle Gallerie di Lamaspina.",h="Il Vincastro per Tartasniffo è una verga da addestramento fornita dall'imprenditore goblin Mebok Ghignofolle...",kw={"tubero di foglia blu","vincastro di comando","citello","mebok ghignofolle","porto paranco","gallerie di lamaspina","tartasniffo","the barrens"},ang={["profession:Cooking"]="Sebbene i tuberi di foglia blu siano considerati una squisita prelibatezza culinaria in tutto il mondo, per estrarli sono necessari un animale addestrato e il bastone di un conduttore, anziché i normali utensili da cucina."},sec={{t="Una verga per roditori",b="I tuberi di foglia blu sono prelibatezze ambite in tutta Azeroth, ma trovarli è quasi impossibile senza un aiuto specializzato. Sepolte nelle spinose profondità sotterranee delle Gallerie di Lamaspina, le radici sono del tutto nascoste alla vista. Per sfruttare questo lucroso mercato senza dover affrontare di persona le tane dei verrospini, il mercante di Porto Paranco Mebok Ghignofolle ha addestrato citelli tartasniffo dal fiuto finissimo affinché dissotterrassero i tuberi. Il Vincastro per Tartasniffo è lo strumento utilizzato dagli avventurieri per guidare queste creature addestrate, incitandole a fiutare e a portare alla luce i nodi di radici fino a cinquanta passi di distanza."}},faq={{q="A cosa serve il Vincastro per Tartasniffo?",a="Il bastone di comando serve a ordinare a un citello tartasniffo addestrato di cercare i tuberi di foglia blu nascosti all'interno degli spinosi cunicoli delle Gallerie di Lamaspina. Quando viene puntata verso un citello evocato, la verga spinge la creatura a seguire le tracce odorose e a dissotterrare i nodi di radici.",al={"come usare il vincastro di comando","cosa fa il vincastro di comando","scopo del vincastro di comando"}},{q="Dove si ottiene il Vincastro per Tartasniffo?",a="Lo si raccoglie a Porto Paranco nelle The Barrens, direttamente fuori dal laboratorio di Mebok Ghignofolle, accanto a una cassa contenente un citello addestrato e un manuale di istruzioni.",al={"dove trovare il vincastro di comando","posizione del vincastro di comando","chi dà il vincastro di comando"}},{q="Perché Mebok Ghignofolle vuole i tuberi di foglia blu?",a="I tuberi di foglia blu sono rare prelibatezze vendute con un sostanziale profitto a facoltosi contatti culinari in tutto il mondo. Poiché crescono solo nelle profondità delle The Barrens in territorio verrospino, Mebok assolda avventurieri per raccoglierli.",al={"perché i tuberi","scopo del tubero di foglia blu","perché mebok vuole i tuberi"}},{q="Si può tenere il bastone dopo aver trovato i tuberi?",a="No. Una volta raccolti i tuberi richiesti, Mebok richiede che tu gli restituisca sia il bastone di comando sia la cassa da trasporto a Porto Paranco insieme al tuo raccolto.",al={"posso tenere il vincastro di comando","restituire il vincastro di comando"}}},fx={["8cc828c2"]={q="Che cos'è il Vincastro per Tartasniffo?",a="Il Vincastro per Tartasniffo è lo strumento brevettato per la gestione dei tartasnaf di Snuff Inc., fornito insieme ai tartasnaf addestrati dell'imprenditore goblin Mebok Ghignofolle a Porto Paranco. È progettato appositamente per dirigere i tartasnaf addestrati e dare loro il segnale di cercare prelibatezze nascoste e difficili da trovare, che una normale guida ignorerebbe del tutto.",al={"cos'è un vincastro","vincastro per tartasniffo","cos'è il vincastro per tartasniffo"}},["9fdd5faa"]={q="Da dove proviene il Vincastro per Tartasniffo e chi lo ha creato?",a="Il vincastro è un prodotto brevettato di Snuff Inc.; il proprietario Marwig Rustbolt ne spiega l'uso nel Manuale di Istruzioni del Tartasniffo. Mebok Ghignofolle, a Porto Paranco, ha addestrato i suoi tartasnaf a raccogliere prelibatezze rare e tiene insieme i vincastri, le gabbie e i manuali, così che i lavoratori assunti possano controllare adeguatamente le bestiole.",al={"chi ha creato il vincastro","origine del vincastro","da dove proviene il vincastro"}},fb1cfa60={q="Perché qualcuno vuole il Vincastro per Tartasniffo?",a="È impossibile individuare senza aiuto i rari tuberi Blueleaf sotto i rovi delle Gallerie di Lamaspina. Il vincastro è indispensabile perché induce un tartasnaf addestrato ad annusare fino a cinquanta passi di distanza e a dissotterrare i tuberi, che poi puoi riportare a Mebok Ghignofolle in cambio di una ricompensa generosa.",al={"perché serve il vincastro","perché si vuole il vincastro","perché procurarsi il vincastro per tartasniffo"}}},fp="25,241,17.568.0,47.250.0,50.159.0,45.230.0,54.165.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Manuale di Istruzioni del Tartasniffo",s="Il Manuale di Istruzioni del Tartasniffo è un libretto di istruzioni redatto da Marwig Bullonaccio della Snuff Inc., custodito accanto all'imprenditore goblin Mebok Ghignofolle a Porto Paranco. Descrive come schierare e dirigere un Snufflenose Gopher addestrato per localizzare i rari Blueleaf Tubers sepolti nelle Gallerie di Lamaspina.",h="Il Manuale di Istruzioni del Tartasniffo è un libretto di istruzioni redatto da Marwig Bullonaccio della...",kw={"tubero di foglia blu","gopher","manuale","mebok ghignofolle","porto paranco","gallerie di lamaspina","snufflenose"},ang={["profession:Cooking"]="Il manuale delinea il processo di recupero dei Blueleaf Tubers, una radice sotterranea considerata una rara prelibatezza da buongustai e commercianti in tutta Azeroth."},sec={{t="Guida Operativa di un Goblin",b="Scritta da Marwig Bullonaccio, proprietario della Snuff Inc., questa breve guida descrive in dettaglio come lavorare con i snufflenose gopher addestrati dell'azienda. Queste bestie possiedono un olfatto acuto capace di rilevare Blueleaf Tubers sotterranei a cinquanta passi di distanza. Il manuale insegna ai cercatori a liberare un gopher usando una cassa ventilata e a guidarne l'istinto di scavare con un bastone di comando, indirizzando la creatura attraverso le spine ostili e i cunicoli dei verrospini delle Gallerie di Lamaspina per assicurarsi queste pregiate prelibatezze culinarie."}},faq={{q="Qual è lo scopo del Manuale di Istruzioni del Tartasniffo?",a="Fornisce istruzioni per gestire i snufflenose gopher addestrati di Mebok Ghignofolle. Gli avventurieri lo leggono per capire come schierare l'animale dalla sua cassa e dirigerlo con un bastone di comando per localizzare i Blueleaf Tubers sepolti all'interno delle Gallerie di Lamaspina.",al={"a cosa serve il manuale","perché leggere il manuale","scopo del manuale"}},{q="Dove posso trovare il manuale?",a="Il manuale è custodito a Porto Paranco nei The Barrens, proprio vicino a Mebok Ghignofolle insieme alle casse specializzate e ai bastoni di comando necessari per raccogliere i tuberi.",al={"posizione del manuale","dove si trova il libro","come ottenere il manuale"}},{q="Perché sono necessari i snufflenose gopher per trovare i Blueleaf Tubers?",a="I Blueleaf Tubers crescono nascosti in profondità nel terreno all'interno delle Gallerie di Lamaspina e sono praticamente impossibili da individuare per gli umanoidi. I gopher addestrati possiedono un fiuto acuto in grado di percepire l'odore di un tubero sepolto a cinquanta passi di distanza.",al={"perché usare i gopher","si possono trovare i tuberi senza gopher"}},{q="Chi ha scritto il manuale?",a="È firmato da Marwig Bullonaccio, proprietario della Snuff Inc., che lo scrisse per insegnare ai nuovi proprietari come nutrire, far passeggiare e comandare i loro gopher con il bastone di comando brevettato.",al={"autore del manuale","chi l'ha creato"}}},fx={["1c231f00"]={q="Che cos'è il Manuale di Istruzioni del Tartasniffo?",a="È un manuale di istruzioni fornito insieme a un tartasnaf addestrato e a un vincastro. Guida gli avventurieri nell'uso della creatura nelle gallerie sotterranee delle Gallerie di Lamaspina e spiega come comandare al tartasnaf di fiutare gli introvabili tuberi Blueleaf sotterranei.",al={"cos'è il manuale di istruzioni del tartasniffo","identità del manuale del tartasniffo","cos'è il manuale"}}},fp="26,280,26.512.0,54.249.0,28.152.0,59.233.0,21.163.0"}
P.entries["item:sodium-nitrate"] = {n="Nitrato di Sodio",s="Il Nitrato di Sodio è un reagente chimico volatile trasportato dagli scavatori nanici e dal presidio di stanza a Bael Modan nelle Savane Meridionali. Sebbene importato dalla spedizione di Forgiardente per farsi strada nella roccia antica mediante esplosioni, il tauren esiliato Gann Spira Dura cerca di recuperarlo per assemblare una carica esplosiva contro gli invasori.",h="Il Nitrato di Sodio è un reagente chimico volatile trasportato dagli scavatori nanici e dal presidio di...",kw={"bael modan","bael'dun","blackforge","gann spira dura","nitroglicerina","revenge of gann","nitrato di sodio","pasta di legno"},ang={["profession:Engineering"]="Gli ingegneri riconoscono prontamente la combinazione di nitrato di sodio, nitroglicerina e pasta di legno come la ricetta classica della dinamite stabilizzata, evidenziando la ferrea logica alla base delle cariche da demolizione improvvisate di Gann.",["race:Tauren"]="Per i tauren, l'uso di sostanze chimiche naniche è un amaro allontanamento dai metodi tradizionali, ma Gann Spira Dura considera giustificate misure disperate per vendicare la distruzione del proprio territorio ancestrale."},sec={{t="Demolizione Industriale",b="La spedizione Bael'dun ha fatto breccia nelle terre ancestrali della tribù Spira Dura armata di pesanti macchine per il movimento terra e reagenti detonanti. Per spaccare i tenaci strati rocciosi delle Savane Meridionali, i nani si sono affidati a composti chimici volatili. Il Nitrato di Sodio costituisce un elemento cruciale come agente stabilizzante e ossidante negli esplosivi ad alto potenziale, trasportato regolarmente da fucilieri, soldati e ufficiali Bael'dun all'interno degli scavi e della vicina fortezza."},{t="Rovescio di Fronte e Ritorsione",b="In seguito alla devastazione della terra natia della sua tribù, Gann Spira Dura ha osservato da vicino gli invasori e ha recuperato i loro schemi ingegneristici. Rendendosi conto che gli attacchi convenzionali non potevano facilmente violare il mastio pesantemente difeso, Gann ha pianificato di rivolgere le scorte per esplosioni industriali dei nani contro di loro. Mescolando il Nitrato di Sodio sottratto con nitroglicerina e pasta di legno, l'esule tauren crea cariche improvvisate progettate per scuotere le fondamenta di Bael Modan."}},faq={{q="A cosa serve il Nitrato di Sodio nelle Barrens?",a="I nani di Forgiardente lo usano come componente chimico per esplosivi con cui far saltare il terreno roccioso del loro sito di scavo. Gann Spira Dura intende combinarlo con nitroglicerina e pasta di legno per creare potenti cariche da demolizione con cui colpire il mastio di Bael Modan.",al={"scopo del nitrato di sodio","a cosa serve il nitrato di sodio"}},{q="Da dove proviene il Nitrato di Sodio?",a="È custodito dalle forze militari naniche di stanza a Bael Modan nelle Savane Meridionali. Soldati, fucilieri, ufficiali e i loro comandanti come Lord Cyrik Blackforge tengono con sé scorte di questo reagente.",al={"chi rilascia il nitrato di sodio","dove trovare il nitrato di sodio"}},{q="Perché Gann Spira Dura ha bisogno di questa sostanza chimica?",a="Gann ha perso il suo villaggio ancestrale a causa degli scavi nanici. Privo di equipaggiamento pesante da assedio, ha studiato gli schemi dei nani per replicare le loro cariche da miniera, con l'obiettivo di smantellare le loro posizioni fortificate con i loro stessi ordigni.",al={"perché gann vuole il nitrato di sodio","esplosivi di gann spira dura"}},{q="Il Nitrato di Sodio è pericoloso da solo?",a="Di per sé, il nitrato di sodio è un ossidante e un sale chimico piuttosto che un esplosivo istantaneo. Diventa pericoloso e volatile quando viene adeguatamente miscelato con una fonte di combustibile e sostanze chimiche sensibili agli urti come la nitroglicerina.",al={"il nitrato di sodio è un esplosivo"}}},fx={caaef0db={q="Che cos'è il Nitrato di Sodio?",a="Il nitrato di sodio è un agente chimico volatile conservato dalle forze di spedizione dei nani stanziate a Bael Modan. Pur essendo relativamente stabile se conservato, i nani lo usano come componente essenziale per preparare cariche esplosive di alta qualità, impiegate per far saltare la roccia compatta nei loro siti di scavo. Nelle mani di un sabotatore astuto, però, può essere facilmente riutilizzato per demolire la fortezza stessa.",al={"cos'è il nitrato di sodio","storia del nitrato di sodio","nitrato di sodio nelle savane"}}},fp="14,325,21.442.0,25.465.1,47.266.0,36.206.0,44.225.0,39.216.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Appello di Solomon a Borgoscuro",s="L'Appello di Solomon a Borgoscuro è un'urgente missiva redatta dal Magistrato Solomon di Borgolago e indirizzata a Ser Ello Serranero. Di fronte alle crescenti minacce degli orchi Blackrock e degli gnoll, la lettera implora la dirigenza di Borgoscuro di inviare la sua milizia scelta, The Night Watch, per rafforzare le stremate difese di Borgolago.",h="L'Appello di Solomon a Borgoscuro è un'urgente missiva redatta dal Magistrato Solomon di Borgolago e...",kw={"borgoscuro","boscovespro","borgolago","ser ello serranero","magistrato solomon","messenger to darkshire","the night watch","redridge","appello di solomon"},ang={["faction:Alliance"]="Il messaggio illustra la frammentazione delle terre meridionali della Grande Alleanza, dove insediamenti lontani devono implorarsi a vicenda per sopravvivere mentre Roccavento rimane indifferente.",["race:Human"]="Per i viaggiatori umani, trasportare questo dispaccio mette in risalto il comune pericolo che minaccia sia le terre di confine di Redridge sia i boschi ombrosi di Boscovespro."},sec={{t="Una disperata richiesta d'aiuto",b="Borgolago è sull'orlo del collasso, minacciata dall'invasione di orchi Blackrock, gnoll e murloc, con rinforzi ufficiali da Roccavento praticamente inesistenti. Preso dalla disperazione, il Magistrato Solomon ha redatto questa supplica formale al sindaco Ello Serranero di Borgoscuro, chiedendogli di inviare membri di The Night Watch a nord verso Redridge. Il documento riflette il grave collasso del supporto militare centrale nelle terre meridionali di Azeroth, costringendo i singoli insediamenti umani ad affidarsi l'un l'altro per la sopravvivenza reciproca."},{t="La tragica situazione di Borgoscuro",b="Sebbene la richiesta di Solomon sia urgente, evidenzia quanto Borgolago sia isolata rispetto ai veri orrori che attanagliano i territori vicini. Boscovespro stessa è assediata da non morti, bestie fameliche e un'oscurità pervasiva, lasciando The Night Watch già spinta oltre i propri limiti semplicemente per difendere i confini del villaggio. Invece di scoprire una riserva intatta di soldati freschi, i corrieri che consegnano la supplica trovano una cittadina altrettanto assediata e totalmente incapace di privarsi di difensori per Redridge."}},faq={{q="Cos'è l'Appello di Solomon a Borgoscuro?",a="È una lettera ufficiale scritta dal Magistrato Solomon di Borgolago a Ser Ello Serranero, il sindaco di Borgoscuro. Il messaggio chiede con urgenza a Borgoscuro di offrire l'aiuto della sua milizia, The Night Watch, per assistere nella difesa di Redridge contro gli orchi Blackrock e gli gnoll.",al={"lettera di solomon a borgoscuro","cos'è l'appello di solomon","lettera da borgolago a boscovespro"}},{q="Perché Borgolago chiede aiuto militare a Borgoscuro invece che a Roccavento?",a="Il governo centrale di Roccavento ha ampiamente mancato di fornire adeguate truppe di guarnigione ai suoi territori periferici a causa dell'inerzia politica e dei conflitti interni. Lasciato a difendere Borgolago da solo contro incursioni sempre più gravi, il Magistrato Solomon si è rivolto alle cittadine umane vicine nella speranza di assicurarsi forze alleate.",al={"perché chiedere a borgoscuro","perché non a roccavento","perché solomon ha bisogno di the night watch"}},{q="Chi è Ser Ello Serranero?",a="Ser Ello Serranero è il sindaco e il principale leader civico di Borgoscuro a Boscovespro. Sovrintende alla cittadina e coordina The Night Watch, la forza di difesa civile votata a respingere gli orrori in agguato nei boschi.",al={"chi è serranero","sindaco di borgoscuro","ser ello"}},{q="Borgoscuro può davvero fare a meno di The Night Watch per aiutare Borgolago?",a="No. Boscovespro è intrappolata nel proprio incubo, circondata da non morti, feroci worgen e magia oscura. The Night Watch ha a malapena personale a sufficienza per presidiare il perimetro di Borgoscuro e non può privarsi di un singolo combattente da inviare a Redridge.",al={"borgoscuro aiuta","arriverà the night watch","serranero ha inviato guardie"}}},fx={a3b7e1d6={q="Da dove proviene l'Appello di Solomon a Borgoscuro e chi l'ha scritto?",a="La lettera fu scritta direttamente dal Magistrato Solomon, il capo della città di Borgolago, a Crestarossa. Con gli orchi del Martello del Crepuscolo che premono sulla città e Roccavento incapace di inviare rinforzi reali, Solomon scrisse di persona l'appello urgente dal municipio di Borgolago, nella speranza di ottenere aiuto dagli insediamenti vicini.",al={"chi ha scritto l'appello di solomon","origine dell'appello di solomon a borgoscuro","chi ha creato l'appello di solomon"}},["5061acb5"]={q="Perché Ser Ello Serranero vuole l'Appello di Solomon a Borgoscuro?",a="Ser Ello Serranero ha bisogno della lettera perché descrive ufficialmente la disperata difesa di Borgolago e la richiesta diretta di assistenza militare del Magistrato Solomon. In quanto sindaco di Borgoscuro e comandante della The Night Watch, Serranero si affida a dispacci ufficiali come questo per comprendere le minacce che affrontano i loro vicini dell'Alleanza e valutare se la città può permettersi di inviare delle guardie.",al={"perché consegnare l'appello di solomon","perché serranero ha bisogno della lettera","scopo dell'appello di solomon a borgoscuro"}}},fp="27,313,24.521.0,23.468.1,36.274.0,73.318.0,27.226.0,63.228.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Appello di Solomon alle Marche Occidentali",s="L'Appello di Solomon alle Marche Occidentali è un urgente appello scritto redatto dal Magistrato Solomon di Borgolago. Nel disperato bisogno di rinforzi contro gli orchi Blackrock e gli gnoll, Solomon invia questo dispaccio a Gryan Stoutmantle nelle Marche Occidentali, sperando che la neonata The People's Militia possa offrire aiuto mentre l'esercito reale di Roccavento non risponde.",h="L'Appello di Solomon alle Marche Occidentali è un urgente appello scritto redatto dal Magistrato Solomon di...",kw={"gryan stoutmantle","borgolago","magistrato solomon","the people's militia","crestarossa","appello di solomon","esercito di roccavento","marche occidentali"},ang={["faction:Alliance"]="Il documento evidenzia la crescente paralisi amministrativa nel cuore dell'Alleanza, dove le città periferiche devono fare affidamento su volontari locali piuttosto che sulle truppe reali.",["race:Human"]="Per gli umani di tutte le province meridionali, questo appello rivela quanto siano diventati tesi gli insediamenti rurali, mentre la scomparsa del re e l'incuria politica lasciano vulnerabili le terre di frontiera."},sec={{t="Una disperata richiesta di aiuto",b="Mentre la minaccia del clan Blackrock e di ostili gnoll incombe su Crestarossa, il Magistrato Solomon si ritrova pericolosamente isolato a Borgolago. L'esercito reale di Roccavento ha inspiegabilmente mancato di giungere in forze per difendere i confini della regione. Incapace di attendere il sostegno ufficiale dalla capitale del regno, Solomon redige questo appello nel disperato tentativo di reclutare assistenza al di fuori della regolare struttura militare. Avendo avuto notizia di una forza difensiva volontaria che si sta formando oltre Elwynn a ovest, si rivolge direttamente alla The People's Militia."},{t="Oltre il confine",b="Il messaggio è indirizzato direttamente a Gryan Stoutmantle, un guerriero veterano che sta organizzando la difesa della frontiera delle Marche Occidentali. Solomon spera che Stoutmantle possa concedere combattenti per rinforzare Borgolago finché la corona di Roccavento non invierà finalmente le riserve regolari. Affidato a un avventuriero con funzioni di corriere, il documento riflette la frammentazione del coordinamento amministrativo nei territori periferici di Roccavento, dove i magistrati locali sono lasciati a negoziare accordi di mutuo soccorso di propria iniziativa."}},faq={{q="Cos'è l'Appello di Solomon alle Marche Occidentali?",a="È una petizione scritta ufficiale redatta dal Magistrato Solomon di Borgolago, che chiede a Gryan Stoutmantle e alla The People's Militia nelle Marche Occidentali di inviare rinforzi militari per aiutare a difendere Crestarossa.",al={"cos'è l'appello di solomon","lettera appello di solomon alle marche occidentali","lettera borgolago marche occidentali"}},{q="Perché il Magistrato Solomon chiede aiuto alle Marche Occidentali invece che a Roccavento?",a="Solomon nota che sta accadendo qualcosa di strano nell'esercito di Roccavento, poiché le truppe reali non sono riuscite ad arrivare in forze nonostante il pericolo crescente di Borgolago. Mancando del tempo per attendere la Corona, Solomon si rivolge a qualsiasi forza combattente vicina disposta ad aiutare.",al={"perché chiedere alle marche occidentali","perché non chiedere a roccavento","perché inviare l'appello alle marche occidentali"}},{q="Chi è Gryan Stoutmantle?",a="Gryan Stoutmantle è il capo della The People's Militia, una lega difensiva popolare organizzata da agricoltori e coloni locali per proteggere le Marche Occidentali dalla Fratellanza dei Defias.",al={"chi è stoutmantle","ruolo di gryan stoutmantle"}},{q="Quali minacce stanno spingendo Solomon a inviare questa lettera?",a="Borgolago sta affrontando aggressive incursioni da parte degli orchi Blackrock, insieme a scorrerie di gnoll in tutte le Montagne Crestarossa, portando la guardia cittadina locale oltre i propri limiti.",al={"perché borgolago è in pericolo","cosa minaccia crestarossa"}}},fx={["7804da1c"]={q="Da dove proviene l'Appello di Solomon alle Marche Occidentali e chi l'ha scritto?",a="La lettera è stata scritta direttamente dal Magistrato Solomon a Borgolago, la città assediata nelle Montagne Crestarossa. Disperato dopo che l'esercito di Roccavento non ha inviato i rinforzi promessi per difendere il suo popolo, Solomon ha scritto di persona questo messaggio urgente per implorare aiuto agli alleati vicini.",al={"chi ha scritto l'appello di solomon alle marche occidentali","da dove proviene l'appello di solomon","autore dell'appello di solomon"}},["6d6e291d"]={q="Perché Gryan Stoutmantle vuole l'Appello di Solomon alle Marche Occidentali?",a="Gryan Stoutmantle guida The People's Militia nelle Marche Occidentali e questo dispaccio lo informa della grave situazione di Borgolago. Solomon spera che la milizia possa inviare combattenti per rinforzare le difese ormai ridotte di Crestarossa, mentre la città attende notizie e truppe dalla corte di Re Anduin a Roccavento.",al={"perché consegnare l'appello di solomon","perché stoutmantle vuole l'appello","a cosa serve la lettera"}}},fp="26,327,24.556.0,26.487.0,35.197.0,72.257.0,25.176.0,53.177.0"}
P.entries["item:soran-ruk-fragment"] = {n="Frammento di Soran'ruk",s="Un Frammento di Soran'ruk è una scheggia infranta di un globo prigione demoniaco un tempo vincolato allo spirito di un servitore caduto in disgrazia della Legione Infuocata. Sebbene divisa e dispersa tra i cultisti nelle profondità di Valtetra, ogni scheggia irradia ancora energia vile residua.",h="Un Frammento di Soran'ruk è una scheggia infranta di un globo prigione demoniaco un tempo vincolato allo...",kw={"abissi di fondocupo","doan karhan","fel","globo di soran'ruk","soran'ruk","soranruk","twilight acolyte"},ang={["class:Warlock"]="I recipienti prigione demoniaci come il Globo di Soran'ruk rappresentano ambiti condotti per gli stregoni che cercano di vincolare e manipolare le energie vili grezze senza una sottomissione demoniaca diretta."},sec={{t="Una prigione infranta",b="Quando i demoni della Legione Infuocata cadono in disgrazia presso i loro padroni, i loro spiriti vengono talvolta condannati all'imprigionamento all'interno di globi specializzati e distribuiti a incantatori vili come condotti di pura potenza. Il Globo di Soran'ruk subì questa sorte, eppure a un certo punto della sua storia andò in frantumi. Una metà fu spezzata in schegge più piccole e finì nelle mani dei cultisti del Martello del Crepuscolo in agguato tra le rovine sommerse degli Abissi di Fondocupo, i quali attingono alla persistente essenza demoniaca per le loro oscure macchinazioni."},{t="Ricostruzione nelle Barrens",b="Nonostante sia frammentato, ogni pezzo conserva una traccia della vitalità dell'entità imprigionata. Nelle Savane Meridionali, il solitario studioso Doan Karhan ha trascorso una vita a studiare questi ricettacoli demoniaci, e possiede un globo simile, il Globo di Zargain. Recuperando tre piccoli frammenti insieme al pezzo più grande custodito a Silverpine, un ambizioso stregone può far riforgiare la reliquia per intero rendendola nuovamente uno strumento di potere."}},faq={{q="Cos'è Soran'ruk?",a="Soran'ruk era un demone della Legione Infuocata caduto in disgrazia presso la guida demoniaca. Come punizione, il suo spirito fu estratto e intrappolato all'interno di un globo cristallino per servire come riserva di energia a stregoni e maghi mortali.",al={"chi è soranruk","storia di soran'ruk","soranruk è un demone"}},{q="Dove si trovano questi frammenti?",a="Le schegge più piccole sono trasportate dai Twilight Acolyte all'interno delle sale cavernose degli Abissi di Fondocupo lungo la Spiaggia di Zoram.",al={"dove trovare frammento di soran'ruk","chi rilascia frammenti di soran'ruk","posizione frammento di soran'ruk"}},{q="Perché il Martello del Crepuscolo possiede queste schegge?",a="Anche quando sono spezzate, le schegge conservano l'essenza magica del demone intrappolato. I cultisti del Martello del Crepuscolo recuperano tali manufatti corrotti per alimentare i loro oscuri rituali e incanalare magia proibita.",al={"perché i cultisti ce l'hanno","martello del crepuscolo soranruk"}},{q="Chi può ripristinare il Globo di Soran'ruk?",a="Doan Karhan, un eremita solitario che vive nelle Savane Meridionali vicino al confine con Millepicchi, è specializzato nello studio e nella riforgiatura dei globi demoniaci della Legione.",al={"chi ripara il globo","dove consegnare frammento di soran'ruk","globo di doan karhan"}}},fx={["49c59cce"]={q="Da dove provengono i Frammenti di Soran'ruk e chi li ha creati?",a="Sono i resti frantumati del Globo di Soran'ruk, un ricettacolo demoniaco forgiato dalla Legione Infuocata. Quando i demoni cadono in disgrazia, la Legione imprigiona i loro spiriti in globi di questo tipo e li affida ai suoi maghi e stregoni. Il Globo di Soran'ruk fu poi spezzato e i frammenti più piccoli finirono nelle mani degli accoliti del Martello del Crepuscolo negli Abissi di Fondocupo.",al={"origine del frammento di soran'ruk","chi ha creato i frammenti di soran'ruk","da dove provengono i frammenti di soran'ruk"}},["5e1e8c12"]={q="Perché qualcuno vuole i Frammenti di Soran'ruk?",a="Anche ridotti in schegge, i frammenti vibrano ancora dell'essenza e del potere del demone intrappolato. Lo stregone eremita Doan Karhan, nelle Savane, ha dedicato la vita allo studio e alla ricostruzione dei globi della Legione. Se gli porti queste schegge più piccole insieme al frammento più grande proveniente dal Forte di Zannascura, potrà riforgiare il Globo di Soran'ruk e trasformarlo in uno strumento potente per la tua professione.",al={"perché raccogliere i frammenti di soran'ruk","chi vuole i frammenti di soran'ruk","perché servono i frammenti di soran'ruk"}}},fp="18,249,18.527.0,29.424.1,18.226.0,32.123.0,49.203.0,37.168.0"}
P.entries["item:southsea-treasure"] = {n="Tesoro dei Mari del Sud",s="Il Tesoro dei Mari del Sud è un prezioso bottino custodito nelle profondità della stiva della Tide Razor, un vascello dei Southsea Freebooter. Ricercato da Wrenix il Miserabile a Porto Paranco, recuperarlo mette alla prova le abilità di scassinamento e infiltrazione dei ladri alle prime armi.",h="Il Tesoro dei Mari del Sud è un prezioso bottino custodito nelle profondità della stiva della Tide Razor, un...",kw={"e.c.a.c.","scassinamento","polly","porto paranco","the shattered hand","tesoro dei mari del sud","tide razor","wrenix il miserabile"},ang={["class:Rogue"]="Recuperare il Tesoro dei Mari del Sud rappresenta un rito di passaggio per i ladri in crescita, offrendo sia pratica reale di scassinamento sia un'introduzione al losco sindacato noto come The Shattered Hand.",["faction:Horde"]="I Southsea Freebooter disturbano regolarmente il commercio attorno a The Barrens e al porto di Porto Paranco, rendendo qualsiasi furto alla loro scorta centrale un gradito intralcio per le autorità locali."},sec={{t="Un colpo mortale",b="Ancorata lungo la Costa dei Mercanti a sud di Porto Paranco, la nave pirata Tide Razor funge da base avanzata e terreno di addestramento per i Southsea Freebooter. Nascosta nelle profondità della sua stiva più bassa si trova una bramata scorta di bottino nota come Tesoro dei Mari del Sud. Wrenix il Miserabile, una canaglia goblin che opera fuori da Porto Paranco, la considera la prova definitiva per gli aspiranti borseggiatori. Secondo Wrenix, gli ultimi cinque operativi inviati a sottrarre la cassa sono tornati a pezzi, a causa dei vigili pirati a bordo e di un guardiano sorprendentemente feroce a guardia della stiva."},{t="Il ricordo di Polly",b="I ladri che riescono a oltrepassare gli addestratori pirati e a scassinare la serratura della cassa bersaglio trovano ad attenderli una feroce sorpresa. Piuttosto che trovarsi sfuso all'interno del forziere, il vero Tesoro dei Mari del Sud è sorvegliato da Polly, un pappagallo innaturalmente ostile. Sconfiggere il feroce volatile — spesso con l'aiuto della Goblin Engineering come il congegno E.C.A.C. di Wrenix — è l'unico modo per sottrarre il tesoro e riportarlo intatto a Porto Paranco."}},faq={{q="Dove si trova il Tesoro dei Mari del Sud?",a="Il tesoro è custodito a bordo della Tide Razor, una nave dei Southsea Freebooter ancorata lungo la costa a sud di Porto Paranco nelle Barrens. Si trova nella stiva più bassa, sotto i quartieri di addestramento dei pirati.",al={"dove si trova il tesoro","posizione tide razor","come trovare il tesoro dei mari del sud"}},{q="Chi vuole il Tesoro dei Mari del Sud?",a="Wrenix il Miserabile, uno scaltro goblin di stanza a Porto Paranco, assolda agenti segreti per infiltrarsi nella nave e recuperare il bottino per suo conto.",al={"chi assegna la missione","chi è wrenix","chi lo vuole"}},{q="Perché la cassa è vuota una volta scassinata?",a="Scassinare la serratura della cassa del tesoro innesca la comparsa di Polly, un pappagallo mostruosamente aggressivo a guardia della stiva. Sconfiggere Polly è ciò che consente effettivamente di ottenere il Tesoro dei Mari del Sud.",al={"da dove viene polly","perché è apparsa polly","perché il tesoro non è nella cassa"}},{q="Cos'è un E.C.A.C. e perché è necessario?",a="L'E.C.A.C. è un dispositivo sperimentale di ingegneria goblin fornito da Wrenix il Miserabile. È progettato per indebolire minacce aeree insolitamente feroci, nello specifico il letale pappagallo guardiano Polly in agguato nella stiva della nave pirata.",al={"cos'è l'ecac","come sconfiggere polly","pappagallo ostile"}},{q="A cosa serve la nave ai Southsea Freebooter?",a="La Tide Razor funge da base operativa e covo di ladri per i Southsea Freebooter, con forzieri di addestramento al secondo livello dove l'equipaggio addestra i propri tagliaborse.",al={"cos'è la tide razor","covo di pirati the barrens","stiva nave mari del sud"}}},fx={c9f033cd={q="Che cos'è il Tesoro dei Mari del Sud?",a="Il Tesoro dei Mari del Sud è il bottino accumulato dai Predoni dei Mari del Sud a bordo della loro nave, la Tide Razor, ancorata al largo delle coste delle Savane. Custodito nelle profondità della stiva e protetto dal notoriamente feroce pappagallo pirata Polly, rappresenta i guadagni illeciti accumulati dai corsari durante le loro scorrerie lungo la Costa dei Mercanti.",al={"cos'è il tesoro dei mari del sud","oggetto tesoro dei mari del sud","che tipo di tesoro è il tesoro dei mari del sud"}}},fp="17,242,14.555.0,16.443.1,39.196.0,32.148.0,35.186.1,41.227.0,50.176.0"}
P.entries["item:spectral-comb"] = {n="Pettine Spettrale",s="Il Pettine Spettrale è uno strumento di toeletta etereo utilizzato per interagire con i morti senza riposo di Boscovespro. Fabbricato per attraversare forme intangibili, viene portato al doloroso spirito di Mary la Cieca per raccogliere ciocche di capelli spettrali.",h="Il Pettine Spettrale è uno strumento di toeletta etereo utilizzato per interagire con i morti senza riposo di...",kw={"mary la cieca","pettine","borgoscuro","boscovespro","fantasma","filo di capelli spettrali","pettine spettrale"},ang={["faction:Alliance"]="Avventurarsi a sud di Borgoscuro con il pettine funge da crudo promemoria dei tragici destini subiti dagli antichi coloni di Boscovespro.",["profession:Tailoring"]="Il Pettine Spettrale dimostra che la sartoria nei luoghi oscuri richiede metodi di raccolta insoliti, ottenendo fibre eteree da fantasmi consenzienti piuttosto che dalla tradizionale tosatura."},sec={{t="Uno strumento per i morti senza riposo",b="I normali utensili non possono toccare o pettinare uno spirito, rendendo la raccolta di materiali eterei quasi impossibile per gli artigiani mortali. Il Pettine Spettrale è particolarmente adatto a interagire con forme spettrali, scivolando attraverso chiome altrimenti intangibili. Viene trasportato a sud di Borgoscuro fino alla fattoria in rovina dove il fantasma in lacrime di Mary la Cieca si lamenta in isolamento. Trovando conforto nel gesto familiare di pettinare i suoi capelli rovinati, Mary usa volentieri il pettine, lasciando le fibre spettrali necessarie per tessere il Filo di Capelli Spettrali."}},faq={{q="A cosa serve il Pettine Spettrale?",a="Il pettine viene dato a Mary la Cieca, un fantasma in lacrime che dimora a sud di Borgoscuro. Quando lo usa per pettinarsi i capelli, raccoglie ciocche eteree che possono poi essere filate in un filo soprannaturale.",al={"scopo del pettine spettrale","perché serve il pettine spettrale","cosa fa il pettine"}},{q="Chi è Mary la Cieca?",a="Mary la Cieca è uno spirito tormentato che infesta una casa abbandonata tra le colline a sud di Borgoscuro. Impazzita per la tragedia, si è strappata gli occhi e rimane terrorizzata dal fatto che gli altri la trovino orribile nella morte.",al={"storia di mary la cieca","chi è il fantasma con il pettine","mary la cieca"}},{q="Perché non si può usare un pettine ordinario?",a="Gli spiriti non possono essere toccati da strumenti fisici e mondani senza magie o incantamenti specializzati. Il Pettine Spettrale è progettato specificamente per interagire con i capelli intangibili di un'apparizione.",al={"perché pettine spettrale","pettine normale fantasma"}}},fx={e893aa2f={q="Che cos'è il Pettine Spettrale?",a="Il Pettine Spettrale è uno strumento etereo per la toelettatura, incantato appositamente per interagire con gli esseri incorporei. Mentre gli strumenti normali attraverserebbero un fantasma senza alcun effetto, questo pettine può toccare, districare e raccogliere i capelli spettrali di un fantasma.",al={"cos'è il pettine spettrale","pettine spettrale","identità del pettine spettrale"}}},fp="13,226,24.517.0,35.189.0,18.203.0,37.187.0"}
P.entries["item:spells-of-shadow"] = {n="Incantesimi dell'Ombra",s="Incantesimi dell'Ombra è un oscuro grimorio trasportato dai cultisti della Lama Rovente in agguato sotto Orgrimmar nel Baratro di Fiamma Furente. Ricolmo di magia vile concessa dalla Legione Infuocata, è l'obiettivo di recupero da parte dei leader dei Reietti a Sepulcro.",h="Incantesimi dell'Ombra è un oscuro grimorio trasportato dai cultisti della Lama Rovente in agguato sotto...",kw={"incanti del fatuo","baratro di fiamma furente","lama rovente","incantesimi dell'ombra","sylvanas","il potere di distruggere","undercity","varimathras"},ang={["class:Warlock"]="Il tomo rappresenta il diretto patrocinio demoniaco della Legione, mostrando come culti rinnegati quali la Lama Rovente brandiscano le arti dell'ombra e del Fatuo.",["race:Undead"]="Recuperare il grimorio serve direttamente a Dama Sylvanas, rivendicando una pericolosa conoscenza demoniaca sotto Orgrimmar per rafforzare Sepulcro contro il Flagello."},sec={{t="Tomi della Lama Rovente",b="Nascosti nelle profondità delle caverne fuse del Baratro di Fiamma Furente, i membri della Lama Rovente — una setta scissionista legata al Concilio dell'Ombra — brandiscono oscuri riti concessi dai signori demoniaci della Legione Infuocata. Tra i loro tesori più protetti vi è Incantesimi dell'Ombra, un testo che racchiude insidiose stregonerie dell'ombra e vili. I cultisti e i negromanti della setta tengono questo libro a portata di mano mentre complottano proprio sotto i piedi dell'Orda a Durotar."},{t="L'ambizione della Dama Oscura",b="La notizia dei doni demoniaci della Lama Rovente giunse alle stanze reali di Sepulcro. Dama Sylvanas Ventolesto e il suo luogotenente signore del terrore, Varimathras, stabilirono che reliquie così potenti fossero sprecate con cultisti di minor visione. Varimathras affida agli avventurieri dell'Orda il compito di avventurarsi nel baratro per impadronirsi di Incantesimi dell'Ombra insieme al suo tomo complementare, Incanti del Fatuo, indirizzando il loro potere verso la causa dei Reietti contro il Flagello e il Re dei Lich."}},faq={{q="Che cos'è Incantesimi dell'Ombra?",a="È un grimorio demoniaco posseduto dai cultisti della Lama Rovente nel Baratro di Fiamma Furente, contenente doni di Shadow Magic elargiti dalla Legione Infuocata.",al={"libro incantesimi dell'ombra","cos'è incantesimi dell'ombra","libro incantesimi dell'ombra rfc"}},{q="Chi vuole questo libro?",a="Varimathras, il signore del terrore consigliere di Dama Sylvanas Ventolesto, cerca il tomo per conto della Dama Oscura. Risiede nel Quartiere Reale di Sepulcro.",al={"a chi serve incantesimi dell'ombra","a chi consegnare incantesimi dell'ombra","chi assegna la missione incantesimi dell'ombra"}},{q="Dove si può trovare il libro?",a="È trasportato dai cultisti e dai negromanti della Lama Rovente all'interno del Baratro di Fiamma Furente, la rete di caverne infuocate situata sotto la città di Orgrimmar.",al={"posizione di incantesimi dell'ombra","dove trovare incantesimi dell'ombra","come ottenere incantesimi dell'ombra"}},{q="Perché i Reietti vogliono questo grimorio?",a="Dama Sylvanas ritiene che gli oscuri doni concessi dalla Legione siano utilizzati meglio dai Reietti rispetto a cultisti minori, usando tale magia per sostenere la sua guerra contro il Flagello e il Re dei Lich.",al={"perché sylvanas vuole il libro","perché varimathras vuole incantesimi dell'ombra"}}},fp="16,244,26.428.0,24.478.0,29.149.0,20.156.0,28.146.0,39.195.0"}
P.entries["item:spotted-sunfish"] = {n="Pesce Mola Maculato",s="I Pesci Mola Maculati sono pesci d'acqua dolce originari del Lago Placido nelle Montagne Crestarossa. Rinomati a livello locale per il loro sapore, sono una merce di base per i moli di Borgolago, sebbene la crescente infestazione di murloc ne renda pericoloso l'approvvigionamento.",h="I Pesci Mola Maculati sono pesci d'acqua dolce originari del Lago Placido nelle Montagne Crestarossa.",kw={"dockmaster baren","lago placido","borgolago","murloc","montagne crestarossa","selling fish","pesce mola maculato"},ang={["profession:Cooking"]="I pesci d'acqua dolce nativi come il pesce mola maculato costituiscono la colonna portante della cucina del Lago Placido, rendendoli una presenza fissa sulle tavole delle taverne di Crestarossa."},sec={{t="Una Cattura Pregiata",b="Il Lago Placido è celebrato da tempo per i suoi pesci mola maculati, che fruttano un prezzo sicuro sia tra i mercanti locali che tra i visitatori. Il Capomolo Baren ne mantiene un commercio costante presso i moli di Borgolago, fornendo cibo e sostentamento a una cittadina sotto pressione. Tuttavia, le aggressive tribù di murloc che perlustrano i bassifondi hanno sconvolto la consueta attività di pesca, accumulando spesso scorte per conto proprio che gli avventurieri devono recuperare con la forza."}},faq={{q="Dove si trovano i Pesci Mola Maculati?",a="Prosperano nelle acque del Lago Placido nelle Montagne Crestarossa. Sebbene i pescatori possano catturarli direttamente dal lago, anche i murloc locali ne raccolgono costantemente, rendendo gli accampamenti dei murloc lungo la costa un punto ideale per recuperarli.",al={"dove trovare il pesce mola maculato","posizione pesce mola maculato","pesce del lago placido"}},{q="Chi compra o ha bisogno di Pesci Mola Maculati?",a="Il Capomolo Baren sui moli di Borgolago acquista lotti di Pesci Mola Maculati. Mantiene un commercio di questa prelibatezza e offre un compenso a chiunque sia disposto a portargliene di freschi.",al={"chi vuole il pesce mola maculato","pesce del capomolo baren","missione selling fish"}},{q="Perché i murloc portano con sé questi pesci?",a="I murloc che vivono lungo il Lago Placido si dedicano alla raccolta e al bracconaggio della fauna selvatica locale per nutrire le loro tribù in crescita. Estraggono i pesci mola dal lago proprio come fanno i pescatori umani, conservandoli nei loro accampamenti lungo le secche.",al={"pesce mola maculato dei murloc","perché i murloc rilasciano pesci"}},{q="È possibile ottenerli senza pescare?",a="Sì. Il Capomolo Baren fa notare che i viaggiatori sprovvisti di canna da pesca possono semplicemente sconfiggere i murloc ostili lungo le rive del Lago Placido e appropriarsi dei pesci che hanno raccolto.",al={"ottenere pesce mola senza canna da pesca","pesce mola senza canna da pesca"}}},fx={["723094c5"]={q="Che cos'è il Pesce Mola Maculato?",a="Il Pesce Mola Maculato è un pregiato pesce d'acqua dolce originario del Lago Placido, nelle Montagne Crestarossa. Rinomato in tutta la regione per il suo sapore e il suo valore commerciale, prospera nelle acque profonde del lago ed è una merce fondamentale per i pescatori di Borgolago, oltre che una delle principali fonti di cibo per i murloc locali.",al={"cos'è il pesce mola maculato","informazioni sul pesce mola maculato","storia del pesce mola maculato"}},["1a933976"]={q="Da dove proviene il Pesce Mola Maculato?",a="Il Pesce Mola Maculato vive naturalmente nelle fresche acque del Lago Placido, nelle Montagne Crestarossa. Non viene creato né allevato: è un pesce selvatico pescato direttamente nel lago, con la lenza lungo i moli e le rive oppure strappato dalle grinfie dei bracconieri murloc locali.",al={"origine del pesce mola maculato","da dove proviene il pesce mola maculato","provenienza del pesce mola maculato"}}},fp="15,243,14.430.0,32.242.0,34.172.0,36.212.0,36.184.0"}
P.entries["item:stalker-claws"] = {n="Artiglio di Inseguitore",s="Gli Artigli di Inseguitore sono gli artigli raccolti dagli inseguitori delle praterie che vagano per la Piana Ondulata di Mulgore. Gli sciamani tauren li usano come componenti vitali nell'intaglio dei tradizionali totem della purificazione per purificare i pozzi d'acqua contaminati.",h="Gli Artigli di Inseguitore sono gli artigli raccolti dagli inseguitori delle praterie che vagano per la Piana...",kw={"totem della purificazione","mulgore","mull corno tonante","inseguitore delle praterie","artiglio di inseguitore","thunderhorn totem","pozzo d'acqua"},ang={["class:Shaman"]="Gli artigli dei selvaggi predatori delle pianure incanalano la fiera purezza della natura, materiale essenziale per legare e infondere potere ai totem della purificazione.",["race:Tauren"]="Raccogliere questi artigli serve al sacro dovere della tua tribù di ripristinare le sacre acque avvelenate da negligenti invasori industriali."},sec={{t="Predatori delle Pianure",b="Le steppe erbose di Mulgore ospitano letali predatori naturali, tra cui i furtivi inseguitori delle praterie. Queste bestie sopravvivono grazie al puro istinto e a una precisione letale, un equilibrio essenziale all'interno del disegno della Madre Terra. Mull Corno Tonante, nel tentativo di guarire la terra devastata, richiede questi artigli non per malvagità verso gli animali, ma perché la pura, naturale ferocia con cui cacciano possiede la risonanza spirituale necessaria a contrastare la corruzione artificiale."},{t="Purificare i Pozzi",b="Quando le imprese dei goblin iniziarono a trivellare e scavare nel centro di Kalimdor, veleni chimici filtrarono in profondità nelle acque sotterranee che alimentavano i pozzi ancestrali dei tauren. Il Pozzo dei Corno Tonante in particolare cadde preda di una vile contaminazione. Legando gli Artigli di Inseguitore e gli Artigli di Puma in un Totem Purificatore dei Corno Tonante, gli sciamani tribali creano un condotto spirituale capace di ripulire il fango e la melma innaturale dalle sorgenti naturali della terra."}},faq={{q="Da dove provengono gli Artigli di Inseguitore?",a="Si ottengono cacciando gli inseguitori delle praterie tra le colline erbose di Mulgore, principalmente a est e a ovest del Villaggio di Zoccolo Sanguinario.",al={"dove trovare gli artigli di inseguitore","chi rilascia gli artigli di inseguitore","fonte degli artigli di inseguitore"}},{q="Perché Mull Corno Tonante ha bisogno di questi artigli?",a="Mull Corno Tonante usa gli artigli, insieme agli artigli di puma delle pianure, per creare un Totem Purificatore dei Corno Tonante. L'innata purezza e la forza dei cacciatori nativi delle pianure sono necessarie per purificare i pozzi d'acqua avvelenati.",al={"perché raccogliere gli artigli di inseguitore","scopo di mull corno tonante","uso degli artigli di inseguitore"}},{q="Perché il Pozzo dei Corno Tonante è contaminato?",a="Il pozzo soffre di un innaturale inquinamento industriale causato dalle operazioni dei goblin a Mulgore, che sconvolgono l'equilibrio naturale e avvelenano la falda acquifera locale.",al={"chi ha avvelenato il pozzo","perché il pozzo dei corno tonante è contaminato","inquinamento di cornotonante"}},{q="Cosa succede dopo aver raccolto gli artigli?",a="Una volta raccolti, Mull intaglia gli artigli in un totem della purificazione, che deve poi essere portato direttamente al Pozzo dei Corno Tonante per epurare la corruzione persistente.",al={"what comes next","fase successiva dopo gli artigli","rituale del totem della purificazione"}}},fx={a496bd75={q="Cosa sono gli Artigli di Inseguitore?",a="Gli Artigli di Inseguitore sono gli artigli naturali ricavati dagli inseguitori della prateria, feroci predatori felini che vagano per le pianure di Mulgore. Per gli estranei sono semplici trofei di caccia, ma gli sciamani tauren li considerano l'incarnazione dell'istinto predatorio della creatura e della sua armonia con la terra.",al={"cosa sono gli artigli di inseguitore","oggetto artigli di inseguitore","artiglio di inseguitore"}}},fp="13,218,23.477.0,19.437.0,33.127.0,43.214.0,42.165.0,42.162.0"}
P.entries["item:steelgrill-s-tools"] = {n="Attrezzi di Grigliafredda",s="Gli Attrezzi di Grigliafredda sono un set specializzato di strumenti meccanici requisiti per Beldin Grigliafredda, il capotecnico dello Scalo di Grigliafredda. Noto per spingere le macchine d'assedio — e la propria attrezzatura — al limite, Beldin rompe spesso i suoi strumenti e fa affidamento sulle spedizioni dalla vicina Kharanos per mantenere operativa la sua officina.",h="Gli Attrezzi di Grigliafredda sono un set specializzato di strumenti meccanici requisiti per Beldin...",kw={"beldin","scalo","kharanos","porto paranco","macchina d'assedio","chiave inglese","grigliafredda","attrezzi"},ang={["profession:Engineering"]="Ogni ingegnere può comprendere il dilemma di Beldin, poiché le riparazioni a coppia elevata sulle pesanti macchine d'assedio sacrificano regolarmente chiavi ad arco e strumenti delicati.",["race:Dwarf"]="Mantenere le macchine d'assedio corazzate dell'Alleanza è una questione di orgoglio nanico, e garantire i rifornimenti a Beldin assicura che l'avanguardia corazzata di Forgiardente resti pronta al combattimento."},sec={{t="Un artigiano dai modi bruschi",b="Beldin Grigliafredda è ampiamente considerato uno dei migliori tecnici di macchine d'assedio di Dun Morogh, ma il suo stile di riparazione aggressivo è tristemente noto tra i mercanti locali. Lavorando instancabilmente su carri armati e congegni meccanici, Beldin tende a distruggere le attrezzature delicate quasi con la stessa rapidità con cui vengono forgiate. Tra chiavi ad arco spezzate e cricchetti dentati spanati, il meccanico invia costantemente nuovi ordini a Kharanos per tenere riforniti i suoi banchi di lavoro."},{t="Mantenere i motori in marcia",b="Questa particolare consegna di attrezzi è vitale per mantenere operative le macchine da guerra di Forgiardente. Presso il suo scalo a nord-est di Kharanos, Beldin si occupa attivamente della manutenzione dei veicoli da combattimento per piloti esperti come il Pilota Grancingolo. Senza nuove chiavi e cricchetti a disposizione, macchine d'assedio fondamentali rimarrebbero mezze montate nella neve, lasciando bloccati sia lo scalo sia le difese locali."}},faq={{q="A cosa servono gli Attrezzi di Grigliafredda?",a="Sono strumenti meccanici di ricambio consegnati a Beldin Grigliafredda presso lo Scalo di Grigliafredda. Beldin ne ha bisogno per revisionare i pesanti macchinari nanici, in particolare la macchina d'assedio danneggiata appartenente al Pilota Grancingolo.",al={"cosa sono questi attrezzi","scopo attrezzi di grigliafredda"}},{q="Perché Beldin Grigliafredda consuma così tanti attrezzi?",a="Beldin è un meccanico dai modi eccezionalmente rudi che spinge i suoi strumenti fino al punto di rottura. Secondo i fornitori di Kharanos, spezza chiavi ad arco e distrugge cricchetti dentati quasi più velocemente di quanto gli artigiani locali riescano a fornirglieli.",al={"perché utensili rotti","perché beldin ha bisogno di attrezzi"}},{q="Da dove proviene questa cassa di attrezzi?",a="La spedizione viene preparata e completata nel vicino insediamento di Kharanos, prima di essere affidata ai viaggiatori diretti a nord-est verso lo Scalo di Grigliafredda.",al={"dove trovo gli attrezzi","origine spedizione attrezzi"}},{q="Chi è Beldin Grigliafredda?",a="Beldin è un mastro meccanico nano che possiede e gestisce lo Scalo di Grigliafredda, situato a nord-est di Kharanos. È considerato il principale tecnico di macchine d'assedio della regione.",al={"chi è beldin","storia di beldin grigliafredda"}}},fx={["8eb066d8"]={q="Cosa sono gli Attrezzi di Grigliafredda?",a="Gli Attrezzi di Grigliafredda sono una fornitura appena imballata di pesanti attrezzature meccaniche, tra cui chiavi arcobaleno e cricchetti a zanna. Sono stati preparati per essere consegnati direttamente a Beldin Grigliafredda, il tecnico esperto di macchine d'assedio che lavora allo Scalo di Grigliafredda, vicino a Kharanos.",al={"cosa sono gli attrezzi di grigliafredda","cassa degli attrezzi di grigliafredda"}},["11454cb4"]={q="Perché Beldin Grigliafredda ha bisogno di questa cassa di attrezzi?",a="Beldin è un meccanico esperto, ma mette a dura prova i suoi attrezzi mentre ripara macchinari pesanti. Ha appena spezzato il suo ultimo cricchetto a zanna e ha urgente bisogno di questa nuova fornitura per completare riparazioni fondamentali alle macchine d'assedio, come quelle di Pilota Grancingolo.",al={"perché beldin vuole gli attrezzi","perché servono gli attrezzi di grigliafredda","perché vogliono gli attrezzi"}}},fp="18,328,24.468.0,27.376.0,37.220.0,52.224.0,40.154.0,25.174.0"}
P.entries["item:steelsnap-s-rib"] = {n="Costola di Ganascia",s="La Costola di Ganascia è un macabro trofeo prelevato dalla carcassa della feroce iena Steelsnap a Millepicchi. Riportata a Picco del Tuono, funge da prova tangibile che una creatura ritenuta al di fuori della benedizione della Madre Terra è stata abbattuta.",h="La Costola di Ganascia è un macabro trofeo prelevato dalla carcassa della feroce iena Steelsnap a Millepicchi.",kw={"accampamento e'thok","altura dei cacciatori","iena","melor zoccolo granitico","steelsnap","costola di ganascia","millepicchi","picco del tuono"},ang={["class:Hunter"]="Prendere la costola di un predatore dominante mette alla prova la capacità di un cacciatore di seguire le tracce di una preda pericolosa e di abbattere le minacce che alterano l'equilibrio della natura selvaggia.",["race:Tauren"]="Per i tauren, riportare questo trofeo adempie a un dovere verso la Madre Terra purificando una creatura la cui incontrollata crudeltà contamina il sacro equilibrio."},sec={{t="Una Caccia al di Fuori della Benedizione",b="La maggior parte delle battute di caccia dei tauren viene intrapresa per sostentamento, For Honor o per cercare l'armonia con la natura. Steelsnap, tuttavia, rappresenta un tipo diverso di preda. Aggirandosi sul fondo del canyon di Millepicchi a sud dell'Accampamento E'thok, questa feroce iena alfa terrorizza la fauna pacifica e raduna branchi di predatori minori portandoli a insensati massacri. Quando il maestro di caccia Melor Zoccolo Granitico sull'Altura dei Cacciatori condanna a morte Steelsnap, esige un osso pesante — la costola di Steelsnap — come innegabile conferma che il tiranno è stato ucciso e il canyon purificato dalla sua piaga."}},faq={{q="A cosa serve la Costola di Ganascia?",a="La costola viene portata a Melor Zoccolo Granitico in cima all'Altura dei Cacciatori a Picco del Tuono per completare la caccia a Steelsnap. Serve come prova tangibile che la feroce iena è stata sconfitta.",al={"missione costola di ganascia","chi vuole la costola di ganascia","cosa fare con la costola di ganascia"}},{q="Dove posso trovare Steelsnap per ottenere la costola?",a="Steelsnap si aggira nelle propaggini nord-occidentali di Millepicchi, vagando sul fondo del canyon a sud dell'Accampamento E'thok, solitamente affiancato da leali compagni di branco.",al={"posizione di steelsnap","dove si trova steelsnap","trova steelsnap"}},{q="Perché Melor Zoccolo Granitico vuole la morte di Steelsnap?",a="Melor considera Steelsnap un tiranno innaturale che esiste al di fuori della benedizione della Madre Terra. A differenza dei normali predatori che cacciano per sopravvivere, Steelsnap diffonde carneficine gratuite e paura tra le bestie pacifiche, rendendo necessaria la sua distruzione.",al={"perché uccidere steelsnap","movente di melor zoccolo granitico","storia di steelsnap"}},{q="Chi è Melor Zoccolo Granitico?",a="Melor Zoccolo Granitico è un veterano cacciatore tauren di stanza sull'Altura dei Cacciatori a Picco del Tuono che incarica gli aspiranti inseguitori di dare la caccia a bestie pericolose in tutta Kalimdor.",al={"chi è melor","posizione di melor zoccolo granitico","melor altura dei cacciatori"}}},fx={["27efcb35"]={q="Cos'è la Costola di Ganascia?",a="È un osso pesante ricavato dalla carcassa di Steelsnap, una iena notoriamente feroce che terrorizza i canyon di Millepicchi. Non è un materiale utile per la fabbricazione né carne: serve come prova tangibile che la bestia sanguinaria è stata abbattuta.",al={"cos'è la costola di ganascia","osso di ganascia"}},["57ae26da"]={q="Da dove proviene la Costola di Ganascia?",a="La costola proviene direttamente dai resti di Steelsnap, una iena insolitamente feroce che si aggira per le aride pianure di Millepicchi, a sud di The Barrens. Per ottenerla, un cacciatore deve rintracciare la bestia e sconfiggere sia Steelsnap sia il suo branco.",al={"dove si trova la costola di ganascia","origine della costola di ganascia","chi rilascia la costola di ganascia"}},["4a69fb67"]={q="Perché Melor Zoccolo Granitico vuole la Costola di Ganascia?",a="Melor Zoccolo Granitico chiede la costola come prova tangibile della morte di Steelsnap. A differenza delle cacce intraprese per procurarsi cibo o onore, Melor manda i cacciatori a eliminare Steelsnap perché la bestia vive al di fuori della benedizione della Madre Terra e diffonde violenza e paura tra le creature più pacifiche. Riportare l'osso conferma che il canyon è stato liberato da quella contaminazione.",al={"perché portare la costola di ganascia a melor","perché a melor serve la costola","perché raccogliere la costola di ganascia"}}},fp="15,245,27.553.0,33.177.0,42.148.0,47.240.0,23.165.0"}
P.entries["item:stolen-silver"] = {n="Argento Rubato",s="L'Argento Rubato è una cassaforte recuperata contenente monete dell'Orda destinate alla guarnigione delle guardie di Crocevia. È stata bizzarramente portata via nelle terre selvagge dai feroci raptor di The Barrens, suscitando incredulità tra i sovrintendenti dell'avamposto.",h="L'Argento Rubato è una cassaforte recuperata contenente monete dell'Orda destinate alla guarnigione delle...",kw={"paga di the barrens","crocevia","gazrog","raptor grounds","cassetta d'argento","argento rubato","sunscale raptor"},ang={["faction:Horde"]="Crocevia funge da cuore strategico della presenza dell'Orda in The Barrens. Recuperare questa paga garantisce che i grugnitori locali rimangano sfamati, pagati e pronti a difendere la linea contro le incursioni dei centauri e dell'Alleanza."},sec={{t="Un colpo bestiale",b="Le vaste terre selvagge di The Barrens rappresentano una minaccia costante per le linee di rifornimento, ma pochi si aspettavano che i Sunscale raptor locali prendessero di mira le casseforti contenenti valuta metallica. Quando una spedizione di argento destinata alla paga della guarnigione di Crocevia è stata rubata dalla torre delle guardie, i raptor hanno trascinato la cassetta fino ai loro nidi comuni presso i Raptor Grounds a sud di Porto Paranco. Per i sovrintendenti come Gazrog, il furto rivela un livello inquietante di astuzia in questi predatori, che a quanto pare apprezzano i ninnoli luccicanti o possiedono un'intelligenza di gran lunga superiore a quella delle normali bestie selvatiche."}},faq={{q="Cos'è l'Argento Rubato?",a="È una pesante cassetta piena di monete d'argento destinate a pagare le guardie di Crocevia. È stata rubata dalla torre delle guardie di Crocevia dai raptor e trasportata nelle loro terre di nidificazione.",al={"cos'è l'argento rubato","cos'è l'argento"}},{q="Perché i raptor hanno rubato una cassetta di monete?",a="Il movente dei predatori rimane un mistero perfino per guerrieri veterani come Gazrog. Sebbene gli animali cerchino tipicamente cibo, i raptor di The Barrens sono noti per la loro insolita astuzia, e queste bestie sono state spinte a trascinare la lucente cassa di metallo nel profondo della loro tana.",al={"perché i raptor vogliono l'argento","intelligenza dei raptor","perché l'argento"}},{q="Dov'è stato portato l'argento?",a="I raptor hanno trascinato la cassetta fino ai Raptor Grounds, un aspro canyon di nidi situato a sud di Porto Paranco, nella parte orientale di The Barrens.",al={"posizione dell'argento rubato","dov'è l'argento"}},{q="Chi sta cercando l'Argento Rubato?",a="Gazrog, un orco di stanza a Crocevia, cerca la cassa. I fondi rappresentano un intero mese di paga per i difensori in difficoltà dell'avamposto.",al={"chi vuole l'argento","a chi consegnare l'argento rubato"}}},fp="13,239,15.556.0,26.183.0,41.248.0,27.128.0,37.141.0"}
P.entries["item:stone-of-relu"] = {n="Pietra di Relu",s="La Pietra di Relu è un antico reperto archeologico recuperato dalle Wetlands. Ritenuta dall'Archeologo Granrutto la chiave per sbloccare i poteri latenti nei fossili primordiali, fu brevemente perduta quando i raptor locali tesero un'imboscata allo studioso lungo la strada.",h="La Pietra di Relu è un antico reperto archeologico recuperato dalle Wetlands.",kw={"archeologo granrutto","lega degli esploratori","fossile","raptor chiazzato","prospettore whelgar","pietra di relu","wetlands"},ang={["faction:Alliance"]="Le spedizioni dell'Alleanza a Porto di Menethil fanno affidamento su manufatti recuperati come la Pietra di Relu per giustificare i faticosi scavi attraverso le pericolose paludi.",["race:Dwarf"]="Per la Lega degli Esploratori, la Pietra di Relu è uno strumento vitale per ricomporre le origini della vita antica e l'eredità dimenticata del mondo."},sec={{t="Una chiave per antiche reliquie",b="Scoperta durante le operazioni della Lega degli Esploratori, si ritiene che la Pietra di Relu racchiuda il potere di decifrazione necessario per sbloccare i fossili preistorici raccolti a Kalimdor e nei Regni Orientali. L'Archeologo Granrutto ha identificato il manufatto come il catalizzatore richiesto per svelare i segreti racchiusi sia nei suoi campioni delle Wetlands, sia nel fossile dissotterrato dal Prospettore Errasogni a Darkshore."},{t="Perduta nelle paludi",b="Mentre Granrutto viaggiava lungo le strade delle Wetland per incontrarsi con il Prospettore Whelgar, un branco di raptor chiazzati gli tese un'imboscata. Durante la concitazione, la reliquia andò perduta e fu inghiottita da una delle bestie fameliche, costringendo la Lega ad assoldare avventurieri per dare la caccia ai raptor della palude ed estrarre l'antica pietra dai loro gozzi."}},faq={{q="Cos'è la Pietra di Relu?",a="La Pietra di Relu è un antico manufatto cercato dall'Archeologo Granrutto. Egli ritiene che funga da cifrario o catalizzatore in grado di sbloccare i misteri nascosti e il potere sopito all'interno dei fossili preistorici.",al={"pietra di relu","cos'è questa pietra","manufatto di relu"}},{q="Come è finita la pietra dentro un raptor?",a="L'Archeologo Granrutto stava trasportando la reliquia lungo la strada delle Wetlands per incontrare il Prospettore Whelgar quando dei raptor chiazzati attaccarono il suo gruppo. Nel caos, la pietra andò perduta e fu ingerita da una delle bestie spazzine.",al={"perché i raptor ce l'hanno","chi ha perso la pietra","come è andata perduta"}},{q="Cosa intende fare Granrutto con la pietra?",a="Granrutto intende abbinare la pietra al fossile da lui recuperato e a quello trovato dal Prospettore Errasogni a Darkshore, usando la reliquia per decifrare e liberare i loro segreti magici latenti.",al={"cosa vuole granrutto","scopo della pietra di relu"}}},fp="13,258,23.387.0,19.330.0,26.207.0,41.217.0,48.190.0"}
P.entries["item:stonetalon-sap"] = {n="Linfa di Petrartiglio",s="La Linfa di Petrartiglio è una sostanza appiccicosa e potente estratta direttamente dalle lente bestie della linfa che vagano per le alture dirupate delle Vette di Petrartiglio. Serve come reagente fondamentale per il Taumaturgo Jin'zil dei Darkspear, che sfrutta le sue grezze proprietà boschive per preparare un infuso malevolo.",h="La Linfa di Petrartiglio è una sostanza appiccicosa e potente estratta direttamente dalle lente bestie della...",kw={"jin'zil","malaka'jin","lago mirkfallon","bestia della linfa","picco di petrartiglio","linfa di petrartiglio"},ang={["race:NightElf"]="La profanazione degli elementi nativi di Petrartiglio da parte di un taumaturgo dell'Orda per avvelenare elfi in gabbia è un oltraggio contro la natura ed Elune.",["race:Troll"]="Il Taumaturgo Jin'zil dimostra il talento dei Darkspear nel trasformare l'amato ambiente del nemico in un letale strumento voodoo."},sec={{t="Un amaro raccolto",b="Trovato a gocciolare dalle bestie della linfa arboree vicino al Lago Mirkfallon e al Picco di Petrartiglio, questo denso fluido racchiude l'essenza concentrata dell'antica flora della montagna. Sebbene innocua quando inattiva in natura, la linfa può essere facilmente trasformata in qualcosa di molto più oscuro nelle mani di un alchimista o taumaturgo esperto. Jin'Zil di Malaka'jin la brama per preparare ciò che chiama beffardamente \"magia della foresta\": una pozione letale destinata a tormentare i suoi prigionieri elfi della notte in gabbia con l'essenza stessa della loro amata natura selvaggia."}},faq={{q="Quali creature portano la Linfa di Petrartiglio?",a="Viene raccolta dalle bestie della linfa, le bizzarre creature boschive che si trovano vicino al Lago Mirkfallon e più in alto lungo i pendii che conducono al Picco di Petrartiglio.",al={"dove trovare la linfa di petrartiglio","chi rilascia la linfa di petrartiglio","bestie della linfa"}},{q="Per cosa usa la linfa il Taumaturgo Jin'zil?",a="Jin'Zil combina la linfa con occhi di corsiero, vibrisse del crepuscolo e una Scaglia di Drago Fatato per produrre un intruglio tossico che scaglia contro i suoi prigionieri elfi della notte in gabbia.",al={"perché jin'zil vuole la linfa","ricetta magia della foresta di jin'zil"}},{q="Qual è il posto migliore per trovare le bestie della linfa?",a="Le bestie della linfa popolano i boschetti che circondano il Lago Mirkfallon e i rigogliosi sentieri che salgono verso il Picco di Petrartiglio.",al={"posizione delle bestie della linfa","bestie della linfa del lago mirkfallon"}},{q="La linfa è magica di per sé?",a="È naturalmente intrisa della vitalità primordiale degli altipiani di Petrartiglio, ma sono necessari il mojo dei troll e reagenti specifici per trasformarla in un veleno letale.",al={"la linfa di petrartiglio è magica","proprietà della linfa di petrartiglio"}}},fx={b24da591={q="Cos'è la Linfa di Petrartiglio?",a="La Linfa di Petrartiglio è una resina naturale e appiccicosa raccolta dalle bestie della linfa che vagano per le Vette di Petrartiglio, soprattutto nei pressi di luoghi come il Lago Mirkfallon e il Picco di Petrartiglio. È densa, viscosa e colma di essenza naturale grezza: un ingrediente ideale per intrugli e pozioni voodoo che attingono alla singolare magia della natura selvaggia locale.",al={"cos'è la linfa di petrartiglio","oggetto linfa di petrartiglio","informazioni sulla linfa di petrartiglio"}},["7615d27b"]={q="Da dove proviene la Linfa di Petrartiglio?",a="Questa linfa ambrata viene raccolta direttamente dalle bestie della linfa viventi che si aggirano per le foreste e lungo le rive dei laghi delle Vette di Petrartiglio. Non viene fabbricata né distillata da alcun artigiano mortale: è secreta naturalmente da queste bizzarre creature vegetali primordiali.",al={"provenienza della linfa di petrartiglio","dove trovare la linfa","origine della linfa di petrartiglio"}}},fp="14,283,16.520.1,36.148.0,47.163.1,43.109.0,30.160.0"}
P.entries["item:stormpike-banner"] = {n="Stendardo dei Piccatonante",s="Lo Stendardo dei Piccatonante è uno stendardo militare nascosto nel profondo dell'insidiosa Caverna di Algidala nella Valle d'Alterac. Le reclute dell'Alleanza devono affrontare arpie selvagge per recuperarlo come prova di iniziazione, dimostrando di essere degne di indossare il Fregio dei Piccatonante.",h="Lo Stendardo dei Piccatonante è uno stendardo militare nascosto nel profondo dell'insidiosa Caverna di...",kw={"valle d'alterac","dun baldar","haggerdin","caverna di algidala","fregio","banco di prova","stendardo dei piccatonante"},ang={["faction:Alliance"]="Il recupero dello stendardo segna il tuo ingresso formale nella Guardia dei Piccatonante, facendoti guadagnare il diritto di portare il loro fregio da battaglia contro il Clan Lupi Bianchi.",["race:Dwarf"]="Lo stendardo rappresenta la rivendicazione sovrana di Forgiardente e la sacra missione del clan Piccatonante di scoprire le reliquie del proprio passato in tutta la valle."},sec={{t="Un rito di iniziazione",b="Per unirsi ufficialmente ai ranghi della spedizione dei Piccatonante nella Valle d'Alterac, le aspiranti reclute devono dimostrare il proprio valore prima ancora di scontrarsi con gli orchi del Clan Lupi Bianchi. Il Tenente Haggerdin invia i soldati dell'Alleanza appena arrivati nella Caverna di Algidala, situata a sud-ovest di Dun Baldar. Piantato nel profondo di questa tana sotterranea ghiacciata, lo Stendardo dei Piccatonante funge da banco di prova: chiunque sia abbastanza coraggioso da affrontare le arpie locali, impadronirsi dello stendardo e riportarlo indietro vivo ottiene il grado e il fregio di iniziato nella Guardia dei Piccatonante."}},faq={{q="Dove si trova lo Stendardo dei Piccatonante?",a="Lo stendardo è piantato nel profondo della Caverna di Algidala, un sistema di caverne soffocato dal gelo situato a sud-ovest di Dun Baldar all'interno della Valle d'Alterac.",al={"posizione dello stendardo","dove si trova lo stendardo dei piccatonante","come trovare lo stendardo"}},{q="Perché le reclute devono recuperare lo stendardo?",a="Il Tenente Haggerdin richiede a tutte le reclute dell'Alleanza di dimostrare il proprio coraggio prima di unirsi alle linee di battaglia. Riportare lo stendardo dalla pericolosa caverna infestata dalle arpie fa guadagnare alla recluta il suo iniziale Fregio dei Piccatonante.",al={"prova di iniziazione","perché prendere lo stendardo","missione di haggerdin"}},{q="Quali minacce proteggono lo stendardo all'interno della caverna?",a="La Caverna di Algidala è ferocemente difesa da feroci arpie locali che attaccheranno con violenza qualunque intruso cerchi lo stendardo.",al={"mostri vicino allo stendardo","nemici della caverna di algidala"}},{q="A chi devo riportare lo stendardo una volta trovato?",a="Consegna lo stendardo recuperato al Tenente Haggerdin, l'ufficiale dell'Alleanza di stanza fuori dall'ingresso nelle Montagne d'Alterac.",al={"consegnare lo stendardo","consegna dello stendardo"}}},fx={["27f01085"]={q="Cos'è lo Stendardo dei Piccatonante?",a="Lo Stendardo dei Piccatonante è un vessillo militare che rappresenta la Guardia dei Piccatonante, la spedizione nanica attualmente impegnata nella guerra in tutta la Valle d'Alterac. Piantato nel cuore delle pericolose Grotte di Ala Gelida, infestate dalle arpie, a sud-ovest di Dun Baldar, lo stendardo funge da prova. Le reclute devono avventurarsi nelle profondità ghiacciate, affrontare le bestie feroci che vi si annidano e recuperare i colori per dimostrare il proprio valore e meritare di indossare il fregio dei Piccatonante.",al={"cos'è lo stendardo dei piccatonante","storia dello stendardo dei piccatonante","informazioni sullo stendardo dei piccatonante"}}},fp="16,248,19.546.0,38.137.0,44.232.0,46.129.0,41.131.0"}
P.entries["item:stormpike-s-request"] = {n="Richiesta dei Piccatonante",s="Richiesta dei Piccatonante è una commissione scritta inviata dal Montanaro Piccatonante dalle colline di Loch Modan a Roccavento. La lettera chiede al maestro fabbricante d'armature Furen Barbalunga di creare uno scudo su misura di ineguagliabile qualità nanica.",h="Richiesta dei Piccatonante è una commissione scritta inviata dal Montanaro Piccatonante dalle colline di Loch...",kw={"fabbro","dun morogh","distretto dei nani","furen barbalunga","richiesta","scudo","piccatonante","roccavento"},ang={["profession:Blacksmithing"]="La richiesta testimonia la reputazione dei maestri armorieri, dimostrando che la grande arte dei fabbri nanici attira clienti attraverso interi regni.",["race:Dwarf"]="Per i nani, recapitare la richiesta mantiene i legami di clan e di mestiere tra i montanari a guardia di Khaz Modan e gli artigiani che vivono all'estero nelle città umane."},sec={{t="Una commissione dal nord",b="Mentre è di stanza nell'estremo nord a Loch Modan, il Montanaro Piccatonante necessita di un nuovo e robusto scudo per affrontare i pericoli della frontiera nanica. Anziché affidarsi a un fabbro qualunque, insiste nel commissionarlo a Furen Barbalunga, un fabbricante d'armature la cui leggendaria maestria tiene nella più alta considerazione. Poiché Furen risiede ora a sud tra gli umani del Distretto dei Nani di Roccavento — allontanato da Forgiardente da quello che Piccatonante suppone debba essere un riscatto da re — il montanaro si affida ad avventurieri di passaggio per recapitare la sua richiesta formale attraverso i regni."},{t="Il lignaggio dei Piccatonante",b="Consegnare la lettera nel vivace Distretto dei Nani di Roccavento fa pervenire l'ordine direttamente nelle mani capaci di Furen Barbalunga. Trattandosi di un fiero e affermato clan nanico, noto in tutta Khaz Modan sia per il coraggio marziale sia per la notevole ricchezza, una commissione dei Piccatonante ha un grande valore. Lieto di ricevere notizie e affari dalle sue ancestrali terre natie del nord, Furen accetta di soddisfare l'ordine e si mette al lavoro forgiando lo scudo del montanaro."}},faq={{q="Cos'è Richiesta dei Piccatonante?",a="È un ordine scritto inviato dal Montanaro Piccatonante da Loch Modan in cui si richiede al maestro fabbricante d'armature Furen Barbalunga di forgiargli uno scudo di alta qualità.",al={"cos'è questa lettera","oggetto ordine dei piccatonante","richiesta dei piccatonante"}},{q="Chi ha scritto questa lettera?",a="È stata scritta dal Montanaro Piccatonante, una sentinella nanica che difende i valichi di Loch Modan e che ammira profondamente l'abilità di fabbro di Furen Barbalunga.",al={"chi ha inviato la richiesta dei piccatonante","chi l'ha scritta","montanaro piccatonante"}},{q="Dove deve andare questa lettera?",a="È indirizzata a Furen Barbalunga, che lavora alla sua forgia all'interno del Distretto dei Nani di Roccavento.",al={"dove portare la richiesta dei piccatonante","a chi è indirizzata questa lettera","consegnare la richiesta dei piccatonante"}},{q="Perché Piccatonante ingaggia un fabbro fino a Roccavento?",a="Il Montanaro Piccatonante considera l'abilità di Furen ineguagliabile e rifiuta di accontentarsi di qualsiasi altro corazzaio, anche se Furen ha scelto di lasciare Forgiardente per esercitare il proprio mestiere tra gli umani nel sud.",al={"perché furen","perché non forgiare a forgiardente","perché inviare a roccavento"}}},fx={["181a24c8"]={q="Perché Furen Barbalunga vuole la Richiesta dei Piccatonante?",a="Questo ordine scritto commissiona uno scudo nanico finemente lavorato. Furen Barbalunga, un armaiolo che vive nel Distretto dei Nani di Roccavento, apprezza gli affari con il celebre clan dei Piccatonante. Sa che la famiglia è orgogliosa e stimata in tutto Khaz Modan, oltre che abbastanza ricca da pagare profumatamente per un lavoro di qualità eccezionale.",al={"perché furen lo vuole","perché vogliono la richiesta dei piccatonante","perché serve la richiesta dei piccatonante"}}},fp="19,237,21.578.0,18.448.0,28.154.0,22.144.0,34.105.0,57.191.0"}
P.entries["item:stormwind-armor-marker"] = {n="Buono per un'Armatura di Roccavento",s="Un Buono per un'Armatura di Roccavento è un gettone di requisizione militare ufficiale rilasciato agli avventurieri che hanno aiutato il regno. Può essere riscattato presso artigiani autorizzati, come Sara Timberlain al Campo di Taglio di Vallevante, in cambio di equipaggiamento appena forgiato.",h="Un Buono per un'Armatura di Roccavento è un gettone di requisizione militare ufficiale rilasciato agli...",kw={"buono per un'armatura","armature in stoffa e cuoio","campo di taglio di vallevante","foresta di elwynn","requisizione","sara timberlain","buono per un'armatura di roccavento"},ang={["faction:Alliance"]="Il buono rappresenta i legami logistici che uniscono gli insediamenti di frontiera come il Campo di Taglio di Vallevante direttamente al comando militare di Roccavento."},sec={{t="Requisizioni militari",b="Mantenere la legge e l'ordine attraverso la Foresta di Elwynn mette a dura prova le risorse del regno. Piuttosto che distribuire equipaggiamento standard direttamente dagli avamposti militari, i comandanti a volte rilasciano gettoni ufficiali noti come buoni per armature. Questi tagliandi di requisizione certificano che il portatore ha reso un servizio valoroso per Roccavento e autorizzano gli artigiani locali convenzionati a fornirgli armature su misura."},{t="Approvvigionamento di Vallevante",b="Una destinazione fondamentale per questi buoni è il Campo di Taglio di Vallevante, situato sulla frontiera orientale di Elwynn. Lì, artigiani come Sara Timberlain lavorano su commissione per l'Esercito di Roccavento, trasformando i materiali locali in indumenti protettivi di stoffa e cuoio. La presentazione di un buono concede alle reclute una difesa su misura per aiutarle a salvaguardare i boschi circostanti."}},faq={{q="Qual è lo scopo del Buono per un'Armatura di Roccavento?",a="Funge da buono militare ufficiale consegnato agli avventurieri che aiutano le guardie di Roccavento. Il gettone attesta il tuo servizio e ti permette di richiedere un pezzo di armatura protettiva da un artigiano convenzionato con l'esercito.",al={"cos'è il buono per un'armatura","scopo del buono","uso del buono di roccavento"}},{q="Chi accetta il buono?",a="Sara Timberlain lo accetta al Campo di Taglio di Vallevante, situato appena a est oltre il fiume nella Foresta di Elwynn. Ha un contratto con l'Esercito di Roccavento per fornire equipaggiamento su misura in stoffa e cuoio.",al={"chi accetta il buono","dove consegnare il buono","buono sara timberlain"}},{q="Perché Roccavento usa dei buoni invece di distribuire direttamente le armature?",a="I posti di guardia periferici spesso mancano dello spazio di stoccaggio o delle attrezzature da forgia e sartoria necessarie per equipaggiare le reclute sul posto. Rilasciando gettoni di requisizione, i comandanti sul campo delegano la fornitura dell'equipaggiamento ad artigiani locali come Sara Timberlain, che dispongono di botteghe dedicate.",al={"perché gettoni invece di armature","perché buoni dell'esercito","buoni militari elwynn"}},{q="Che tipo di equipaggiamento fornisce il buono?",a="Il buono conferisce al portatore il diritto di scegliere tra pezzi di armatura appena fabbricati in stoffa o in cuoio, realizzati su ordinazione da fornitori convenzionati dell'esercito.",al={"quale armatura ricevo","ricompense del buono","stoffa o cuoio"}}},fx={e5398b12={q="Cos'è il Buono per un'Armatura di Roccavento?",a="È un buono militare ufficiale emesso per conto dell'Esercito di Roccavento. Anziché trasportare ingombranti armature protettive attraverso la Foresta di Elwynn, i comandanti locali rilasciano questo gettone come garanzia di requisizione, che dà al portatore il diritto di ritirare un'armatura di stoffa o di cuoio appena realizzata presso un armaiolo autorizzato.",al={"cos'è il buono per un'armatura di roccavento","buono per un'armatura","cos'è il buono"}},["3e7f2980"]={q="Da dove proviene il Buono per un'Armatura di Roccavento e chi l'ha creato?",a="Il buono viene emesso per conto dell'Esercito di Roccavento dalla Guardia Thomas, presso il suo avamposto vicino al ponte orientale di Elwynn, e assegnato ai difensori che dimostrano astuzia e valore. È munito dell'autorità dell'esercito del regno e incarica gli artigiani locali di rifornire le reclute a spese della corona.",al={"chi ha creato il buono per l'armatura","da dove proviene il buono","chi rilascia il buono per l'armatura"}},["618263b5"]={q="Perché Sara Timberlain vuole il Buono per un'Armatura di Roccavento?",a="L'Esercito di Roccavento ha incaricato Sara Timberlain di equipaggiare le proprie reclute e i volontari con armature di stoffa e di cuoio. Prima di consegnare i suoi manufatti, esige il buono come prova ufficiale dell'autorizzazione, così da garantire che le scorte del regno vadano solo ai difensori riconosciuti.",al={"perché sara vuole il buono","perché portare il buono a vallenera","perché serve il buono per l'armatura"}}},fp="22,251,21.397.0,21.379.0,50.208.0,23.204.0,69.259.0,47.137.0"}
